INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52802, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地中", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "地球", "is_correct": false, "explanation": "「ちきゅう」で、ちゅ→きゅの1拍違い。"}, {"text": "市中", "is_correct": false, "explanation": "「しちゅう」で、ち→しの1拍違い。"}, {"text": "忌中", "is_correct": false, "explanation": "「きちゅう」で、ち→きの1拍違い。"}, {"text": "地上", "is_correct": false, "explanation": "「ちじょう」で、ちゅ→じょの1拍違い。"}], "explanations": {"地中": "見出し語そのもの。", "地球": "「ちきゅう」で、ちゅ→きゅの1拍違い。", "市中": "「しちゅう」で、ち→しの1拍違い。", "忌中": "「きちゅう」で、ち→きの1拍違い。", "地上": "「ちじょう」で、ちゅ→じょの1拍違い。"}, "sentence_index": null, "correct_answer": "地中"}, "level_3": {"options": [{"text": "地中", "is_correct": true, "explanation": "炭素を地中へ封じ込める技術という文意に合う。"}, {"text": "空中", "is_correct": false, "explanation": "形は合うが、空中に炭素を封じ込めるという意味が合わない。"}, {"text": "机上", "is_correct": false, "explanation": "形は合うが、机の上に炭素を封じ込めるという意味が合わない。"}, {"text": "頭上", "is_correct": false, "explanation": "形は合うが、頭上に炭素を封じ込めるという意味が合わない。"}], "explanations": {"地中": "炭素を地中へ封じ込める技術という文意に合う。", "空中": "形は合うが、空中に炭素を封じ込めるという意味が合わない。", "机上": "形は合うが、机の上に炭素を封じ込めるという意味が合わない。", "頭上": "形は合うが、頭上に炭素を封じ込めるという意味が合わない。"}, "sentence_index": 0, "correct_answer": "地中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥は地中を高く飛んでいる。", "explanation": "地中は地面の下で、鳥が飛ぶのは空。場所の使い方が誤り。"}, {"text": "地中の魚が、池でゆっくり泳いでいる。", "explanation": "池の水中を「地中」とは言わない。意味が違う。"}, {"text": "家の二階にある地中で本を読んだ。", "explanation": "二階は地面より上で、地中ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52802, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地中", "is_correct": true, "explanation": "地面の下で何かが動くという文意に合う。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、時間で何かが動くという意味が合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、鉛筆で何かが動くという意味が合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "形は合うが、手紙で何かが動くという意味が合わない。"}], "explanations": {"地中": "地面の下で何かが動くという文意に合う。", "時間": "形は合うが、時間で何かが動くという意味が合わない。", "鉛筆": "形は合うが、鉛筆で何かが動くという意味が合わない。", "手紙": "形は合うが、手紙で何かが動くという意味が合わない。"}, "sentence_index": 6, "correct_answer": "地中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飛行機が地中を飛んで空港に着いた。", "explanation": "飛行機は空を飛ぶ。地中は地面の下で、使い方が誤り。"}, {"text": "地中の雲が白くて、とてもきれいだった。", "explanation": "雲は空にあるもので、地中にはない。"}, {"text": "木の高い枝の地中に小鳥の巣があった。", "explanation": "高い枝は地面の上で、地中ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52802, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水道管が地中を埋まっている。", "corrected_sentence": "水道管が地中に埋まっている。", "error_description": "埋まる場所は「地中を」でなく「地中に」と表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52802, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "セミの子どもは、地中を何年も育つ。", "corrected_sentence": "セミの子どもは、地中で何年も育つ。", "error_description": "育つ場所は「地中を」でなく「地中で」と表す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52803, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "閉じ込める先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「塔を」では「王子を」と重なり非文になる。"}, {"text": "の", "is_correct": false, "explanation": "「塔の封じ込めた」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「塔と封じ込めた」は場所を表せず非文になる。"}], "correct_answer": "に", "explanations": {"に": "閉じ込める先を示す。", "を": "「塔を」では「王子を」と重なり非文になる。", "の": "「塔の封じ込めた」は文として成り立たない。", "と": "「塔と封じ込めた」は場所を表せず非文になる。"}, "error_tags": {"を": "double_object", "の": "possessive", "と": "accompaniment"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解き放たれた", "is_correct": true, "explanation": "閉じ込められたの反対で、自由になること。"}, {"text": "閉じ込められた", "is_correct": false, "explanation": "ほぼ同じ意味で、反対ではない。"}, {"text": "見つけられた", "is_correct": false, "explanation": "反対の関係ではない。"}, {"text": "運ばれた", "is_correct": false, "explanation": "反対の関係ではない。"}], "correct_answer": "解き放たれた", "explanations": {"解き放たれた": "閉じ込められたの反対で、自由になること。", "閉じ込められた": "ほぼ同じ意味で、反対ではない。", "見つけられた": "反対の関係ではない。", "運ばれた": "反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
