INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52803, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "中に入れて、外に出ないようにすること。", "primary_collocate": null, "pronunciation": "ふうじこめる", "ipa": "ɸɯːʑikomeɾɯ", "syllable_count": 6, "sentences": [{"text": "彼は手紙を箱に封じ込めた。", "target_word": "封じ込めた", "complexity_tier": "T3", "furigana": "かれはてがみをはこにふうじこめた。", "sentence_source": "generated"}, {"text": "魔女は王子を塔に封じ込めた。", "target_word": "封じ込めた", "complexity_tier": "T3", "furigana": "まじょはおうじをとうにふうじこめた。", "sentence_source": "generated"}, {"text": "古い写真に思い出を封じ込める。", "target_word": "封じ込める", "complexity_tier": "T3", "furigana": "ふるいしゃしんにおもいでをふうじこめる。", "sentence_source": "generated"}, {"text": "悪魔は石の中に封じ込められた。", "target_word": "封じ込められた", "complexity_tier": "T4", "furigana": "あくまはいしのなかにふうじこめられた。", "sentence_source": "generated"}, {"text": "彼女は怒りを心に封じ込めている。", "target_word": "封じ込めている", "complexity_tier": "T3", "furigana": "かのじょはいかりをこころにふうじこめている。", "sentence_source": "generated"}, {"text": "私は夢を瓶に封じ込めたい。", "target_word": "封じ込めたい", "complexity_tier": "T3", "furigana": "わたしはゆめをびんにふうじこめたい。", "sentence_source": "generated"}, {"text": "箱に封じ込めれば、音は外に漏れません。", "target_word": "封じ込めれば", "complexity_tier": "T4", "furigana": "はこにふうじこめれば、おとはそとにもれません。", "sentence_source": "generated"}, {"text": "昔の人は魔物を壺に封じ込めたそうだ。", "target_word": "封じ込めた", "complexity_tier": "T4", "furigana": "むかしのひとはまものをつぼにふうじこめたそうだ。", "sentence_source": "generated"}, {"text": "この絵は夏の光を封じ込めています。", "target_word": "封じ込めています", "complexity_tier": "T3", "furigana": "このえはなつのひかりをふうじこめています。", "sentence_source": "generated"}, {"text": "子どもを部屋に封じ込めてはいけません。", "target_word": "封じ込めて", "complexity_tier": "T3", "furigana": "こどもをへやにふうじこめてはいけません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "封じ込めた", "label": "活用"}, {"form": "封じ込めて", "label": "活用"}, {"form": "封じ込められる", "label": "活用"}, {"form": "封じ込めたい", "label": "活用"}, {"form": "封じ込め", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 中に入れて外へ出さない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71984b75-a7f2-4235-a5ab-be3dacb672ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52803, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "封じ込めた", "is_correct": true, "explanation": "手紙を箱の中に入れて出さない意味で合う。"}, {"text": "洗った", "is_correct": false, "explanation": "形は合うが、手紙を箱に洗うという意味が合わない。"}, {"text": "褒めた", "is_correct": false, "explanation": "形は合うが、手紙を箱に褒めるという意味が合わない。"}, {"text": "疑った", "is_correct": false, "explanation": "形は合うが、手紙を箱に疑うという意味が合わない。"}], "explanations": {"封じ込めた": "手紙を箱の中に入れて出さない意味で合う。", "洗った": "形は合うが、手紙を箱に洗うという意味が合わない。", "褒めた": "形は合うが、手紙を箱に褒めるという意味が合わない。", "疑った": "形は合うが、手紙を箱に疑うという意味が合わない。"}, "sentence_index": 0, "correct_answer": "封じ込めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は昨日、友だちを駅で封じ込めた。", "explanation": "「封じ込める」は中に入れて出さないことで、駅で友だちに会う意味には使えない。"}, {"text": "彼は大きな声で歌を封じ込めて、みんなを笑わせた。", "explanation": "「封じ込める」に歌を歌う意味はない。"}, {"text": "母は冷蔵庫から野菜を封じ込めて、料理を始めた。", "explanation": "「封じ込める」は中に入れる意味で、取り出す意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52803, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封じ込めれば", "is_correct": true, "explanation": "箱の中に閉じ込めれば音が漏れないという意味で合う。"}, {"text": "眺めれば", "is_correct": false, "explanation": "形は合うが、箱に眺めても音が漏れないという意味にならない。"}, {"text": "褒めれば", "is_correct": false, "explanation": "形は合うが、箱に褒めても音が漏れないという意味にならない。"}, {"text": "疑えば", "is_correct": false, "explanation": "形は合うが、箱に疑っても音が漏れないという意味にならない。"}], "explanations": {"封じ込めれば": "箱の中に閉じ込めれば音が漏れないという意味で合う。", "眺めれば": "形は合うが、箱に眺めても音が漏れないという意味にならない。", "褒めれば": "形は合うが、箱に褒めても音が漏れないという意味にならない。", "疑えば": "形は合うが、箱に疑っても音が漏れないという意味にならない。"}, "sentence_index": 6, "correct_answer": "封じ込めれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝、電車を封じ込めて会社へ行く。", "explanation": "「封じ込める」は中に入れて出さないことで、電車に乗る意味には使えない。"}, {"text": "先生は生徒の質問に笑顔で封じ込めた。", "explanation": "「封じ込める」に質問へ答える意味はない。"}, {"text": "私は新しい服を封じ込めて、パーティーに出かけた。", "explanation": "「封じ込める」は服を着る意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52803, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は夢を瓶から封じ込めたい。", "corrected_sentence": "私は夢を瓶に封じ込めたい。", "error_description": "入れる先は「に」で示すので、「から」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "封じ込めた", "is_correct": true, "explanation": "文末の過去形として正しい。"}, {"text": "封じ込めれば", "is_correct": false, "explanation": "条件形で文を終えられない。"}, {"text": "封じ込めて", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "封じ込め", "is_correct": false, "explanation": "連用形のままでは文末にならない。"}], "correct_form": "封じ込めた", "base_form": "封じ込める", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"封じ込めた": "文末の過去形として正しい。", "封じ込めれば": "条件形で文を終えられない。", "封じ込めて": "て形では文が終わらない。", "封じ込め": "連用形のままでは文末にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52803, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "魔女は王子を塔を封じ込めた。", "corrected_sentence": "魔女は王子を塔に封じ込めた。", "error_description": "閉じ込める先は「に」で示すので、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "封じ込めた", "is_correct": true, "explanation": "伝聞の「そうだ」に続く過去形として正しい。"}, {"text": "封じ込めよう", "is_correct": false, "explanation": "意志形は「そうだ」に続かない。"}, {"text": "封じ込めれば", "is_correct": false, "explanation": "条件形は「そうだ」に続かない。"}, {"text": "封じ込めて", "is_correct": false, "explanation": "て形は「そうだ」に続かない。"}], "correct_form": "封じ込めた", "base_form": "封じ込める", "form_label": "過去形（た形）", "sentence_index": 7, "explanations": {"封じ込めた": "伝聞の「そうだ」に続く過去形として正しい。", "封じ込めよう": "意志形は「そうだ」に続かない。", "封じ込めれば": "条件形は「そうだ」に続かない。", "封じ込めて": "て形は「そうだ」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52804, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "封じ込める対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「ガスが封じ込めた」では対象が主語になり不自然。"}, {"text": "の", "is_correct": false, "explanation": "「ガスの封じ込めた」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "対象を表せず、非文になる。"}], "correct_answer": "を", "explanations": {"を": "封じ込める対象を示す。", "が": "「ガスが封じ込めた」では対象が主語になり不自然。", "の": "「ガスの封じ込めた」は文として成り立たない。", "へ": "対象を表せず、非文になる。"}, "error_tags": {"が": "subject_object_confusion", "の": "possessive", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解き放つ", "is_correct": true, "explanation": "閉じ込めるの反対で、外へ出すこと。"}, {"text": "見つける", "is_correct": false, "explanation": "反対の関係ではない。"}, {"text": "守る", "is_correct": false, "explanation": "反対の関係ではない。"}, {"text": "数える", "is_correct": false, "explanation": "反対の関係ではない。"}], "correct_answer": "解き放つ", "explanations": {"解き放つ": "閉じ込めるの反対で、外へ出すこと。", "見つける": "反対の関係ではない。", "守る": "反対の関係ではない。", "数える": "反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
