INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52804, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や人を外に出られないように閉じ込めること。特に、有害なものを広がらないように密閉すること。", "primary_collocate": null, "pronunciation": "ふうじこめる", "ipa": "ɸɯːʑikomeɾɯ", "syllable_count": 6, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "封じ込める", "complexity_tier": "T6", "furigana": "たんなるはいきぶつとしてのかくりにとどまらず、たんそをしげんへとてんかんし、あるいはちちゅうへふうじこめるこのぎじゅつは、けいざいかつどうとだつたんそかのりょうりつというなんだいにたいする、げんじてんでのさいてきかいたりうる。", "sentence_source": "mined"}, {"text": "工場は有害なガスを封じ込めた。", "target_word": "封じ込めた", "complexity_tier": "T3", "furigana": "こうじょうはゆうがいなガスをふうじこめた。", "sentence_source": "generated"}, {"text": "医師たちは感染を封じ込めようとした。", "target_word": "封じ込めよう", "complexity_tier": "T4", "furigana": "いしたちはかんせんをふうじこめようとした。", "sentence_source": "generated"}, {"text": "ウイルスを封じ込めるため、町は閉鎖された。", "target_word": "封じ込める", "complexity_tier": "T4", "furigana": "ウイルスをふうじこめるため、まちはへいさされた。", "sentence_source": "generated"}, {"text": "毒ガスは地下の容器に封じ込められている。", "target_word": "封じ込められている", "complexity_tier": "T4", "furigana": "どくガスはちかのようきにふうじこめられている。", "sentence_source": "generated"}, {"text": "政府は火災を早く封じ込めます。", "target_word": "封じ込めます", "complexity_tier": "T2", "furigana": "せいふはかさいをはやくふうじこめます。", "sentence_source": "generated"}, {"text": "汚染水を封じ込める方法を探している。", "target_word": "封じ込める", "complexity_tier": "T3", "furigana": "おせんすいをふうじこめるほうほうをさがしている。", "sentence_source": "generated"}, {"text": "放射性物質を封じ込めることはできなかった。", "target_word": "封じ込める", "complexity_tier": "T3", "furigana": "ほうしゃせいぶっしつをふうじこめることはできなかった。", "sentence_source": "generated"}, {"text": "感染を封じ込めれば、被害は広がらない。", "target_word": "封じ込めれば", "complexity_tier": "T4", "furigana": "かんせんをふうじこめれば、ひがいはひろがらない。", "sentence_source": "generated"}, {"text": "研究者は菌を封じ込めて、実験を続けた。", "target_word": "封じ込めて", "complexity_tier": "T3", "furigana": "けんきゅうしゃはきんをふうじこめて、じっけんをつづけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "封じ込めた", "label": "活用"}, {"form": "封じ込めて", "label": "活用"}, {"form": "封じ込められる", "label": "活用"}, {"form": "封じ込めない", "label": "活用"}, {"form": "封じ込め", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 有害なものを外に出さず密閉する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71984b75-a7f2-4235-a5ab-be3dacb672ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52804, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "封じ込める", "is_correct": true, "explanation": "炭素を地中に閉じ込める意味で文脈に合う。"}, {"text": "見つめる", "is_correct": false, "explanation": "形は合うが、炭素を地中へ見つめるという意味が合わない。"}, {"text": "笑い飛ばす", "is_correct": false, "explanation": "形は合うが、技術の説明として意味が合わない。"}, {"text": "読み上げる", "is_correct": false, "explanation": "形は合うが、炭素を地中へ読み上げるという意味が合わない。"}], "explanations": {"封じ込める": "炭素を地中に閉じ込める意味で文脈に合う。", "見つめる": "形は合うが、炭素を地中へ見つめるという意味が合わない。", "笑い飛ばす": "形は合うが、技術の説明として意味が合わない。", "読み上げる": "形は合うが、炭素を地中へ読み上げるという意味が合わない。"}, "sentence_index": 0, "correct_answer": "封じ込める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は新しい靴を封じ込めて公園を歩いた。", "explanation": "「封じ込める」は有害なものを外に出さない意味で、靴を履く意味には使えない。"}, {"text": "子どもたちは公園でボールを封じ込めて遊んだ。", "explanation": "「封じ込める」は外に出さないことで、ボールを投げて遊ぶ意味には使えない。"}, {"text": "毎朝、窓を封じ込めて部屋の空気を入れ替えた。", "explanation": "「封じ込める」は外に出さないことで、窓を開ける意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52804, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封じ込める", "is_correct": true, "explanation": "汚染水を外へ広げない方法として合う。"}, {"text": "組み立てる", "is_correct": false, "explanation": "形は合うが、汚染水を組み立てるという意味が合わない。"}, {"text": "読み上げる", "is_correct": false, "explanation": "形は合うが、汚染水を読み上げるという意味が合わない。"}, {"text": "褒め称える", "is_correct": false, "explanation": "形は合うが、汚染水を褒め称えるという意味が合わない。"}], "explanations": {"封じ込める": "汚染水を外へ広げない方法として合う。", "組み立てる": "形は合うが、汚染水を組み立てるという意味が合わない。", "読み上げる": "形は合うが、汚染水を読み上げるという意味が合わない。", "褒め称える": "形は合うが、汚染水を褒め称えるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "封じ込める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降ってきたので、傘を封じ込めて出かけた。", "explanation": "「封じ込める」は傘を持つ・さす意味では使えない。"}, {"text": "母は毎晩、本を封じ込めて子どもに読んであげた。", "explanation": "「封じ込める」は本を読む意味では使えない。"}, {"text": "先生は黒板の文字を封じ込めて、授業を始めた。", "explanation": "「封じ込める」に文字を消す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
