INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52805, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とてもむずかしい問題のことです。", "primary_collocate": null, "pronunciation": "なんだい", "ipa": "nandai", "syllable_count": 4, "sentences": [{"text": "この宿題は難題です。", "target_word": "難題", "complexity_tier": "T2", "furigana": "このしゅくだいはなんだいです。", "sentence_source": "generated"}, {"text": "難題を先生に聞いた。", "target_word": "難題", "complexity_tier": "T1", "furigana": "なんだいをせんせいにきいた。", "sentence_source": "generated"}, {"text": "今日のテストは難題ばかりだった。", "target_word": "難題", "complexity_tier": "T3", "furigana": "きょうのテストはなんだいばかりだった。", "sentence_source": "generated"}, {"text": "友だちと難題を考えた。", "target_word": "難題", "complexity_tier": "T1", "furigana": "ともだちとなんだいをかんがえた。", "sentence_source": "generated"}, {"text": "難題が出て、みんな困った。", "target_word": "難題", "complexity_tier": "T3", "furigana": "なんだいがでて、みんなこまった。", "sentence_source": "generated"}, {"text": "兄は難題をすぐ解いた。", "target_word": "難題", "complexity_tier": "T1", "furigana": "あにはなんだいをすぐといた。", "sentence_source": "generated"}, {"text": "これは大人にも難題です。", "target_word": "難題", "complexity_tier": "T2", "furigana": "これはおとなにもなんだいです。", "sentence_source": "generated"}, {"text": "難題の答えがわかりません。", "target_word": "難題", "complexity_tier": "T2", "furigana": "なんだいのこたえがわかりません。", "sentence_source": "generated"}, {"text": "難題に出会ったら、助けを求めよう。", "target_word": "難題", "complexity_tier": "T4", "furigana": "なんだいにであったら、たすけをもとめよう。", "sentence_source": "generated"}, {"text": "先生が出した難題は、とても長い問題でした。", "target_word": "難題", "complexity_tier": "T3", "furigana": "せんせいがだしたなんだいは、とてもながいもんだいでした。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | とてもむずかしい問題", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', t