INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52805, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "難題", "is_correct": true, "explanation": "見出し語（なんだい）。"}, {"text": "寛大", "is_correct": false, "explanation": "かんだい。最初の1モーラだけが違う。"}, {"text": "番台", "is_correct": false, "explanation": "ばんだい。最初の1モーラだけが違う。"}, {"text": "短大", "is_correct": false, "explanation": "たんだい。最初の1モーラだけが違う。"}], "explanations": {"難題": "見出し語（なんだい）。", "寛大": "かんだい。最初の1モーラだけが違う。", "番台": "ばんだい。最初の1モーラだけが違う。", "短大": "たんだい。最初の1モーラだけが違う。"}, "sentence_index": null, "correct_answer": "難題"}, "level_3": {"options": [{"text": "難題", "is_correct": true, "explanation": "宿題がとても難しいという意味で合う。"}, {"text": "友だち", "is_correct": false, "explanation": "形は合うが、宿題が友だちという意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、宿題が天気という意味が合わない。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、宿題が果物という意味が合わない。"}], "explanations": {"難題": "宿題がとても難しいという意味で合う。", "友だち": "形は合うが、宿題が友だちという意味が合わない。", "天気": "形は合うが、宿題が天気という意味が合わない。", "果物": "形は合うが、宿題が果物という意味が合わない。"}, "sentence_index": 0, "correct_answer": "難題"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は難題を作って、家族みんなで食べた。", "explanation": "「難題」は難しい問題で、料理のように作って食べるものではない。"}, {"text": "雨が降ったので、難題をさして帰った。", "explanation": "「難題」は傘のようにさすものではない。"}, {"text": "兄は簡単な難題で、五分で全部解いた。", "explanation": "「難題」はとても難しい問題なので、簡単という内容と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
