INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52806, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「多い」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「多い」は目的語を取らず非文になる。"}, {"text": "に", "is_correct": false, "explanation": "「難題に多い」では意味が通らず非文になる。"}, {"text": "と", "is_correct": false, "explanation": "「難題と多い」は非文になる。"}], "correct_answer": "が", "explanations": {"が": "「多い」の主語を示す。", "を": "「多い」は目的語を取らず非文になる。", "に": "「難題に多い」では意味が通らず非文になる。", "と": "「難題と多い」は非文になる。"}, "error_tags": {"を": "object_marker", "に": "location", "と": "accompaniment"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "朝飯前", "is_correct": true, "explanation": "非常に簡単なことで、難題の反対。"}, {"text": "宿題", "is_correct": false, "explanation": "反対の関係ではない。"}, {"text": "質問", "is_correct": false, "explanation": "反対の関係ではない。"}, {"text": "試験", "is_correct": false, "explanation": "反対の関係ではない。"}], "correct_answer": "朝飯前", "explanations": {"朝飯前": "非常に簡単なことで、難題の反対。", "宿題": "反対の関係ではない。", "質問": "反対の関係ではない。", "試験": "反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
