INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52806, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "解決するのが非常に困難な問題や課題。", "primary_collocate": null, "pronunciation": "なんだい", "ipa": "nandai", "syllable_count": 4, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "難題", "complexity_tier": "T6", "furigana": "たんなるはいきぶつとしてのかくりにとどまらず、たんそをしげんへとてんかんし、あるいはちちゅうへふうじこめるこのぎじゅつは、けいざいかつどうとだつたんそかのりょうりつというなんだいにたいする、げんじてんでのさいてきかいたりうる。", "sentence_source": "mined"}, {"text": "この会社には難題が多い。", "target_word": "難題", "complexity_tier": "T3", "furigana": "このかいしゃにはなんだいがおおい。", "sentence_source": "generated"}, {"text": "先生は私たちに難題を出した。", "target_word": "難題", "complexity_tier": "T3", "furigana": "せんせいはわたしたちになんだいをだした。", "sentence_source": "generated"}, {"text": "難題を解決するには時間がかかる。", "target_word": "難題", "complexity_tier": "T3", "furigana": "なんだいをかいけつするにはじかんがかかる。", "sentence_source": "generated"}, {"text": "新しい難題に直面しています。", "target_word": "難題", "complexity_tier": "T2", "furigana": "あたらしいなんだいにちょくめんしています。", "sentence_source": "generated"}, {"text": "それは世界が抱える難題です。", "target_word": "難題", "complexity_tier": "T2", "furigana": "それはせかいがかかえるなんだいです。", "sentence_source": "generated"}, {"text": "難題に挑戦するのが好きだ。", "target_word": "難題", "complexity_tier": "T3", "furigana": "なんだいにちょうせんするのがすきだ。", "sentence_source": "generated"}, {"text": "彼は難題を次々と解いてしまった。", "target_word": "難題", "complexity_tier": "T3", "furigana": "かれはなんだいをつぎつぎとといてしまった。", "sentence_source": "generated"}, {"text": "難題だと言われた仕事を、彼女は一人で終わらせた。", "target_word": "難題", "complexity_tier": "T4", "furigana": "なんだいだといわれたしごとを、かのじょはひとりでおわらせた。", "sentence_source": "generated"}, {"text": "難題が解ければ、会社は救われる。", "target_word": "難題", "complexity_tier": "T4", "furigana": "なんだいがとければ、かいしゃはすくわれる。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 解決が非常に難しい問題や課題", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71984b75-a7f2-4235-a5ab-be3dacb672ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52806, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "難題", "is_correct": true, "explanation": "見出し語（なんだい）。"}, {"text": "寛大", "is_correct": false, "explanation": "かんだい。最初の1モーラだけが違う。"}, {"text": "番台", "is_correct": false, "explanation": "ばんだい。最初の1モーラだけが違う。"}, {"text": "短大", "is_correct": false, "explanation": "たんだい。最初の1モーラだけが違う。"}], "explanations": {"難題": "見出し語（なんだい）。", "寛大": "かんだい。最初の1モーラだけが違う。", "番台": "ばんだい。最初の1モーラだけが違う。", "短大": "たんだい。最初の1モーラだけが違う。"}, "sentence_index": null, "correct_answer": "難題"}, "level_3": {"options": [{"text": "難題", "is_correct": true, "explanation": "両立という解決の難しい問題を表し、文脈に合う。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが、最適解が対応する問題という意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、両立という内容と意味が合わない。"}, {"text": "習慣", "is_correct": false, "explanation": "形は合うが、最適解が対応する問題という意味が合わない。"}], "explanations": {"難題": "両立という解決の難しい問題を表し、文脈に合う。", "趣味": "形は合うが、最適解が対応する問題という意味が合わない。", "季節": "形は合うが、両立という内容と意味が合わない。", "習慣": "形は合うが、最適解が対応する問題という意味が合わない。"}, "sentence_index": 0, "correct_answer": "難題"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の昼ごはんは難題でとてもおいしかった。", "explanation": "「難題」は難しい問題で、料理の味を表す語ではない。"}, {"text": "雨の日は難題が降るので傘が必要だ。", "explanation": "「難題」は降るものではなく、天気を表せない。"}, {"text": "兄は毎朝、難題を飲んでから学校へ行く。", "explanation": "「難題」は問題で、飲み物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
