INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52807, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるときのこと。", "primary_collocate": null, "pronunciation": "じてん", "ipa": "dʑiteɴ", "syllable_count": 3, "sentences": [{"text": "今の時点で、私は元気です。", "target_word": "時点", "complexity_tier": "T2", "furigana": "いまのじてんで、わたしはげんきです。", "sentence_source": "generated"}, {"text": "その時点では、まだ雨でした。", "target_word": "時点", "complexity_tier": "T2", "furigana": "そのじてんでは、まだあめでした。", "sentence_source": "generated"}, {"text": "十時の時点で、客は五人だった。", "target_word": "時点", "complexity_tier": "T3", "furigana": "じゅうじのじてんで、きゃくはごにんだった。", "sentence_source": "generated"}, {"text": "いつの時点ですか。", "target_word": "時点", "complexity_tier": "T2", "furigana": "いつのじてんですか。", "sentence_source": "generated"}, {"text": "この時点で帰ってもいいですか。", "target_word": "時点", "complexity_tier": "T2", "furigana": "このじてんでかえってもいいですか。", "sentence_source": "generated"}, {"text": "出発の時点では、天気がよかった。", "target_word": "時点", "complexity_tier": "T3", "furigana": "しゅっぱつのじてんでは、てんきがよかった。", "sentence_source": "generated"}, {"text": "あの時点の私は、まだ小さかった。", "target_word": "時点", "complexity_tier": "T3", "furigana": "あのじてんのわたしは、まだちいさかった。", "sentence_source": "generated"}, {"text": "七時の時点で、店はもう閉まっていた。", "target_word": "時点", "complexity_tier": "T3", "furigana": "しちじのじてんで、みせはもうしまっていた。", "sentence_source": "generated"}, {"text": "昨日の時点で、宿題は終わっていた。", "target_word": "時点", "complexity_tier": "T3", "furigana": "きのうのじてんで、しゅくだいはおわっていた。", "sentence_source": "generated"}, {"text": "この時点から、話は変わる。", "target_word": "時点", "complexity_tier": "T3", "furigana": "このじてんから、はなしはかわる。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | ある一つの時、そのとき", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-se