INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52807, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "時点", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "支店", "is_correct": false, "explanation": "「してん」で、じ→しの一拍違い。"}, {"text": "地点", "is_correct": false, "explanation": "「ちてん」で、じ→ちの一拍違い。"}, {"text": "自伝", "is_correct": false, "explanation": "「じでん」で、て→での一拍違い。"}, {"text": "事件", "is_correct": false, "explanation": "「じけん」で、て→けの一拍違い。"}], "explanations": {"時点": "見出し語そのもの。", "支店": "「してん」で、じ→しの一拍違い。", "地点": "「ちてん」で、じ→ちの一拍違い。", "自伝": "「じでん」で、て→での一拍違い。", "事件": "「じけん」で、て→けの一拍違い。"}, "sentence_index": null, "correct_answer": "時点"}, "level_3": {"options": [{"text": "時点", "is_correct": true, "explanation": "「今の時点」で「今この時」を表す。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、「今の値段で私は元気」は意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、「今の辞書で元気」は意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、「今の野菜で元気」は意味が合わない。"}], "explanations": {"時点": "「今の時点」で「今この時」を表す。", "値段": "形は合うが、「今の値段で私は元気」は意味が合わない。", "辞書": "形は合うが、「今の辞書で元気」は意味が合わない。", "野菜": "形は合うが、「今の野菜で元気」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "時点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この時点は三時間ありますから、ゆっくり休めます。", "explanation": "時点は一点の時で、長さのある時間には使えない。"}, {"text": "時点の中で、魚を泳がせた。", "explanation": "時点は容器や場所ではなく、魚を泳がせる対象にならない。"}, {"text": "新しい時点を買って、机の上に置いた。", "explanation": "時点は物ではなく、買ったり置いたりできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id