INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52808, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある特定の時刻や時期。その時。", "primary_collocate": null, "pronunciation": "じてん", "ipa": "dʑiteɴ", "syllable_count": 3, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "現時点", "complexity_tier": "T6", "furigana": "たんなるはいきぶつとしてのかくりにとどまらず、たんそをしげんへとてんかんし、あるいはちちゅうへふうじこめるこのぎじゅつは、けいざいかつどうとだつたんそかのりょうりつというなんだいにたいする、げんじてんでのさいてきかいたりうる。", "sentence_source": "mined"}, {"text": "その時点では、誰も知らなかった。", "target_word": "時点", "complexity_tier": "T3", "furigana": "そのじてんでは、だれもしらなかった。", "sentence_source": "generated"}, {"text": "いつの時点の話ですか。", "target_word": "時点", "complexity_tier": "T2", "furigana": "いつのじてんのはなしですか。", "sentence_source": "generated"}, {"text": "三月の時点で、売り上げは倍になった。", "target_word": "時点", "complexity_tier": "T3", "furigana": "さんがつのじてんで、うりあげはばいになった。", "sentence_source": "generated"}, {"text": "この時点を過ぎると、変更はできない。", "target_word": "時点", "complexity_tier": "T3", "furigana": "このじてんをすぎると、へんこうはできない。", "sentence_source": "generated"}, {"text": "事故が起きた時点で、彼は家にいなかった。", "target_word": "時点", "complexity_tier": "T4", "furigana": "じこがおきたじてんで、かれはいえにいなかった。", "sentence_source": "generated"}, {"text": "九月末の時点の人口を調べた。", "target_word": "時点", "complexity_tier": "T3", "furigana": "くがつまつのじてんのじんこうをしらべた。", "sentence_source": "generated"}, {"text": "契約した時点から、料金が発生する。", "target_word": "時点", "complexity_tier": "T4", "furigana": "けいやくしたじてんから、りょうきんがはっせいする。", "sentence_source": "generated"}, {"text": "ある時点を境に、町は変わり始めた。", "target_word": "時点", "complexity_tier": "T4", "furigana": "あるじてんをさかいに、まちはかわりはじめた。", "sentence_source": "generated"}, {"text": "その時点に戻れたら、違う道を選ぶだろう。", "target_word": "時点", "complexity_tier": "T4", "furigana": "そのじてんにもどれたら、ちがうみちをえらぶだろう。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | ある特定の時刻や時期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): とどまら (Zipf 3.23), 地中 (Zipf 3.61), 封じ込める (Zipf 2.62), 難題 (Zipf 3.21)']::text[], '71984b75-a7f2-4235-a5ab-be3dacb672ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52808, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "時点", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "支店", "is_correct": false, "explanation": "「してん」で、じ→しの一拍違い。"}, {"text": "地点", "is_correct": false, "explanation": "「ちてん」で、じ→ちの一拍違い。"}, {"text": "自伝", "is_correct": false, "explanation": "「じでん」で、て→での一拍違い。"}, {"text": "事件", "is_correct": false, "explanation": "「じけん」で、て→けの一拍違い。"}], "explanations": {"時点": "見出し語そのもの。", "支店": "「してん」で、じ→しの一拍違い。", "地点": "「ちてん」で、じ→ちの一拍違い。", "自伝": "「じでん」で、て→での一拍違い。", "事件": "「じけん」で、て→けの一拍違い。"}, "sentence_index": null, "correct_answer": "時点"}, "level_3": {"options": [{"text": "現時点", "is_correct": true, "explanation": "「今この時」の意味で、文意に合う。"}, {"text": "現金", "is_correct": false, "explanation": "形は合うが、お金の意味で「最適解」の時間的限定にならず意味が合わない。"}, {"text": "現象", "is_correct": false, "explanation": "形は合うが、「現象での最適解」は意味が合わない。"}, {"text": "現住所", "is_correct": false, "explanation": "形は合うが、住所の意味で文脈に合わない。"}], "explanations": {"現時点": "「今この時」の意味で、文意に合う。", "現金": "形は合うが、お金の意味で「最適解」の時間的限定にならず意味が合わない。", "現象": "形は合うが、「現象での最適解」は意味が合わない。", "現住所": "形は合うが、住所の意味で文脈に合わない。"}, "sentence_index": 0, "correct_answer": "現時点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みの時点は四十日間も続いた。", "explanation": "時点は一点の時を指し、期間の長さには使えない。"}, {"text": "この時点は広くて、駐車場が百台ある。", "explanation": "時点は時を表す語で、場所の広さを表せない。"}, {"text": "兄は時点がとても高くて、天井に頭が届く。", "explanation": "時点は背の高さなどの物理的な量を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52808, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "時点", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "起点", "is_correct": false, "explanation": "「きてん」で、じ→きの一拍違い。"}, {"text": "視点", "is_correct": false, "explanation": "「してん」で、じ→しの一拍違い。"}, {"text": "自選", "is_correct": false, "explanation": "「じせん」で、て→せの一拍違い。"}, {"text": "事前", "is_correct": false, "explanation": "「じぜん」で、て→ぜの一拍違い。"}], "explanations": {"時点": "見出し語そのもの。", "起点": "「きてん」で、じ→きの一拍違い。", "視点": "「してん」で、じ→しの一拍違い。", "自選": "「じせん」で、て→せの一拍違い。", "事前": "「じぜん」で、て→ぜの一拍違い。"}, "sentence_index": null, "correct_answer": "時点"}, "level_3": {"options": [{"text": "時点", "is_correct": true, "explanation": "「九月末の時点」で調査の基準時を示す。"}, {"text": "手紙", "is_correct": false, "explanation": "形は合うが、「手紙の人口」は意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「天気の人口」は意味が合わない。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが、「料理の人口」は意味が合わない。"}], "explanations": {"時点": "「九月末の時点」で調査の基準時を示す。", "手紙": "形は合うが、「手紙の人口」は意味が合わない。", "天気": "形は合うが、「天気の人口」は意味が合わない。", "料理": "形は合うが、「料理の人口」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "時点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北海道は寒いので、冬の時点が長く続く。", "explanation": "時点は一点の時で、長く続く期間には使えない。"}, {"text": "彼の時点は美しく、部屋に飾った。", "explanation": "時点は物ではなく、飾れる対象を表さない。"}, {"text": "駅の時点で電車を待っている人が多い。", "explanation": "時点は場所を指さない。場所なら「地点」や「ホーム」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52808, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "六月の時点を、在庫は半分になった。", "corrected_sentence": "六月の時点で、在庫は半分になった。", "error_description": "時点に付く助詞が「を」では誤り。「その時に」を表す「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
