INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52810, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "解", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "顔", "is_correct": false, "explanation": "「かお」で、い→おの一拍違い。"}, {"text": "柿", "is_correct": false, "explanation": "「かき」で、い→きの一拍違い。"}, {"text": "隊", "is_correct": false, "explanation": "「たい」で、か→たの一拍違い。"}, {"text": "舞", "is_correct": false, "explanation": "「まい」で、か→まの一拍違い。"}], "explanations": {"解": "見出し語そのもの。", "顔": "「かお」で、い→おの一拍違い。", "柿": "「かき」で、い→きの一拍違い。", "隊": "「たい」で、か→たの一拍違い。", "舞": "「まい」で、か→まの一拍違い。"}, "sentence_index": null, "correct_answer": "解"}, "level_3": {"options": [{"text": "解", "is_correct": true, "explanation": "難しい問題にも答えがあるという文意に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、「机は必ずある」は意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、「難しい問題だが靴は必ずある」は意味が合わない。"}, {"text": "皿", "is_correct": false, "explanation": "形は合うが、「難しい問題だが、皿は必ずある」は意味が合わない。"}], "explanations": {"解": "難しい問題にも答えがあるという文意に合う。", "机": "形は合うが、「机は必ずある」は意味が合わない。", "靴": "形は合うが、「難しい問題だが靴は必ずある」は意味が合わない。", "皿": "形は合うが、「難しい問題だが、皿は必ずある」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は、解をさして外へ出た。", "explanation": "解は傘のような道具ではない。"}, {"text": "解の色が青くて、空のようだった。", "explanation": "解は抽象的な答えで、色を持たない。"}, {"text": "夕食に解を焼いて、家族で食べた。", "explanation": "解は食材ではなく、焼いて食べられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_i