INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52811, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "超越するの対象を示す助詞で正しい。"}, {"text": "と", "is_correct": false, "explanation": "「時代と超越した人」は意味が通らず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「時代で超越した人」は対象を表せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「時代へ超越した人」は方向を表す「へ」を対象に使っており不自然。"}], "correct_answer": "を", "explanations": {"を": "超越するの対象を示す助詞で正しい。", "と": "「時代と超越した人」は意味が通らず不自然。", "で": "「時代で超越した人」は対象を表せず不自然。", "へ": "「時代へ超越した人」は方向を表す「へ」を対象に使っており不自然。"}, "error_tags": {"と": "comitative", "で": "means", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
