INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52811, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものをこえて、もっと上にいくこと。", "primary_collocate": null, "pronunciation": "ちょうえつ", "ipa": "tɕoːetsɯ", "syllable_count": 4, "sentences": [{"text": "この力は人間を超越している。", "target_word": "超越している", "complexity_tier": "T3", "furigana": "このちからはにんげんをちょうえつしている。", "sentence_source": "generated"}, {"text": "彼は時代を超越した人だ。", "target_word": "超越した", "complexity_tier": "T3", "furigana": "かれはじだいをちょうえつしたひとだ。", "sentence_source": "generated"}, {"text": "音楽は国境を超越する。", "target_word": "超越する", "complexity_tier": "T2", "furigana": "おんがくはこっきょうをちょうえつする。", "sentence_source": "generated"}, {"text": "彼の考えは常識を超越している。", "target_word": "超越している", "complexity_tier": "T3", "furigana": "かれのかんがえはじょうしきをちょうえつしている。", "sentence_source": "generated"}, {"text": "彼の歌は国を超越して愛される。", "target_word": "超越して", "complexity_tier": "T4", "furigana": "かれのうたはくにをちょうえつしてあいされる。", "sentence_source": "generated"}, {"text": "スポーツは言葉の壁を超越する。", "target_word": "超越する", "complexity_tier": "T3", "furigana": "スポーツはことばのかべをちょうえつする。", "sentence_source": "generated"}, {"text": "年齢を超越した友情がある。", "target_word": "超越した", "complexity_tier": "T3", "furigana": "ねんれいをちょうえつしたゆうじょうがある。", "sentence_source": "generated"}, {"text": "彼の力は想像を超越している。", "target_word": "超越している", "complexity_tier": "T3", "furigana": "かれのちからはそうぞうをちょうえつしている。", "sentence_source": "generated"}, {"text": "その美しさは言葉を超越していた。", "target_word": "超越していた", "complexity_tier": "T3", "furigana": "そのうつくしさはことばをちょうえつしていた。", "sentence_source": "generated"}, {"text": "超越の意味を辞書で調べた。", "target_word": "超越", "complexity_tier": "T3", "furigana": "ちょうえつのいみをじしょでしらべた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "超越する", "label": "活用"}, {"form": "超越した", "label": "活用"}, {"form": "超越して", "label": "活用"}, {"form": "超越的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | あるものをこえて上にいく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71984b75-a7f2-4235-a5ab-be3dacb672ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52811, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超越している", "is_correct": true, "explanation": "人間をこえているという意味で合う。"}, {"text": "掃除している", "is_correct": false, "explanation": "形は合うが、人間を掃除しているでは意味が合わない。"}, {"text": "注文している", "is_correct": false, "explanation": "形は合うが、人間を注文しているでは意味が合わない。"}, {"text": "運転している", "is_correct": false, "explanation": "形は合うが、人間を運転しているでは意味が合わない。"}], "explanations": {"超越している": "人間をこえているという意味で合う。", "掃除している": "形は合うが、人間を掃除しているでは意味が合わない。", "注文している": "形は合うが、人間を注文しているでは意味が合わない。", "運転している": "形は合うが、人間を運転しているでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "超越している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日のテストは超越に難しかった。", "explanation": "超越は程度を強める副詞ではなく、名詞を誤用している。"}, {"text": "私は超越を机の上で食べた。", "explanation": "超越は抽象概念で、食べ物ではなく誤用している。"}, {"text": "駅で超越して電車を待った。", "explanation": "超越するは上にこえる意味で、待つ動作とは結びつかず誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52811, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超越した", "is_correct": true, "explanation": "年齢をこえた友情という意味で合う。"}, {"text": "洗濯した", "is_correct": false, "explanation": "形は合うが、年齢を洗濯した友情では意味が合わない。"}, {"text": "印刷した", "is_correct": false, "explanation": "形は合うが、年齢を印刷した友情では意味が合わない。"}, {"text": "販売した", "is_correct": false, "explanation": "形は合うが、年齢を販売した友情では意味が合わない。"}], "explanations": {"超越した": "年齢をこえた友情という意味で合う。", "洗濯した": "形は合うが、年齢を洗濯した友情では意味が合わない。", "印刷した": "形は合うが、年齢を印刷した友情では意味が合わない。", "販売した": "形は合うが、年齢を販売した友情では意味が合わない。"}, "sentence_index": 6, "correct_answer": "超越した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は超越を履いて学校へ行った。", "explanation": "超越は抽象概念で、履く物ではなく誤用している。"}, {"text": "今日は超越して寒い。", "explanation": "超越するは「とても」の意味の副詞的用法を持たず誤用している。"}, {"text": "母は超越を作って皿に盛った。", "explanation": "超越は料理のように作って盛れる物ではなく誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
