INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52812, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "超越するの対象を示す助詞で正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「理性へ超越する力」は対象を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「理性と超越する力」は意味が通らず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「理性に超越する力」は対象の示し方として誤り。"}], "correct_answer": "を", "explanations": {"を": "超越するの対象を示す助詞で正しい。", "へ": "「理性へ超越する力」は対象を示せず不自然。", "と": "「理性と超越する力」は意味が通らず不自然。", "に": "「理性に超越する力」は対象の示し方として誤り。"}, "error_tags": {"へ": "direction", "と": "comitative", "に": "target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52812, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "普通の限界や範囲をこえて、もっと高い段階に進むこと。", "primary_collocate": null, "pronunciation": "ちょうえつ", "ipa": "tɕoːetsɯ", "syllable_count": 4, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "超越する", "complexity_tier": "T6", "furigana": "われわれがちょくめんするかんきょうてきげんかいをちょうえつするため、CCUSのしゃかいじっそうは、さんぎょうこうぞうのてんかんをささえるかなめいしとして、そのそんざいかんをさらにましていくであろう。", "sentence_source": "mined"}, {"text": "神は人間を超越した存在だ。", "target_word": "超越した", "complexity_tier": "T3", "furigana": "かみはにんげんをちょうえつしたそんざいだ。", "sentence_source": "generated"}, {"text": "彼の才能は常識を超越している。", "target_word": "超越している", "complexity_tier": "T3", "furigana": "かれのさいのうはじょうしきをちょうえつしている。", "sentence_source": "generated"}, {"text": "超越の境地に達した僧がいる。", "target_word": "超越", "complexity_tier": "T3", "furigana": "ちょうえつのきょうちにたっしたそうがいる。", "sentence_source": "generated"}, {"text": "時代を超越した音楽が生まれた。", "target_word": "超越した", "complexity_tier": "T3", "furigana": "じだいをちょうえつしたおんがくがうまれた。", "sentence_source": "generated"}, {"text": "自分の限界を超越することは簡単ではない。", "target_word": "超越する", "complexity_tier": "T3", "furigana": "じぶんのげんかいをちょうえつすることはかんたんではない。", "sentence_source": "generated"}, {"text": "彼女は国境を超越して活躍している。", "target_word": "超越して", "complexity_tier": "T3", "furigana": "かのじょはこっきょうをちょうえつしてかつやくしている。", "sentence_source": "generated"}, {"text": "理性を超越する力を信じる人もいる。", "target_word": "超越する", "complexity_tier": "T3", "furigana": "りせいをちょうえつするちからをしんじるひともいる。", "sentence_source": "generated"}, {"text": "彼の演奏は技術の域を超越している。", "target_word": "超越している", "complexity_tier": "T4", "furigana": "かれのえんそうはぎじゅつのいきをちょうえつしている。", "sentence_source": "generated"}, {"text": "古い考えを超越できれば、新しい世界が見える。", "target_word": "超越できれば", "complexity_tier": "T4", "furigana": "ふるいかんがえをちょうえつできれば、あたらしいせかいがみえる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "超越する", "label": "活用"}, {"form": "超越した", "label": "活用"}, {"form": "超越して", "label": "活用"}, {"form": "超越的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 限界や範囲をこえて高い段階へ進む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71984b75-a7f2-4235-a5ab-be3dacb672ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52812, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超越する", "is_correct": true, "explanation": "環境的限界をこえるという意味で文脈に合う。"}, {"text": "修理する", "is_correct": false, "explanation": "形は合うが、限界を修理するでは意味が合わない。"}, {"text": "暗記する", "is_correct": false, "explanation": "形は合うが、限界を暗記するでは意味が合わない。"}, {"text": "収穫する", "is_correct": false, "explanation": "形は合うが、限界を収穫するでは意味が合わない。"}], "explanations": {"超越する": "環境的限界をこえるという意味で文脈に合う。", "修理する": "形は合うが、限界を修理するでは意味が合わない。", "暗記する": "形は合うが、限界を暗記するでは意味が合わない。", "収穫する": "形は合うが、限界を収穫するでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "超越する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夕食は超越においしかった。", "explanation": "超越は「とても」の意味の副詞として使えず、名詞を程度の強調に誤用している。"}, {"text": "私は毎朝コーヒーを超越して飲む。", "explanation": "超越するは限界をこえる意味で、飲む動作の様子を表す語として誤用している。"}, {"text": "超越を机の上に置いた。", "explanation": "超越は抽象的な概念で、物のように置くことはできず、誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52812, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超越して", "is_correct": true, "explanation": "国境をこえて活躍するという意味で合う。"}, {"text": "掃除して", "is_correct": false, "explanation": "形は合うが、国境を掃除して活躍では意味が合わない。"}, {"text": "購入して", "is_correct": false, "explanation": "形は合うが、国境を購入して活躍では意味が合わない。"}, {"text": "提出して", "is_correct": false, "explanation": "形は合うが、国境を提出して活躍では意味が合わない。"}], "explanations": {"超越して": "国境をこえて活躍するという意味で合う。", "掃除して": "形は合うが、国境を掃除して活躍では意味が合わない。", "購入して": "形は合うが、国境を購入して活躍では意味が合わない。", "提出して": "形は合うが、国境を提出して活躍では意味が合わない。"}, "sentence_index": 6, "correct_answer": "超越して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅まで超越で五分かかる。", "explanation": "超越は移動手段や距離を表す語ではなく、誤用している。"}, {"text": "母は昼ご飯に超越を作ってくれた。", "explanation": "超越は抽象概念で、料理のように作れる物ではなく誤用している。"}, {"text": "超越は電車に乗って学校へ行った。", "explanation": "超越は人ではなく、主語として動作の主体にはならず誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52812, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の努力は想像に超越している。", "corrected_sentence": "彼女の努力は想像を超越している。", "error_description": "超越するの対象を示す助詞は「を」で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
