INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52814, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二酸化炭素の排出を減らしたり、大気中の炭素を取り除いたりすること。", "primary_collocate": null, "pronunciation": "だったん", "ipa": "dattaɴ", "syllable_count": 4, "sentences": [{"text": "脱炭は世界の大きな課題だ。", "target_word": "脱炭", "complexity_tier": "T3", "furigana": "だったんはせかいのおおきなかだいだ。", "sentence_source": "generated"}, {"text": "会社は脱炭を進めている。", "target_word": "脱炭", "complexity_tier": "T3", "furigana": "かいしゃはだったんをすすめている。", "sentence_source": "generated"}, {"text": "脱炭のため、工場が設備を変えた。", "target_word": "脱炭", "complexity_tier": "T3", "furigana": "だったんのため、こうじょうがせつびをかえた。", "sentence_source": "generated"}, {"text": "政府は脱炭に向けて、新しい計画を発表した。", "target_word": "脱炭", "complexity_tier": "T4", "furigana": "せいふはだったんにむけて、あたらしいけいかくをはっぴょうした。", "sentence_source": "generated"}, {"text": "脱炭を急ぐ国が増えている。", "target_word": "脱炭", "complexity_tier": "T3", "furigana": "だったんをいそぐくにがふえている。", "sentence_source": "generated"}, {"text": "脱炭への取り組みを紹介します。", "target_word": "脱炭", "complexity_tier": "T2", "furigana": "だったんへのとりくみをしょうかいします。", "sentence_source": "generated"}, {"text": "脱炭が進めば、空気はきれいになる。", "target_word": "脱炭", "complexity_tier": "T4", "furigana": "だったんがすすめば、くうきはきれいになる。", "sentence_source": "generated"}, {"text": "森を守ることも脱炭につながる。", "target_word": "脱炭", "complexity_tier": "T3", "furigana": "もりをまもることもだったんにつながる。", "sentence_source": "generated"}, {"text": "脱炭に成功した町を見学した。", "target_word": "脱炭", "complexity_tier": "T3", "furigana": "だったんにせいこうしたまちをけんがくした。", "sentence_source": "generated"}, {"text": "脱炭の技術には、お金がかかる。", "target_word": "脱炭", "complexity_tier": "T3", "furigana": "だったんのぎじゅつには、おかねがかかる。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 二酸化炭素の排出を減らし除去する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71984b75-a7f2-4235-a5ab-be3dacb672ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52814, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱炭", "is_correct": true, "explanation": "二酸化炭素を減らす取り組みが世界の課題という意味で合う。"}, {"text": "昼寝", "is_correct": false, "explanation": "形は合うが、昼寝が世界の大きな課題では意味が合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、散歩が世界の大きな課題では意味が合わない。"}, {"text": "握手", "is_correct": false, "explanation": "形は合うが、握手が世界の大きな課題では意味が合わない。"}], "explanations": {"脱炭": "二酸化炭素を減らす取り組みが世界の課題という意味で合う。", "昼寝": "形は合うが、昼寝が世界の大きな課題では意味が合わない。", "散歩": "形は合うが、散歩が世界の大きな課題では意味が合わない。", "握手": "形は合うが、握手が世界の大きな課題では意味が合わない。"}, "sentence_index": 0, "correct_answer": "脱炭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "脱炭を食べて、昼ご飯にした。", "explanation": "脱炭は排出削減の取り組みで、食べ物ではなく誤用している。"}, {"text": "脱炭は朝七時に駅に着いた。", "explanation": "脱炭は抽象概念で、移動して到着する主体にならず誤用している。"}, {"text": "脱炭の色は赤くて、足が四本ある。", "explanation": "脱炭は取り組みを指し、色や足がある生き物ではなく誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52814, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脱炭", "is_correct": true, "explanation": "炭素を減らす取り組みが進めば空気がきれいになるという意味で合う。"}, {"text": "読書", "is_correct": false, "explanation": "形は合うが、読書が進めば空気がきれいになるでは意味が合わない。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが、料理が進めば空気がきれいになるでは意味が合わない。"}, {"text": "昼食", "is_correct": false, "explanation": "形は合うが、昼食が進めば空気がきれいになるでは意味が合わない。"}], "explanations": {"脱炭": "炭素を減らす取り組みが進めば空気がきれいになるという意味で合う。", "読書": "形は合うが、読書が進めば空気がきれいになるでは意味が合わない。", "料理": "形は合うが、料理が進めば空気がきれいになるでは意味が合わない。", "昼食": "形は合うが、昼食が進めば空気がきれいになるでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "脱炭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は脱炭を履いて公園を走った。", "explanation": "脱炭は取り組みで、履く物ではなく誤用している。"}, {"text": "脱炭は今日、友だちに会いに行った。", "explanation": "脱炭は人ではなく、会いに行く主体にならず誤用している。"}, {"text": "昨日の脱炭はとても甘かった。", "explanation": "脱炭は味のある食べ物ではなく誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fb8e28-a4bf-40ef-ad52-2b99641493b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
