INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52815, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大事なものを支える石のことです。", "primary_collocate": null, "pronunciation": "かなめいし", "ipa": "kanameiɕi", "syllable_count": 5, "sentences": [{"text": "要石を見た。", "target_word": "要石", "complexity_tier": "T1", "furigana": "要石[かなめいし]を見[み]た。", "sentence_source": "generated"}, {"text": "大きな要石があります。", "target_word": "要石", "complexity_tier": "T2", "furigana": "大[おお]きな要石[かなめいし]があります。", "sentence_source": "generated"}, {"text": "要石は門の一番上にあります。", "target_word": "要石", "complexity_tier": "T2", "furigana": "要石[かなめいし]は門[もん]の一番[いちばん]上[うえ]にあります。", "sentence_source": "generated"}, {"text": "職人は橋の真ん中に要石を置いた。", "target_word": "要石", "complexity_tier": "T3", "furigana": "職人[しょくにん]は橋[はし]の真[ま]ん中[なか]に要石[かなめいし]を置[お]いた。", "sentence_source": "generated"}, {"text": "要石を外すと、アーチは崩れてしまう。", "target_word": "要石", "complexity_tier": "T3", "furigana": "要石[かなめいし]を外[はず]すと、アーチは崩[くず]れてしまう。", "sentence_source": "generated"}, {"text": "古い石橋の要石を、写真に撮った。", "target_word": "要石", "complexity_tier": "T3", "furigana": "古[ふる]い石橋[いしばし]の要石[かなめいし]を、写真[しゃしん]に撮[と]った。", "sentence_source": "generated"}, {"text": "要石が、石のアーチ全体を支えている。", "target_word": "要石", "complexity_tier": "T4", "furigana": "要石[かなめいし]が、石[いし]のアーチ全体[ぜんたい]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "石を積むときは、最後に要石を入れて形を固める。", "target_word": "要石", "complexity_tier": "T4", "furigana": "石[いし]を積[つ]むときは、最後[さいご]に要石[かなめいし]を入[い]れて形[かたち]を固[かた]める。", "sentence_source": "generated"}, {"text": "大きな要石のおかげで、門は何百年も立っている。", "target_word": "要石", "complexity_tier": "T4", "furigana": "大[おお]きな要石[かなめいし]のおかげで、門[もん]は何百年[なんびゃくねん]も立[た]っている。", "sentence_source": "generated"}, {"text": "要石が動かなければ、この建物は倒れないはずだ。", "target_word": "要石", "complexity_tier": "T4", "furigana": "要石[かなめいし]が動[うご]かなければ、この建物[たてもの]は倒[たお]れないはずだ。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 大事なものを支える石", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52815, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要石", "is_correct": true, "explanation": "「見る」対象になる石なので意味が合う。"}, {"text": "匂い", "is_correct": false, "explanation": "形は合うが、匂いは「見る」ものではなく意味が合わない。"}, {"text": "音", "is_correct": false, "explanation": "形は合うが、音は「見る」ものではなく意味が合わない。"}, {"text": "味", "is_correct": false, "explanation": "形は合うが、味は「見る」ものではなく意味が合わない。"}], "explanations": {"要石": "「見る」対象になる石なので意味が合う。", "匂い": "形は合うが、匂いは「見る」ものではなく意味が合わない。", "音": "形は合うが、音は「見る」ものではなく意味が合わない。", "味": "形は合うが、味は「見る」ものではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "要石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "要石を飲んで、のどの痛みを治した。", "explanation": "要石は飲む物ではなく、薬のように使う文脈が誤り。"}, {"text": "要石は昨日、急に泣き出した。", "explanation": "石である要石を泣く主体にするのは誤り。"}, {"text": "この橋は要石が不要なので、最初に取り除いた方が安定する。", "explanation": "要石は支えに欠かせない石なので、不要で取り除くと安定するという内容は意味が逆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52815, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要石", "is_correct": true, "explanation": "アーチ全体を支える石という意味に合う。"}, {"text": "傘", "is_correct": false, "explanation": "形は合うが、傘は石のアーチを支えるものではない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、地図は石のアーチを支えるものではない。"}, {"text": "時計", "is_correct": false, "explanation": "形は合うが、時計は石のアーチを支えるものではない。"}], "explanations": {"要石": "アーチ全体を支える石という意味に合う。", "傘": "形は合うが、傘は石のアーチを支えるものではない。", "地図": "形は合うが、地図は石のアーチを支えるものではない。", "時計": "形は合うが、時計は石のアーチを支えるものではない。"}, "sentence_index": 6, "correct_answer": "要石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "要石が歌えば、この建物は倒れないはずだ。", "explanation": "石の要石が歌うという使い方は誤り。"}, {"text": "要石は薄い紙でできているので、建物をしっかり支えている。", "explanation": "要石は固い石であり、紙でできて支えるという内容は誤り。"}, {"text": "要石を毎朝食べれば、この建物は倒れないはずだ。", "explanation": "要石は食べるものではなく、食べる対象としての使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
