INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52816, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「チームの要石」と名詞をつなぐ「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「チームを要石です」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「チームから要石です」は文として成り立たない。"}, {"text": "まで", "is_correct": false, "explanation": "「チームまで要石です」は文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「チームの要石」と名詞をつなぐ「の」が入る。", "を": "「チームを要石です」は文として成り立たない。", "から": "「チームから要石です」は文として成り立たない。", "まで": "「チームまで要石です」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "から": "origin", "まで": "limit"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "枝葉", "is_correct": true, "explanation": "中心の要石に対し、重要でない部分を表す反対の語。"}, {"text": "基盤", "is_correct": false, "explanation": "全体を支える土台で、要石の類義語にあたる。"}, {"text": "中枢", "is_correct": false, "explanation": "中心となる部分で、要石の類義語にあたる。"}, {"text": "大黒柱", "is_correct": false, "explanation": "全体を支える中心で、要石の類義語にあたる。"}], "correct_answer": "枝葉", "explanations": {"枝葉": "中心の要石に対し、重要でない部分を表す反対の語。", "基盤": "全体を支える土台で、要石の類義語にあたる。", "中枢": "中心となる部分で、要石の類義語にあたる。", "大黒柱": "全体を支える中心で、要石の類義語にあたる。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52816, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「要石を失う」と目的語を示す「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「失う」は「に」を取らず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「要石へ失った」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「失う」は起点の「から」を取らず、「要石から失った」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「要石を失う」と目的語を示す「を」が入る。", "に": "「失う」は「に」を取らず、文として成り立たない。", "へ": "「要石へ失った」は文として成り立たない。", "から": "「失う」は起点の「から」を取らず、「要石から失った」は成り立たない。"}, "error_tags": {"に": "wrong_case", "へ": "direction", "から": "origin"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "末端", "is_correct": true, "explanation": "中心の要石に対し、はしの重要度が低い部分を表す反対の語。"}, {"text": "屋台骨", "is_correct": false, "explanation": "全体を支える中心で、要石の類義語にあたる。"}, {"text": "核心", "is_correct": false, "explanation": "中心となる最も重要な部分で、類義語にあたる。"}, {"text": "支柱", "is_correct": false, "explanation": "全体を支えるもので、類義語にあたる。"}], "correct_answer": "末端", "explanations": {"末端": "中心の要石に対し、はしの重要度が低い部分を表す反対の語。", "屋台骨": "全体を支える中心で、要石の類義語にあたる。", "核心": "中心となる最も重要な部分で、類義語にあたる。", "支柱": "全体を支えるもので、類義語にあたる。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52816, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の基礎や中心となって、全体を支える重要なもののたとえ。", "primary_collocate": null, "pronunciation": "かなめいし", "ipa": "kanameiɕi", "syllable_count": 5, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "要石", "complexity_tier": "T6", "furigana": "我々[われわれ]が直面[ちょくめん]する環境的[かんきょうてき]限界[げんかい]を超越[ちょうえつ]するため、CCUSの社会[しゃかい]実装[じっそう]は、産業[さんぎょう]構造[こうぞう]の転換[てんかん]を支[ささ]える要石[かなめいし]として、その存在感[そんざいかん]をさらに増[ま]していくであろう。", "sentence_source": "mined"}, {"text": "彼はチームの要石です。", "target_word": "要石", "complexity_tier": "T2", "furigana": "彼[かれ]はチームの要石[かなめいし]です。", "sentence_source": "generated"}, {"text": "この工場は町の要石でした。", "target_word": "要石", "complexity_tier": "T2", "furigana": "この工場[こうじょう]は町[まち]の要石[かなめいし]でした。", "sentence_source": "generated"}, {"text": "母は、家族を支える要石だと思う。", "target_word": "要石", "complexity_tier": "T3", "furigana": "母[はは]は、家族[かぞく]を支[ささ]える要石[かなめいし]だと思[おも]う。", "sentence_source": "generated"}, {"text": "教育は、国の未来の要石になるだろう。", "target_word": "要石", "complexity_tier": "T3", "furigana": "教育[きょういく]は、国[くに]の未来[みらい]の要石[かなめいし]になるだろう。", "sentence_source": "generated"}, {"text": "彼女が要石となって、計画は進んだ。", "target_word": "要石", "complexity_tier": "T3", "furigana": "彼女[かのじょ]が要石[かなめいし]となって、計画[けいかく]は進[すす]んだ。", "sentence_source": "generated"}, {"text": "信頼こそが、良い人間関係の要石だと言われる。", "target_word": "要石", "complexity_tier": "T4", "furigana": "信頼[しんらい]こそが、良[よ]い人間関係[にんげんかんけい]の要石[かなめいし]だと言[い]われる。", "sentence_source": "generated"}, {"text": "要石を失ったチームは、勝てなくなってしまった。", "target_word": "要石", "complexity_tier": "T4", "furigana": "要石[かなめいし]を失[うしな]ったチームは、勝[か]てなくなってしまった。", "sentence_source": "generated"}, {"text": "この条約は、両国の平和の要石となっている。", "target_word": "要石", "complexity_tier": "T4", "furigana": "この条約[じょうやく]は、両国[りょうこく]の平和[へいわ]の要石[かなめいし]となっている。", "sentence_source": "generated"}, {"text": "地域医療を支える病院は、この町の要石として大切にされてきた。", "target_word": "要石", "complexity_tier": "T5", "furigana": "地域[ちいき]医療[いりょう]を支[ささ]える病院[びょういん]は、この町[まち]の要石[かなめいし]として大切[たいせつ]にされてきた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 全体を支える中心的存在のたとえ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52816, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要石", "is_correct": true, "explanation": "産業構造の転換を支える中心的存在という意味に合う。"}, {"text": "障害", "is_correct": false, "explanation": "形は合うが、転換を『支える』ものという意味が合わない。"}, {"text": "脅威", "is_correct": false, "explanation": "形は合うが、支える存在という意味が合わない。"}, {"text": "副産物", "is_correct": false, "explanation": "形は合うが、全体を支える中心という意味が合わない。"}], "explanations": {"要石": "産業構造の転換を支える中心的存在という意味に合う。", "障害": "形は合うが、転換を『支える』ものという意味が合わない。", "脅威": "形は合うが、支える存在という意味が合わない。", "副産物": "形は合うが、全体を支える中心という意味が合わない。"}, "sentence_index": 0, "correct_answer": "要石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、要石を飲んで元気になる。", "explanation": "要石は飲めるものではなく、飲む対象としての使い方が誤り。"}, {"text": "このアイデアは要石なので、すぐに捨てても問題ない。", "explanation": "要石は重要なもののたとえなので、捨てても問題ないという文脈は意味が逆。"}, {"text": "要石は急に走り出して、バスに乗った。", "explanation": "要石を走ったり乗り物に乗ったりする動作の主語にするのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52816, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要石", "is_correct": true, "explanation": "人間関係の基礎となる最も重要なものという意味に合う。"}, {"text": "弊害", "is_correct": false, "explanation": "形は合うが、信頼が良い関係の悪い面だという意味になり合わない。"}, {"text": "障害", "is_correct": false, "explanation": "形は合うが、信頼が良い関係の妨げという意味になり合わない。"}, {"text": "敵", "is_correct": false, "explanation": "形は合うが、信頼が人間関係の敵という意味になり合わない。"}], "explanations": {"要石": "人間関係の基礎となる最も重要なものという意味に合う。", "弊害": "形は合うが、信頼が良い関係の悪い面だという意味になり合わない。", "障害": "形は合うが、信頼が良い関係の妨げという意味になり合わない。", "敵": "形は合うが、信頼が人間関係の敵という意味になり合わない。"}, "sentence_index": 6, "correct_answer": "要石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この病院は町の要石で、いつ閉まっても誰も困らない。", "explanation": "要石は欠かせない中心のたとえなので、いつ閉まっても困らないという内容は矛盾する。"}, {"text": "要石を三つ買って、昼ご飯にした。", "explanation": "要石は食べ物ではなく、食事にする対象としての使い方が誤り。"}, {"text": "要石の天気は、明日は雨になるそうだ。", "explanation": "要石は天気を表す語ではなく、「要石の天気」という使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52816, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この制度は社会の要石をなっている。", "corrected_sentence": "この制度は社会の要石になっている。", "error_description": "「なる」には「を」ではなく「に」を使うので、「要石をなっている」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52816, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はチームの要石だったので、彼が抜けてもチームは何も変わらなかった。", "corrected_sentence": "彼はチームの要石だったので、彼が抜けるとチームは弱くなった。", "error_description": "要石は全体を支える中心のたとえなので、抜ければ全体が弱くなる。「何も変わらなかった」は意味が矛盾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
