INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52817, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「買う」の対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「棚に買う」では「買う」の対象を示せず、非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「棚へ買う」は方向の意味にならず、非文になる。"}, {"text": "と", "is_correct": false, "explanation": "「棚と買う」では買う対象が示せず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「買う」の対象を示す。", "に": "「棚に買う」では「買う」の対象を示せず、非文になる。", "へ": "「棚へ買う」は方向の意味にならず、非文になる。", "と": "「棚と買う」では買う対象が示せず、意味が通らない。"}, "error_tags": {"に": "target_dative", "へ": "direction", "と": "comitative"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52817, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あらかじめ作ってあること。", "primary_collocate": null, "pronunciation": "きせい", "ipa": "kiseː", "syllable_count": 3, "sentences": [{"text": "これは既製の家具だ。", "target_word": "既製", "complexity_tier": "T1", "furigana": "これは既製[きせい]の家具[かぐ]だ。", "sentence_source": "generated"}, {"text": "既製の服は安い。", "target_word": "既製", "complexity_tier": "T1", "furigana": "既製[きせい]の服[ふく]は安[やす]い。", "sentence_source": "generated"}, {"text": "既製のくつを買った。", "target_word": "既製", "complexity_tier": "T1", "furigana": "既製[きせい]のくつを買[か]った。", "sentence_source": "generated"}, {"text": "既製の服より、注文して作る服の方が高い。", "target_word": "既製", "complexity_tier": "T2", "furigana": "既製[きせい]の服[ふく]より、注文[ちゅうもん]して作[つく]る服[ふく]の方[ほう]が高[たか]い。", "sentence_source": "generated"}, {"text": "既製のシャツは店ですぐ買える。", "target_word": "既製", "complexity_tier": "T2", "furigana": "既製[きせい]のシャツは店[みせ]ですぐ買[か]える。", "sentence_source": "generated"}, {"text": "私のかばんは既製のものです。", "target_word": "既製", "complexity_tier": "T2", "furigana": "私[わたし]のかばんは既製[きせい]のものです。", "sentence_source": "generated"}, {"text": "既製の箱に好きな絵をかいた。", "target_word": "既製", "complexity_tier": "T3", "furigana": "既製[きせい]の箱[はこ]に好[す]きな絵[え]をかいた。", "sentence_source": "generated"}, {"text": "既製の棚を買うか、自分で作るか考えている。", "target_word": "既製", "complexity_tier": "T3", "furigana": "既製[きせい]の棚[たな]を買[か]うか、自分[じぶん]で作[つく]るか考[かんが]えている。", "sentence_source": "generated"}, {"text": "子ども用の既製の服が少なくて困っている。", "target_word": "既製", "complexity_tier": "T3", "furigana": "子[こ]ども用[よう]の既製[きせい]の服[ふく]が少[すく]なくて困[こま]っている。", "sentence_source": "generated"}, {"text": "既製のかばんでも、色を変えれば自分だけの物になる。", "target_word": "既製", "complexity_tier": "T4", "furigana": "既製[きせい]のかばんでも、色[いろ]を変[か]えれば自分[じぶん]だけの物[もの]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "既製品", "label": "派生"}, {"form": "既製服", "label": "派生"}, {"form": "既製靴", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 前もって作ってあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52817, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "既製", "is_correct": true, "explanation": "見出し語そのもの（きせい）。"}, {"text": "季節", "is_correct": false, "explanation": "きせつ。最後の「い」が「つ」に変わる別の語。"}, {"text": "軌跡", "is_correct": false, "explanation": "きせき。最後の「い」が「き」に変わる別の語。"}, {"text": "汽船", "is_correct": false, "explanation": "きせん。最後の「い」が「ん」に変わる別の語。"}], "explanations": {"既製": "見出し語そのもの（きせい）。", "季節": "きせつ。最後の「い」が「つ」に変わる別の語。", "軌跡": "きせき。最後の「い」が「き」に変わる別の語。", "汽船": "きせん。最後の「い」が「ん」に変わる別の語。"}, "sentence_index": null, "correct_answer": "既製"}, "level_3": {"options": [{"text": "既製", "is_correct": true, "explanation": "あらかじめ作られた家具の意味で、文意に合う。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが、病気の家具という意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気の家具という意味が合わない。"}, {"text": "試験", "is_correct": false, "explanation": "形は合うが、試験の家具という意味が合わない。"}], "explanations": {"既製": "あらかじめ作られた家具の意味で、文意に合う。", "病気": "形は合うが、病気の家具という意味が合わない。", "天気": "形は合うが、天気の家具という意味が合わない。", "試験": "形は合うが、試験の家具という意味が合わない。"}, "sentence_index": 0, "correct_answer": "既製"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の母が毎日手で編んだ既製のマフラーを巻いている。", "explanation": "手で編んだ品は「既製」ではない。既製は店で売られる出来合いの品。"}, {"text": "今日は既製がいい天気ですね。", "explanation": "「既製」は天気の程度を表す語ではなく、天気の話には使えない。"}, {"text": "既製を食べすぎて、お腹が痛い。", "explanation": "「既製」は食べ物の名前ではなく、食べる対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52817, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "既製", "is_correct": true, "explanation": "見出し語そのもの（きせい）。"}, {"text": "期待", "is_correct": false, "explanation": "きたい。「せ」が「た」に変わる別の語。"}, {"text": "機会", "is_correct": false, "explanation": "きかい。「せ」が「か」に変わる別の語。"}, {"text": "犠牲", "is_correct": false, "explanation": "ぎせい。「き」が「ぎ」に変わる別の語。"}, {"text": "危害", "is_correct": false, "explanation": "きがい。「せ」が「が」に変わる別の語。"}], "explanations": {"既製": "見出し語そのもの（きせい）。", "期待": "きたい。「せ」が「た」に変わる別の語。", "機会": "きかい。「せ」が「か」に変わる別の語。", "犠牲": "ぎせい。「き」が「ぎ」に変わる別の語。", "危害": "きがい。「せ」が「が」に変わる別の語。"}, "sentence_index": null, "correct_answer": "既製"}, "level_3": {"options": [{"text": "既製", "is_correct": true, "explanation": "あらかじめ作られた箱に絵をかく、という文意に合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、約束の箱という意味が合わない。"}, {"text": "悲しみ", "is_correct": false, "explanation": "形は合うが、悲しみの箱という意味が合わない。"}, {"text": "試合", "is_correct": false, "explanation": "形は合うが、試合の箱という意味が合わない。"}], "explanations": {"既製": "あらかじめ作られた箱に絵をかく、という文意に合う。", "約束": "形は合うが、約束の箱という意味が合わない。", "悲しみ": "形は合うが、悲しみの箱という意味が合わない。", "試合": "形は合うが、試合の箱という意味が合わない。"}, "sentence_index": 6, "correct_answer": "既製"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "注文を受けてから一つずつ作る既製の靴は、半年待たないと届かない。", "explanation": "注文を受けてから作る品は「既製」ではなく、意味が矛盾する。"}, {"text": "彼は既製の人で、いつもみんなに優しい。", "explanation": "「既製」は人の性格を表す語ではなく、人の説明には使えない。"}, {"text": "窓の外で既製が降っている。", "explanation": "「既製」は気象を表す語ではなく、「降る」の主語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52817, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "既製の家具を、私の部屋に合わせて一から作ってもらった。", "corrected_sentence": "注文の家具を、私の部屋に合わせて一から作ってもらった。", "error_description": "一から作ってもらう家具は「注文」であり、「既製」とは意味が矛盾する。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52817, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "既製の机を買ったので、受け取るのに三か月も待った。", "corrected_sentence": "特注の机を買ったので、受け取るのに三か月も待った。", "error_description": "既製品はすぐ手に入るので、三か月待つのは特注品の場合。「既製」は意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
