INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52818, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あらかじめ作ってあること。また、その品物。", "primary_collocate": null, "pronunciation": "きせい", "ipa": "kiseː", "syllable_count": 3, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "既製", "complexity_tier": "T6", "furigana": "既製品[きせいひん]への安易[あんい]な依存[いぞん]を排[はい]し、自[みずか]らの手[て]でカスタマイズを通[つう]じて素材[そざい]と対話[たいわ]する行為[こうい]は、DIYファッションの本質的[ほんしつてき]な愉楽[ゆらく]であり、自己[じこ]効力感[こうりょくかん]の再確認[さいかくにん]でもある。", "sentence_source": "mined"}, {"text": "既製の服を買って、少し直した。", "target_word": "既製", "complexity_tier": "T2", "furigana": "既製[きせい]の服[ふく]を買[か]って、少[すこ]し直[なお]した。", "sentence_source": "generated"}, {"text": "既製と注文では値段がちがう。", "target_word": "既製", "complexity_tier": "T2", "furigana": "既製[きせい]と注文[ちゅうもん]では値段[ねだん]がちがう。", "sentence_source": "generated"}, {"text": "このスーツは既製のものです。", "target_word": "既製", "complexity_tier": "T2", "furigana": "このスーツは既製[きせい]のものです。", "sentence_source": "generated"}, {"text": "既製は早く手に入るのが良い点だ。", "target_word": "既製", "complexity_tier": "T3", "furigana": "既製[きせい]は早[はや]く手[て]に入[はい]るのが良[よ]い点[てん]だ。", "sentence_source": "generated"}, {"text": "既製の靴が足に合わない人もいる。", "target_word": "既製", "complexity_tier": "T3", "furigana": "既製[きせい]の靴[くつ]が足[あし]に合[あ]わない人[ひと]もいる。", "sentence_source": "generated"}, {"text": "店で既製を選ぶか、注文するか迷っている。", "target_word": "既製", "complexity_tier": "T4", "furigana": "店[みせ]で既製[きせい]を選[えら]ぶか、注文[ちゅうもん]するか迷[まよ]っている。", "sentence_source": "generated"}, {"text": "既製のカーテンは大きさが決まっている。", "target_word": "既製", "complexity_tier": "T3", "furigana": "既製[きせい]のカーテンは大[おお]きさが決[き]まっている。", "sentence_source": "generated"}, {"text": "私は既製より注文の服が好きだ。", "target_word": "既製", "complexity_tier": "T2", "furigana": "私[わたし]は既製[きせい]より注文[ちゅうもん]の服[ふく]が好[す]きだ。", "sentence_source": "generated"}, {"text": "既製であっても、工夫すれば自分らしくなる。", "target_word": "既製", "complexity_tier": "T4", "furigana": "既製[きせい]であっても、工夫[くふう]すれば自分[じぶん]らしくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "既製品", "label": "派生"}, {"form": "既製服", "label": "派生"}, {"form": "既製靴", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | あらかじめ作られた品物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52818, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "既製", "is_correct": true, "explanation": "見出し語そのもの（きせい）。"}, {"text": "季節", "is_correct": false, "explanation": "きせつ。最後の「い」が「つ」に変わる別の語。"}, {"text": "軌跡", "is_correct": false, "explanation": "きせき。最後の「い」が「き」に変わる別の語。"}, {"text": "汽船", "is_correct": false, "explanation": "きせん。最後の「い」が「ん」に変わる別の語。"}], "explanations": {"既製": "見出し語そのもの（きせい）。", "季節": "きせつ。最後の「い」が「つ」に変わる別の語。", "軌跡": "きせき。最後の「い」が「き」に変わる別の語。", "汽船": "きせん。最後の「い」が「ん」に変わる別の語。"}, "sentence_index": null, "correct_answer": "既製"}, "level_3": {"options": [{"text": "既製", "is_correct": true, "explanation": "「既製品」で、あらかじめ作られた品物の意味。文脈に合う。"}, {"text": "医薬", "is_correct": false, "explanation": "形は合うが、カスタマイズや素材との対話とは意味が合わない。"}, {"text": "贈答", "is_correct": false, "explanation": "形は合うが、カスタマイズや素材との対話とは意味が合わない。"}, {"text": "食料", "is_correct": false, "explanation": "形は合うが、カスタマイズや素材との対話とは意味が合わない。"}], "explanations": {"既製": "「既製品」で、あらかじめ作られた品物の意味。文脈に合う。", "医薬": "形は合うが、カスタマイズや素材との対話とは意味が合わない。", "贈答": "形は合うが、カスタマイズや素材との対話とは意味が合わない。", "食料": "形は合うが、カスタマイズや素材との対話とは意味が合わない。"}, "sentence_index": 0, "correct_answer": "既製"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母が私のために一針ずつ縫ってくれた既製のセーターを着ている。", "explanation": "手作りの品は「既製」ではない。既製は店で売られるあらかじめ作られた品。"}, {"text": "今日の既製の天気は晴れのち曇りです。", "explanation": "「既製」は天気を表す語ではなく、天気の修飾には使えない。"}, {"text": "彼は既製の約束を忘れて遅刻した。", "explanation": "「既製」は約束を修飾する語ではなく、約束には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52818, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "既製", "is_correct": true, "explanation": "見出し語そのもの（きせい）。"}, {"text": "期待", "is_correct": false, "explanation": "きたい。「せ」が「た」に変わる別の語。"}, {"text": "機会", "is_correct": false, "explanation": "きかい。「せ」が「か」に変わる別の語。"}, {"text": "犠牲", "is_correct": false, "explanation": "ぎせい。「き」が「ぎ」に変わる別の語。"}, {"text": "危害", "is_correct": false, "explanation": "きがい。「せ」が「が」に変わる別の語。"}], "explanations": {"既製": "見出し語そのもの（きせい）。", "期待": "きたい。「せ」が「た」に変わる別の語。", "機会": "きかい。「せ」が「か」に変わる別の語。", "犠牲": "ぎせい。「き」が「ぎ」に変わる別の語。", "危害": "きがい。「せ」が「が」に変わる別の語。"}, "sentence_index": null, "correct_answer": "既製"}, "level_3": {"options": [{"text": "既製", "is_correct": true, "explanation": "注文と対になり、店で選べる出来合いの品を指す。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気を店で選ぶという意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節を店で選び注文するという意味が合わない。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが、病気を店で選び注文するという意味が合わない。"}], "explanations": {"既製": "注文と対になり、店で選べる出来合いの品を指す。", "天気": "形は合うが、天気を店で選ぶという意味が合わない。", "季節": "形は合うが、季節を店で選び注文するという意味が合わない。", "病気": "形は合うが、病気を店で選び注文するという意味が合わない。"}, "sentence_index": 6, "correct_answer": "既製"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その店は注文を受けてから作る既製の服が自慢だ。", "explanation": "注文を受けてから作る品は「既製」ではなく、意味が矛盾する。"}, {"text": "既製を飲んで、少し元気になった。", "explanation": "「既製」は飲み物や薬の名前ではなく、飲む対象にならない。"}, {"text": "彼女は既製に走って、バスに間に合った。", "explanation": "「既製」は場所や道を表す語ではなく、走る先にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors