INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52818, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の体に合わせて作ってもらった既製のスーツを着た。", "corrected_sentence": "私の体に合わせて作ってもらった注文のスーツを着た。", "error_description": "体に合わせて作らせた品は「注文」であり、「既製」では意味が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52818, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は既製の手紙を書いて友達に送った。", "corrected_sentence": "彼は心のこもった手紙を書いて友達に送った。", "error_description": "自分で書く手紙を「既製」とは言わない。「既製」は書く手紙の修飾には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
