INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52819, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「カスタマイズすると」で「〜したら」という条件を表す。"}, {"text": "を", "is_correct": false, "explanation": "「カスタマイズするを、」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「カスタマイズするへ、」は文法的に成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「カスタマイズするで、」は文法的に成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「カスタマイズすると」で「〜したら」という条件を表す。", "を": "「カスタマイズするを、」は文法的に成り立たない。", "へ": "「カスタマイズするへ、」は文法的に成り立たない。", "で": "「カスタマイズするで、」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52819, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の好きなように変えること。", "primary_collocate": null, "pronunciation": "かすたまいず", "ipa": "kasɯtamaizɯ", "syllable_count": 6, "sentences": [{"text": "部屋をカスタマイズした。", "target_word": "カスタマイズ", "complexity_tier": "T2", "furigana": "部屋[へや]をカスタマイズした。", "sentence_source": "generated"}, {"text": "カスタマイズは楽しい。", "target_word": "カスタマイズ", "complexity_tier": "T1", "furigana": "カスタマイズは楽[たの]しい。", "sentence_source": "generated"}, {"text": "私のパソコンはカスタマイズしてある。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "私[わたし]のパソコンはカスタマイズしてある。", "sentence_source": "generated"}, {"text": "スマホの画面をカスタマイズしたい。", "target_word": "カスタマイズ", "complexity_tier": "T2", "furigana": "スマホの画面[がめん]をカスタマイズしたい。", "sentence_source": "generated"}, {"text": "カスタマイズの方法を教えてください。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "カスタマイズの方法[ほうほう]を教[おし]えてください。", "sentence_source": "generated"}, {"text": "好きなようにカスタマイズできる。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "好[す]きなようにカスタマイズできる。", "sentence_source": "generated"}, {"text": "友達がバイクをカスタマイズしている。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "友達[ともだち]がバイクをカスタマイズしている。", "sentence_source": "generated"}, {"text": "カスタマイズすると、自分だけの物になる。", "target_word": "カスタマイズ", "complexity_tier": "T4", "furigana": "カスタマイズすると、自分[じぶん]だけの物[もの]になる。", "sentence_source": "generated"}, {"text": "カスタマイズを楽しむ人が増えている。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "カスタマイズを楽[たの]しむ人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "このサイトでは、色もカスタマイズできる。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "このサイトでは、色[いろ]もカスタマイズできる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カスタマイズする", "label": "活用"}, {"form": "カスタマイズして", "label": "活用"}, {"form": "カスタマイズされた", "label": "活用"}, {"form": "カスタマイズ性", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 好きなように変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52819, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カスタマイズ", "is_correct": true, "explanation": "部屋を自分好みに変える意味で、文に合う。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、部屋は運転するものではなく意味が合わない。"}, {"text": "質問", "is_correct": false, "explanation": "形は合うが、部屋を質問するという意味が合わない。"}, {"text": "反対", "is_correct": false, "explanation": "形は合うが、部屋を反対するという意味が合わない。"}], "explanations": {"カスタマイズ": "部屋を自分好みに変える意味で、文に合う。", "運転": "形は合うが、部屋は運転するものではなく意味が合わない。", "質問": "形は合うが、部屋を質問するという意味が合わない。", "反対": "形は合うが、部屋を反対するという意味が合わない。"}, "sentence_index": 0, "correct_answer": "カスタマイズ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の天気はとてもカスタマイズだった。", "explanation": "カスタマイズは好きなように変える行為で、天気の様子を表す語として使えない。"}, {"text": "大きな地震で、家が一瞬でカスタマイズされた。", "explanation": "カスタマイズは好みで変えることで、地震で壊れる意味には使えない。"}, {"text": "毎朝、カスタマイズを飲んでから学校に行く。", "explanation": "カスタマイズは飲み物の名前ではなく、飲む対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52819, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カスタマイズ", "is_correct": true, "explanation": "バイクを自分好みに変える意味で、文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、バイクを散歩するという意味が合わない。"}, {"text": "出席", "is_correct": false, "explanation": "「出席」は「を」をとらず、バイクとも意味が合わない。"}, {"text": "会議", "is_correct": false, "explanation": "形は合うが、バイクを会議するという意味が合わない。"}], "explanations": {"カスタマイズ": "バイクを自分好みに変える意味で、文に合う。", "散歩": "形は合うが、バイクを散歩するという意味が合わない。", "出席": "「出席」は「を」をとらず、バイクとも意味が合わない。", "会議": "形は合うが、バイクを会議するという意味が合わない。"}, "sentence_index": 6, "correct_answer": "カスタマイズ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日は風邪でカスタマイズを休んだ。", "explanation": "カスタマイズは授業や仕事の名前ではなく、休む対象として使えない。"}, {"text": "駅で友達とカスタマイズして、電車に乗った。", "explanation": "カスタマイズは「会う」意味ではなく、待ち合わせの意味では使えない。"}, {"text": "お風呂で体をカスタマイズして汚れを落とした。", "explanation": "カスタマイズは「洗う」意味ではなく、汚れを落とす意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52819, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机にカスタマイズして使っている。", "corrected_sentence": "机をカスタマイズして使っている。", "error_description": "カスタマイズする対象を示す助詞は「に」ではなく「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
