INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52820, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "既製品を自分の好みや目的に合わせて変更・調整すること。", "primary_collocate": null, "pronunciation": "かすたまいず", "ipa": "kasɯtamaizɯ", "syllable_count": 6, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "カスタマイズ", "complexity_tier": "T6", "furigana": "既製品[きせいひん]への安易[あんい]な依存[いぞん]を排[はい]し、自[みずか]らの手[て]でカスタマイズを通[つう]じて素材[そざい]と対話[たいわ]する行為[こうい]は、DIYファッションの本質的[ほんしつてき]な愉楽[ゆらく]であり、自己[じこ]効力感[こうりょくかん]の再確認[さいかくにん]でもある。", "sentence_source": "mined"}, {"text": "車をカスタマイズして楽しむ。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "車[くるま]をカスタマイズして楽[たの]しむ。", "sentence_source": "generated"}, {"text": "カスタマイズは自分らしさを出す方法だ。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "カスタマイズは自分[じぶん]らしさを出[だ]す方法[ほうほう]だ。", "sentence_source": "generated"}, {"text": "このアプリは画面をカスタマイズできる。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "このアプリは画面[がめん]をカスタマイズできる。", "sentence_source": "generated"}, {"text": "既製のかばんにカスタマイズを加えた。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "既製[きせい]のかばんにカスタマイズを加[くわ]えた。", "sentence_source": "generated"}, {"text": "好みのカスタマイズができる店だ。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "好[この]みのカスタマイズができる店[みせ]だ。", "sentence_source": "generated"}, {"text": "靴のカスタマイズを頼んだ。", "target_word": "カスタマイズ", "complexity_tier": "T2", "furigana": "靴[くつ]のカスタマイズを頼[たの]んだ。", "sentence_source": "generated"}, {"text": "色や形をカスタマイズするのが好きだ。", "target_word": "カスタマイズ", "complexity_tier": "T3", "furigana": "色[いろ]や形[かたち]をカスタマイズするのが好[す]きだ。", "sentence_source": "generated"}, {"text": "カスタマイズされた服は一つしかない。", "target_word": "カスタマイズ", "complexity_tier": "T4", "furigana": "カスタマイズされた服[ふく]は一[ひと]つしかない。", "sentence_source": "generated"}, {"text": "自分でカスタマイズすれば、安くすむ。", "target_word": "カスタマイズ", "complexity_tier": "T4", "furigana": "自分[じぶん]でカスタマイズすれば、安[やす]くすむ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カスタマイズする", "label": "活用"}, {"form": "カスタマイズして", "label": "活用"}, {"form": "カスタマイズされた", "label": "活用"}, {"form": "カスタマイズ性", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 既製品を好みに合わせ変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 愉楽 (Zipf 1.65)']::text[], '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52820, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カスタマイズ", "is_correct": true, "explanation": "素材と対話しながら既製品を自分流に変える行為で、文意に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが、旅行を通じて素材と対話するという意味が合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "形は合うが、掃除を通じて素材と対話するという意味が合わない。"}, {"text": "貯金", "is_correct": false, "explanation": "形は合うが、貯金を通じて素材と対話するという意味が合わない。"}], "explanations": {"カスタマイズ": "素材と対話しながら既製品を自分流に変える行為で、文意に合う。", "旅行": "形は合うが、旅行を通じて素材と対話するという意味が合わない。", "掃除": "形は合うが、掃除を通じて素材と対話するという意味が合わない。", "貯金": "形は合うが、貯金を通じて素材と対話するという意味が合わない。"}, "sentence_index": 0, "correct_answer": "カスタマイズ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、近所の公園をカスタマイズして、健康のために歩いている。", "explanation": "「カスタマイズ」は好みに合わせて変えることで、歩くことではない。"}, {"text": "彼はカスタマイズが痛いので、病院に行った。", "explanation": "「カスタマイズ」は体の部位や症状を表す語ではない。"}, {"text": "この商品は工場で全部同じ形にカスタマイズされ、一つも違いがない。", "explanation": "「カスタマイズ」は一人ひとりの好みに合わせることで、全部同じにすることではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52820, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カスタマイズ", "is_correct": true, "explanation": "靴を自分の好みに変えてもらうことを頼む、という文意に合う。"}, {"text": "入学", "is_correct": false, "explanation": "形は合うが、靴の入学を頼むという意味が合わない。"}, {"text": "勝利", "is_correct": false, "explanation": "形は合うが、靴の勝利を頼むという意味が合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、靴の結婚を頼むという意味が合わない。"}], "explanations": {"カスタマイズ": "靴を自分の好みに変えてもらうことを頼む、という文意に合う。", "入学": "形は合うが、靴の入学を頼むという意味が合わない。", "勝利": "形は合うが、靴の勝利を頼むという意味が合わない。", "結婚": "形は合うが、靴の結婚を頼むという意味が合わない。"}, "sentence_index": 6, "correct_answer": "カスタマイズ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、友達とカスタマイズを食べに行った。", "explanation": "「カスタマイズ」は食べ物の名前ではなく、食べる対象にならない。"}, {"text": "彼は毎日、一人でカスタマイズして、遠くの町まで歩いた。", "explanation": "「カスタマイズ」は移動や散歩を表す語ではない。"}, {"text": "この書類は何も変えずにそのまま提出するので、カスタマイズして出した。", "explanation": "何も変えないことと「カスタマイズ」は意味が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
