INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52820, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い服を自分でカスタマイズされて、新しく見えるようになった。", "corrected_sentence": "古い服を自分でカスタマイズして、新しく見えるようになった。", "error_description": "自分で行う動作なので、受身の「カスタマイズされて」は誤り。「カスタマイズして」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52821, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "て", "options": [{"text": "て", "is_correct": true, "explanation": "「排して、」で動作をつなぐて形になる。"}, {"text": "で", "is_correct": false, "explanation": "「排しで、」は文法的に成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「排しが、」は文法的に成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「排しを、」は文法的に成り立たない。"}], "correct_answer": "て", "explanations": {"て": "「排して、」で動作をつなぐて形になる。", "で": "「排しで、」は文法的に成り立たない。", "が": "「排しが、」は文法的に成り立たない。", "を": "「排しを、」は文法的に成り立たない。"}, "error_tags": {"で": "form_confusion", "が": "subject_marker", "を": "object_marker"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取り入れる", "is_correct": true, "explanation": "古い考えを取り除くの反対で、中に入れることを表す。"}, {"text": "取り除く", "is_correct": false, "explanation": "排するの類義語で、反対ではない。"}, {"text": "捨てる", "is_correct": false, "explanation": "いらない物を手放す意味で、類義語に近く反対ではない。"}, {"text": "除く", "is_correct": false, "explanation": "排するに近い類義語で、反対ではない。"}], "correct_answer": "取り入れる", "explanations": {"取り入れる": "古い考えを取り除くの反対で、中に入れることを表す。", "取り除く": "排するの類義語で、反対ではない。", "捨てる": "いらない物を手放す意味で、類義語に近く反対ではない。", "除く": "排するに近い類義語で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52821, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "排する対象「争い」を示す助詞。"}, {"text": "が", "is_correct": false, "explanation": "「争いが排して」は他動詞の対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「争いへ排して」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「争いの排して」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "排する対象「争い」を示す助詞。", "が": "「争いが排して」は他動詞の対象として成り立たない。", "へ": "「争いへ排して」は文法的に成り立たない。", "の": "「争いの排して」は文法的に成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "の": "possessive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加える", "is_correct": true, "explanation": "余分な言葉を取り除くの反対で、付け足すことを表す。"}, {"text": "省く", "is_correct": false, "explanation": "取り除く意味の類義語で、反対ではない。"}, {"text": "削る", "is_correct": false, "explanation": "取り除く意味に近く、反対ではない。"}, {"text": "除く", "is_correct": false, "explanation": "排するに近い類義語で、反対ではない。"}], "correct_answer": "加える", "explanations": {"加える": "余分な言葉を取り除くの反対で、付け足すことを表す。", "省く": "取り除く意味の類義語で、反対ではない。", "削る": "取り除く意味に近く、反対ではない。", "除く": "排するに近い類義語で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52821, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いらないものを、とりのぞくこと。", "primary_collocate": null, "pronunciation": "はいする", "ipa": "haisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "いらない物を排する。", "target_word": "排する", "complexity_tier": "T2", "furigana": "いらない物[もの]を排[はい]する。", "sentence_source": "generated"}, {"text": "無駄を排した。", "target_word": "排した", "complexity_tier": "T1", "furigana": "無駄[むだ]を排[はい]した。", "sentence_source": "generated"}, {"text": "余計な飾りを排して、部屋をすっきりさせた。", "target_word": "排して", "complexity_tier": "T3", "furigana": "余計[よけい]な飾[かざ]りを排[はい]して、部屋[へや]をすっきりさせた。", "sentence_source": "generated"}, {"text": "古い考えを排したい。", "target_word": "排し", "complexity_tier": "T2", "furigana": "古[ふる]い考[かんが]えを排[はい]したい。", "sentence_source": "generated"}, {"text": "悪い物は排すべきだ。", "target_word": "排す", "complexity_tier": "T3", "furigana": "悪[わる]い物[もの]は排[はい]すべきだ。", "sentence_source": "generated"}, {"text": "彼は自分の悪い習慣を排した。", "target_word": "排した", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の悪[わる]い習慣[しゅうかん]を排[はい]した。", "sentence_source": "generated"}, {"text": "部屋の不要な物を排すると、広く見える。", "target_word": "排する", "complexity_tier": "T4", "furigana": "部屋[へや]の不要[ふよう]な物[もの]を排[はい]すると、広[ひろ]く見[み]える。", "sentence_source": "generated"}, {"text": "争いを排して、話し合いで決めた。", "target_word": "排して", "complexity_tier": "T3", "furigana": "争[あらそ]いを排[はい]して、話[はな]し合[あ]いで決[き]めた。", "sentence_source": "generated"}, {"text": "ミスを排するために、二回確認する。", "target_word": "排する", "complexity_tier": "T4", "furigana": "ミスを排[はい]するために、二回[にかい]確認[かくにん]する。", "sentence_source": "generated"}, {"text": "余分な言葉は排した方がいい。", "target_word": "排した", "complexity_tier": "T4", "furigana": "余分[よぶん]な言葉[ことば]は排[はい]した方[ほう]がいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排し", "label": "活用"}, {"form": "排した", "label": "活用"}, {"form": "排せば", "label": "活用"}, {"form": "排される", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | いらない物を取り除く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52821, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排する", "is_correct": true, "explanation": "見出し語。「はいする」。"}, {"text": "愛する", "is_correct": false, "explanation": "「あいする」で、最初の拍だけが違う。"}, {"text": "介する", "is_correct": false, "explanation": "「かいする」で、最初の拍だけが違う。"}, {"text": "害する", "is_correct": false, "explanation": "「がいする」で、最初の拍だけが違う。"}, {"text": "対する", "is_correct": false, "explanation": "「たいする」で、最初の拍だけが違う。"}], "explanations": {"排する": "見出し語。「はいする」。", "愛する": "「あいする」で、最初の拍だけが違う。", "介する": "「かいする」で、最初の拍だけが違う。", "害する": "「がいする」で、最初の拍だけが違う。", "対する": "「たいする」で、最初の拍だけが違う。"}, "sentence_index": null, "correct_answer": "排する"}, "level_3": {"options": [{"text": "排する", "is_correct": true, "explanation": "いらない物を取り除く意味で、文に合う。"}, {"text": "歌う", "is_correct": false, "explanation": "形は合うが、いらない物を歌うという意味が合わない。"}, {"text": "育てる", "is_correct": false, "explanation": "形は合うが、いらない物を育てるという意味が合わない。"}, {"text": "祝う", "is_correct": false, "explanation": "形は合うが、いらない物を祝うという意味が合わない。"}], "explanations": {"排する": "いらない物を取り除く意味で、文に合う。", "歌う": "形は合うが、いらない物を歌うという意味が合わない。", "育てる": "形は合うが、いらない物を育てるという意味が合わない。", "祝う": "形は合うが、いらない物を祝うという意味が合わない。"}, "sentence_index": 0, "correct_answer": "排する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに、パンを排して食べた。", "explanation": "排するは取り除く意味で、食べるために用意する意味には使えない。"}, {"text": "弟に宿題を排してあげた。", "explanation": "排するは教える意味ではなく、宿題を教える意味では使えない。"}, {"text": "毎日、庭の花を排して大切に育てている。", "explanation": "排するは取り除く意味なので、花を大切に育てる文脈と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52821, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "排する", "is_correct": true, "explanation": "見出し語。「はいする」。"}, {"text": "題する", "is_correct": false, "explanation": "「だいする」で、最初の拍だけが違う。"}, {"text": "際する", "is_correct": false, "explanation": "「さいする」で、最初の拍だけが違う。"}, {"text": "解する", "is_correct": false, "explanation": "「かいする」で、最初の拍だけが違う。"}], "explanations": {"排する": "見出し語。「はいする」。", "題する": "「だいする」で、最初の拍だけが違う。", "際する": "「さいする」で、最初の拍だけが違う。", "解する": "「かいする」で、最初の拍だけが違う。"}, "sentence_index": null, "correct_answer": "排する"}, "level_3": {"options": [{"text": "排する", "is_correct": true, "explanation": "不要な物を取り除くと広く見える、という意味に合う。"}, {"text": "増やす", "is_correct": false, "explanation": "形は合うが、物を増やすと狭く見えるので意味が合わない。"}, {"text": "集める", "is_correct": false, "explanation": "形は合うが、物を集めると広く見えず意味が合わない。"}, {"text": "買う", "is_correct": false, "explanation": "形は合うが、物を買っても広く見えず意味が合わない。"}], "explanations": {"排する": "不要な物を取り除くと広く見える、という意味に合う。", "増やす": "形は合うが、物を増やすと狭く見えるので意味が合わない。", "集める": "形は合うが、物を集めると広く見えず意味が合わない。", "買う": "形は合うが、物を買っても広く見えず意味が合わない。"}, "sentence_index": 6, "correct_answer": "排する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "道が混んでいたので、バスを排して学校へ行った。", "explanation": "排するは取り除く意味で、乗り物に乗る意味には使えない。"}, {"text": "祖母の誕生日に花を排した。", "explanation": "排するは取り除く意味で、プレゼントを贈る意味には使えない。"}, {"text": "寒いので、ジャケットを排して外に出た。", "explanation": "排するは「着る」意味ではなく、上着を着る意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52821, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "無駄な説明に排して、話を短くした。", "corrected_sentence": "無駄な説明を排して、話を短くした。", "error_description": "排する対象を示す助詞は「に」ではなく「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "排した", "is_correct": true, "explanation": "過去を表すた形で、文末に合う。"}, {"text": "排さ", "is_correct": false, "explanation": "未然形で、このままでは文が終われない。"}, {"text": "排し", "is_correct": false, "explanation": "連用形で、このままでは文を終えられない。"}, {"text": "排せば", "is_correct": false, "explanation": "仮定形で、後に続く文がなく文が終われない。"}], "correct_form": "排した", "base_form": "排する", "form_label": "た形", "sentence_index": 1, "explanations": {"排した": "過去を表すた形で、文末に合う。", "排さ": "未然形で、このままでは文が終われない。", "排し": "連用形で、このままでは文を終えられない。", "排せば": "仮定形で、後に続く文がなく文が終われない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
