INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52822, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "排除する。拒否して取り除くこと。", "primary_collocate": null, "pronunciation": "はいする", "ipa": "haisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "排し", "complexity_tier": "T6", "furigana": "既製品[きせいひん]への安易[あんい]な依存[いぞん]を排[はい]し、自[みずか]らの手[て]でカスタマイズを通[つう]じて素材[そざい]と対話[たいわ]する行為[こうい]は、DIYファッションの本質的[ほんしつてき]な愉楽[ゆらく]であり、自己[じこ]効力感[こうりょくかん]の再確認[さいかくにん]でもある。", "sentence_source": "mined"}, {"text": "偏見を排して物事を見る。", "target_word": "排して", "complexity_tier": "T3", "furigana": "偏見[へんけん]を排[はい]して物事[ものごと]を見[み]る。", "sentence_source": "generated"}, {"text": "無駄を排することが大切だ。", "target_word": "排する", "complexity_tier": "T3", "furigana": "無駄[むだ]を排[はい]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "反対意見を排したわけではない。", "target_word": "排した", "complexity_tier": "T4", "furigana": "反対[はんたい]意見[いけん]を排[はい]したわけではない。", "sentence_source": "generated"}, {"text": "彼は感情を排して判断した。", "target_word": "排して", "complexity_tier": "T3", "furigana": "彼[かれ]は感情[かんじょう]を排[はい]して判断[はんだん]した。", "sentence_source": "generated"}, {"text": "危険なものは排する必要がある。", "target_word": "排する", "complexity_tier": "T3", "furigana": "危険[きけん]なものは排[はい]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "不正は完全に排さなければならない。", "target_word": "排さ", "complexity_tier": "T4", "furigana": "不正[ふせい]は完全[かんぜん]に排[はい]さなければならない。", "sentence_source": "generated"}, {"text": "先入観を排せば、真実が見える。", "target_word": "排せ", "complexity_tier": "T4", "furigana": "先入観[せんにゅうかん]を排[はい]せば、真実[しんじつ]が見[み]える。", "sentence_source": "generated"}, {"text": "悪い習慣が排された。", "target_word": "排され", "complexity_tier": "T4", "furigana": "悪[わる]い習慣[しゅうかん]が排[はい]された。", "sentence_source": "generated"}, {"text": "個人の利益を排して、全体のために働く。", "target_word": "排して", "complexity_tier": "T4", "furigana": "個人[こじん]の利益[りえき]を排[はい]して、全体[ぜんたい]のために働[はたら]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排し", "label": "活用"}, {"form": "排した", "label": "活用"}, {"form": "排せば", "label": "活用"}, {"form": "排される", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 拒んで取り除く、排除する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52822, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排する", "is_correct": true, "explanation": "見出し語。「はいする」。"}, {"text": "愛する", "is_correct": false, "explanation": "「あいする」で、最初の拍だけが違う。"}, {"text": "介する", "is_correct": false, "explanation": "「かいする」で、最初の拍だけが違う。"}, {"text": "害する", "is_correct": false, "explanation": "「がいする」で、最初の拍だけが違う。"}, {"text": "対する", "is_correct": false, "explanation": "「たいする」で、最初の拍だけが違う。"}], "explanations": {"排する": "見出し語。「はいする」。", "愛する": "「あいする」で、最初の拍だけが違う。", "介する": "「かいする」で、最初の拍だけが違う。", "害する": "「がいする」で、最初の拍だけが違う。", "対する": "「たいする」で、最初の拍だけが違う。"}, "sentence_index": null, "correct_answer": "排する"}, "level_3": {"options": [{"text": "排し", "is_correct": true, "explanation": "依存を取り除く意味で、後の文脈に合う。"}, {"text": "強め", "is_correct": false, "explanation": "形は合うが、依存を強めては自らの手で、という文脈と意味が合わない。"}, {"text": "深め", "is_correct": false, "explanation": "形は合うが、依存を深めては文脈と意味が合わない。"}, {"text": "広げ", "is_correct": false, "explanation": "形は合うが、依存を広げては文脈と意味が合わない。"}], "explanations": {"排し": "依存を取り除く意味で、後の文脈に合う。", "強め": "形は合うが、依存を強めては自らの手で、という文脈と意味が合わない。", "深め": "形は合うが、依存を深めては文脈と意味が合わない。", "広げ": "形は合うが、依存を広げては文脈と意味が合わない。"}, "sentence_index": 0, "correct_answer": "排し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅で友達を排して、一緒に映画を見た。", "explanation": "排するは拒んで取り除く意味で、友達と会う意味には使えない。"}, {"text": "公園の花を排して、毎朝水をやる。", "explanation": "排するは取り除く意味なので、花を大切に世話する文脈と矛盾する。"}, {"text": "友達に手紙を排した。", "explanation": "排するは拒んで取り除く意味で、手紙を送る意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52822, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "排する", "is_correct": true, "explanation": "見出し語。「はいする」。"}, {"text": "題する", "is_correct": false, "explanation": "「だいする」で、最初の拍だけが違う。"}, {"text": "際する", "is_correct": false, "explanation": "「さいする」で、最初の拍だけが違う。"}, {"text": "解する", "is_correct": false, "explanation": "「かいする」で、最初の拍だけが違う。"}], "explanations": {"排する": "見出し語。「はいする」。", "題する": "「だいする」で、最初の拍だけが違う。", "際する": "「さいする」で、最初の拍だけが違う。", "解する": "「かいする」で、最初の拍だけが違う。"}, "sentence_index": null, "correct_answer": "排する"}, "level_3": {"options": [{"text": "排さ", "is_correct": true, "explanation": "不正を取り除く意味で、「なければならない」に合う。"}, {"text": "増やさ", "is_correct": false, "explanation": "形は合うが、不正を増やすのは意味が合わない。"}, {"text": "守ら", "is_correct": false, "explanation": "形は合うが、不正を守るのは意味が合わない。"}, {"text": "育て", "is_correct": false, "explanation": "形は合うが、不正を育てるのは意味が合わない。"}], "explanations": {"排さ": "不正を取り除く意味で、「なければならない」に合う。", "増やさ": "形は合うが、不正を増やすのは意味が合わない。", "守ら": "形は合うが、不正を守るのは意味が合わない。", "育て": "形は合うが、不正を育てるのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "排さ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "重い荷物を排して、駅まで運んだ。", "explanation": "排するは取り除く意味で、荷物を持つ意味には使えない。"}, {"text": "先生の話を排して、ノートに書いた。", "explanation": "排するは拒んで取り除く意味で、話を聞く意味には使えない。"}, {"text": "私は毎朝、犬を排して公園を歩く。", "explanation": "排するは連れて行く意味ではなく、犬を連れる意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
