INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52823, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「薬の効力」で、薬のききめという所有関係を表す。"}, {"text": "を", "is_correct": false, "explanation": "「薬を効力は」は成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「薬へ効力は」は成立しない。"}, {"text": "まで", "is_correct": false, "explanation": "「薬まで効力は」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「薬の効力」で、薬のききめという所有関係を表す。", "を": "「薬を効力は」は成立しない。", "へ": "「薬へ効力は」は成立しない。", "まで": "「薬まで効力は」は意味が通らない。"}, "error_tags": {"を": "wrong_case", "へ": "direction", "まで": "wrong_case"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無効", "is_correct": true, "explanation": "ききめがないことで、効力の反対にあたる。"}, {"text": "効果", "is_correct": false, "explanation": "効力に近い類義語で、反対の意味ではない。"}, {"text": "薬効", "is_correct": false, "explanation": "薬のききめで、反対の意味ではない。"}, {"text": "副作用", "is_correct": false, "explanation": "薬の望ましくない作用で、ききめの反対とは言えない。"}], "correct_answer": "無効", "explanations": {"無効": "ききめがないことで、効力の反対にあたる。", "効果": "効力に近い類義語で、反対の意味ではない。", "薬効": "薬のききめで、反対の意味ではない。", "副作用": "薬の望ましくない作用で、ききめの反対とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
