INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52823, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ききめの こと。", "primary_collocate": null, "pronunciation": "こうりょく", "ipa": "koːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "この薬は効力が強い。", "target_word": "効力", "complexity_tier": "T1", "furigana": "この薬[くすり]は効力[こうりょく]が強[つよ]い。", "sentence_source": "generated"}, {"text": "薬の効力は三時間です。", "target_word": "効力", "complexity_tier": "T2", "furigana": "薬[くすり]の効力[こうりょく]は三時間[さんじかん]です。", "sentence_source": "generated"}, {"text": "薬の効力が現れるまで待った。", "target_word": "効力", "complexity_tier": "T2", "furigana": "薬[くすり]の効力[こうりょく]が現[あらわ]れるまで待[ま]った。", "sentence_source": "generated"}, {"text": "この薬は、飲むとすぐに効力を発揮します。", "target_word": "効力", "complexity_tier": "T4", "furigana": "この薬[くすり]は、飲[の]むとすぐに効力[こうりょく]を発揮[はっき]します。", "sentence_source": "generated"}, {"text": "効力の強い薬ほど、副作用にも注意が必要だ。", "target_word": "効力", "complexity_tier": "T3", "furigana": "効力[こうりょく]の強[つよ]い薬[くすり]ほど、副作用[ふくさよう]にも注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "効力を試すために、少し使ってみた。", "target_word": "効力", "complexity_tier": "T3", "furigana": "効力[こうりょく]を試[ため]すために、少[すこ]し使[つか]ってみた。", "sentence_source": "generated"}, {"text": "この薬の効力は一週間続きます。", "target_word": "効力", "complexity_tier": "T2", "furigana": "この薬[くすり]の効力[こうりょく]は一週間[いっしゅうかん]続[つづ]きます。", "sentence_source": "generated"}, {"text": "効力のある薬を医者にもらった。", "target_word": "効力", "complexity_tier": "T2", "furigana": "効力[こうりょく]のある薬[くすり]を医者[いしゃ]にもらった。", "sentence_source": "generated"}, {"text": "効力が切れる前に、もう一度飲んでください。", "target_word": "効力", "complexity_tier": "T3", "furigana": "効力[こうりょく]が切[き]れる前[まえ]に、もう一度[いちど]飲[の]んでください。", "sentence_source": "generated"}, {"text": "この薬の効力を、医者が説明してくれた。", "target_word": "効力", "complexity_tier": "T3", "furigana": "この薬[くすり]の効力[こうりょく]を、医者[いしゃ]が説明[せつめい]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "効力感", "label": "派生"}, {"form": "効力発生", "label": "派生"}, {"form": "効力期間", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 薬などのききめのこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0dbfc7-ded3-42fa-8956-25a04f821c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
