INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52824, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「効力が続く」で続くものを主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞で、「効力を続く」は成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「効力に三日間続く」は成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「効力と三日間続く」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「効力が続く」で続くものを主語として示す。", "を": "「続く」は自動詞で、「効力を続く」は成立しない。", "に": "「効力に三日間続く」は成立しない。", "と": "「効力と三日間続く」は意味が通らない。"}, "error_tags": {"を": "wrong_case", "に": "wrong_case", "と": "wrong_case"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無効", "is_correct": true, "explanation": "効力がなくなることで、効力の反対にあたる。"}, {"text": "効果", "is_correct": false, "explanation": "効力に近い類義語で、反対の意味ではない。"}, {"text": "威力", "is_correct": false, "explanation": "強い力を表し、反対の意味ではない。"}, {"text": "薬効", "is_correct": false, "explanation": "薬のききめで、反対の意味ではない。"}], "correct_answer": "無効", "explanations": {"無効": "効力がなくなることで、効力の反対にあたる。", "効果": "効力に近い類義語で、反対の意味ではない。", "威力": "強い力を表し、反対の意味ではない。", "薬効": "薬のききめで、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52824, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「効力が足りなかった」で足りないものを示す。"}, {"text": "を", "is_correct": false, "explanation": "「効力を足りなかった」は成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「効力と足りなかった」は成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「効力へ足りなかった」は成立しない。"}], "correct_answer": "が", "explanations": {"が": "「効力が足りなかった」で足りないものを示す。", "を": "「効力を足りなかった」は成立しない。", "と": "「効力と足りなかった」は成立しない。", "へ": "「効力へ足りなかった」は成立しない。"}, "error_tags": {"を": "wrong_case", "と": "wrong_case", "へ": "wrong_case"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無効", "is_correct": true, "explanation": "ききめがないことで、効力の反対にあたる。"}, {"text": "威力", "is_correct": false, "explanation": "強い力を表し、反対の意味ではない。"}, {"text": "効能", "is_correct": false, "explanation": "ききめのことで効力に近く、反対の意味ではない。"}, {"text": "能力", "is_correct": false, "explanation": "物事をする力で、反対の意味ではない。"}], "correct_answer": "無効", "explanations": {"無効": "ききめがないことで、効力の反対にあたる。", "威力": "強い力を表し、反対の意味ではない。", "効能": "ききめのことで効力に近く、反対の意味ではない。", "能力": "物事をする力で、反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52824, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ききめ。効果を及ぼす力。", "primary_collocate": null, "pronunciation": "こうりょく", "ipa": "koːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "効力", "complexity_tier": "T6", "furigana": "既製品[きせいひん]への安易[あんい]な依存[いぞん]を排[はい]し、自[みずか]らの手[て]でカスタマイズを通[つう]じて素材[そざい]と対話[たいわ]する行為[こうい]は、DIYファッションの本質的[ほんしつてき]な愉楽[ゆらく]であり、自己[じこ]効力感[こうりょくかん]の再確認[さいかくにん]でもある。", "sentence_source": "mined"}, {"text": "この薬は効力が三日間続く。", "target_word": "効力", "complexity_tier": "T2", "furigana": "この薬[くすり]は効力[こうりょく]が三日間[みっかかん]続[つづ]く。", "sentence_source": "generated"}, {"text": "契約書の効力は、署名した日から始まる。", "target_word": "効力", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]の効力[こうりょく]は、署名[しょめい]した日[ひ]から始[はじ]まる。", "sentence_source": "generated"}, {"text": "古い薬は効力を失っていることがある。", "target_word": "効力", "complexity_tier": "T3", "furigana": "古[ふる]い薬[くすり]は効力[こうりょく]を失[うしな]っていることがある。", "sentence_source": "generated"}, {"text": "この法律は来月から効力を持つ。", "target_word": "効力", "complexity_tier": "T2", "furigana": "この法律[ほうりつ]は来月[らいげつ]から効力[こうりょく]を持[も]つ。", "sentence_source": "generated"}, {"text": "薬の効力を高めるために、毎日同じ時間に飲んでください。", "target_word": "効力", "complexity_tier": "T4", "furigana": "薬[くすり]の効力[こうりょく]を高[たか]めるために、毎日[まいにち]同[おな]じ時間[じかん]に飲[の]んでください。", "sentence_source": "generated"}, {"text": "効力のある対策を早く考えなければならない。", "target_word": "効力", "complexity_tier": "T4", "furigana": "効力[こうりょく]のある対策[たいさく]を早[はや]く考[かんが]えなければならない。", "sentence_source": "generated"}, {"text": "警告だけでは、効力が足りなかった。", "target_word": "効力", "complexity_tier": "T3", "furigana": "警告[けいこく]だけでは、効力[こうりょく]が足[た]りなかった。", "sentence_source": "generated"}, {"text": "期限が切れて、クーポンの効力はなくなりました。", "target_word": "効力", "complexity_tier": "T3", "furigana": "期限[きげん]が切[き]れて、クーポンの効力[こうりょく]はなくなりました。", "sentence_source": "generated"}, {"text": "この殺虫剤は強い効力を発揮する。", "target_word": "効力", "complexity_tier": "T2", "furigana": "この殺虫剤[さっちゅうざい]は強[つよ]い効力[こうりょく]を発揮[はっき]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "効力感", "label": "派生"}, {"form": "効力発生", "label": "派生"}, {"form": "効力期間", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ききめ、効果を及ぼす力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 愉楽 (Zipf 1.65)']::text[], '3a0dbfc7-ded3-42fa-8956-25a04f821c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52824, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "効力", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "動力", "is_correct": false, "explanation": "どうりょくで、こ→どの1拍だけが違う別の語。"}, {"text": "労力", "is_correct": false, "explanation": "ろうりょくで、こ→ろの1拍だけが違う別の語。"}, {"text": "総力", "is_correct": false, "explanation": "そうりょくで、こ→その1拍だけが違う別の語。"}, {"text": "暴力", "is_correct": false, "explanation": "ぼうりょくで、こ→ぼの1拍だけが違う別の語。"}], "explanations": {"効力": "見出し語そのもの。", "動力": "どうりょくで、こ→どの1拍だけが違う別の語。", "労力": "ろうりょくで、こ→ろの1拍だけが違う別の語。", "総力": "そうりょくで、こ→その1拍だけが違う別の語。", "暴力": "ぼうりょくで、こ→ぼの1拍だけが違う別の語。"}, "sentence_index": null, "correct_answer": "効力"}, "level_3": {"options": [{"text": "効力", "is_correct": true, "explanation": "「自己効力感」という語を作り、文意に合う。"}, {"text": "温度", "is_correct": false, "explanation": "形は合うが、自己温度感では意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、自己地図感では意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、自己季節感では意味が合わない。"}], "explanations": {"効力": "「自己効力感」という語を作り、文意に合う。", "温度": "形は合うが、自己温度感では意味が合わない。", "地図": "形は合うが、自己地図感では意味が合わない。", "季節": "形は合うが、自己季節感では意味が合わない。"}, "sentence_index": 0, "correct_answer": "効力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この椅子は効力が四本あって、とても丈夫だ。", "explanation": "効力は物の部品ではなく、数えられる脚のようには使えない。"}, {"text": "彼は毎朝、効力を着て会社へ行く。", "explanation": "効力はききめの意味で、服のように着る対象ではない。"}, {"text": "北の効力は寒くて、雪がたくさん降る。", "explanation": "効力は地域や場所を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52824, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "効力", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "光量", "is_correct": false, "explanation": "こうりょうで、く→うの1拍だけが違う別の語。"}, {"text": "合力", "is_correct": false, "explanation": "ごうりょくで、こ→ごの清濁だけが違う別の語。"}, {"text": "能力", "is_correct": false, "explanation": "のうりょくで、こ→のの1拍だけが違う別の語。"}, {"text": "省力", "is_correct": false, "explanation": "しょうりょくで、こ→しょの1拍だけが違う別の語。"}], "explanations": {"効力": "見出し語そのもの。", "光量": "こうりょうで、く→うの1拍だけが違う別の語。", "合力": "ごうりょくで、こ→ごの清濁だけが違う別の語。", "能力": "のうりょくで、こ→のの1拍だけが違う別の語。", "省力": "しょうりょくで、こ→しょの1拍だけが違う別の語。"}, "sentence_index": null, "correct_answer": "効力"}, "level_3": {"options": [{"text": "効力", "is_correct": true, "explanation": "「効力のある対策」で、ききめのある対策という意味になる。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、湿度のある対策では意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、辞書のある対策では意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、地図のある対策では意味が合わない。"}], "explanations": {"効力": "「効力のある対策」で、ききめのある対策という意味になる。", "湿度": "形は合うが、湿度のある対策では意味が合わない。", "辞書": "形は合うが、辞書のある対策では意味が合わない。", "地図": "形は合うが、地図のある対策では意味が合わない。"}, "sentence_index": 6, "correct_answer": "効力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この殺虫剤は強い効力を飲んで、元気になった。", "explanation": "効力はききめで、飲む対象ではない。"}, {"text": "新しい効力を買うために、駅前の店に行った。", "explanation": "効力は売り買いする物ではなく、買う対象にならない。"}, {"text": "今日の効力は雨なので、傘を持っていこう。", "explanation": "効力は天気を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warn