INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52826, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "困難を避けて、楽な方法を選ぶこと。また、その様子。", "primary_collocate": null, "pronunciation": "あんい", "ipa": "aɴi", "syllable_count": 3, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "安易な", "complexity_tier": "T6", "furigana": "既製品[きせいひん]への安易[あんい]な依存[いぞん]を排[はい]し、自[みずか]らの手[て]でカスタマイズを通[つう]じて素材[そざい]と対話[たいわ]する行為[こうい]は、DIYファッションの本質的[ほんしつてき]な愉楽[ゆらく]であり、自己[じこ]効力感[こうりょくかん]の再確認[さいかくにん]でもある。", "sentence_source": "mined"}, {"text": "安易な気持ちで引き受けてはいけない。", "target_word": "安易な", "complexity_tier": "T3", "furigana": "安易[あんい]な気持[きも]ちで引[ひ]き受[う]けてはいけない。", "sentence_source": "generated"}, {"text": "彼は安易に人の意見に流される。", "target_word": "安易に", "complexity_tier": "T4", "furigana": "彼[かれ]は安易[あんい]に人[ひと]の意見[いけん]に流[なが]される。", "sentence_source": "generated"}, {"text": "方法が安易だと、後で困ることになる。", "target_word": "安易だ", "complexity_tier": "T4", "furigana": "方法[ほうほう]が安易[あんい]だと、後[あと]で困[こま]ることになる。", "sentence_source": "generated"}, {"text": "その決断は安易だったと思う。", "target_word": "安易だった", "complexity_tier": "T3", "furigana": "その決断[けつだん]は安易[あんい]だったと思[おも]う。", "sentence_source": "generated"}, {"text": "安易に答えを見るのはやめよう。", "target_word": "安易に", "complexity_tier": "T3", "furigana": "安易[あんい]に答[こた]えを見[み]るのはやめよう。", "sentence_source": "generated"}, {"text": "安易な値上げは、客の信頼を失うことになる。", "target_word": "安易な", "complexity_tier": "T3", "furigana": "安易[あんい]な値上[ねあ]げは、客[きゃく]の信頼[しんらい]を失[うしな]うことになる。", "sentence_source": "generated"}, {"text": "彼の考えは安易で、現実的ではない。", "target_word": "安易で", "complexity_tier": "T3", "furigana": "彼[かれ]の考[かんが]えは安易[あんい]で、現実的[げんじつてき]ではない。", "sentence_source": "generated"}, {"text": "安易な近道を選んだせいで、質が落ちてしまった。", "target_word": "安易な", "complexity_tier": "T3", "furigana": "安易[あんい]な近道[ちかみち]を選[えら]んだせいで、質[しつ]が落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "彼女は安易に約束をしない人だ。", "target_word": "安易に", "complexity_tier": "T2", "furigana": "彼女[かのじょ]は安易[あんい]に約束[やくそく]をしない人[ひと]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安易な", "label": "活用"}, {"form": "安易に", "label": "活用"}, {"form": "安易だ", "label": "活用"}, {"form": "安易さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 困難を避けて楽な方法を選ぶ様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 愉楽 (Zipf 1.65)']::text[], '3a0dbfc7-ded3-42fa-8956-25a04f821c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52826, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "安易", "is_correct": true, "explanation": "「あんい」と読む。正解。"}, {"text": "品位", "is_correct": false, "explanation": "「ひんい」で、一音目が違う。"}, {"text": "範囲", "is_correct": false, "explanation": "「はんい」で、一音目が違う。"}, {"text": "悪意", "is_correct": false, "explanation": "「あくい」で、二音目が違う。"}, {"text": "暗記", "is_correct": false, "explanation": "「あんき」で、三音目が違う。"}], "explanations": {"安易": "「あんい」と読む。正解。", "品位": "「ひんい」で、一音目が違う。", "範囲": "「はんい」で、一音目が違う。", "悪意": "「あくい」で、二音目が違う。", "暗記": "「あんき」で、三音目が違う。"}, "sentence_index": null, "correct_answer": "安易"}, "level_3": {"options": [{"text": "安易な", "is_correct": true, "explanation": "楽な方法に頼る依存という意味で文脈に合う。"}, {"text": "鮮やかな", "is_correct": false, "explanation": "形は合うが、「依存」を修飾する意味が合わない。"}, {"text": "貴重な", "is_correct": false, "explanation": "形は合うが、「依存を排し」という文脈に意味が合わない。"}, {"text": "静かな", "is_correct": false, "explanation": "形は合うが、「依存」の様子として意味が合わない。"}], "explanations": {"安易な": "楽な方法に頼る依存という意味で文脈に合う。", "鮮やかな": "形は合うが、「依存」を修飾する意味が合わない。", "貴重な": "形は合うが、「依存を排し」という文脈に意味が合わない。", "静かな": "形は合うが、「依存」の様子として意味が合わない。"}, "sentence_index": 0, "correct_answer": "安易な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは安易な味がして、とてもおいしい。", "explanation": "「安易」は楽な方法を選ぶ様子で、味の性質には使えない。"}, {"text": "彼は何年も苦労して、安易に研究を完成させた。", "explanation": "「安易に」は苦労しない様子で、「何年も苦労して」と矛盾する。"}, {"text": "この機械は安易で、一度でも触ると壊れやすい。", "explanation": "「安易」は物の壊れやすさを表さない。「もろい」などが適切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52826, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "安易", "is_correct": true, "explanation": "「あんい」と読む。正解。"}, {"text": "転移", "is_correct": false, "explanation": "「てんい」で、一音目が違う。"}, {"text": "権威", "is_correct": false, "explanation": "「けんい」で、一音目が違う。"}, {"text": "暗示", "is_correct": false, "explanation": "「あんじ」で、三音目が違う。"}, {"text": "安堵", "is_correct": false, "explanation": "「あんど」で、三音目が違う。"}], "explanations": {"安易": "「あんい」と読む。正解。", "転移": "「てんい」で、一音目が違う。", "権威": "「けんい」で、一音目が違う。", "暗示": "「あんじ」で、三音目が違う。", "安堵": "「あんど」で、三音目が違う。"}, "sentence_index": null, "correct_answer": "安易"}, "level_3": {"options": [{"text": "安易な", "is_correct": true, "explanation": "深く考えない値上げという意味で、信頼を失う結果に合う。"}, {"text": "爽やかな", "is_correct": false, "explanation": "形は合うが、「値上げ」の様子として意味が合わない。"}, {"text": "豊かな", "is_correct": false, "explanation": "形は合うが、値上げと信頼を失う流れに意味が合わない。"}, {"text": "華やかな", "is_correct": false, "explanation": "形は合うが、値上げを修飾する意味が合わない。"}], "explanations": {"安易な": "深く考えない値上げという意味で、信頼を失う結果に合う。", "爽やかな": "形は合うが、「値上げ」の様子として意味が合わない。", "豊かな": "形は合うが、値上げと信頼を失う流れに意味が合わない。", "華やかな": "形は合うが、値上げを修飾する意味が合わない。"}, "sentence_index": 6, "correct_answer": "安易な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "安易な気温の中、彼は薄着で散歩に出かけた。", "explanation": "「安易」は気温の性質を表さない。「穏やかな」などが適切。"}, {"text": "彼女は安易に考え抜いた末、転職を決意した。", "explanation": "「安易に」は深く考えない様子で、「考え抜いた」と矛盾する。"}, {"text": "彼は安易な友人を大切にし、長年の付き合いを続けている。", "explanation": "「安易」は人を評する語ではなく、友人の説明に使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX