INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52826, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "安易の方法で問題を解決してしまった。", "corrected_sentence": "安易な方法で問題を解決してしまった。", "error_description": "名詞を修飾する形は「安易な」で、「安易の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "安易な", "is_correct": true, "explanation": "「気持ち」を修飾する連体形で正しい。"}, {"text": "安易に", "is_correct": false, "explanation": "連用形で、名詞「気持ち」を修飾できない。"}, {"text": "安易だ", "is_correct": false, "explanation": "終止形で、名詞の前には置けない。"}, {"text": "安易さ", "is_correct": false, "explanation": "名詞形で、「気持ち」を修飾する形にならない。"}], "correct_form": "安易な", "base_form": "安易", "form_label": "連体形（な）", "sentence_index": 1, "explanations": {"安易な": "「気持ち」を修飾する連体形で正しい。", "安易に": "連用形で、名詞「気持ち」を修飾できない。", "安易だ": "終止形で、名詞の前には置けない。", "安易さ": "名詞形で、「気持ち」を修飾する形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
