INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52827, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「思い出す」の目的語を示す「を」で正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「愉楽へ思い出す」は動詞とつながらない。"}, {"text": "の", "is_correct": false, "explanation": "「愉楽の思い出す」は文として成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "「愉楽や思い出す」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「思い出す」の目的語を示す「を」で正しい。", "へ": "「愉楽へ思い出す」は動詞とつながらない。", "の": "「愉楽の思い出す」は文として成り立たない。", "や": "「愉楽や思い出す」は文として成り立たない。"}, "error_tags": {"へ": "direction", "の": "possessive", "や": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "苦悩", "is_correct": true, "explanation": "悩み苦しむことで、楽しさの反対。"}, {"text": "喜び", "is_correct": false, "explanation": "うれしい気持ちで、愉楽と近い意味。"}, {"text": "娯楽", "is_correct": false, "explanation": "楽しみの意味で、愉楽と近い。"}, {"text": "幸福", "is_correct": false, "explanation": "満たされた状態で、愉楽と近い意味。"}], "correct_answer": "苦悩", "explanations": {"苦悩": "悩み苦しむことで、楽しさの反対。", "喜び": "うれしい気持ちで、愉楽と近い意味。", "娯楽": "楽しみの意味で、愉楽と近い。", "幸福": "満たされた状態で、愉楽と近い意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
