INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52827, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たのしいと感じること。", "primary_collocate": null, "pronunciation": "ゆらく", "ipa": "jɯɾakɯ", "syllable_count": 3, "sentences": [{"text": "友だちと遊ぶのは、人生の愉楽だ。", "target_word": "愉楽", "complexity_tier": "T2", "furigana": "友[とも]だちと遊[あそ]ぶのは、人生[じんせい]の愉楽[ゆらく]だ。", "sentence_source": "generated"}, {"text": "旅行の愉楽を思い出す。", "target_word": "愉楽", "complexity_tier": "T2", "furigana": "旅行[りょこう]の愉楽[ゆらく]を思[おも]い出[だ]す。", "sentence_source": "generated"}, {"text": "愉楽を感じる時間が好きだ。", "target_word": "愉楽", "complexity_tier": "T2", "furigana": "愉楽[ゆらく]を感[かん]じる時間[じかん]が好[す]きだ。", "sentence_source": "generated"}, {"text": "彼は休日の愉楽を心から味わった。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "彼[かれ]は休日[きゅうじつ]の愉楽[ゆらく]を心[こころ]から味[あじ]わった。", "sentence_source": "generated"}, {"text": "一人で歩く愉楽もある。", "target_word": "愉楽", "complexity_tier": "T2", "furigana": "一人[ひとり]で歩[ある]く愉楽[ゆらく]もある。", "sentence_source": "generated"}, {"text": "家族と食べる夕食は、一日の愉楽です。", "target_word": "愉楽", "complexity_tier": "T2", "furigana": "家族[かぞく]と食[た]べる夕食[ゆうしょく]は、一日[いちにち]の愉楽[ゆらく]です。", "sentence_source": "generated"}, {"text": "愉楽に満ちた音楽が流れている。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "愉楽[ゆらく]に満[み]ちた音楽[おんがく]が流[なが]れている。", "sentence_source": "generated"}, {"text": "本を読む愉楽を子どもに教えたい。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "本[ほん]を読[よ]む愉楽[ゆらく]を子[こ]どもに教[おし]えたい。", "sentence_source": "generated"}, {"text": "彼女は絵を描く愉楽に夢中になった。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は絵[え]を描[か]く愉楽[ゆらく]に夢中[むちゅう]になった。", "sentence_source": "generated"}, {"text": "愉楽の時間は、あっという間に過ぎた。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "愉楽[ゆらく]の時間[じかん]は、あっという間[ま]に過[す]ぎた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | たのしいと感じる気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0dbfc7-ded3-42fa-8956-25a04f821c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52827, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "愉楽", "is_correct": true, "explanation": "「ゆらく」と読む。正解。"}, {"text": "気楽", "is_correct": false, "explanation": "「きらく」で、一音目が違う。"}, {"text": "奈落", "is_correct": false, "explanation": "「ならく」で、一音目が違う。"}, {"text": "由来", "is_correct": false, "explanation": "「ゆらい」で、三音目が違う。"}, {"text": "揺らぎ", "is_correct": false, "explanation": "「ゆらぎ」で、三音目が違う。"}], "explanations": {"愉楽": "「ゆらく」と読む。正解。", "気楽": "「きらく」で、一音目が違う。", "奈落": "「ならく」で、一音目が違う。", "由来": "「ゆらい」で、三音目が違う。", "揺らぎ": "「ゆらぎ」で、三音目が違う。"}, "sentence_index": null, "correct_answer": "愉楽"}, "level_3": {"options": [{"text": "愉楽", "is_correct": true, "explanation": "友だちと遊ぶ楽しさという意味で合う。"}, {"text": "期限", "is_correct": false, "explanation": "名詞として入るが、遊ぶことの説明として意味が合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "名詞として入るが、「遊ぶのは」に意味が合わない。"}, {"text": "予算", "is_correct": false, "explanation": "名詞として入るが、遊ぶことの説明として意味が合わない。"}], "explanations": {"愉楽": "友だちと遊ぶ楽しさという意味で合う。", "期限": "名詞として入るが、遊ぶことの説明として意味が合わない。", "時刻": "名詞として入るが、「遊ぶのは」に意味が合わない。", "予算": "名詞として入るが、遊ぶことの説明として意味が合わない。"}, "sentence_index": 0, "correct_answer": "愉楽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は財布を落とし、愉楽に暮れて立ち尽くした。", "explanation": "「愉楽」は楽しみで、「途方に暮れる」のような困惑には使えない。"}, {"text": "窓から愉楽の風が吹き込んで、寒くなった。", "explanation": "「愉楽」は風の性質を表さない。"}, {"text": "愉楽を二つ買って、昼食に食べた。", "explanation": "「愉楽」は数えて買う物ではなく、感情を表す語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52827, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "愉楽", "is_correct": true, "explanation": "「ゆらく」と読む。正解。"}, {"text": "苦楽", "is_correct": false, "explanation": "「くらく」で、一音目が違う。"}, {"text": "奈落", "is_correct": false, "explanation": "「ならく」で、一音目が違う。"}, {"text": "揺らぐ", "is_correct": false, "explanation": "「ゆらぐ」で、三音目が濁って違う。"}, {"text": "揺らす", "is_correct": false, "explanation": "「ゆらす」で、三音目が違う。"}], "explanations": {"愉楽": "「ゆらく」と読む。正解。", "苦楽": "「くらく」で、一音目が違う。", "奈落": "「ならく」で、一音目が違う。", "揺らぐ": "「ゆらぐ」で、三音目が濁って違う。", "揺らす": "「ゆらす」で、三音目が違う。"}, "sentence_index": null, "correct_answer": "愉楽"}, "level_3": {"options": [{"text": "愉楽", "is_correct": true, "explanation": "楽しさに満ちた音楽という意味で合う。"}, {"text": "書類", "is_correct": false, "explanation": "名詞として入るが、「に満ちた」と意味が合わない。"}, {"text": "天井", "is_correct": false, "explanation": "名詞として入るが、音楽を修飾する意味が合わない。"}, {"text": "定価", "is_correct": false, "explanation": "名詞として入るが、音楽の様子として意味が合わない。"}], "explanations": {"愉楽": "楽しさに満ちた音楽という意味で合う。", "書類": "名詞として入るが、「に満ちた」と意味が合わない。", "天井": "名詞として入るが、音楽を修飾する意味が合わない。", "定価": "名詞として入るが、音楽の様子として意味が合わない。"}, "sentence_index": 6, "correct_answer": "愉楽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この計算の愉楽は、答えが三つある。", "explanation": "「愉楽」は計算の性質を表さない。"}, {"text": "愉楽を落として、画面が割れてしまった。", "explanation": "「愉楽」は感情で、落とす物ではない。"}, {"text": "歯の愉楽がひどくて、歯医者に行った。", "explanation": "「愉楽」は楽しさで、歯の痛みを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
