INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52828, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作る」の目的語を示す「を」で正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「料理へ作る」は動詞とつながらない。"}, {"text": "や", "is_correct": false, "explanation": "「料理や作る」は文として成り立たない。"}, {"text": "か", "is_correct": false, "explanation": "「料理か作る」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「作る」の目的語を示す「を」で正しい。", "へ": "「料理へ作る」は動詞とつながらない。", "や": "「料理や作る」は文として成り立たない。", "か": "「料理か作る」は文として成り立たない。"}, "error_tags": {"へ": "direction", "や": "listing", "か": "question"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "苦悩", "is_correct": true, "explanation": "悩み苦しむことで、楽しみの反対。"}, {"text": "歓喜", "is_correct": false, "explanation": "大きな喜びで、愉楽と近い意味。"}, {"text": "娯楽", "is_correct": false, "explanation": "楽しみの意味で、愉楽と近い。"}, {"text": "快感", "is_correct": false, "explanation": "心地よさで、愉楽と近い意味。"}], "correct_answer": "苦悩", "explanations": {"苦悩": "悩み苦しむことで、楽しみの反対。", "歓喜": "大きな喜びで、愉楽と近い意味。", "娯楽": "楽しみの意味で、愉楽と近い。", "快感": "心地よさで、愉楽と近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52828, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心が満たされて、楽しいと感じる喜びや楽しみ。", "primary_collocate": null, "pronunciation": "ゆらく", "ipa": "jɯɾakɯ", "syllable_count": 3, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "愉楽", "complexity_tier": "T6", "furigana": "既製品[きせいひん]への安易[あんい]な依存[いぞん]を排[はい]し、自[みずか]らの手[て]でカスタマイズを通[つう]じて素材[そざい]と対話[たいわ]する行為[こうい]は、DIYファッションの本質的[ほんしつてき]な愉楽[ゆらく]であり、自己[じこ]効力感[こうりょくかん]の再確認[さいかくにん]でもある。", "sentence_source": "mined"}, {"text": "旅先で味わう愉楽は格別だ。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "旅先[たびさき]で味[あじ]わう愉楽[ゆらく]は格別[かくべつ]だ。", "sentence_source": "generated"}, {"text": "彼女は読書に愉楽を見いだしている。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は読書[どくしょ]に愉楽[ゆらく]を見[み]いだしている。", "sentence_source": "generated"}, {"text": "音楽に浸る時間は、私にとって最大の愉楽だ。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "音楽[おんがく]に浸[ひた]る時間[じかん]は、私[わたし]にとって最大[さいだい]の愉楽[ゆらく]だ。", "sentence_source": "generated"}, {"text": "子どもたちの笑い声は、大人にも愉楽を与える。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "子[こ]どもたちの笑[わら]い声[ごえ]は、大人[おとな]にも愉楽[ゆらく]を与[あた]える。", "sentence_source": "generated"}, {"text": "愉楽に満ちた一日だった。", "target_word": "愉楽", "complexity_tier": "T2", "furigana": "愉楽[ゆらく]に満[み]ちた一日[いちにち]だった。", "sentence_source": "generated"}, {"text": "愉楽を求めすぎると、かえって心が疲れてしまう。", "target_word": "愉楽", "complexity_tier": "T4", "furigana": "愉楽[ゆらく]を求[もと]めすぎると、かえって心[こころ]が疲[つか]れてしまう。", "sentence_source": "generated"}, {"text": "料理を作る愉楽は、食べてもらう喜びにつながる。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "料理[りょうり]を作[つく]る愉楽[ゆらく]は、食[た]べてもらう喜[よろこ]びにつながる。", "sentence_source": "generated"}, {"text": "彼は愉楽の中にも、どこか寂しさを感じていた。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "彼[かれ]は愉楽[ゆらく]の中[なか]にも、どこか寂[さび]しさを感[かん]じていた。", "sentence_source": "generated"}, {"text": "祭りの夜、町の人々は愉楽のひとときを過ごした。", "target_word": "愉楽", "complexity_tier": "T3", "furigana": "祭[まつ]りの夜[よる]、町[まち]の人々[ひとびと]は愉楽[ゆらく]のひとときを過[す]ごした。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 心が満たされる喜びや楽しみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0dbfc7-ded3-42fa-8956-25a04f821c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52828, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "愉楽", "is_correct": true, "explanation": "「ゆらく」と読む。正解。"}, {"text": "気楽", "is_correct": false, "explanation": "「きらく」で、一音目が違う。"}, {"text": "奈落", "is_correct": false, "explanation": "「ならく」で、一音目が違う。"}, {"text": "由来", "is_correct": false, "explanation": "「ゆらい」で、三音目が違う。"}, {"text": "苦楽", "is_correct": false, "explanation": "「くらく」で、一音目が違う。"}], "explanations": {"愉楽": "「ゆらく」と読む。正解。", "気楽": "「きらく」で、一音目が違う。", "奈落": "「ならく」で、一音目が違う。", "由来": "「ゆらい」で、三音目が違う。", "苦楽": "「くらく」で、一音目が違う。"}, "sentence_index": null, "correct_answer": "愉楽"}, "level_3": {"options": [{"text": "愉楽", "is_correct": true, "explanation": "素材と対話する行為の喜びという意味で合う。"}, {"text": "価格", "is_correct": false, "explanation": "名詞として入るが、行為の本質としての喜びという意味に合わない。"}, {"text": "損失", "is_correct": false, "explanation": "名詞として入るが、前向きな文脈に意味が合わない。"}, {"text": "距離", "is_correct": false, "explanation": "名詞として入るが、行為の本質を表す意味が合わない。"}], "explanations": {"愉楽": "素材と対話する行為の喜びという意味で合う。", "価格": "名詞として入るが、行為の本質としての喜びという意味に合わない。", "損失": "名詞として入るが、前向きな文脈に意味が合わない。", "距離": "名詞として入るが、行為の本質を表す意味が合わない。"}, "sentence_index": 0, "correct_answer": "愉楽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "転んで足を骨折し、愉楽で歩けなくなった。", "explanation": "「愉楽」は楽しみで、骨折の痛みを表さない。"}, {"text": "駅までの愉楽は三百メートルだ。", "explanation": "「愉楽」は距離を表さない。「距離」が適切。"}, {"text": "彼は上司に叱られ、深い愉楽に沈んだ。", "explanation": "「愉楽」は喜びで、叱られて沈む気持ちには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52828, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "愉楽", "is_correct": true, "explanation": "「ゆらく」と読む。正解。"}, {"text": "揺らぎ", "is_correct": false, "explanation": "「ゆらぎ」で、三音目が違う。"}, {"text": "奈落", "is_correct": false, "explanation": "「ならく」で、一音目が違う。"}, {"text": "揺らぐ", "is_correct": false, "explanation": "「ゆらぐ」で、三音目が濁って違う。"}, {"text": "揺らす", "is_correct": false, "explanation": "「ゆらす」で、三音目が違う。"}], "explanations": {"愉楽": "「ゆらく」と読む。正解。", "揺らぎ": "「ゆらぎ」で、三音目が違う。", "奈落": "「ならく」で、一音目が違う。", "揺らぐ": "「ゆらぐ」で、三音目が濁って違う。", "揺らす": "「ゆらす」で、三音目が違う。"}, "sentence_index": null, "correct_answer": "愉楽"}, "level_3": {"options": [{"text": "愉楽", "is_correct": true, "explanation": "求めすぎて心が疲れるものとして、喜びや楽しみが合う。"}, {"text": "地図", "is_correct": false, "explanation": "名詞として入るが、「求めすぎて心が疲れる」に意味が合わない。"}, {"text": "気温", "is_correct": false, "explanation": "名詞として入るが、求める対象として意味が合わない。"}, {"text": "荷物", "is_correct": false, "explanation": "名詞として入るが、心が疲れる理由として意味が合わない。"}], "explanations": {"愉楽": "求めすぎて心が疲れるものとして、喜びや楽しみが合う。", "地図": "名詞として入るが、「求めすぎて心が疲れる」に意味が合わない。", "気温": "名詞として入るが、求める対象として意味が合わない。", "荷物": "名詞として入るが、心が疲れる理由として意味が合わない。"}, "sentence_index": 6, "correct_answer": "愉楽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の会議で、予算について愉楽を話し合った。", "explanation": "「愉楽」は予算のような話題にはならない。意味が合わない。"}, {"text": "大事な試験に落ちて、彼は愉楽の涙を流した。", "explanation": "「愉楽」は楽しみで、試験に落ちた涙と意味が合わない。"}, {"text": "この道具は愉楽が重く、持ち運びに不便だ。", "explanation": "「愉楽」は重さのような物の性質を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52828, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちの笑い声は、大人にも愉楽が与える。", "corrected_sentence": "子どもたちの笑い声は、大人にも愉楽を与える。", "error_description": "「与える」の目的語は「愉楽を」で、「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52828, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅先で味わう愉楽に格別だ。", "corrected_sentence": "旅先で味わう愉楽は格別だ。", "error_description": "「愉楽」が主題なので「は」が正しく、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52829, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「暗闇に」は「慣れる」の対象を示す。目が慣れる相手の状態を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示す。「慣れる」は自動詞なので「暗闇を」は取らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「暗闇と目が慣れる」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「暗闇へ慣れる」は不自然で、対象を示す「に」が合う。"}], "correct_answer": "に", "explanations": {"に": "「暗闇に」は「慣れる」の対象を示す。目が慣れる相手の状態を表す。", "を": "「を」は他動詞の目的語を示す。「慣れる」は自動詞なので「暗闇を」は取らない。", "と": "「と」は相手や並列を示す。「暗闇と目が慣れる」では成り立たない。", "へ": "「へ」は方向を示す。「暗闇へ慣れる」は不自然で、対象を示す「に」が合う。"}, "error_tags": {"を": "目的語", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52829, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「暗闇の中」と名詞を修飾し、場所の範囲を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「暗闇が中では」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「暗闇から中では」は場所の範囲を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「暗闇より中では」は場所の範囲として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「暗闇の中」と名詞を修飾し、場所の範囲を示す。", "が": "「が」は主語を示す。「暗闇が中では」では文が成り立たない。", "から": "「から」は起点を示す。「暗闇から中では」は場所の範囲を示せない。", "より": "「より」は比較を示す。「暗闇より中では」は場所の範囲として成り立たない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52829, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "光がまったくない、真っ黒なところ。", "primary_collocate": null, "pronunciation": "くらやみ", "ipa": "kɯɾajami", "syllable_count": 4, "sentences": [{"text": "窓のない地下室は、ドアを閉めると完全な暗闇だ。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "窓[まど]のない地下室[ちかしつ]は、ドアを閉[し]めると完全[かんぜん]な暗闇[くらやみ]だ。", "sentence_source": "generated"}, {"text": "暗闇に目が慣れてくると、家具の形が見えてきた。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]に目[め]が慣[な]れてくると、家具[かぐ]の形[かたち]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "彼は暗闇を怖がらず、電気を消して眠る。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "彼[かれ]は暗闇[くらやみ]を怖[こわ]がらず、電気[でんき]を消[け]して眠[ねむ]る。", "sentence_source": "generated"}, {"text": "暗闇の向こうから、足音が近づいてきた。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]の向[む]こうから、足音[あしおと]が近[ちか]づいてきた。", "sentence_source": "generated"}, {"text": "懐中電灯の光が、暗闇を丸く照らした。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "懐中電灯[かいちゅうでんとう]の光[ひかり]が、暗闇[くらやみ]を丸[まる]く照[て]らした。", "sentence_source": "generated"}, {"text": "電池が切れて、暗闇に一人取り残された。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "電池[でんち]が切[き]れて、暗闇[くらやみ]に一人[ひとり]取[と]り残[のこ]された。", "sentence_source": "generated"}, {"text": "映画館が暗闇になって、本編が始まった。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "映画館[えいがかん]が暗闇[くらやみ]になって、本編[ほんぺん]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "暗闇の中では、小さな音もよく聞こえる。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]の中[なか]では、小[ちい]さな音[おと]もよく聞[き]こえる。", "sentence_source": "generated"}, {"text": "深い海の底は、光の届かない暗闇だ。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "深[ふか]い海[うみ]の底[そこ]は、光[ひかり]の届[とど]かない暗闇[くらやみ]だ。", "sentence_source": "generated"}, {"text": "暗闇で手探りしながら、スイッチを探した。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]で手探[てさぐ]りしながら、スイッチを探[さが]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗闇", "label": "基本形"}], "register": "標準", "sense_fingerprint": "光がまったく届かない真っ暗な場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52829, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暗闇", "is_correct": true, "explanation": "「完全な暗闇だ」と、光が全くない場所を指す。地下室の状態に合う。"}, {"text": "返事", "is_correct": false, "explanation": "応答の言葉を表し、部屋の暗さの状態を示す語にはならない。"}, {"text": "価格", "is_correct": false, "explanation": "値段を表す語で、部屋の状態を表す「完全な〜だ」には合わない。"}, {"text": "近所", "is_correct": false, "explanation": "住んでいる周辺の地域を表し、暗さの状態を表す語にはならない。"}], "explanations": {"暗闇": "「完全な暗闇だ」と、光が全くない場所を指す。地下室の状態に合う。", "返事": "応答の言葉を表し、部屋の暗さの状態を示す語にはならない。", "価格": "値段を表す語で、部屋の状態を表す「完全な〜だ」には合わない。", "近所": "住んでいる周辺の地域を表し、暗さの状態を表す語にはならない。"}, "sentence_index": 0, "correct_answer": "暗闇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は、会社の暗闇を知りながら、黙って仕事を続けた。", "explanation": "ここは〈暗闇〉を「隠された不正や悪事」の意味で使っている。光がない場所という定義とは別の意味になる。"}, {"text": "懐中電灯の暗闇で、地図を広げた。", "explanation": "懐中電灯の明かりの中で地図を広げる場面。「暗闇」は光がまったくない状態なので、明かりのある場面とは両立しない。"}, {"text": "その国は、戦争の暗闇の時代を経て、ようやく平和を取り戻した。", "explanation": "ここは〈暗闇〉を「不幸で苦しい時代」の比喩で使っている。光がない場所という定義とは別の意味になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52829, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暗闇", "is_correct": true, "explanation": "上映前に館内が暗くなる状態を指し、「映画館が〜になって」と自然につながる。"}, {"text": "拍手", "is_correct": false, "explanation": "「拍手になる」は不自然で、場内の状態を表さない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気になる」は成り立たず、映画館の状態を表す語にはならない。"}, {"text": "料金", "is_correct": false, "explanation": "「料金になる」は不自然で、館内の状態を示す語として合わない。"}], "explanations": {"暗闇": "上映前に館内が暗くなる状態を指し、「映画館が〜になって」と自然につながる。", "拍手": "「拍手になる」は不自然で、場内の状態を表さない。", "天気": "「天気になる」は成り立たず、映画館の状態を表す語にはならない。", "料金": "「料金になる」は不自然で、館内の状態を示す語として合わない。"}, "sentence_index": 6, "correct_answer": "暗闇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方の陽射しが、暗闇を明るく照らしていた。", "explanation": "ここは〈暗闇〉を「薄暗い場所」の意味で使っている。暗闇は光がまったくない状態なので、陽射しで明るく照らされる場面とは両立しない。"}, {"text": "彼女は、暗闇のような明るい声で話しかけた。", "explanation": "ここは〈暗闇〉を「暗く陰気な雰囲気」の意味で使っている。明るい声とは矛盾する。"}, {"text": "彼女は、暗闇の色のドレスで、会場の中で一番目立った。", "explanation": "ここは〈暗闇〉を「暗い色合い」の意味で使っている。光がない状態という定義とは別の意味になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52829, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ブレーカーが落ちて、部屋は完全な暗闇にした。", "corrected_sentence": "ブレーカーが落ちて、部屋は完全な暗闇になった。", "error_description": "「暗闇になった」は自動詞「なる」の形。「暗闇にした」は他動詞「する」で、主語の部屋が動作主となり文が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52829, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "照明が消えて、部屋は暗闇を包まれた。", "corrected_sentence": "照明が消えて、部屋は暗闇に包まれた。", "error_description": "「包まれる」は「〜に包まれる」の形で「に」を取る。「を」は誤りで、正しくは「暗闇に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
