INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52830, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "光がなくて、何も見えない状態。暗い場所。", "primary_collocate": null, "pronunciation": "くらやみ", "ipa": "kɯɾajami", "syllable_count": 4, "sentences": [{"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "革[かわ]の匂[にお]いが漂[ただよ]う暗闇[くらやみ]の奥底[おくそこ]で、長[なが]き眠[ねむ]りについていたそれを引[ひ]きずり出[だ]した瞬間[しゅんかん]、埃[ほこり]っぽい記憶[きおく]の粒子[りゅうし]が舞[ま]い上[あ]がる。", "sentence_source": "mined"}, {"text": "停電で部屋が暗闇になり、何も見えなくなった。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "停電[ていでん]で部屋[へや]が暗闇[くらやみ]になり、何[なに]も見[み]えなくなった。", "sentence_source": "generated"}, {"text": "目が暗闇に慣れるまで、少し時間がかかった。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "目[め]が暗闇[くらやみ]に慣[な]れるまで、少[すこ]し時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "暗闇の中で、猫の目だけが光っていた。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]の中[なか]で、猫[ねこ]の目[め]だけが光[ひか]っていた。", "sentence_source": "generated"}, {"text": "子どものころは、暗闇が怖くて一人で寝られなかった。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "子[こ]どものころは、暗闇[くらやみ]が怖[こわ]くて一人[ひとり]で寝[ね]られなかった。", "sentence_source": "generated"}, {"text": "洞窟の奥は暗闇で、懐中電灯がないと進めない。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の奥[おく]は暗闇[くらやみ]で、懐中電灯[かいちゅうでんとう]がないと進[すす]めない。", "sentence_source": "generated"}, {"text": "暗闇のなかから、突然人の声が聞こえた。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]のなかから、突然[とつぜん]人[ひと]の声[こえ]が聞[き]こえた。", "sentence_source": "generated"}, {"text": "月が雲に隠れて、あたりは暗闇に包まれた。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "月[つき]が雲[くも]に隠[かく]れて、あたりは暗闇[くらやみ]に包[つつ]まれた。", "sentence_source": "generated"}, {"text": "暗闇で足元が見えず、階段で転びそうになった。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]で足元[あしもと]が見[み]えず、階段[かいだん]で転[ころ]びそうになった。", "sentence_source": "generated"}, {"text": "山道で日が暮れて、暗闇の中を歩くはめになった。", "target_word": "暗闇", "complexity_tier": "T3", "furigana": "山道[やまみち]で日[ひ]が暮[く]れて、暗闇[くらやみ]の中[なか]を歩[ある]くはめになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗闇", "label": "基本形"}], "register": "標準", "sense_fingerprint": "光がなく何も見えない状態やその場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 奥底 (Zipf 3.21), 長き (Zipf 3.3), 引きずり出し (Zipf 2.55), 舞い上がる (Zipf 2.61)']::text[], 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52830, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暗闇", "is_correct": true, "explanation": "光のない暗い場所を指し、「奥底で」と場面がつながる。"}, {"text": "夜明け", "is_correct": false, "explanation": "夜が明けてくる時刻を表し、暗い場所の奥底という意味にはならない。"}, {"text": "日差し", "is_correct": false, "explanation": "太陽の光の強さを表し、物を引き出す奥底の場所には合わない。"}, {"text": "轟音", "is_correct": false, "explanation": "大きな音を表し、場所の奥底を示す語としては成り立たない。"}], "explanations": {"暗闇": "光のない暗い場所を指し、「奥底で」と場面がつながる。", "夜明け": "夜が明けてくる時刻を表し、暗い場所の奥底という意味にはならない。", "日差し": "太陽の光の強さを表し、物を引き出す奥底の場所には合わない。", "轟音": "大きな音を表し、場所の奥底を示す語としては成り立たない。"}, "sentence_index": 0, "correct_answer": "暗闇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は、昔の暗闇を家族にだけそっと打ち明けた。", "explanation": "ここは〈暗闇〉を「人に言えない過去や秘密」の意味で使っている。光がない場所という定義とは別の意味になる。"}, {"text": "ろうそくの暗闇で、本を読んだ。", "explanation": "ろうそくの明かりで本を読む場面。「暗闇」は光がまったくない状態なので、本を読めるほどの明かりとは両立しない。"}, {"text": "彼女は、暗闇のような色の服を選んで、パーティーに出かけた。", "explanation": "ここは〈暗闇〉を「暗い色合い」の意味で使っている。光がない状態という定義とは別の意味になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52830, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暗闇", "is_correct": true, "explanation": "光のない暗い場所を指し、「のなかから声が聞こえた」という場所の語として正しい。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕方の空の色を表し、声が聞こえてくる場所の語としては合わない。"}, {"text": "吐息", "is_correct": false, "explanation": "息を吐く動作や息そのものを表し、声が聞こえる場所にはならない。"}, {"text": "目覚まし", "is_correct": false, "explanation": "目を覚ますための道具や音を表し、人の声が出てくる場所の語にはならない。"}], "explanations": {"暗闇": "光のない暗い場所を指し、「のなかから声が聞こえた」という場所の語として正しい。", "夕焼け": "夕方の空の色を表し、声が聞こえてくる場所の語としては合わない。", "吐息": "息を吐く動作や息そのものを表し、声が聞こえる場所にはならない。", "目覚まし": "目を覚ますための道具や音を表し、人の声が出てくる場所の語にはならない。"}, "sentence_index": 6, "correct_answer": "暗闇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暗闇が部屋の隅を照らしていた。", "explanation": "暗闇は光がまったくない状態なので、部屋の隅を照らすという働きと矛盾する。"}, {"text": "彼は暗闇のような大声で、会場中を驚かせた。", "explanation": "ここは〈暗闇〉を「大きくて怖い音」の比喩で使っている。光がない場所という定義とは別の意味になる。"}, {"text": "夕日の赤い暗闇が、街を染めていた。", "explanation": "ここは〈暗闇〉を「薄暗い夕暮れの色あい」の意味で使っている。暗闇は光がまったくない状態なので、夕日の赤さとは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52830, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街灯のない山道は、暗闇を包まれていた。", "corrected_sentence": "街灯のない山道は、暗闇に包まれていた。", "error_description": "「包まれる」は「〜に包まれる」の形で「に」を取る。「を」は誤りで、正しくは「暗闇に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52830, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街灯が消えて、通りは暗闇に包む。", "corrected_sentence": "街灯が消えて、通りは暗闇に包まれた。", "error_description": "「暗闇に包まれた」は受け身の過去形。「包む」の能動形では暗闇が主語になり、「通りは」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52831, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「奥底には」の「に」。光が届く場所を示し、海の一番深い部分を場所として表すので自然。"}, {"text": "を", "is_correct": false, "explanation": "「届く」は対象を取らない動詞なので、「奥底を」と目的語にすると文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「奥底が」にすると主語が「光が」と二つ並び、「届きません」の主語として合わなくなる。"}, {"text": "の", "is_correct": false, "explanation": "「奥底の」の後に名詞がなく、文が成り立たない。連体修飾の誤り。"}], "correct_answer": "に", "explanations": {"に": "「奥底には」の「に」。光が届く場所を示し、海の一番深い部分を場所として表すので自然。", "を": "「届く」は対象を取らない動詞なので、「奥底を」と目的語にすると文が成り立たない。", "が": "「奥底が」にすると主語が「光が」と二つ並び、「届きません」の主語として合わなくなる。", "の": "「奥底の」の後に名詞がなく、文が成り立たない。連体修飾の誤り。"}, "error_tags": {"を": "目的語の誤り", "が": "主語の誤り", "の": "連体修飾の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52831, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「奥底に」の「に」。鍵が「ありました」と存在する場所を示し、かばんの一番深い部分として自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞同士をつなぐだけで、「奥底の鍵がありました」では存在する場所が示されない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す語で、存在を表す「ありました」には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作が行われる場所を示すので、存在を表す「ありました」の場所には不自然。"}], "correct_answer": "に", "explanations": {"に": "「奥底に」の「に」。鍵が「ありました」と存在する場所を示し、かばんの一番深い部分として自然。", "の": "「の」は名詞同士をつなぐだけで、「奥底の鍵がありました」では存在する場所が示されない。", "へ": "「へ」は移動の方向を示す語で、存在を表す「ありました」には合わない。", "で": "「で」は動作が行われる場所を示すので、存在を表す「ありました」の場所には不自然。"}, "error_tags": {"の": "連体修飾の誤り", "へ": "方向の誤り", "で": "存在の場所の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52831, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いちばん下の深いところ。", "primary_collocate": null, "pronunciation": "おくそこ", "ipa": "okɯsoko", "syllable_count": 4, "sentences": [{"text": "心の奥底で、彼はまだ不安を感じていました。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "心[こころ]の奥底[おくそこ]で、彼[かれ]はまだ不安[ふあん]を感[かん]じていました。", "sentence_source": "generated"}, {"text": "海の奥底には、光がほとんど届きません。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "海[うみ]の奥底[おくそこ]には、光[ひかり]がほとんど届[とど]きません。", "sentence_source": "generated"}, {"text": "古い箱を引き出しの奥底から見つけました。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "古[ふる]い箱[はこ]を引[ひ]き出[だ]しの奥底[おくそこ]から見[み]つけました。", "sentence_source": "generated"}, {"text": "彼女は笑っていましたが、奥底には悲しみがありました。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は笑[わら]っていましたが、奥底[おくそこ]には悲[かな]しみがありました。", "sentence_source": "generated"}, {"text": "洞窟の奥底まで行くのは、とても危険です。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の奥底[おくそこ]まで行[い]くのは、とても危険[きけん]です。", "sentence_source": "generated"}, {"text": "心の奥底にしまっていた思い出が、ふとよみがえりました。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "心[こころ]の奥底[おくそこ]にしまっていた思い出[おもいで]が、ふとよみがえりました。", "sentence_source": "generated"}, {"text": "井戸の奥底は暗くて、水の音だけが聞こえました。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "井戸[いど]の奥底[おくそこ]は暗[くら]くて、水[みず]の音[おと]だけが聞[き]こえました。", "sentence_source": "generated"}, {"text": "かばんの奥底に、なくしたと思った鍵がありました。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "かばんの奥底[おくそこ]に、なくしたと思[おも]った鍵[かぎ]がありました。", "sentence_source": "generated"}, {"text": "彼の言葉は、私の心の奥底に残っています。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]は、私[わたし]の心[こころ]の奥底[おくそこ]に残[のこ]っています。", "sentence_source": "generated"}, {"text": "湖の奥底に、古い船がしずんでいるそうです。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "湖[みずうみ]の奥底[おくそこ]に、古[ふる]い船[ふね]がしずんでいるそうです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奥底", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物や心のいちばん深い底の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ac41b1-bf6a-4b52-9986-43adaca85130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52831, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奥底", "is_correct": true, "explanation": "心のいちばん深いところを表し、「心の奥底で不安を感じていた」と自然に続く。"}, {"text": "窓辺", "is_correct": false, "explanation": "窓辺は場所の一つだが、「心の窓辺」は不自然で、感情の深さを表せない。"}, {"text": "山頂", "is_correct": false, "explanation": "山頂は高い場所を指し、「心の山頂で不安を感じる」は意味が成り立たない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は生活の場所で、心の中の状態を示す語としては合わない。"}], "explanations": {"奥底": "心のいちばん深いところを表し、「心の奥底で不安を感じていた」と自然に続く。", "窓辺": "窓辺は場所の一つだが、「心の窓辺」は不自然で、感情の深さを表せない。", "山頂": "山頂は高い場所を指し、「心の山頂で不安を感じる」は意味が成り立たない。", "台所": "台所は生活の場所で、心の中の状態を示す語としては合わない。"}, "sentence_index": 0, "correct_answer": "奥底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖の奥底に、葉っぱが浮いていました。", "explanation": "ここは〈表面〉の意味。奥底は一番深い底の部分で、そこに浮いているという状況は成り立たない。"}, {"text": "山の奥底から、景色が見えました。", "explanation": "ここは〈頂上〉の意味。奥底は一番深い部分を指すので、高い所から景色が見える話には合わない。"}, {"text": "遠くから、かすかな奥底が聞こえました。", "explanation": "ここは〈音〉の意味。奥底は場所を表す名詞で、聞こえるものとしては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52831, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奥底", "is_correct": true, "explanation": "井戸のいちばん深い部分を指し、「暗くて水の音が聞こえた」という場面に合う。"}, {"text": "月給", "is_correct": false, "explanation": "月給は収入を表し、井戸の場所を示す文脈では成り立たない。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は日付を表し、井戸の様子を説明する文の主語として合わない。"}, {"text": "休日", "is_correct": false, "explanation": "休日は日付を表し、「井戸の休日は暗い」という内容は意味をなさない。"}], "explanations": {"奥底": "井戸のいちばん深い部分を指し、「暗くて水の音が聞こえた」という場面に合う。", "月給": "月給は収入を表し、井戸の場所を示す文脈では成り立たない。", "誕生日": "誕生日は日付を表し、井戸の様子を説明する文の主語として合わない。", "休日": "休日は日付を表し、「井戸の休日は暗い」という内容は意味をなさない。"}, "sentence_index": 6, "correct_answer": "奥底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の奥底を、友だちに伝えました。", "explanation": "ここは〈予定〉の意味。奥底は深いところを指すので、これから行う計画の説明には使わない。"}, {"text": "奥底が悪いので、遠足は中止になりました。", "explanation": "ここは〈天気〉の意味。奥底は場所を表す語で、空模様の状態は表せない。"}, {"text": "奥底を取ると、体の動きが遅くなります。", "explanation": "ここは〈年〉（年齢）の意味。「年を取る」の「年」の代わりに奥底を使うと、年齢の意味にはならず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52831, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "金庫の奥底を、大事な書類をしまいました。", "corrected_sentence": "金庫の奥底に、大事な書類をしまいました。", "error_description": "助詞の誤り。「しまう」は場所に「に」を使うので、「奥底に」が正しい。「奥底を」では目的語のように扱われ誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52831, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い手紙が、引き出しの奥底を眠っていました。", "corrected_sentence": "古い手紙が、引き出しの奥底に眠っていました。", "error_description": "助詞の誤り。「眠る」は場所を表す「に」を取るので、「奥底に」が正しい。「奥底を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52834, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「作られる」の材料を示す「で」。革が材料であることを表す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は行為者や相手を示すが、革が作り手になることはないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は作る行為の対象を示すが、受身文では使えないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、材料を表す文脈に合わない。"}], "correct_answer": "で", "explanations": {"で": "「作られる」の材料を示す「で」。革が材料であることを表す。", "に": "「に」は行為者や相手を示すが、革が作り手になることはないので合わない。", "を": "「を」は作る行為の対象を示すが、受身文では使えないので合わない。", "と": "「と」は並列や相手を示すので、材料を表す文脈に合わない。"}, "error_tags": {"に": "行為者の誤用", "を": "受身文の目的語", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52834, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「かたくて」の主語を示す「が」。革がかたい状態を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を取る動詞に付くので、形容詞「かたい」の主語には使えず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すので、かたさの主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「かたくて」の主語にはできない。"}], "correct_answer": "が", "explanations": {"が": "「かたくて」の主語を示す「が」。革がかたい状態を表す。", "を": "「を」は対象を取る動詞に付くので、形容詞「かたい」の主語には使えず不自然。", "に": "「に」は方向や相手を示すので、かたさの主語にはならない。", "で": "「で」は手段や場所を示すので、「かたくて」の主語にはできない。"}, "error_tags": {"を": "形容詞の目的語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52834, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物の皮をなめして加工したもの。バッグや靴、ベルトなどに使われる。", "primary_collocate": null, "pronunciation": "かわ", "ipa": "kawa", "syllable_count": 2, "sentences": [{"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "革", "complexity_tier": "T5", "furigana": "革[かわ]の匂[にお]いが漂[ただよ]う暗闇[くらやみ]の奥底[おくそこ]で、長[なが]き眠[ねむ]りについていたそれを引[ひ]きずり出[だ]した瞬間[しゅんかん]、埃[ほこり]っぽい記憶[きおく]の粒子[りゅうし]が舞[ま]い上[あ]がる。", "sentence_source": "mined"}, {"text": "このブーツは、なめした革で作られていて、履くほど足になじむ。", "target_word": "革", "complexity_tier": "T3", "furigana": "このブーツは、なめした革[かわ]で作[つく]られていて、履[は]くほど足[あし]になじむ。", "sentence_source": "generated"}, {"text": "古い革のベルトは、使うほど手になじんで柔らかくなる。", "target_word": "革", "complexity_tier": "T3", "furigana": "古[ふる]い革[かわ]のベルトは、使[つか]うほど手[て]になじんで柔[やわ]らかくなる。", "sentence_source": "generated"}, {"text": "この店では、丈夫な革でカバンや財布を一つずつ手作りしている。", "target_word": "革", "complexity_tier": "T3", "furigana": "この店[みせ]では、丈夫[じょうぶ]な革[かわ]でカバンや財布[さいふ]を一[ひと]つずつ手作[てづく]りしている。", "sentence_source": "generated"}, {"text": "雨に濡れた革の靴は、乾いたあとに専用のクリームを塗るとひびが入りにくい。", "target_word": "革", "complexity_tier": "T4", "furigana": "雨[あめ]に濡[ぬ]れた革[かわ]の靴[くつ]は、乾[かわ]いたあとに専用[せんよう]のクリームを塗[ぬ]るとひびが入[はい]りにくい。", "sentence_source": "generated"}, {"text": "兄は誕生日に、牛の革で作られた黒いベルトをもらった。", "target_word": "革", "complexity_tier": "T3", "furigana": "兄[あに]は誕生日[たんじょうび]に、牛[うし]の革[かわ]で作[つく]られた黒[くろ]いベルトをもらった。", "sentence_source": "generated"}, {"text": "革は水に弱いので、雨の日にこのバッグを持つのは避けたい。", "target_word": "革", "complexity_tier": "T3", "furigana": "革[かわ]は水[みず]に弱[よわ]いので、雨[あめ]の日[ひ]にこのバッグを持[も]つのは避[さ]けたい。", "sentence_source": "generated"}, {"text": "革がかたくて歩くと足が痛くなるため、新しい靴は少しずつ慣らしている。", "target_word": "革", "complexity_tier": "T4", "furigana": "革[かわ]がかたくて歩[ある]くと足[あし]が痛[いた]くなるため、新[あたら]しい靴[くつ]は少[すこ]しずつ慣[な]らしている。", "sentence_source": "generated"}, {"text": "本物の革は値段が高いが、十年以上使えるので結局は得だ。", "target_word": "革", "complexity_tier": "T4", "furigana": "本物[ほんもの]の革[かわ]は値段[ねだん]が高[たか]いが、十年[じゅうねん]以上[いじょう]使[つか]えるので結局[けっきょく]は得[とく]だ。", "sentence_source": "generated"}, {"text": "職人は、なめした革を型に合わせて切り、丁寧に縫い合わせていった。", "target_word": "革", "complexity_tier": "T4", "furigana": "職人[しょくにん]は、なめした革[かわ]を型[かた]に合[あ]わせて切[き]り、丁寧[ていねい]に縫[ぬ]い合[あ]わせていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "革", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "なめして加工した動物の皮。バッグ・靴・ベルトなどの素材", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 奥底 (Zipf 3.21), 長き (Zipf 3.3), 引きずり出し (Zipf 2.55), 舞い上がる (Zipf 2.61)']::text[], 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52834, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "革", "is_correct": true, "explanation": "なめした動物の皮を指し、「匂いが漂う」「眠っていた」という文脈に合う。"}, {"text": "鏡", "is_correct": false, "explanation": "鏡はガラス板で、匂いを漂わせる素材ではないので合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は機械で、匂いを放つ物ではないので、ここでは意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部で、匂いを漂わせる素材ではないので合わない。"}], "explanations": {"革": "なめした動物の皮を指し、「匂いが漂う」「眠っていた」という文脈に合う。", "鏡": "鏡はガラス板で、匂いを漂わせる素材ではないので合わない。", "時計": "時計は機械で、匂いを放つ物ではないので、ここでは意味が通らない。", "窓": "窓は建物の開口部で、匂いを漂わせる素材ではないので合わない。"}, "sentence_index": 0, "correct_answer": "革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "りんごの革をむいてから食べた。", "explanation": "ここは果物の外側の〈皮〉の意味。革は加工した動物の皮なので、果物には使わない。"}, {"text": "転んで膝の革がすりむけた。", "explanation": "ここは人の体の〈皮膚〉の意味。革は加工品なので、生きた体の皮には使わない。"}, {"text": "この出来事は社会の仕組みを根本から変える大きな革となった。", "explanation": "ここは〈変革〉の意味。革は単独で社会の大きな変化を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52834, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "革", "is_correct": true, "explanation": "水に弱い素材として、革が文脈の説明に合う。"}, {"text": "石", "is_correct": false, "explanation": "石は水に強く、「水に弱い」という文の内容と合わない。"}, {"text": "硝子", "is_correct": false, "explanation": "硝子は水で傷まない素材なので、「水に弱い」という文脈に合わない。"}, {"text": "ゴム", "is_correct": false, "explanation": "ゴムは水に強い素材で、文の述べる弱さと逆になる。"}], "explanations": {"革": "水に弱い素材として、革が文脈の説明に合う。", "石": "石は水に強く、「水に弱い」という文の内容と合わない。", "硝子": "硝子は水で傷まない素材なので、「水に弱い」という文脈に合わない。", "ゴム": "ゴムは水に強い素材で、文の述べる弱さと逆になる。"}, "sentence_index": 6, "correct_answer": "革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この猫の革は長い毛で覆われて、冬は暖かい。", "explanation": "毛が付いたままの皮を指す〈毛皮〉の意味。革は毛を除いて加工したものなので、毛のある皮には使わない。"}, {"text": "みかんの革をむくと、さわやかな香りが広がる。", "explanation": "果実の外側の〈果皮〉の意味。革は加工した動物の皮を指すので、果物には使わない。"}, {"text": "この木の革は厚く、雨でひび割れている。", "explanation": "木の外側の〈樹皮〉の意味。革は動物の皮から作るので、木には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52834, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この財布は革を作られていて、長持ちする。", "corrected_sentence": "この財布は革で作られていて、長持ちする。", "error_description": "「作られる」の材料は「で」で表す。「を」は作る対象に付く助詞なので、「革を作られて」は誤り。正しくは「革で作られて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
