INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52836, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校、特に中学校や高校で教育を受ける人。", "primary_collocate": null, "pronunciation": "せいと", "ipa": "seːto", "syllable_count": 3, "sentences": [{"text": "生徒たちが体育館で歌の練習をしている。", "target_word": "生徒たち", "complexity_tier": "T2", "furigana": "生徒[せいと]たちが体育館[たいいくかん]で歌[うた]の練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "生徒は教室で静かに本を読んでいる。", "target_word": "生徒", "complexity_tier": "T3", "furigana": "生徒[せいと]は教室[きょうしつ]で静[しず]かに本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "この学校には、約五百人の生徒がいます。", "target_word": "生徒", "complexity_tier": "T3", "furigana": "この学校[がっこう]には、約[やく]五百人[ごひゃくにん]の生徒[せいと]がいます。", "sentence_source": "generated"}, {"text": "先生は生徒に宿題を出した。", "target_word": "生徒", "complexity_tier": "T2", "furigana": "先生[せんせい]は生徒[せいと]に宿題[しゅくだい]を出[だ]した。", "sentence_source": "generated"}, {"text": "生徒の質問に、先生は丁寧に答えた。", "target_word": "生徒", "complexity_tier": "T2", "furigana": "生徒[せいと]の質問[しつもん]に、先生[せんせい]は丁寧[ていねい]に答[こた]えた。", "sentence_source": "generated"}, {"text": "欠席した生徒には、プリントを渡してください。", "target_word": "生徒", "complexity_tier": "T3", "furigana": "欠席[けっせき]した生徒[せいと]には、プリントを渡[わた]してください。", "sentence_source": "generated"}, {"text": "彼は生徒に好かれる先生だ。", "target_word": "生徒", "complexity_tier": "T4", "furigana": "彼[かれ]は生徒[せいと]に好[す]かれる先生[せんせい]だ。", "sentence_source": "generated"}, {"text": "生徒たちは先生の話を静かに聞いていた。", "target_word": "生徒たち", "complexity_tier": "T3", "furigana": "生徒[せいと]たちは先生[せんせい]の話[はなし]を静[しず]かに聞[き]いていた。", "sentence_source": "generated"}, {"text": "雨の日は、生徒が傘を持って登校する。", "target_word": "生徒", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、生徒[せいと]が傘[かさ]を持[も]って登校[とうこう]する。", "sentence_source": "generated"}, {"text": "授業中に生徒を立たせてはいけません。", "target_word": "生徒", "complexity_tier": "T4", "furigana": "授業中[じゅぎょうちゅう]に生徒[せいと]を立[た]たせてはいけません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生徒たち", "label": "派生"}, {"form": "生徒さん", "label": "敬語形"}], "register": "plain", "sense_fingerprint": "名詞 | 中学・高校などで学ぶ人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0dbfc7-ded3-42fa-8956-25a04f821c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52836, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生徒", "is_correct": true, "explanation": "「せいと」で、聞こえた語そのものです。"}, {"text": "制度", "is_correct": false, "explanation": "「せいど」で、最後の「と」が「ど」(清濁)に変わっています。"}, {"text": "世紀", "is_correct": false, "explanation": "「せいき」で、最後の「と」が「き」に変わっています。"}, {"text": "成果", "is_correct": false, "explanation": "「せいか」で、最後の「と」が「か」に変わっています。"}, {"text": "政府", "is_correct": false, "explanation": "「せいふ」で、最後の「と」が「ふ」に変わっています。"}], "explanations": {"生徒": "「せいと」で、聞こえた語そのものです。", "制度": "「せいど」で、最後の「と」が「ど」(清濁)に変わっています。", "世紀": "「せいき」で、最後の「と」が「き」に変わっています。", "成果": "「せいか」で、最後の「と」が「か」に変わっています。", "政府": "「せいふ」で、最後の「と」が「ふ」に変わっています。"}, "sentence_index": null, "correct_answer": "生徒"}, "level_3": {"options": [{"text": "生徒たち", "is_correct": true, "explanation": "学校で学ぶ人たちが歌の練習をするので、意味が合います。"}, {"text": "黒板", "is_correct": false, "explanation": "形は合うが、黒板は歌の練習をしないので意味が合わない。"}, {"text": "時計", "is_correct": false, "explanation": "形は合うが、時計は歌の練習をしないので意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机は歌の練習をしないので意味が合わない。"}], "explanations": {"生徒たち": "学校で学ぶ人たちが歌の練習をするので、意味が合います。", "黒板": "形は合うが、黒板は歌の練習をしないので意味が合わない。", "時計": "形は合うが、時計は歌の練習をしないので意味が合わない。", "机": "形は合うが、机は歌の練習をしないので意味が合わない。"}, "sentence_index": 0, "correct_answer": "生徒たち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は会社の生徒で、毎日残業している。", "explanation": "生徒は学校で学ぶ子どもを指し、会社で働く人には使えません。"}, {"text": "生徒は海の中で泳ぐ魚だ。", "explanation": "生徒は人であり、魚を表す語ではありません。"}, {"text": "この生徒は三年前に建てられた古い建物だ。", "explanation": "生徒は人を指す語で、建物の意味はありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52836, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生徒", "is_correct": true, "explanation": "「せいと」で、聞こえた語そのものです。"}, {"text": "政治", "is_correct": false, "explanation": "「せいじ」で、最後の「と」が「じ」に変わっています。"}, {"text": "毛糸", "is_correct": false, "explanation": "「けいと」で、最初の「せ」が「け」に変わっています。"}, {"text": "帝都", "is_correct": false, "explanation": "「ていと」で、最初の「せ」が「て」に変わっています。"}, {"text": "整理", "is_correct": false, "explanation": "「せいり」で、最後の「と」が「り」に変わっています。"}], "explanations": {"生徒": "「せいと」で、聞こえた語そのものです。", "政治": "「せいじ」で、最後の「と」が「じ」に変わっています。", "毛糸": "「けいと」で、最初の「せ」が「け」に変わっています。", "帝都": "「ていと」で、最初の「せ」が「て」に変わっています。", "整理": "「せいり」で、最後の「と」が「り」に変わっています。"}, "sentence_index": null, "correct_answer": "生徒"}, "level_3": {"options": [{"text": "生徒", "is_correct": true, "explanation": "先生に好かれるのは学ぶ人なので、意味が合います。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机は人に「好かれる」関係にならず意味が合わない。"}, {"text": "時計", "is_correct": false, "explanation": "形は合うが、時計が先生を好きになるという意味にならない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが、電車が人を好きになるという意味にならない。"}], "explanations": {"生徒": "先生に好かれるのは学ぶ人なので、意味が合います。", "机": "形は合うが、机は人に「好かれる」関係にならず意味が合わない。", "時計": "形は合うが、時計が先生を好きになるという意味にならない。", "電車": "形は合うが、電車が人を好きになるという意味にならない。"}, "sentence_index": 6, "correct_answer": "生徒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病院で働く生徒が患者を診察した。", "explanation": "生徒は学ぶ側の人で、診察する職業の人には使えません。"}, {"text": "この生徒は、木の枝に実る赤い果物だ。", "explanation": "生徒は人を指す語で、果物の意味はありません。"}, {"text": "私の父は会社の生徒で、部長をしている。", "explanation": "生徒は学校の子どもで、会社員には使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED