INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52841, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が着るための服のことです。", "primary_collocate": null, "pronunciation": "ひふく", "ipa": "çiɸɯkɯ", "syllable_count": 3, "sentences": [{"text": "被服を買う。", "target_word": "被服", "complexity_tier": "T1", "furigana": "ひふくをかう。", "sentence_source": "generated"}, {"text": "被服が多い。", "target_word": "被服", "complexity_tier": "T1", "furigana": "ひふくがおおい。", "sentence_source": "generated"}, {"text": "この店は被服を売っています。", "target_word": "被服", "complexity_tier": "T2", "furigana": "このみせはひふくをうっています。", "sentence_source": "generated"}, {"text": "学校で決まった被服を着ます。", "target_word": "被服", "complexity_tier": "T2", "furigana": "がっこうできまったひふくをきます。", "sentence_source": "generated"}, {"text": "被服の工場で働く父は、毎日とても忙しい。", "target_word": "被服", "complexity_tier": "T3", "furigana": "ひふくのこうじょうではたらくちちは、まいにちとてもいそがしい。", "sentence_source": "generated"}, {"text": "子どもの被服は、すぐ小さくなってしまう。", "target_word": "被服", "complexity_tier": "T3", "furigana": "こどものひふくは、すぐちいさくなってしまう。", "sentence_source": "generated"}, {"text": "災害で被服を失った人たちに、支援団体が服を配った。", "target_word": "被服", "complexity_tier": "T4", "furigana": "さいがいでひふくをうしなったひとたちに、しえんだんたいがふくをくばった。", "sentence_source": "generated"}, {"text": "被服が汚れたら、洗ってから乾かしておいてください。", "target_word": "被服", "complexity_tier": "T4", "furigana": "ひふくがよごれたら、あらってからかわかしておいてください。", "sentence_source": "generated"}, {"text": "季節によって被服を選ぶ基準は変わり、夏は涼しさが一番大切になる。", "target_word": "被服", "complexity_tier": "T5", "furigana": "きせつによってひふくをえらぶきじゅんはかわり、なつはすずしさがいちばんたいせつになる。", "sentence_source": "generated"}, {"text": "被服にかかる費用を見直したところ、家計に少し余裕ができた。", "target_word": "被服", "complexity_tier": "T5", "furigana": "ひふくにかかるひようをみなおしたところ、かけいにすこしよゆうができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "被服費", "label": "派生"}, {"form": "被服学", "label": "派生"}, {"form": "被服製作", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 人が着るための服のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52841, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "被服", "is_correct": true, "explanation": "見出し語そのもので、正しい発音です。"}, {"text": "私服", "is_correct": false, "explanation": "「ひ」が「し」に変わった別の語です。"}, {"text": "比較", "is_correct": false, "explanation": "「ふ」が「か」に変わった別の語です。"}, {"text": "被告", "is_correct": false, "explanation": "「ふ」が「こ」に変わった別の語です。"}], "explanations": {"被服": "見出し語そのもので、正しい発音です。", "私服": "「ひ」が「し」に変わった別の語です。", "比較": "「ふ」が「か」に変わった別の語です。", "被告": "「ふ」が「こ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "被服"}, "level_3": {"options": [{"text": "被服", "is_correct": true, "explanation": "「被服を買う」で、衣服を買う意味に合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「買う」対象として意味が合わない。"}, {"text": "空", "is_correct": false, "explanation": "形は合うが、「買う」対象として意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「買う」対象として意味が合わない。"}], "explanations": {"被服": "「被服を買う」で、衣服を買う意味に合います。", "天気": "形は合うが、「買う」対象として意味が合わない。", "空": "形は合うが、「買う」対象として意味が合わない。", "地震": "形は合うが、「買う」対象として意味が合わない。"}, "sentence_index": 0, "correct_answer": "被服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校で決まった被服を飲みます。", "explanation": "被服は着るもので、飲み物ではないので意味が誤り。"}, {"text": "学校で決まった被服が走って、教室に入りました。", "explanation": "被服は物で、自分で走る主体としては使えない。"}, {"text": "学校で決まった被服の水が深いです。", "explanation": "被服は水の深さを持つ場所ではないので意味が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52841, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "被服", "is_correct": true, "explanation": "見出し語そのもので、正しい発音です。"}, {"text": "皮膜", "is_correct": false, "explanation": "「ふ」が「ま」に変わった別の語です。"}, {"text": "肥沃", "is_correct": false, "explanation": "「ふ」が「よ」に変わった別の語です。"}, {"text": "至福", "is_correct": false, "explanation": "「ひ」が「し」に変わった別の語です。"}], "explanations": {"被服": "見出し語そのもので、正しい発音です。", "皮膜": "「ふ」が「ま」に変わった別の語です。", "肥沃": "「ふ」が「よ」に変わった別の語です。", "至福": "「ひ」が「し」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "被服"}, "level_3": {"options": [{"text": "被服", "is_correct": true, "explanation": "災害で失ったのは衣服で、支援団体が服を配る文脈に合います。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、「失う」対象として、服を配る文脈に意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「失う」対象として意味が合わない。"}, {"text": "時差", "is_correct": false, "explanation": "形は合うが、「失う」対象として意味が合わない。"}], "explanations": {"被服": "災害で失ったのは衣服で、支援団体が服を配る文脈に合います。", "気温": "形は合うが、「失う」対象として、服を配る文脈に意味が合わない。", "天気": "形は合うが、「失う」対象として意味が合わない。", "時差": "形は合うが、「失う」対象として意味が合わない。"}, "sentence_index": 6, "correct_answer": "被服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "被服を毎朝焼いて食べたところ、家計に少し余裕ができた。", "explanation": "被服は着る物で、焼いて食べる物ではないので意味が誤り。"}, {"text": "被服が笑って話しかけたので、家計に余裕ができた。", "explanation": "被服は物であり、笑って話しかける主体としては使えない。"}, {"text": "被服に乗って通勤したところ、交通費が少し浮いた。", "explanation": "被服は乗り物ではないので、「乗る」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52841, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は被服に買いました。", "corrected_sentence": "姉は被服を買いました。", "error_description": "「買う」の対象は「を」で表す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52841, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は汚れた被服が洗濯機に入れた。", "corrected_sentence": "弟は汚れた被服を洗濯機に入れた。", "error_description": "「入れる」の対象は「を」で表す。「被服が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52843, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「立った」の主語を示す「が」。白い埃が立つ状態を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、「立つ」は目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所を示すので、立つ主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「立った」の主語を示す「が」。白い埃が立つ状態を表す。", "を": "「を」は他動詞の目的語を示すが、「立つ」は目的語を取らないので合わない。", "に": "「に」は場所を示すので、立つ主語にはならない。", "で": "「で」は手段や場所を示すので、主語にはならない。"}, "error_tags": {"を": "自動詞の目的語", "に": "場所", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52843, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「照らされて」の主語を示す「が」。埃が日差しに照らされる主語になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、照らされる主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、主語にはできない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、受身文の主語には使えないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「照らされて」の主語を示す「が」。埃が日差しに照らされる主語になる。", "で": "「で」は手段や場所を示すので、照らされる主語にはならない。", "と": "「と」は並列や相手を示すので、主語にはできない。", "を": "「を」は他動詞の目的語を示すが、受身文の主語には使えないので合わない。"}, "error_tags": {"で": "手段・場所", "と": "並列・相手", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52843, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ちりやごみが空にふわっととぶこと。", "primary_collocate": null, "pronunciation": "ほこり", "ipa": "hokoɾi", "syllable_count": 3, "sentences": [{"text": "風が強い日は、校庭の埃が舞って目を開けていられない。", "target_word": "埃", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、校庭[こうてい]の埃[ほこり]が舞[ま]って目[め]を開[あ]けていられない。", "sentence_source": "generated"}, {"text": "布団をたたくと、白い埃がぱっと立った。", "target_word": "埃", "complexity_tier": "T3", "furigana": "布団[ふとん]をたたくと、白[しろ]い埃[ほこり]がぱっと立[た]った。", "sentence_source": "generated"}, {"text": "走るトラックの後ろで、埃がもうもうと上がっている。", "target_word": "埃", "complexity_tier": "T4", "furigana": "走[はし]るトラックの後[うし]ろで、埃[ほこり]がもうもうと上[あ]がっている。", "sentence_source": "generated"}, {"text": "埃を立てないように、そっとカーペットの上を歩いた。", "target_word": "埃", "complexity_tier": "T3", "furigana": "埃[ほこり]を立[た]てないように、そっとカーペットの上[うえ]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "古い図書館の本を動かしたとたん、埃が舞い、私は何度もくしゃみをした。", "target_word": "埃", "complexity_tier": "T4", "furigana": "古[ふる]い図書館[としょかん]の本[ほん]を動[うご]かしたとたん、埃[ほこり]が舞[ま]い、私[わたし]は何度[なんど]もくしゃみをした。", "sentence_source": "generated"}, {"text": "砂利道を自転車で走ると、後ろに埃が上がって友達に怒られた。", "target_word": "埃", "complexity_tier": "T4", "furigana": "砂利道[じゃりみち]を自転車[じてんしゃ]で走[はし]ると、後[うし]ろに埃[ほこり]が上[あ]がって友達[ともだち]に怒[おこ]られた。", "sentence_source": "generated"}, {"text": "掃除機をかける前にはたきをかけると、埃が部屋じゅうに広がってしまう。", "target_word": "埃", "complexity_tier": "T4", "furigana": "掃除機[そうじき]をかける前[まえ]にはたきをかけると、埃[ほこり]が部屋[へや]じゅうに広[ひろ]がってしまう。", "sentence_source": "generated"}, {"text": "埃が日差しに照らされて、部屋の中が霧のように白く見えた。", "target_word": "埃", "complexity_tier": "T4", "furigana": "埃[ほこり]が日差[ひざ]しに照[て]らされて、部屋[へや]の中[なか]が霧[きり]のように白[しろ]く見[み]えた。", "sentence_source": "generated"}, {"text": "馬が駆け抜けたあとには、長いあいだ埃が空に残っていた。", "target_word": "埃", "complexity_tier": "T4", "furigana": "馬[うま]が駆[か]け抜[ぬ]けたあとには、長[なが]いあいだ埃[ほこり]が空[そら]に残[のこ]っていた。", "sentence_source": "generated"}, {"text": "工事の音とともに埃が大量に飛んできて、近所の人たちは慌てて窓を閉めた。", "target_word": "埃", "complexity_tier": "T4", "furigana": "工事[こうじ]の音[おと]とともに埃[ほこり]が大量[たいりょう]に飛[と]んできて、近所[きんじょ]の人[ひと]たちは慌[あわ]てて窓[まど]を閉[し]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "埃", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ちりやごみが空中にふわっと飛び立つこと・その状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T4: contains vocabulary far above tier T4: もうもうと (Zipf 1.2)']::text[], 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52843, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "埃", "is_correct": true, "explanation": "「舞う」の主語で、校庭のちりが空に舞う文脈に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は舞うものではないので、「校庭の雨が舞って」は意味が通らない。"}, {"text": "記憶", "is_correct": false, "explanation": "記憶は舞わない抽象語で、校庭の描写に合わない。"}, {"text": "音", "is_correct": false, "explanation": "音は舞うものではなく、校庭の描写に合わない。"}], "explanations": {"埃": "「舞う」の主語で、校庭のちりが空に舞う文脈に合う。", "雨": "雨は舞うものではないので、「校庭の雨が舞って」は意味が通らない。", "記憶": "記憶は舞わない抽象語で、校庭の描写に合わない。", "音": "音は舞うものではなく、校庭の描写に合わない。"}, "sentence_index": 0, "correct_answer": "埃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑さで、額の埃が流れ落ちた。", "explanation": "〈汗〉の意味。汗は体から出る液体で、ちりの埃とは別物。"}, {"text": "鍋を開けると、熱い埃が立ち上った。", "explanation": "〈湯気〉の意味。湯気は熱い水が蒸発したもので、鍋から埃は出ない。"}, {"text": "洗剤を入れると、埃がぶくぶくと立った。", "explanation": "〈泡〉の意味。泡は洗剤などでできるもので、洗剤から埃は生じない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52843, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "埃", "is_correct": true, "explanation": "「広がってしまう」の主語で、ほこりが部屋に広がる文脈に合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は部屋に広がるものではないので合わない。"}, {"text": "床", "is_correct": false, "explanation": "床は広がるものではなく、「部屋じゅうに広がる」の主語にはならない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は部屋じゅうに広がるものではないので、文の意味が通らない。"}], "explanations": {"埃": "「広がってしまう」の主語で、ほこりが部屋に広がる文脈に合う。", "窓": "窓は部屋に広がるものではないので合わない。", "床": "床は広がるものではなく、「部屋じゅうに広がる」の主語にはならない。", "椅子": "椅子は部屋じゅうに広がるものではないので、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "埃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桜の埃が校庭に舞って、春の景色になった。", "explanation": "〈花びら〉の意味。花びらは植物の花の一部で、物から出るちりの埃とは別物。"}, {"text": "庭の池に、埃の魚が泳いでいた。", "explanation": "〈魚〉の意味。魚は生き物で、ちりの埃とは別物。"}, {"text": "転んだひざの埃から、赤い液がにじんだ。", "explanation": "〈血〉の意味。血は体の液体で、ちりの埃とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52843, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を開けると、風で埃を舞い込んだ。", "corrected_sentence": "窓を開けると、風で埃が舞い込んだ。", "error_description": "「舞い込む」の主語は「が」で示す。「を」は他動詞の目的語に使うので、ここでは誤り。正しくは「埃が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52843, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "車が通ると、道の埃に舞い上がった。", "corrected_sentence": "車が通ると、道の埃が舞い上がった。", "error_description": "「舞い上がる」の主語は「が」で示す。「に」は場所や相手を示すので、ここでは誤り。正しくは「埃が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52844, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「積もる」の主語を示す「が」。埃がたまる状態を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、「積もる」は目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所を示すので、埃が主語の文では使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、積もる主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「積もる」の主語を示す「が」。埃がたまる状態を表す。", "を": "「を」は他動詞の目的語を示すが、「積もる」は目的語を取らないので合わない。", "に": "「に」は場所を示すので、埃が主語の文では使えない。", "で": "「で」は手段や場所を示すので、積もる主語にはならない。"}, "error_tags": {"を": "目的語", "に": "場所", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52844, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「気をつける」の対象を示す「に」。埃について注意していることを表す。"}, {"text": "を", "is_correct": false, "explanation": "「気を」の「を」がすでにあるので、埃に重ねて「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、気をつける対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、気をつける対象の埃には使えない。"}], "correct_answer": "に", "explanations": {"に": "「気をつける」の対象を示す「に」。埃について注意していることを表す。", "を": "「気を」の「を」がすでにあるので、埃に重ねて「を」は使えない。", "で": "「で」は手段や場所を示すので、気をつける対象にはならない。", "と": "「と」は並列や相手を示すので、気をつける対象の埃には使えない。"}, "error_tags": {"を": "目的語の重複", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52844, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ほこり。物の表面や空気中にうかぶ細かいちり。また、そのような状態であること。", "primary_collocate": null, "pronunciation": "ほこり", "ipa": "hokoɾi", "syllable_count": 3, "sentences": [{"text": "古いぬいぐるみの耳に、細かい埃がついていた。", "target_word": "埃", "complexity_tier": "T3", "furigana": "古[ふる]いぬいぐるみの耳[みみ]に、細[こま]かい埃[ほこり]がついていた。", "sentence_source": "generated"}, {"text": "棚の上に埃が積もっていたので、雑巾で丁寧に拭いた。", "target_word": "埃", "complexity_tier": "T3", "furigana": "棚[たな]の上[うえ]に埃[ほこり]が積[つ]もっていたので、雑巾[ぞうきん]で丁寧[ていねい]に拭[ふ]いた。", "sentence_source": "generated"}, {"text": "長い間使っていない部屋は、どこも埃だらけだった。", "target_word": "埃", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]使[つか]っていない部屋[へや]は、どこも埃[ほこり]だらけだった。", "sentence_source": "generated"}, {"text": "本の埃を払ってから、段ボール箱に詰めた。", "target_word": "埃", "complexity_tier": "T3", "furigana": "本[ほん]の埃[ほこり]を払[はら]ってから、段[だん]ボール箱[ばこ]に詰[つ]めた。", "sentence_source": "generated"}, {"text": "掃除機をかけたのに、ベッドの下にはまだ埃が残っている。", "target_word": "埃", "complexity_tier": "T3", "furigana": "掃除機[そうじき]をかけたのに、ベッドの下[した]にはまだ埃[ほこり]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "窓を開けると、日の光の中に細かい埃がきらきらと見えた。", "target_word": "埃", "complexity_tier": "T4", "furigana": "窓[まど]を開[あ]けると、日[ひ]の光[ひかり]の中[なか]に細[こま]かい埃[ほこり]がきらきらと見[み]えた。", "sentence_source": "generated"}, {"text": "古い時計は埃をかぶっていて、針も止まったままだった。", "target_word": "埃", "complexity_tier": "T4", "furigana": "古[ふる]い時計[とけい]は埃[ほこり]をかぶっていて、針[はり]も止[と]まったままだった。", "sentence_source": "generated"}, {"text": "喘息の子がいるので、家の埃には特に気をつけている。", "target_word": "埃", "complexity_tier": "T4", "furigana": "喘息[ぜんそく]の子[こ]がいるので、家[いえ]の埃[ほこり]には特[とく]に気[き]をつけている。", "sentence_source": "generated"}, {"text": "引っ越しの日、押し入れの奥から出てきた荷物は埃にまみれていた。", "target_word": "埃", "complexity_tier": "T4", "furigana": "引[ひ]っ越[こ]しの日[ひ]、押[お]し入[い]れの奥[おく]から出[で]てきた荷物[にもつ]は埃[ほこり]にまみれていた。", "sentence_source": "generated"}, {"text": "工事の現場の近くを通ると、服や髪に埃がつく。", "target_word": "埃", "complexity_tier": "T3", "furigana": "工事[こうじ]の現場[げんば]の近[ちか]くを通[とお]ると、服[ふく]や髪[かみ]に埃[ほこり]がつく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "埃", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物の上や空気中にたまる・うかぶ細かいちり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52844, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "埃", "is_correct": true, "explanation": "耳に細かいちりがついている描写に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は耳につくものではなく、この文には合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は細かく耳につくものではなく、この文には合わない。"}, {"text": "風", "is_correct": false, "explanation": "風は物として耳につかず、この文には合わない。"}], "explanations": {"埃": "耳に細かいちりがついている描写に合う。", "雨": "雨は耳につくものではなく、この文には合わない。", "紙": "紙は細かく耳につくものではなく、この文には合わない。", "風": "風は物として耳につかず、この文には合わない。"}, "sentence_index": 0, "correct_answer": "埃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑さで、額の埃が流れ落ちた。", "explanation": "〈汗〉の意味。汗は体から出る液体で、ちりの埃とは別物。"}, {"text": "転んだひざの埃から、赤い液がにじんだ。", "explanation": "〈血〉の意味。血は体の液体で、ちりの埃とは別物。"}, {"text": "悲しい映画で、頬の埃がこぼれた。", "explanation": "〈涙〉の意味。涙は目から出る液体で、ちりの埃とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52844, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "埃", "is_correct": true, "explanation": "「かぶる」の目的語として、ほこりが時計の表面にたまる文脈に合う。"}, {"text": "石", "is_correct": false, "explanation": "石は時計にかぶせるものではなく、かぶる目的語として不自然。"}, {"text": "皿", "is_correct": false, "explanation": "皿は器で、物の表面にかぶるものではないので合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の一部で、時計をかぶるものではないので合わない。"}], "explanations": {"埃": "「かぶる」の目的語として、ほこりが時計の表面にたまる文脈に合う。", "石": "石は時計にかぶせるものではなく、かぶる目的語として不自然。", "皿": "皿は器で、物の表面にかぶるものではないので合わない。", "窓": "窓は建物の一部で、時計をかぶるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "埃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷凍庫の中で、埃が固まって氷になった。", "explanation": "〈氷〉の意味。氷は水が凍ったもので、埃からはできない。"}, {"text": "揚げ物の鍋から、埃がはねて手についた。", "explanation": "〈油〉の意味。油は液体で、ちりの埃とは別物。"}, {"text": "雨の日に、埃が水になって流れた。", "explanation": "〈水〉の意味。埃が水になることはなく、液体の水とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52844, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の桟に埃を積もっていたので、そっと拭いた。", "corrected_sentence": "窓の桟に埃が積もっていたので、そっと拭いた。", "error_description": "「積もる」は自動詞なので、積もるものは「が」で示す。「を」は他動詞の目的語に付くので、ここでは誤り。正しくは「埃が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52844, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風が吹くと、埃で舞い上がった。", "corrected_sentence": "風が吹くと、埃が舞い上がった。", "error_description": "「舞い上がる」の主語は「が」で示す。「で」は手段や場所を表すので、ここでは誤り。正しくは「埃が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
