INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52845, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、ひっぱってうごかすこと。", "primary_collocate": null, "pronunciation": "ひきずる", "ipa": "çikizɯɾɯ", "syllable_count": 4, "sentences": [{"text": "重い荷物を、床の上で引き摺って運んだ。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を、床[ゆか]の上[うえ]で引[ひ]き摺[ず]って運[はこ]んだ。", "sentence_source": "generated"}, {"text": "重い鉄の箱を、ロープで引き摺って倉庫まで運んだ。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "重[おも]い鉄[てつ]の箱[はこ]を、ロープで引[ひ]き摺[ず]って倉庫[そうこ]まで運[はこ]んだ。", "sentence_source": "generated"}, {"text": "弟は大きな袋を引き摺って、階段を上がった。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "弟[おとうと]は大[おお]きな袋[ふくろ]を引[ひ]き摺[ず]って、階段[かいだん]を上[あ]がった。", "sentence_source": "generated"}, {"text": "雪の上に重い箱を引き摺ったので、長い跡が残った。", "target_word": "引き摺った", "complexity_tier": "T3", "furigana": "雪[ゆき]の上[うえ]に重[おも]い箱[はこ]を引[ひ]き摺[ず]ったので、長[なが]い跡[あと]が残[のこ]った。", "sentence_source": "generated"}, {"text": "犬が散歩の途中でリードを引き摺って逃げてしまった。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "犬[いぬ]が散歩[さんぽ]の途中[とちゅう]でリードを引[ひ]き摺[ず]って逃[に]げてしまった。", "sentence_source": "generated"}, {"text": "木の枝を引き摺ると、地面に線が描けるよ。", "target_word": "引き摺る", "complexity_tier": "T3", "furigana": "木[き]の枝[えだ]を引[ひ]き摺[ず]ると、地面[じめん]に線[せん]が描[えが]けるよ。", "sentence_source": "generated"}, {"text": "机を引き摺ったせいで、床に傷がついてしまった。", "target_word": "引き摺った", "complexity_tier": "T3", "furigana": "机[つくえ]を引[ひ]き摺[ず]ったせいで、床[ゆか]に傷[きず]がついてしまった。", "sentence_source": "generated"}, {"text": "布団を引き摺って運ぶと汚れるから、持ち上げてください。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "布団[ふとん]を引[ひ]き摺[ず]って運[はこ]ぶと汚[よご]れるから、持[も]ち上[あ]げてください。", "sentence_source": "generated"}, {"text": "大きな魚を網ごと引き摺って、岸まで上げた。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "大[おお]きな魚[さかな]を網[あみ]ごと引[ひ]き摺[ず]って、岸[きし]まで上[あ]げた。", "sentence_source": "generated"}, {"text": "重すぎてスーツケースが持ち上がらず、引き摺って駅まで歩いた。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "重[おも]すぎてスーツケースが持[も]ち上[あ]がらず、引[ひ]き摺[ず]って駅[えき]まで歩[ある]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引き摺る", "label": "辞書形"}, {"form": "引き摺り", "label": "連用形"}, {"form": "引き摺って", "label": "て形"}, {"form": "引き摺った", "label": "過去形"}, {"form": "引き摺らない", "label": "否定形"}, {"form": "引き摺れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "重いものや長いものを持ち上げず、引っ張って動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52845, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引き摺って", "is_correct": true, "explanation": "床の上で物を擦らせながら運ぶ動作で、文の意味に合う。"}, {"text": "眺めて", "is_correct": false, "explanation": "見つめる動作で、荷物を運ぶ場面の説明にはならない。"}, {"text": "磨いて", "is_correct": false, "explanation": "表面を擦って光らせる動作で、運ぶ行為を表す語としては合わない。"}, {"text": "折って", "is_correct": false, "explanation": "曲げて割る動作で、運ぶ行為とはつながらない。"}], "explanations": {"引き摺って": "床の上で物を擦らせながら運ぶ動作で、文の意味に合う。", "眺めて": "見つめる動作で、荷物を運ぶ場面の説明にはならない。", "磨いて": "表面を擦って光らせる動作で、運ぶ行為を表す語としては合わない。", "折って": "曲げて割る動作で、運ぶ行為とはつながらない。"}, "sentence_index": 0, "correct_answer": "引き摺って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い箱を両手で引き摺って、棚の上に置いた。", "explanation": "ここは〈持ち上げる〉の意味。引き摺るは地面に擦らせて動かすことなので、物を持ち上げて棚に載せる動作には合わない。"}, {"text": "失恋をいつまでも引き摺って、なかなか立ち直れない。", "explanation": "ここは〈いつまでも気にかける〉の意味。物を引っ張って動かす意味ではなく、心に残る影響を指すので、この文は誤り。"}, {"text": "ガラスの汚れを布で引き摺ると、きれいになる。", "explanation": "ここは〈擦る〉の意味。引き摺るは物を引っ張って動かすことで、汚れを拭う動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52845, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引き摺った", "is_correct": true, "explanation": "机を床に擦らせて動かした結果、床に傷がつく流れに合う。"}, {"text": "撫でた", "is_correct": false, "explanation": "手でなでる動作で、床に傷がつく原因にはならない。"}, {"text": "組み立てた", "is_correct": false, "explanation": "部品をつなげる動作で、床に傷がつく原因として不自然。"}, {"text": "塗った", "is_correct": false, "explanation": "表面に色を重ねる動作で、床に傷がつく流れには合わない。"}], "explanations": {"引き摺った": "机を床に擦らせて動かした結果、床に傷がつく流れに合う。", "撫でた": "手でなでる動作で、床に傷がつく原因にはならない。", "組み立てた": "部品をつなげる動作で、床に傷がつく原因として不自然。", "塗った": "表面に色を重ねる動作で、床に傷がつく流れには合わない。"}, "sentence_index": 6, "correct_answer": "引き摺った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "重い荷物を肩に引き摺って、駅まで歩いた。", "explanation": "ここは〈担ぐ〉の意味。引き摺るは地面に擦らせて動かすことで、肩に乗せて運ぶ場面には合わない。"}, {"text": "壊れかけた柱を、両手で引き摺って支えた。", "explanation": "ここは〈支える〉の意味（倒れないように押さえる）。引き摺るは地面に擦らせて動かすことで、物を押さえて保つ動作には合わない。"}, {"text": "天井から重いランプを引き摺って、部屋を明るくした。", "explanation": "ここは〈吊るす〉の意味。引き摺るは床や地面を擦って動かすことで、天井から吊り下げる行為には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52845, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い石が庭の端まで引き摺った。", "corrected_sentence": "重い石を庭の端まで引き摺った。", "error_description": "格助詞の誤り。「引き摺る」は動かす対象に「を」を取るので、「石が」ではなく「石を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引き摺って", "is_correct": true, "explanation": "て形。後ろの「運んだ」へつなぎ、動作を続けて述べる。"}, {"text": "引き摺ろう", "is_correct": false, "explanation": "意向形。「ろう」は意志を表すので、過去の動作を述べる「運んだ」へはつながらない。"}, {"text": "引き摺れば", "is_correct": false, "explanation": "仮定形。条件を表す形になり、この文の動作の説明と合わない。"}, {"text": "引き摺らない", "is_correct": false, "explanation": "否定形。「引き摺らない倉庫まで」となり、文の意味が変わって不自然。"}], "correct_form": "引き摺って", "base_form": "引き摺る", "form_label": "て形（後ろの動詞へつなぐ）", "sentence_index": 1, "explanations": {"引き摺って": "て形。後ろの「運んだ」へつなぎ、動作を続けて述べる。", "引き摺ろう": "意向形。「ろう」は意志を表すので、過去の動作を述べる「運んだ」へはつながらない。", "引き摺れば": "仮定形。条件を表す形になり、この文の動作の説明と合わない。", "引き摺らない": "否定形。「引き摺らない倉庫まで」となり、文の意味が変わって不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52845, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は机を引き摺てしまい、床が傷ついた。", "corrected_sentence": "彼は机を引き摺ってしまい、床が傷ついた。", "error_description": "て形の誤り。「引き摺る」のて形は促音を入れて「引き摺って」とする。「引き摺て」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引き摺って", "is_correct": true, "explanation": "て形。後ろの「運ぶ」へつなぎ、「引きずりながら運ぶ」の意味になる。"}, {"text": "引き摺る", "is_correct": false, "explanation": "辞書形。「運ぶ」の前に直接置くと文が成り立たない。"}, {"text": "引き摺らない", "is_correct": false, "explanation": "否定形。「運ぶと汚れる」の前提となる動作として、文の流れに合わない。"}, {"text": "引き摺った", "is_correct": false, "explanation": "過去形。「運ぶと汚れる」という一般的な条件を表せず不自然。"}], "correct_form": "引き摺って", "base_form": "引き摺る", "form_label": "て形（後ろの「運ぶ」へつなぐ）", "sentence_index": 7, "explanations": {"引き摺って": "て形。後ろの「運ぶ」へつなぎ、「引きずりながら運ぶ」の意味になる。", "引き摺る": "辞書形。「運ぶ」の前に直接置くと文が成り立たない。", "引き摺らない": "否定形。「運ぶと汚れる」の前提となる動作として、文の流れに合わない。", "引き摺った": "過去形。「運ぶと汚れる」という一般的な条件を表せず不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52846, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "受身の動作主（車）を示す「に」で、「引き摺られた」に直接かかるので正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。受身文の動作主には使えず、「車を引き摺られた」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「車が引き摺られた」は受身の動作主の示し方として誤り。"}, {"text": "と", "is_correct": false, "explanation": "共同や相手を示す「と」。受身の動作主には使えず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "受身の動作主（車）を示す「に」で、「引き摺られた」に直接かかるので正しい。", "を": "目的語を示す「を」。受身文の動作主には使えず、「車を引き摺られた」は不自然。", "が": "主語を示す「が」。「車が引き摺られた」は受身の動作主の示し方として誤り。", "と": "共同や相手を示す「と」。受身の動作主には使えず、文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "が": "主語の誤り", "と": "相手・共同の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52846, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52846, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を地面などにこすりながら引っ張る。また、無理に連れて行く。", "primary_collocate": null, "pronunciation": "ひきずる", "ipa": "çikizɯɾɯ", "syllable_count": 4, "sentences": [{"text": "母は嫌がる弟を引き摺って、病院へ連れていった。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "母[はは]は嫌[いや]がる弟[おとうと]を引[ひ]き摺[ず]って、病院[びょういん]へ連[つ]れていった。", "sentence_source": "generated"}, {"text": "車に引き摺られた荷物が、道路に長い傷を残した。", "target_word": "引き摺られた", "complexity_tier": "T3", "furigana": "車[くるま]に引[ひ]き摺[ず]られた荷物[にもつ]が、道路[どうろ]に長[なが]い傷[きず]を残[のこ]した。", "sentence_source": "generated"}, {"text": "彼はコートの裾を雪の上に引き摺りながら歩いた。", "target_word": "引き摺り", "complexity_tier": "T3", "furigana": "彼[かれ]はコートの裾[すそ]を雪[ゆき]の上[うえ]に引[ひ]き摺[ず]りながら歩[ある]いた。", "sentence_source": "generated"}, {"text": "酔った友達を、みんなで家まで引き摺って帰った。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "酔[よ]った友達[ともだち]を、みんなで家[いえ]まで引[ひ]き摺[ず]って帰[かえ]った。", "sentence_source": "generated"}, {"text": "警備員が男を引き摺って、会場の外へ出した。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "警備員[けいびいん]が男[おとこ]を引[ひ]き摺[ず]って、会場[かいじょう]の外[そと]へ出[だ]した。", "sentence_source": "generated"}, {"text": "重いタイヤを地面に引き摺ると、ごろごろと大きな音がした。", "target_word": "引き摺る", "complexity_tier": "T3", "furigana": "重[おも]いタイヤを地面[じめん]に引[ひ]き摺[ず]ると、ごろごろと大[おお]きな音[おと]がした。", "sentence_source": "generated"}, {"text": "子どもは行きたくないと泣いたが、父は無理に店から引き摺って出た。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "子[こ]どもは行[い]きたくないと泣[な]いたが、父[ちち]は無理[むり]に店[みせ]から引[ひ]き摺[ず]って出[で]た。", "sentence_source": "generated"}, {"text": "工事の人が鉄の棒を引き摺ったので、アスファルトに線がついた。", "target_word": "引き摺った", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が鉄[てつ]の棒[ぼう]を引[ひ]き摺[ず]ったので、アスファルトに線[せん]がついた。", "sentence_source": "generated"}, {"text": "馬に引き摺られた男は、足にひどい怪我をした。", "target_word": "引き摺られた", "complexity_tier": "T3", "furigana": "馬[うま]に引[ひ]き摺[ず]られた男[おとこ]は、足[あし]にひどい怪我[けが]をした。", "sentence_source": "generated"}, {"text": "部長は断る私を、飲み会まで引き摺っていった。", "target_word": "引き摺って", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は断[ことわ]る私[わたし]を、飲[の]み会[かい]まで引[ひ]き摺[ず]っていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引き摺る", "label": "辞書形"}, {"form": "引き摺り", "label": "連用形"}, {"form": "引き摺って", "label": "て形"}, {"form": "引き摺った", "label": "過去形"}, {"form": "引き摺らない", "label": "否定形"}, {"form": "引き摺れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "地面にこすりながら引っ張る。嫌がる人を無理に連れて行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52846, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引き摺って", "is_correct": true, "explanation": "嫌がる相手を無理に連れていく意味で、文の流れに合う。"}, {"text": "眺めて", "is_correct": false, "explanation": "見つめる動作で、弟を病院へ連れていく行為とはつながらない。"}, {"text": "磨いて", "is_correct": false, "explanation": "表面を磨く動作で、人を連れていく文脈には合わない。"}, {"text": "洗って", "is_correct": false, "explanation": "汚れを落とす動作で、病院へ連れていく行為と合わない。"}], "explanations": {"引き摺って": "嫌がる相手を無理に連れていく意味で、文の流れに合う。", "眺めて": "見つめる動作で、弟を病院へ連れていく行為とはつながらない。", "磨いて": "表面を磨く動作で、人を連れていく文脈には合わない。", "洗って": "汚れを落とす動作で、病院へ連れていく行為と合わない。"}, "sentence_index": 0, "correct_answer": "引き摺って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子犬を引き摺って、やさしく抱きしめた。", "explanation": "ここは〈抱きしめる〉の意味。引き摺るは地面にこすりながら引っ張る、または無理に連れて行く意味で、やさしく抱く動作には合わない。"}, {"text": "ドアの取っ手を引き摺って、開けた。", "explanation": "ここは〈引く〉の意味。引き摺るは地面に擦らせて動かす、または無理に連れていく意味で、ドアを開ける動作には合わない。"}, {"text": "洗濯物を物干し竿に引き摺って、乾かした。", "explanation": "ここは〈吊るす〉（掛けて下げる）の意味。引き摺るは地面などに擦って動かすことなので、竿に掛ける動作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52846, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引き摺って", "is_correct": true, "explanation": "無理に店から連れ出す意味で、父が子どもを外へ出す文の流れに合う。"}, {"text": "撫でて", "is_correct": false, "explanation": "優しく触れる動作で、無理に連れ出す文脈と矛盾する。"}, {"text": "折って", "is_correct": false, "explanation": "曲げて割る動作で、人を店から連れ出す場面には合わない。"}, {"text": "組み立てて", "is_correct": false, "explanation": "部品を組む動作で、人を店から連れ出す文脈には合わない。"}], "explanations": {"引き摺って": "無理に店から連れ出す意味で、父が子どもを外へ出す文の流れに合う。", "撫でて": "優しく触れる動作で、無理に連れ出す文脈と矛盾する。", "折って": "曲げて割る動作で、人を店から連れ出す場面には合わない。", "組み立てて": "部品を組む動作で、人を店から連れ出す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "引き摺って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "酔った友人を肩に引き摺って、タクシーまで運んだ。", "explanation": "ここは〈担ぐ〉の意味。引き摺るは地面に擦らせる、または無理に連れていく意味で、肩に乗せる動作には使えない。"}, {"text": "先生は迷う生徒を、教室まで静かに引き摺っていった。", "explanation": "ここは〈導く〉の意味ではない。「静かに」という穏やかな副詞と、力ずくで動かす意味の「引き摺る」が衝突している。"}, {"text": "友人を引き摺って、腹がよじれるほど笑わせた。", "explanation": "ここは〈笑わせる〉の意味（おかしい話や動作で楽しませる）。引き摺るは無理に連れて行く意味なので、人を笑わせる行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52846, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は嫌がる娘を引き摺られて、病院へ連れていった。", "corrected_sentence": "母は嫌がる娘を引き摺って、病院へ連れていった。", "error_description": "態の誤り。「娘を」と目的語が続くので能動形の「引き摺って」が正しく、受身形「引き摺られて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引き摺られた", "is_correct": true, "explanation": "受身の過去形で、「荷物」を修飾しつつ「車に引っ張られた」の意味になる。"}, {"text": "引き摺り", "is_correct": false, "explanation": "連用形。名詞を修飾できず、「荷物が」へ続かない。"}, {"text": "引き摺れば", "is_correct": false, "explanation": "仮定形。条件の意味になり、名詞を修飾できない。"}, {"text": "引き摺らない", "is_correct": false, "explanation": "否定形。「引き摺らない荷物」となり、傷を残したという事実と矛盾する。"}], "correct_form": "引き摺られた", "base_form": "引き摺る", "form_label": "受身の過去形（「荷物」を修飾）", "sentence_index": 1, "explanations": {"引き摺られた": "受身の過去形で、「荷物」を修飾しつつ「車に引っ張られた」の意味になる。", "引き摺り": "連用形。名詞を修飾できず、「荷物が」へ続かない。", "引き摺れば": "仮定形。条件の意味になり、名詞を修飾できない。", "引き摺らない": "否定形。「引き摺らない荷物」となり、傷を残したという事実と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52846, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警備員が男に、会場の外まで引き摺っていった。", "corrected_sentence": "警備員が男を、会場の外まで引き摺っていった。", "error_description": "格助詞の誤り。「引き摺る」は動かす対象に「を」を取るので、「男に」ではなく「男を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引き摺った", "is_correct": true, "explanation": "過去形。「ので、線がついた」の原因として、既に行った動作を表す。"}, {"text": "引き摺って", "is_correct": false, "explanation": "て形。「ので」の前に続けられず、原因を述べる節として成り立たない。"}, {"text": "引き摺ろう", "is_correct": false, "explanation": "意志形。「ので」の前で意志や勧誘を表し、既に起きた動作の原因を述べられない。"}, {"text": "引き摺らせた", "is_correct": false, "explanation": "使役の過去形。人に引かせた意味になり、工事の人自身が棒を引いたという文の内容と合わない。"}], "correct_form": "引き摺った", "base_form": "引き摺る", "form_label": "過去形（「ので」の前）", "sentence_index": 7, "explanations": {"引き摺った": "過去形。「ので、線がついた」の原因として、既に行った動作を表す。", "引き摺って": "て形。「ので」の前に続けられず、原因を述べる節として成り立たない。", "引き摺ろう": "意志形。「ので」の前で意志や勧誘を表し、既に起きた動作の原因を述べられない。", "引き摺らせた": "使役の過去形。人に引かせた意味になり、工事の人自身が棒を引いたという文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52847, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「彼の主張はいつも短い」で、主張を話題にする。"}, {"text": "を", "is_correct": false, "explanation": "「主張をいつも短いです」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「主張にいつも短いです」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ここでは使えない。"}], "correct_answer": "は", "explanations": {"は": "「彼の主張はいつも短い」で、主張を話題にする。", "を": "「主張をいつも短いです」は文として成り立たない。", "に": "「主張にいつも短いです」は文として成り立たない。", "へ": "「へ」は方向を表すので、ここでは使えない。"}, "error_tags": {"を": "ungrammatical", "に": "ungrammatical", "へ": "direction"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遠慮", "is_correct": true, "explanation": "自分の考えを言う「主張」に対し、言うのを控える「遠慮」が反対の意味。"}, {"text": "意見", "is_correct": false, "explanation": "考えを表す語で、反対の意味ではない。"}, {"text": "発表", "is_correct": false, "explanation": "考えを人に示すことで、反対の意味ではない。"}, {"text": "説明", "is_correct": false, "explanation": "考えを人に伝えることで、反対の意味ではない。"}], "correct_answer": "遠慮", "explanations": {"遠慮": "自分の考えを言う「主張」に対し、言うのを控える「遠慮」が反対の意味。", "意見": "考えを表す語で、反対の意味ではない。", "発表": "考えを人に示すことで、反対の意味ではない。", "説明": "考えを人に伝えることで、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52847, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "ばかり", "options": [{"text": "ばかり", "is_correct": true, "explanation": "「主張ばかりして」で、主張ばかりを繰り返す意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "「主張へして」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「主張のして」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「主張がして」は文として成り立たない。"}], "correct_answer": "ばかり", "explanations": {"ばかり": "「主張ばかりして」で、主張ばかりを繰り返す意味になる。", "へ": "「主張へして」は文として成り立たない。", "の": "「主張のして」は文として成り立たない。", "が": "「主張がして」は文として成り立たない。"}, "error_tags": {"へ": "direction", "の": "ungrammatical", "が": "ungrammatical"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黙秘", "is_correct": true, "explanation": "考えを言う「主張」に対し、何も言わない「黙秘」が反対の意味。"}, {"text": "発言", "is_correct": false, "explanation": "意見を口に出すことで、むしろ近い意味。"}, {"text": "主催", "is_correct": false, "explanation": "会などを開く意味で、反対の意味ではない。"}, {"text": "報告", "is_correct": false, "explanation": "事実を伝えることで、反対の意味ではない。"}], "correct_answer": "黙秘", "explanations": {"黙秘": "考えを言う「主張」に対し、何も言わない「黙秘」が反対の意味。", "発言": "意見を口に出すことで、むしろ近い意味。", "主催": "会などを開く意味で、反対の意味ではない。", "報告": "事実を伝えることで、反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52847, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の考えを言うこと。", "primary_collocate": null, "pronunciation": "しゅちょう", "ipa": "ɕɯtɕoː", "syllable_count": 3, "sentences": [{"text": "主張を聞く。", "target_word": "主張", "complexity_tier": "T1", "furigana": "しゅちょうをきく。", "sentence_source": "generated"}, {"text": "主張は同じだ。", "target_word": "主張", "complexity_tier": "T1", "furigana": "しゅちょうはおなじだ。", "sentence_source": "generated"}, {"text": "彼の主張はいつも短いです。", "target_word": "主張", "complexity_tier": "T2", "furigana": "かれのしゅちょうはいつもみじかいです。", "sentence_source": "generated"}, {"text": "私は自分の意見を主張しました。", "target_word": "主張し", "complexity_tier": "T2", "furigana": "わたしはじぶんのいけんをしゅちょうしました。", "sentence_source": "generated"}, {"text": "会議で自分の主張をはっきり伝えた。", "target_word": "主張", "complexity_tier": "T3", "furigana": "かいぎでじぶんのしゅちょうをはっきりつたえた。", "sentence_source": "generated"}, {"text": "子どもが自分の主張を曲げずに泣いている。", "target_word": "主張", "complexity_tier": "T3", "furigana": "こどもがじぶんのしゅちょうをまげずにないている。", "sentence_source": "generated"}, {"text": "彼は新しい計画が必要だと主張している。", "target_word": "主張し", "complexity_tier": "T4", "furigana": "かれはあたらしいけいかくがひつようだとしゅちょうしている。", "sentence_source": "generated"}, {"text": "主張ばかりして、相手の話を聞かない人は困る。", "target_word": "主張", "complexity_tier": "T4", "furigana": "しゅちょうばかりして、あいてのはなしをきかないひとはこまる。", "sentence_source": "generated"}, {"text": "先生は私の主張を最後まで聞いたうえで、別の考えも教えてくれた。", "target_word": "主張", "complexity_tier": "T5", "furigana": "せんせいはわたしのしゅちょうをさいごまできいたうえで、べつのかんがえもおしえてくれた。", "sentence_source": "generated"}, {"text": "どれほど強く主張しても、証拠がなければ誰も信じてくれないだろう。", "target_word": "主張し", "complexity_tier": "T5", "furigana": "どれほどつよくしゅちょうしても、しょうこがなければだれもしんじてくれないだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主張する", "label": "活用"}, {"form": "主張した", "label": "活用"}, {"form": "主張される", "label": "活用"}, {"form": "自己主張", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自分の考えを言うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52847, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主張", "is_correct": true, "explanation": "「しゅちょう」で、聞こえた語と一致する。"}, {"text": "主将", "is_correct": false, "explanation": "「しゅしょう」で、「ちょ」が「しょ」に変わっている。"}, {"text": "手帳", "is_correct": false, "explanation": "「てちょう」で、最初の「しゅ」が「て」に変わっている。"}, {"text": "狩猟", "is_correct": false, "explanation": "「しゅりょう」で、「ち」が「り」に変わっている。"}, {"text": "主教", "is_correct": false, "explanation": "「しゅきょう」で、「ちょ」が「きょ」に変わっている。"}], "explanations": {"主張": "「しゅちょう」で、聞こえた語と一致する。", "主将": "「しゅしょう」で、「ちょ」が「しょ」に変わっている。", "手帳": "「てちょう」で、最初の「しゅ」が「て」に変わっている。", "狩猟": "「しゅりょう」で、「ち」が「り」に変わっている。", "主教": "「しゅきょう」で、「ちょ」が「きょ」に変わっている。"}, "sentence_index": null, "correct_answer": "主張"}, "level_3": {"options": [{"text": "主張", "is_correct": true, "explanation": "「主張を聞く」で、人の考えを聞くという意味に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、「机を聞く」では意味が合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、「帽子を聞く」では意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、「財布を聞く」では意味が合わない。"}], "explanations": {"主張": "「主張を聞く」で、人の考えを聞くという意味に合う。", "机": "形は合うが、「机を聞く」では意味が合わない。", "帽子": "形は合うが、「帽子を聞く」では意味が合わない。", "財布": "形は合うが、「財布を聞く」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "主張"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天気がよかったので、公園で主張を歩きました。", "explanation": "「主張」は考えを言うことで、歩く場所や道ではない。"}, {"text": "昨日の夜、主張を二枚食べました。", "explanation": "「主張」は食べ物ではなく、「二枚食べる」は使い方が誤り。"}, {"text": "部屋が暗いので、主張をつけてください。", "explanation": "「主張」は明かりのような物ではなく、「つける」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52847, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主張", "is_correct": true, "explanation": "「しゅちょう」で、聞こえた語と一致する。"}, {"text": "種痘", "is_correct": false, "explanation": "「しゅとう」で、「ちょ」が「と」に変わっている。"}, {"text": "手中", "is_correct": false, "explanation": "「しゅちゅう」で、「ちょ」が「ちゅ」に変わっている。"}, {"text": "所長", "is_correct": false, "explanation": "「しょちょう」で、「しゅ」が「しょ」に変わっている。"}, {"text": "酒量", "is_correct": false, "explanation": "「しゅりょう」で、「ち」が「り」に変わっている。"}], "explanations": {"主張": "「しゅちょう」で、聞こえた語と一致する。", "種痘": "「しゅとう」で、「ちょ」が「と」に変わっている。", "手中": "「しゅちゅう」で、「ちょ」が「ちゅ」に変わっている。", "所長": "「しょちょう」で、「しゅ」が「しょ」に変わっている。", "酒量": "「しゅりょう」で、「ち」が「り」に変わっている。"}, "sentence_index": null, "correct_answer": "主張"}, "level_3": {"options": [{"text": "主張し", "is_correct": true, "explanation": "「必要だと主張している」で、考えを言い張る意味に合う。"}, {"text": "散歩し", "is_correct": false, "explanation": "形は合うが、「必要だと散歩している」では意味が合わない。"}, {"text": "掃除し", "is_correct": false, "explanation": "形は合うが、「必要だと掃除している」では意味が合わない。"}, {"text": "運転し", "is_correct": false, "explanation": "形は合うが、「必要だと運転している」では意味が合わない。"}], "explanations": {"主張し": "「必要だと主張している」で、考えを言い張る意味に合う。", "散歩し": "形は合うが、「必要だと散歩している」では意味が合わない。", "掃除し": "形は合うが、「必要だと掃除している」では意味が合わない。", "運転し": "形は合うが、「必要だと運転している」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "主張し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、友だちと主張に乗って学校へ行きます。", "explanation": "「主張」は乗り物ではなく、「主張に乗る」は使い方が誤り。"}, {"text": "この主張は冷たくて、とてもおいしい。", "explanation": "「主張」は味わう物ではなく、「冷たくておいしい」は合わない。"}, {"text": "先生に主張を借りて、本を読んだ。", "explanation": "「主張」は借りられる物ではなく、「借りる」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
