INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52847, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は会議で自分の主張を歩いた。", "corrected_sentence": "彼は会議で自分の主張を伝えた。", "error_description": "「主張」と組み合わせる動詞が不自然。「歩く」ではなく「伝える」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52848, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「主張が正しいか」で、主張を主語にする。"}, {"text": "に", "is_correct": false, "explanation": "「主張に正しいか」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「主張と正しいか」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ここでは使えない。"}], "correct_answer": "が", "explanations": {"が": "「主張が正しいか」で、主張を主語にする。", "に": "「主張に正しいか」は文として成り立たない。", "と": "「主張と正しいか」は文として成り立たない。", "へ": "「へ」は方向を表すので、ここでは使えない。"}, "error_tags": {"に": "ungrammatical", "と": "ungrammatical", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "譲歩", "is_correct": true, "explanation": "自分の考えを押し通す「主張」に対し、相手に譲るのが「譲歩」で反対の意味。"}, {"text": "意見", "is_correct": false, "explanation": "考えを表す語で、反対の意味ではない。"}, {"text": "提案", "is_correct": false, "explanation": "考えを示す点で近く、反対の意味ではない。"}, {"text": "発言", "is_correct": false, "explanation": "意見を口に出すことで、むしろ近い意味。"}], "correct_answer": "譲歩", "explanations": {"譲歩": "自分の考えを押し通す「主張」に対し、相手に譲るのが「譲歩」で反対の意味。", "意見": "考えを表す語で、反対の意味ではない。", "提案": "考えを示す点で近く、反対の意味ではない。", "発言": "意見を口に出すことで、むしろ近い意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52848, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「主張を支える」で、主張が支える対象になる。"}, {"text": "に", "is_correct": false, "explanation": "「主張に支える根拠」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ここでは使えない。"}, {"text": "と", "is_correct": false, "explanation": "「主張と支える根拠」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「主張を支える」で、主張が支える対象になる。", "に": "「主張に支える根拠」は文として成り立たない。", "へ": "「へ」は方向を表すので、ここでは使えない。", "と": "「主張と支える根拠」は文として成り立たない。"}, "error_tags": {"に": "ungrammatical", "へ": "direction", "と": "ungrammatical"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "沈黙", "is_correct": true, "explanation": "意見を言う「主張」に対し、何も言わないのが「沈黙」で反対の意味。"}, {"text": "反論", "is_correct": false, "explanation": "相手に意見を述べる行為で、反対の意味ではない。"}, {"text": "論争", "is_correct": false, "explanation": "意見を言い合うことで、反対の意味ではない。"}, {"text": "結論", "is_correct": false, "explanation": "考えの到達点で、反対の意味ではない。"}], "correct_answer": "沈黙", "explanations": {"沈黙": "意見を言う「主張」に対し、何も言わないのが「沈黙」で反対の意味。", "反論": "相手に意見を述べる行為で、反対の意味ではない。", "論争": "意見を言い合うことで、反対の意味ではない。", "結論": "考えの到達点で、反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52848, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分が正しいと思う意見や考えを、はっきりと述べること。", "primary_collocate": null, "pronunciation": "しゅちょう", "ipa": "ɕɯtɕoː", "syllable_count": 3, "sentences": [{"text": "生徒たちが繊維の纹理に想いを込め、独自のプロットを紡ぎ出すとき、それは単なる被服製作ではなく、記号的な自己主張の確立へと昇華されるのである。", "target_word": "主張", "complexity_tier": "T6", "furigana": "せいとたちがせんいのもんりにおもいをこめ、どくじのぷろっとをつむぎだすとき、それはたんなるひふくせいさくではなく、きごうてきなじこしゅちょうのかくりつへとしょうかされるのである。", "sentence_source": "mined"}, {"text": "主張が正しいかどうか調べます。", "target_word": "主張", "complexity_tier": "T2", "furigana": "しゅちょうがただしいかどうかしらべます。", "sentence_source": "generated"}, {"text": "彼女は反対の主張をしました。", "target_word": "主張", "complexity_tier": "T2", "furigana": "かのじょははんたいのしゅちょうをしました。", "sentence_source": "generated"}, {"text": "私は無料にするべきだと主張した。", "target_word": "主張した", "complexity_tier": "T3", "furigana": "わたしはむりょうにするべきだとしゅちょうした。", "sentence_source": "generated"}, {"text": "その主張には、はっきりした理由がある。", "target_word": "主張", "complexity_tier": "T3", "furigana": "そのしゅちょうには、はっきりしたりゆうがある。", "sentence_source": "generated"}, {"text": "相手の主張に問題があるなら、具体的に指摘したほうがいい。", "target_word": "主張", "complexity_tier": "T4", "furigana": "あいてのしゅちょうにもんだいがあるなら、ぐたいてきにしてきしたほうがいい。", "sentence_source": "generated"}, {"text": "彼の主張は、データを見ると正しいとは言えない。", "target_word": "主張", "complexity_tier": "T4", "furigana": "かれのしゅちょうは、でーたをみるとただしいとはいえない。", "sentence_source": "generated"}, {"text": "議論では、自分の主張を支える根拠をきちんと示すことが何より大切だ。", "target_word": "主張", "complexity_tier": "T5", "furigana": "ぎろんでは、じぶんのしゅちょうをささえるこんきょをきちんとしめすことがなによりたいせつだ。", "sentence_source": "generated"}, {"text": "彼女は最後まで無実を主張し続けたが、裁判所は認めなかった。", "target_word": "主張し", "complexity_tier": "T5", "furigana": "かのじょはさいごまでむじつをしゅちょうしつづけたが、さいばんしょはみとめなかった。", "sentence_source": "generated"}, {"text": "主張が強すぎると、周りの人に頑固な性格だと思われてしまうことがある。", "target_word": "主張", "complexity_tier": "T5", "furigana": "しゅちょうがつよすぎると、まわりのひとにがんこなせいかくだとおもわれてしまうことがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主張する", "label": "活用"}, {"form": "主張した", "label": "活用"}, {"form": "主張される", "label": "活用"}, {"form": "自己主張", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自分の意見をはっきり述べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 被服 (Zipf 2.42)']::text[], '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52848, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主張", "is_correct": true, "explanation": "「しゅちょう」で、聞こえた語と一致する。"}, {"text": "主将", "is_correct": false, "explanation": "「しゅしょう」で、「ちょ」が「しょ」に変わっている。"}, {"text": "手帳", "is_correct": false, "explanation": "「てちょう」で、最初の「しゅ」が「て」に変わっている。"}, {"text": "狩猟", "is_correct": false, "explanation": "「しゅりょう」で、「ち」が「り」に変わっている。"}, {"text": "主教", "is_correct": false, "explanation": "「しゅきょう」で、「ちょ」が「きょ」に変わっている。"}], "explanations": {"主張": "「しゅちょう」で、聞こえた語と一致する。", "主将": "「しゅしょう」で、「ちょ」が「しょ」に変わっている。", "手帳": "「てちょう」で、最初の「しゅ」が「て」に変わっている。", "狩猟": "「しゅりょう」で、「ち」が「り」に変わっている。", "主教": "「しゅきょう」で、「ちょ」が「きょ」に変わっている。"}, "sentence_index": null, "correct_answer": "主張"}, "level_3": {"options": [{"text": "主張", "is_correct": true, "explanation": "「自己主張の確立」で、自分の考えをはっきり示す意味に合う。"}, {"text": "紹介", "is_correct": false, "explanation": "形は合うが、「自己紹介の確立」では意味が合わない。"}, {"text": "嫌悪", "is_correct": false, "explanation": "形は合うが、「自己嫌悪の確立」では文脈に意味が合わない。"}, {"text": "批判", "is_correct": false, "explanation": "形は合うが、「自己批判の確立」では意味が合わない。"}], "explanations": {"主張": "「自己主張の確立」で、自分の考えをはっきり示す意味に合う。", "紹介": "形は合うが、「自己紹介の確立」では意味が合わない。", "嫌悪": "形は合うが、「自己嫌悪の確立」では文脈に意味が合わない。", "批判": "形は合うが、「自己批判の確立」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "主張"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週、仕事で大阪へ主張します。", "explanation": "「主張」を、仕事で出かける意味の「出張」と取り違えている。"}, {"text": "雨が強く降って、道に主張が流れた。", "explanation": "「主張」は意見のことで、道を流れる物の名前としては使えない。"}, {"text": "彼女は主張を机の上に置いて、部屋を出た。", "explanation": "「主張」は考えを述べることで、机に置ける物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52848, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主張", "is_correct": true, "explanation": "「しゅちょう」で、聞こえた語と一致する。"}, {"text": "種痘", "is_correct": false, "explanation": "「しゅとう」で、「ちょ」が「と」に変わっている。"}, {"text": "手中", "is_correct": false, "explanation": "「しゅちゅう」で、「ちょ」が「ちゅ」に変わっている。"}, {"text": "所長", "is_correct": false, "explanation": "「しょちょう」で、「しゅ」が「しょ」に変わっている。"}, {"text": "酒量", "is_correct": false, "explanation": "「しゅりょう」で、「ち」が「り」に変わっている。"}], "explanations": {"主張": "「しゅちょう」で、聞こえた語と一致する。", "種痘": "「しゅとう」で、「ちょ」が「と」に変わっている。", "手中": "「しゅちゅう」で、「ちょ」が「ちゅ」に変わっている。", "所長": "「しょちょう」で、「しゅ」が「しょ」に変わっている。", "酒量": "「しゅりょう」で、「ち」が「り」に変わっている。"}, "sentence_index": null, "correct_answer": "主張"}, "level_3": {"options": [{"text": "主張", "is_correct": true, "explanation": "データと照らして「正しいとは言えない」と評価できるのは、考えを述べた主張。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが、趣味は正しいかどうかで評価するものではなく、意味が合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、帽子が「正しいとは言えない」では意味が合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、散歩がデータで正しいか判断されるのは意味が合わない。"}], "explanations": {"主張": "データと照らして「正しいとは言えない」と評価できるのは、考えを述べた主張。", "趣味": "形は合うが、趣味は正しいかどうかで評価するものではなく、意味が合わない。", "帽子": "形は合うが、帽子が「正しいとは言えない」では意味が合わない。", "散歩": "形は合うが、散歩がデータで正しいか判断されるのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "主張"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、新しい靴の主張を買いに店へ行った。", "explanation": "「主張」は買える物ではなく、「靴の主張を買う」は意味が通らない。"}, {"text": "主張を飲みすぎて、頭が痛くなった。", "explanation": "「主張」は考えを述べることで、飲み物ではない。"}, {"text": "会議で上司に主張を貸してもらった。", "explanation": "「主張」は物のように貸し借りできるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52848, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議で彼女は自分の主張を洗った。", "corrected_sentence": "会議で彼女は自分の主張を述べた。", "error_description": "「主張」と組み合わせる動詞が不自然。「洗う」ではなく「述べる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52848, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "議論で彼は自分の主張を履いた。", "corrected_sentence": "議論で彼は自分の主張を曲げなかった。", "error_description": "「主張」に「履く」は合わない。「曲げなかった」などが自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
