INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52849, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「友情の永続を信じていた」の「信じる」の対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「信じる」は対象に「を」を取るので、「が」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すので、「永続に信じていた」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、信じる対象を示す位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "「友情の永続を信じていた」の「信じる」の対象を示す「を」。", "が": "「信じる」は対象に「を」を取るので、「が」は合わない。", "に": "「に」は相手や場所を示すので、「永続に信じていた」は意味が通らない。", "へ": "方向を示す「へ」は、信じる対象を示す位置には合わない。"}, "error_tags": {"が": "主格", "に": "相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52849, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっと続くこと。", "primary_collocate": null, "pronunciation": "えいぞく", "ipa": "eizoku", "syllable_count": 4, "sentences": [{"text": "この平和が永続することを、世界中の人が願っている。", "target_word": "永続", "complexity_tier": "T3", "furigana": "この平和[へいわ]が永続[えいぞく]することを、世界中[せかいじゅう]の人[ひと]が願[ねが]っている。", "sentence_source": "generated"}, {"text": "人の幸せは永続しないから、今を大切にしたい。", "target_word": "永続", "complexity_tier": "T3", "furigana": "人[ひと]の幸[しあわ]せは永続[えいぞく]しないから、今[いま]を大切[たいせつ]にしたい。", "sentence_source": "generated"}, {"text": "国は、この制度を永続させるために予算を増やした。", "target_word": "永続", "complexity_tier": "T3", "furigana": "国[くに]は、この制度[せいど]を永続[えいぞく]させるために予算[よさん]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "二人は愛の永続を誓って、指輪を交換した。", "target_word": "永続", "complexity_tier": "T3", "furigana": "二人[ふたり]は愛[あい]の永続[えいぞく]を誓[ちか]って、指輪[ゆびわ]を交換[こうかん]した。", "sentence_source": "generated"}, {"text": "王は国の永続を願い、毎年神に祈った。", "target_word": "永続", "complexity_tier": "T3", "furigana": "王[おう]は国[くに]の永続[えいぞく]を願[ねが]い、毎年[まいとし]神[かみ]に祈[いの]った。", "sentence_source": "generated"}, {"text": "会社が永続するには、時代に合わせて変わる必要がある。", "target_word": "永続", "complexity_tier": "T3", "furigana": "会社[かいしゃ]が永続[えいぞく]するには、時代[じだい]に合[あ]わせて変[か]わる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "氷の彫刻は永続するものではなく、春には消えてしまう。", "target_word": "永続", "complexity_tier": "T3", "furigana": "氷[こおり]の彫刻[ちょうこく]は永続[えいぞく]するものではなく、春[はる]には消[き]えてしまう。", "sentence_source": "generated"}, {"text": "彼は友情の永続を信じていたが、卒業して連絡が減った。", "target_word": "永続", "complexity_tier": "T3", "furigana": "彼[かれ]は友情[ゆうじょう]の永続[えいぞく]を信[しん]じていたが、卒業[そつぎょう]して連絡[れんらく]が減[へ]った。", "sentence_source": "generated"}, {"text": "永続を望むなら、まず小さな約束を守ることだ。", "target_word": "永続", "complexity_tier": "T3", "furigana": "永続[えいぞく]を望[のぞ]むなら、まず小[ちい]さな約束[やくそく]を守[まも]ることだ。", "sentence_source": "generated"}, {"text": "好景気が永続すると考えるのは危険だ。", "target_word": "永続", "complexity_tier": "T3", "furigana": "好景気[こうけいき]が永続[えいぞく]すると考[かんが]えるのは危険[きけん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "永続", "label": "基本形"}, {"form": "永続する", "label": "する動詞の辞書形"}, {"form": "永続させる", "label": "使役形"}], "register": "やや硬い", "sense_fingerprint": "いつまでもずっと続くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52849, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永続", "is_correct": true, "explanation": "「いつまでもずっと続くこと」の意味で、平和が続くことを願う文に合う。"}, {"text": "協議", "is_correct": false, "explanation": "「協議」は話し合う意味で、「平和が協議することを」は成り立たない。"}, {"text": "配達", "is_correct": false, "explanation": "「配達」は物を届ける意味で、平和には使えない。"}, {"text": "照会", "is_correct": false, "explanation": "「照会」は問い合わせる意味で、平和が続くという文には合わない。"}], "explanations": {"永続": "「いつまでもずっと続くこと」の意味で、平和が続くことを願う文に合う。", "協議": "「協議」は話し合う意味で、「平和が協議することを」は成り立たない。", "配達": "「配達」は物を届ける意味で、平和には使えない。", "照会": "「照会」は問い合わせる意味で、平和が続くという文には合わない。"}, "sentence_index": 0, "correct_answer": "永続"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花火の永続は、ほんの一瞬だった。", "explanation": "ここは〈はかなさ〉の意味。永続は長く続く状態を表すので、すぐ消える様子を指す語ではない。"}, {"text": "朝ごはんの永続は、パンとコーヒーだ。", "explanation": "ここは〈定番〉の意味。永続は続く状態を表すので、いつも決まっている食べ物を指す語ではない。"}, {"text": "彼女は部屋の永続を掃除した。", "explanation": "ここは〈片付け〉の意味。永続は続く状態を表すので、部屋を整える作業を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52849, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永続", "is_correct": true, "explanation": "「ずっと続くこと」の意味で、氷の彫刻が続かないという文の対比に合う。"}, {"text": "上演", "is_correct": false, "explanation": "「上演」は舞台などで演じる意味で、「上演するものではなく」は合わない。"}, {"text": "保険", "is_correct": false, "explanation": "「保険」は備えの仕組みで、彫刻の性質を表す文には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点」は点数をつける意味で、彫刻の持続性を述べる文には合わない。"}], "explanations": {"永続": "「ずっと続くこと」の意味で、氷の彫刻が続かないという文の対比に合う。", "上演": "「上演」は舞台などで演じる意味で、「上演するものではなく」は合わない。", "保険": "「保険」は備えの仕組みで、彫刻の性質を表す文には合わない。", "採点": "「採点」は点数をつける意味で、彫刻の持続性を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "永続"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の答えを永続して、ノートに書いた。", "explanation": "ここは〈覚える〉の意味。永続は続く状態を表すので、答えを暗記する動作には使わない。"}, {"text": "この料理は永続が早いので、すぐに食べられる。", "explanation": "ここは〈仕上がり〉の意味。永続は続くことを表すので、料理が仕上がるまでの速さを表す語ではない。"}, {"text": "彼は昨日の会議を永続した。", "explanation": "ここは〈終える〉の意味。永続は続くことを表すので、会議を終わらせる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52849, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は、この店の永続の望んでいる。", "corrected_sentence": "彼は、この店の永続を望んでいる。", "error_description": "「を」が正しい。「望む」は対象を目的語にとるので「を」が必要で、「の」では文の構造が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52849, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この制度が永続しようよう、国は努力している。", "corrected_sentence": "この制度が永続するよう、国は努力している。", "error_description": "「永続するよう」が正しい。「永続しようよう」は意向形と「よう」の重複で、活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52851, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一斉に」の「に」で、後ろの「舞い上がり」を修飾している。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す格助詞で、「一斉が舞い上がり」は副詞句にならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、自動詞の「舞い上がる」は目的語をとらないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞だが、「一斉へ舞い上がり」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「一斉に」の「に」で、後ろの「舞い上がり」を修飾している。", "が": "主語を示す格助詞で、「一斉が舞い上がり」は副詞句にならず不自然。", "を": "目的語を示すが、自動詞の「舞い上がる」は目的語をとらないので合わない。", "へ": "方向を示す助詞だが、「一斉へ舞い上がり」は意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52851, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「小麦粉が舞い上がらない」の主語を示す「が」で、後ろの動詞に直接つながる。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を示すため、「小麦粉と舞い上がらない」では主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞修飾になるため、「小麦粉の舞い上がらない」では文の動詞として続かない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、自動詞の「舞い上がる」は目的語をとらないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「小麦粉が舞い上がらない」の主語を示す「が」で、後ろの動詞に直接つながる。", "と": "共同の相手を示すため、「小麦粉と舞い上がらない」では主語として成り立たない。", "の": "名詞修飾になるため、「小麦粉の舞い上がらない」では文の動詞として続かない。", "を": "「を」は他動詞の目的語を示すが、自動詞の「舞い上がる」は目的語をとらないので合わない。"}, "error_tags": {"と": "共同", "の": "連体修飾", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52851, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが、空気の中でふわふわと上にうごくこと。", "primary_collocate": null, "pronunciation": "まいあがる", "ipa": "maiaɡaɾɯ", "syllable_count": 5, "sentences": [{"text": "綿毛がふわりと舞い上がり、青い空へ消えていった。", "target_word": "舞い上がり", "complexity_tier": "T3", "furigana": "綿毛[わたげ]がふわりと舞[ま]い上[あ]がり、青[あお]い空[そら]へ消[き]えていった。", "sentence_source": "generated"}, {"text": "紙ふぶきが一斉に舞い上がり、会場は歓声に包まれた。", "target_word": "舞い上がり", "complexity_tier": "T3", "furigana": "紙[かみ]ふぶきが一斉[いっせい]に舞[ま]い上[あ]がり、会場[かいじょう]は歓声[かんせい]に包[つつ]まれた。", "sentence_source": "generated"}, {"text": "洗濯物を取り込むとき、風で小さなタオルが舞い上がってしまった。", "target_word": "舞い上がって", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]を取[と]り込[こ]むとき、風[かぜ]で小[ちい]さなタオルが舞[ま]い上[あ]がってしまった。", "sentence_source": "generated"}, {"text": "強い風が吹くたびに、公園の落ち葉が舞い上がる。", "target_word": "舞い上がる", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]が吹[ふ]くたびに、公園[こうえん]の落[お]ち葉[ば]が舞[ま]い上[あ]がる。", "sentence_source": "generated"}, {"text": "粉雪が地面から舞い上がり、前がよく見えなかった。", "target_word": "舞い上がり", "complexity_tier": "T4", "furigana": "粉雪[こなゆき]が地面[じめん]から舞[ま]い上[あ]がり、前[まえ]がよく見[み]えなかった。", "sentence_source": "generated"}, {"text": "窓から入った風で、レースのカーテンと一緒にほこりが舞い上がった。", "target_word": "舞い上がった", "complexity_tier": "T4", "furigana": "窓[まど]から入[はい]った風[かぜ]で、レースのカーテンと一緒[いっしょ]にほこりが舞[ま]い上[あ]がった。", "sentence_source": "generated"}, {"text": "鳥が飛び立つと、足もとの羽根がふわふわと舞い上がった。", "target_word": "舞い上がった", "complexity_tier": "T3", "furigana": "鳥[とり]が飛[と]び立[た]つと、足[あし]もとの羽根[はね]がふわふわと舞[ま]い上[あ]がった。", "sentence_source": "generated"}, {"text": "小麦粉が舞い上がらないように、ボウルの中でそっと混ぜた。", "target_word": "舞い上がらない", "complexity_tier": "T4", "furigana": "小麦粉[こむぎこ]が舞[ま]い上[あ]がらないように、ボウルの中[なか]でそっと混[ま]ぜた。", "sentence_source": "generated"}, {"text": "干したシーツがばさっと風にあおられて舞い上がった。", "target_word": "舞い上がった", "complexity_tier": "T4", "furigana": "干[ほ]したシーツがばさっと風[かぜ]にあおられて舞[ま]い上[あ]がった。", "sentence_source": "generated"}, {"text": "竹ぼうきで掃くと、細かい砂が舞い上がって、まわりの人が咳をした。", "target_word": "舞い上がって", "complexity_tier": "T4", "furigana": "竹[たけ]ぼうきで掃[は]くと、細[こま]かい砂[すな]が舞[ま]い上[あ]がって、まわりの人[ひと]が咳[せき]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "舞い上がる", "label": "基本形"}, {"form": "舞い上がった", "label": "過去形"}, {"form": "舞い上がって", "label": "て形"}, {"form": "舞い上がり", "label": "連用形"}, {"form": "舞い上がらない", "label": "否定形"}, {"form": "舞い上がれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "軽いものが空気の中でふわふわと上へ動く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52851, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舞い上がり", "is_correct": true, "explanation": "連用形で、「ふわりと舞い上がり、青い空へ消えていった」と続く中止の形になる。"}, {"text": "舞い上げた", "is_correct": false, "explanation": "他動詞の過去形で、綿毛を動かす主体が必要になり、綿毛が自ら上がる文と合わない。"}, {"text": "舞い上がらせて", "is_correct": false, "explanation": "使役形なので、誰かが綿毛を上げさせるという意味になり、文脈と合わない。"}, {"text": "舞い上げ", "is_correct": false, "explanation": "他動詞の連用形で、綿毛が主語の自動的な上昇と合わない。"}], "explanations": {"舞い上がり": "連用形で、「ふわりと舞い上がり、青い空へ消えていった」と続く中止の形になる。", "舞い上げた": "他動詞の過去形で、綿毛を動かす主体が必要になり、綿毛が自ら上がる文と合わない。", "舞い上がらせて": "使役形なので、誰かが綿毛を上げさせるという意味になり、文脈と合わない。", "舞い上げ": "他動詞の連用形で、綿毛が主語の自動的な上昇と合わない。"}, "sentence_index": 0, "correct_answer": "舞い上がり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作業員の力で、重い鉄板がゆっくり舞い上がった。", "explanation": "〈持ち上がる〉の意味。重いものを力で持ち上げる場合は持ち上がるを使い、舞い上がるは軽いものがふわふわ上がる語なので合わない。"}, {"text": "暖房をつけると、室温がみるみる舞い上がった。", "explanation": "〈上がる（上昇する）〉の意味。温度の上昇は上がると言い、ものが空気中をふわふわ上がる舞い上がるとは言わない。"}, {"text": "古い壁が舞い上がって、崩れ落ちた。", "explanation": "〈崩れる〉の意味。舞い上がるは軽いものが空中を動く語なので、重い壁が崩れる意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52851, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舞い上がった", "is_correct": true, "explanation": "過去形で、羽根が舞い上がったという出来事を文末で正しく述べている。"}, {"text": "舞い上がって", "is_correct": false, "explanation": "て形のため文末に置けず、文が途中で切れてしまう。"}, {"text": "舞い上がらせた", "is_correct": false, "explanation": "使役形になり、羽根を誰かが上げさせたという意味になって文脈と合わない。"}, {"text": "舞い上げる", "is_correct": false, "explanation": "他動詞なので羽根を上げる主体が必要になり、羽根が自ら舞う描写と合わない。"}], "explanations": {"舞い上がった": "過去形で、羽根が舞い上がったという出来事を文末で正しく述べている。", "舞い上がって": "て形のため文末に置けず、文が途中で切れてしまう。", "舞い上がらせた": "使役形になり、羽根を誰かが上げさせたという意味になって文脈と合わない。", "舞い上げる": "他動詞なので羽根を上げる主体が必要になり、羽根が自ら舞う描写と合わない。"}, "sentence_index": 6, "correct_answer": "舞い上がった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天井から電球が舞い上がって、ぶら下がっている。", "explanation": "〈ぶら下がる〉の意味。紐などにつられて下がっている物は、軽く空中を舞う意味の舞い上がるとは合わない。"}, {"text": "桜の花びらが地面へ舞い上がった。", "explanation": "〈舞い降りる〉の意味。舞い上がるは上へ向かう動きなので、地面へ落ちる花びらには合わない。"}, {"text": "湖の底に石が舞い上がっていた。", "explanation": "〈沈む〉の意味。舞い上がるは軽いものが上へ動く様子なので、重い石には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52851, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "綿毛がふわりと舞い上がらせ、やがて空へ消えていった。", "corrected_sentence": "綿毛がふわりと舞い上がり、やがて空へ消えていった。", "error_description": "使役の「らせ」が誤り。「舞い上がる」は自動詞なので、使役形にせず連用形「舞い上がり」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "舞い上がり", "is_correct": true, "explanation": "連用形で、「紙ふぶきが一斉に舞い上がり、会場は」と中止の形でつながる。"}, {"text": "舞い上がる", "is_correct": false, "explanation": "基本形は中止の「、」の前に置くと不自然で、連用形が必要。"}, {"text": "舞い上がれば", "is_correct": false, "explanation": "仮定形で条件の意味になり、実際に起きた出来事を述べていない。"}, {"text": "舞い上がれ", "is_correct": false, "explanation": "命令形で、文の途中で「、」を続ける中止の形にはならない。"}], "correct_form": "舞い上がり", "base_form": "舞い上がる", "form_label": "連用形", "sentence_index": 1, "explanations": {"舞い上がり": "連用形で、「紙ふぶきが一斉に舞い上がり、会場は」と中止の形でつながる。", "舞い上がる": "基本形は中止の「、」の前に置くと不自然で、連用形が必要。", "舞い上がれば": "仮定形で条件の意味になり、実際に起きた出来事を述べていない。", "舞い上がれ": "命令形で、文の途中で「、」を続ける中止の形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52851, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風が強いと、ほこりを舞い上がる。", "corrected_sentence": "風が強いと、ほこりが舞い上がる。", "error_description": "格助詞の「を」が誤り。「舞い上がる」は自動詞なので、主語の「ほこりが」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "舞い上がらない", "is_correct": true, "explanation": "否定形で、「舞い上がらないように」と粉が上がるのを防ぐ目的を表す。"}, {"text": "舞い上がらなかった", "is_correct": false, "explanation": "過去否定で時制が合わず、「ように」の目的を表せない。"}, {"text": "舞い上がった", "is_correct": false, "explanation": "過去形で、「ように」の前では完了した様子の比喩になり、粉が上がるのを防ぐ目的にはならない。"}, {"text": "舞い上がれ", "is_correct": false, "explanation": "命令形で、「ように」の前に置くと文が成り立たない。"}], "correct_form": "舞い上がらない", "base_form": "舞い上がる", "form_label": "否定形", "sentence_index": 7, "explanations": {"舞い上がらない": "否定形で、「舞い上がらないように」と粉が上がるのを防ぐ目的を表す。", "舞い上がらなかった": "過去否定で時制が合わず、「ように」の目的を表せない。", "舞い上がった": "過去形で、「ように」の前では完了した様子の比喩になり、粉が上がるのを防ぐ目的にはならない。", "舞い上がれ": "命令形で、「ように」の前に置くと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52852, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一斉に」の「に」で、後ろの「舞い上がった」を修飾している。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す格助詞で、「一斉が舞い上がった」は副詞句にならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、自動詞の「舞い上がる」は目的語をとらないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞だが、「一斉へ舞い上がった」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「一斉に」の「に」で、後ろの「舞い上がった」を修飾している。", "が": "主語を示す格助詞で、「一斉が舞い上がった」は副詞句にならず不自然。", "を": "目的語を示すが、自動詞の「舞い上がる」は目的語をとらないので合わない。", "へ": "方向を示す助詞だが、「一斉へ舞い上がった」は意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52852, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「埃が舞い上がる」の主語を示す「が」で、後ろの動詞に直接つながる。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を示すため、「埃と舞い上がって」では主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞修飾になるため、「埃の舞い上がって」では文の動詞として続かない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、自動詞の「舞い上がる」は目的語をとらないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「埃が舞い上がる」の主語を示す「が」で、後ろの動詞に直接つながる。", "と": "共同の相手を示すため、「埃と舞い上がって」では主語として成り立たない。", "の": "名詞修飾になるため、「埃の舞い上がって」では文の動詞として続かない。", "を": "「を」は他動詞の目的語を示すが、自動詞の「舞い上がる」は目的語をとらないので合わない。"}, "error_tags": {"と": "共同", "の": "連体修飾", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52852, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "空中に浮かび上がるように、軽やかに上昇すること。ほこりや花びら、紙くずなどが風に乗って舞い上がる様子を表す。", "primary_collocate": null, "pronunciation": "まいあがる", "ipa": "maiaɡaɾɯ", "syllable_count": 5, "sentences": [{"text": "風が強いと、庭の落ち葉が舞い上がる。", "target_word": "舞い上がる", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]いと、庭[にわ]の落[お]ち葉[ば]が舞[ま]い上[あ]がる。", "sentence_source": "generated"}, {"text": "強い風が吹いて、机の上の紙が一斉に舞い上がった。", "target_word": "舞い上がった", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]が吹[ふ]いて、机[つくえ]の上[うえ]の紙[かみ]が一斉[いっせい]に舞[ま]い上[あ]がった。", "sentence_source": "generated"}, {"text": "桜の花びらが風に乗って、空高く舞い上がっていく。", "target_word": "舞い上がって", "complexity_tier": "T3", "furigana": "桜[さくら]の花[はな]びらが風[かぜ]に乗[の]って、空高[そらたか]く舞[ま]い上[あ]がっていく。", "sentence_source": "generated"}, {"text": "乾いた校庭では、走るたびに砂ぼこりが舞い上がる。", "target_word": "舞い上がる", "complexity_tier": "T3", "furigana": "乾[かわ]いた校庭[こうてい]では、走[はし]るたびに砂[すな]ぼこりが舞[ま]い上[あ]がる。", "sentence_source": "generated"}, {"text": "突風で枯れ葉が舞い上がり、通りがしばらく茶色に染まった。", "target_word": "舞い上がり", "complexity_tier": "T4", "furigana": "突風[とっぷう]で枯[か]れ葉[は]が舞[ま]い上[あ]がり、通[とお]りがしばらく茶色[ちゃいろ]に染[そ]まった。", "sentence_source": "generated"}, {"text": "窓を開けた瞬間、カーテンとともに軽い羽毛が舞い上がった。", "target_word": "舞い上がった", "complexity_tier": "T4", "furigana": "窓[まど]を開[あ]けた瞬間[しゅんかん]、カーテンとともに軽[かる]い羽毛[うもう]が舞[ま]い上[あ]がった。", "sentence_source": "generated"}, {"text": "火の粉が夜空に舞い上がる様子を、私たちは黙って見つめていた。", "target_word": "舞い上がる", "complexity_tier": "T4", "furigana": "火[ひ]の粉[こ]が夜空[よぞら]に舞[ま]い上[あ]がる様子[ようす]を、私[わたし]たちは黙[だま]って見[み]つめていた。", "sentence_source": "generated"}, {"text": "床を強くたたくと、積もった埃が舞い上がってしまうので、そっと歩いてください。", "target_word": "舞い上がって", "complexity_tier": "T4", "furigana": "床[ゆか]を強[つよ]くたたくと、積[つ]もった埃[ほこり]が舞[ま]い上[あ]がってしまうので、そっと歩[ある]いてください。", "sentence_source": "generated"}, {"text": "ヘリコプターが降りるとき、風に押されて雪が白く舞い上がった。", "target_word": "舞い上がった", "complexity_tier": "T4", "furigana": "ヘリコプターが降[お]りるとき、風[かぜ]に押[お]されて雪[ゆき]が白[しろ]く舞[ま]い上[あ]がった。", "sentence_source": "generated"}, {"text": "風が止めば、舞い上がった灰もゆっくり地面に落ちてくる。", "target_word": "舞い上がった", "complexity_tier": "T4", "furigana": "風[かぜ]が止[や]めば、舞[ま]い上[あ]がった灰[はい]もゆっくり地面[じめん]に落[お]ちてくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "舞い上がる", "label": "基本形"}, {"form": "舞い上がった", "label": "過去形"}, {"form": "舞い上がって", "label": "て形"}, {"form": "舞い上がり", "label": "連用形"}, {"form": "舞い上がらない", "label": "否定形"}, {"form": "舞い上がれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ほこり・花びら・紙などが風に乗って軽やかに空中へ上がる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52852, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舞い上がる", "is_correct": true, "explanation": "基本形で文を終え、「粒子が上へ舞う」という現象を述べている。"}, {"text": "舞い上がって", "is_correct": false, "explanation": "て形のため文末に置けず、文が途中で切れてしまう。"}, {"text": "舞い上げる", "is_correct": false, "explanation": "他動詞なので「粒子を上げる」の形になり、粒子が自ら上がる文脈と合わない。"}, {"text": "舞い上がれ", "is_correct": false, "explanation": "命令形で、事実を述べる文の末尾には使えない。"}], "explanations": {"舞い上がる": "基本形で文を終え、「粒子が上へ舞う」という現象を述べている。", "舞い上がって": "て形のため文末に置けず、文が途中で切れてしまう。", "舞い上げる": "他動詞なので「粒子を上げる」の形になり、粒子が自ら上がる文脈と合わない。", "舞い上がれ": "命令形で、事実を述べる文の末尾には使えない。"}, "sentence_index": 0, "correct_answer": "舞い上がる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作業員の力で、重い木箱がゆっくり舞い上がった。", "explanation": "〈持ち上がる〉の意味。重いものを力で上へ動かす場合は持ち上がるを使い、軽いものが空中を舞う意味の舞い上がるは重い木箱には合わない。"}, {"text": "午後になると、気温がぐんぐん舞い上がった。", "explanation": "〈上がる（上昇する）〉の意味。温度の上昇は上がると言い、軽いものが空気中を舞う意味の舞い上がるとは言わない。"}, {"text": "古い壁が舞い上がって、崩れ落ちた。", "explanation": "〈崩れる〉の意味。舞い上がるは軽いものが空中を動く語なので、重い壁が崩れる意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52852, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舞い上がる", "is_correct": true, "explanation": "基本形で、「火の粉が夜空に舞い上がる様子」という名詞句を作れる。"}, {"text": "舞い上がり", "is_correct": false, "explanation": "連用形のため「様子を」に続かず、名詞を修飾できない。"}, {"text": "舞い上がらせる", "is_correct": false, "explanation": "使役形になり、火の粉が自分で舞う現象の描写と合わない。"}, {"text": "舞い上げた", "is_correct": false, "explanation": "他動詞の過去形で、火の粉が主語の自然な上昇現象と合わない。"}], "explanations": {"舞い上がる": "基本形で、「火の粉が夜空に舞い上がる様子」という名詞句を作れる。", "舞い上がり": "連用形のため「様子を」に続かず、名詞を修飾できない。", "舞い上がらせる": "使役形になり、火の粉が自分で舞う現象の描写と合わない。", "舞い上げた": "他動詞の過去形で、火の粉が主語の自然な上昇現象と合わない。"}, "sentence_index": 6, "correct_answer": "舞い上がる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪が地面に舞い上がった。", "explanation": "〈舞い降りる〉の意味。舞い上がるは上へ向かう動きなので、地面へ落ちる雪には合わない。"}, {"text": "港で、重い錨が舞い上がった。", "explanation": "〈下ろされる〉の意味。錨は重く、軽く空中を舞う舞い上がるとは合わない。"}, {"text": "床にビーズが舞い上がっていた。", "explanation": "〈散らばる〉の意味。床に広がって止まっているものには、空中へ上がる意味の舞い上がるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52852, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "突風で木の葉が舞い上がらた。", "corrected_sentence": "突風で木の葉が舞い上がった。", "error_description": "過去形の活用が誤り。「舞い上がらた」は誤った形で、正しくは「舞い上がった」（ラ行五段動詞の促音便）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "舞い上がった", "is_correct": true, "explanation": "過去形で、紙が一斉に上がったという完了した出来事を正しく表す。"}, {"text": "舞い上がって", "is_correct": false, "explanation": "て形のため「紙が舞い上がって、」と続く形になり、出来事を完結させられない。"}, {"text": "舞い上がらない", "is_correct": false, "explanation": "否定形なので、紙が上がらなかったという意味になり、文脈と逆になる。"}, {"text": "舞い上がれば", "is_correct": false, "explanation": "仮定形で条件の意味になり、実際に起きた出来事を述べていない。"}], "correct_form": "舞い上がった", "base_form": "舞い上がる", "form_label": "過去形", "sentence_index": 1, "explanations": {"舞い上がった": "過去形で、紙が一斉に上がったという完了した出来事を正しく表す。", "舞い上がって": "て形のため「紙が舞い上がって、」と続く形になり、出来事を完結させられない。", "舞い上がらない": "否定形なので、紙が上がらなかったという意味になり、文脈と逆になる。", "舞い上がれば": "仮定形で条件の意味になり、実際に起きた出来事を述べていない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52852, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い風で紙を舞い上がった。", "corrected_sentence": "強い風で紙が舞い上がった。", "error_description": "目的語の「を」が誤り。「舞い上がる」は自動詞なので、主語を示す「が」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "舞い上がって", "is_correct": true, "explanation": "て形で、「舞い上がってしまう」と続けて動作の完了や結果を表せる。"}, {"text": "舞い上がり", "is_correct": false, "explanation": "連用形では「しまう」に続かず、文として成り立たない。"}, {"text": "舞い上がった", "is_correct": false, "explanation": "過去形の後に「しまう」は続かず、「舞い上がったしまう」は不自然。"}, {"text": "舞い上がる", "is_correct": false, "explanation": "基本形の後に「しまう」は続かず、「舞い上がるしまう」は不自然。"}], "correct_form": "舞い上がって", "base_form": "舞い上がる", "form_label": "て形", "sentence_index": 7, "explanations": {"舞い上がって": "て形で、「舞い上がってしまう」と続けて動作の完了や結果を表せる。", "舞い上がり": "連用形では「しまう」に続かず、文として成り立たない。", "舞い上がった": "過去形の後に「しまう」は続かず、「舞い上がったしまう」は不自然。", "舞い上がる": "基本形の後に「しまう」は続かず、「舞い上がるしまう」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52853, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「学校の行事」と名詞をつなぐ「の」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「学校を行事」では名詞を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "「学校へ行事」では文が成り立たない。"}, {"text": "まで", "is_correct": false, "explanation": "「学校まで行事」では「行事」を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「学校の行事」と名詞をつなぐ「の」が自然。", "を": "「学校を行事」では名詞を修飾できない。", "へ": "「学校へ行事」では文が成り立たない。", "まで": "「学校まで行事」では「行事」を修飾できない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "まで": "extent"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "日常", "is_correct": true, "explanation": "特別な催しである行事に対し、ふだんの生活を表す反意的な語。"}, {"text": "催し", "is_correct": false, "explanation": "催しは行事の類義語である。"}, {"text": "イベント", "is_correct": false, "explanation": "イベントは行事の類義語である。"}, {"text": "大会", "is_correct": false, "explanation": "大会は行事の一種で、反意語ではない。"}], "correct_answer": "日常", "explanations": {"日常": "特別な催しである行事に対し、ふだんの生活を表す反意的な語。", "催し": "催しは行事の類義語である。", "イベント": "イベントは行事の類義語である。", "大会": "大会は行事の一種で、反意語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
