INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52853, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "行事は、学校や会社で行う特別な催しやイベントのことです。", "primary_collocate": null, "pronunciation": "ぎょうじ", "ipa": "ɡjoːdʑi", "syllable_count": 3, "sentences": [{"text": "行事がある。", "target_word": "行事", "complexity_tier": "T1", "furigana": "ぎょうじがある。", "sentence_source": "generated"}, {"text": "行事は明日だ。", "target_word": "行事", "complexity_tier": "T1", "furigana": "ぎょうじはあしただ。", "sentence_source": "generated"}, {"text": "学校の行事に参加します。", "target_word": "行事", "complexity_tier": "T2", "furigana": "がっこうのぎょうじにさんかします。", "sentence_source": "generated"}, {"text": "会社で行事を行いました。", "target_word": "行事", "complexity_tier": "T2", "furigana": "かいしゃでぎょうじをおこないました。", "sentence_source": "generated"}, {"text": "運動会は、秋の大きな行事の一つだ。", "target_word": "行事", "complexity_tier": "T3", "furigana": "うんどうかいは、あきのおおきなぎょうじのひとつだ。", "sentence_source": "generated"}, {"text": "行事の前に、みんなで教室を掃除した。", "target_word": "行事", "complexity_tier": "T3", "furigana": "ぎょうじのまえに、みんなできょうしつをそうじした。", "sentence_source": "generated"}, {"text": "新年の行事に出るため、社員全員が朝早く集まった。", "target_word": "行事", "complexity_tier": "T4", "furigana": "しんねんのぎょうじにでるため、しゃいんぜんいんがあさはやくあつまった。", "sentence_source": "generated"}, {"text": "雨で行事が延期になったので、予定を組み直した。", "target_word": "行事", "complexity_tier": "T4", "furigana": "あめでぎょうじがえんきになったので、よていをくみなおした。", "sentence_source": "generated"}, {"text": "季節ごとの行事を通して、子どもたちは日本の文化を自然に学んでいく。", "target_word": "行事", "complexity_tier": "T5", "furigana": "きせつごとのぎょうじをとおして、こどもたちはにほんのぶんかをしぜんにまなんでいく。", "sentence_source": "generated"}, {"text": "行事の準備が忙しくて、先生たちは夜遅くまで学校に残っていた。", "target_word": "行事", "complexity_tier": "T5", "furigana": "ぎょうじのじゅんびがいそがしくて、せんせいたちはよるおそくまでがっこうにのこっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年中行事", "label": "派生"}, {"form": "学校行事", "label": "派生"}, {"form": "行事食", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 学校や会社で行う特別な催し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52853, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行事", "is_correct": true, "explanation": "ぎょうじ。見出し語。"}, {"text": "凝視", "is_correct": false, "explanation": "ぎょうし。「じ」と「し」の一拍だけが違う。"}, {"text": "教示", "is_correct": false, "explanation": "きょうじ。「ぎょ」と「きょ」の一拍だけが違う。"}, {"text": "餃子", "is_correct": false, "explanation": "ぎょうざ。「じ」と「ざ」の一拍だけが違う。"}], "explanations": {"行事": "ぎょうじ。見出し語。", "凝視": "ぎょうし。「じ」と「し」の一拍だけが違う。", "教示": "きょうじ。「ぎょ」と「きょ」の一拍だけが違う。", "餃子": "ぎょうざ。「じ」と「ざ」の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "行事"}, "level_3": {"options": [{"text": "行事", "is_correct": true, "explanation": "学校や会社で行う催しがあるという意味になる。"}, {"text": "一緒", "is_correct": false, "explanation": "形は合うが意味が合わない。「一緒がある」とは言えない。"}, {"text": "以内", "is_correct": false, "explanation": "形は合うが意味が合わない。「以内がある」とは言えない。"}, {"text": "以上", "is_correct": false, "explanation": "形は合うが意味が合わない。「以上がある」は文として意味をなさない。"}], "explanations": {"行事": "学校や会社で行う催しがあるという意味になる。", "一緒": "形は合うが意味が合わない。「一緒がある」とは言えない。", "以内": "形は合うが意味が合わない。「以内がある」とは言えない。", "以上": "形は合うが意味が合わない。「以上がある」は文として意味をなさない。"}, "sentence_index": 0, "correct_answer": "行事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社で行事を食べました。", "explanation": "行事は催しなので、食べる対象にならない。"}, {"text": "行事を机の上に置きました。", "explanation": "行事は催しで、机の上に置ける物ではない。"}, {"text": "行事は私の右足にあります。", "explanation": "行事は催しなので、体の一部にあるものとしては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
