INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52854, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「世代を超えて」で、越える対象を示す「を」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「世代に超えて」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「超える」の対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「世代で超えて」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「世代を超えて」で、越える対象を示す「を」が自然。", "に": "「世代に超えて」とは言えない。", "へ": "方向の「へ」では「超える」の対象を示せない。", "で": "「世代で超えて」は文として成り立たない。"}, "error_tags": {"に": "target_or_location", "へ": "direction", "で": "means_or_location"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "日常", "is_correct": true, "explanation": "特別な催しである行事に対し、ふだんの生活を表す反意的な語。"}, {"text": "儀式", "is_correct": false, "explanation": "儀式は行事に近い語で、反意語ではない。"}, {"text": "祝日", "is_correct": false, "explanation": "祝日は特別な日で、反意語ではない。"}, {"text": "会合", "is_correct": false, "explanation": "会合は人が集まる催しで、反意語ではない。"}], "correct_answer": "日常", "explanations": {"日常": "特別な催しである行事に対し、ふだんの生活を表す反意的な語。", "儀式": "儀式は行事に近い語で、反意語ではない。", "祝日": "祝日は特別な日で、反意語ではない。", "会合": "会合は人が集まる催しで、反意語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52854, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "行事とは、特定の目的や日程に基づいて計画・実施される、公的または集団的な催しや儀式。", "primary_collocate": null, "pronunciation": "ぎょうじ", "ipa": "ɡjoːdʑi", "syllable_count": 3, "sentences": [{"text": "この創造的プロセスこそが、行事の記憶を永続的なものへと変貌させ、参加者の帰属意識を強固なものへと昇華させるのである。", "target_word": "行事", "complexity_tier": "T6", "furigana": "このそうぞうてきぷろせすこそが、ぎょうじのきおくをえいぞくてきなものへとへんぼうさせ、さんかしゃのきぞくいしきをきょうこなものへとしょうかさせるのである。", "sentence_source": "mined"}, {"text": "この町の行事は有名です。", "target_word": "行事", "complexity_tier": "T2", "furigana": "このまちのぎょうじはゆうめいです。", "sentence_source": "generated"}, {"text": "毎年、神社で行事が行われる。", "target_word": "行事", "complexity_tier": "T2", "furigana": "まいとし、じんじゃでぎょうじがおこなわれる。", "sentence_source": "generated"}, {"text": "年に一度の行事には、昔からの意味がある。", "target_word": "行事", "complexity_tier": "T3", "furigana": "ねんにいちどのぎょうじには、むかしからのいみがある。", "sentence_source": "generated"}, {"text": "行事の日程が、町の掲示板に出ていた。", "target_word": "行事", "complexity_tier": "T3", "furigana": "ぎょうじのにっていが、まちのけいじばんにでていた。", "sentence_source": "generated"}, {"text": "地域の行事を守るために、若者が運営に加わった。", "target_word": "行事", "complexity_tier": "T4", "furigana": "ちいきのぎょうじをまもるために、わかものがうんえいにくわわった。", "sentence_source": "generated"}, {"text": "国の行事として、式典が厳かに執り行われた。", "target_word": "行事", "complexity_tier": "T4", "furigana": "くにのぎょうじとして、しきてんがおごそかにとりおこなわれた。", "sentence_source": "generated"}, {"text": "伝統的な行事は、世代を超えて地域の人々をつなぐ役割を果たしてきた。", "target_word": "行事", "complexity_tier": "T5", "furigana": "でんとうてきなぎょうじは、せだいをこえてちいきのひとびとをつなぐやくわりをはたしてきた。", "sentence_source": "generated"}, {"text": "行事の簡素化を求める声がある一方で、続けたいという住民も多い。", "target_word": "行事", "complexity_tier": "T5", "furigana": "ぎょうじのかんそかをもとめるこえがあるいっぽうで、つづけたいというじゅうみんもおおい。", "sentence_source": "generated"}, {"text": "行事を減らすべきかどうかについて、保護者の間で議論が起きている。", "target_word": "行事", "complexity_tier": "T5", "furigana": "ぎょうじをへらすべきかどうかについて、ほごしゃのあいだでぎろんがおきている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年中行事", "label": "派生"}, {"form": "学校行事", "label": "派生"}, {"form": "行事食", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 計画的に実施される公的な催しや儀式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52854, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行事", "is_correct": true, "explanation": "ぎょうじ。見出し語。"}, {"text": "凝視", "is_correct": false, "explanation": "ぎょうし。「じ」と「し」の一拍だけが違う。"}, {"text": "教示", "is_correct": false, "explanation": "きょうじ。「ぎょ」と「きょ」の一拍だけが違う。"}, {"text": "餃子", "is_correct": false, "explanation": "ぎょうざ。「じ」と「ざ」の一拍だけが違う。"}], "explanations": {"行事": "ぎょうじ。見出し語。", "凝視": "ぎょうし。「じ」と「し」の一拍だけが違う。", "教示": "きょうじ。「ぎょ」と「きょ」の一拍だけが違う。", "餃子": "ぎょうざ。「じ」と「ざ」の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "行事"}, "level_3": {"options": [{"text": "行事", "is_correct": true, "explanation": "参加者の記憶や帰属意識につながる催しという意味に合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。参加者の帰属意識を強める記憶の対象にならない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。参加者の帰属意識を強める記憶とは結びつかない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが意味が合わない。参加者の帰属意識を強める記憶の対象としては不自然。"}], "explanations": {"行事": "参加者の記憶や帰属意識につながる催しという意味に合う。", "野菜": "形は合うが意味が合わない。参加者の帰属意識を強める記憶の対象にならない。", "天気": "形は合うが意味が合わない。参加者の帰属意識を強める記憶とは結びつかない。", "電車": "形は合うが意味が合わない。参加者の帰属意識を強める記憶の対象としては不自然。"}, "sentence_index": 0, "correct_answer": "行事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "行事を毎朝コップに入れて飲みます。", "explanation": "行事は催しや儀式で、飲み物のように飲むことはできない。"}, {"text": "この行事は、一年中ずっと終わらない一つの川です。", "explanation": "行事は計画された催しで、川のような自然物ではない。"}, {"text": "彼は行事を着て、会場へ向かった。", "explanation": "行事は催しなので、服のように着ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52854, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行事", "is_correct": true, "explanation": "ぎょうじ。見出し語。"}, {"text": "業務", "is_correct": false, "explanation": "ぎょうむ。「じ」と「む」の一拍だけが違う。"}, {"text": "行儀", "is_correct": false, "explanation": "ぎょうぎ。「じ」と「ぎ」の一拍だけが違う。"}, {"text": "矜持", "is_correct": false, "explanation": "きょうじ。「ぎょ」と「きょ」の一拍だけが違う。"}], "explanations": {"行事": "ぎょうじ。見出し語。", "業務": "ぎょうむ。「じ」と「む」の一拍だけが違う。", "行儀": "ぎょうぎ。「じ」と「ぎ」の一拍だけが違う。", "矜持": "きょうじ。「ぎょ」と「きょ」の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "行事"}, "level_3": {"options": [{"text": "行事", "is_correct": true, "explanation": "「国の行事として式典が行われた」と、公的な催しの意味に合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。野菜として式典が行われるとは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気として式典が行われるとは言えない。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが意味が合わない。果物として式典が行われるとは言えない。"}], "explanations": {"行事": "「国の行事として式典が行われた」と、公的な催しの意味に合う。", "野菜": "形は合うが意味が合わない。野菜として式典が行われるとは言えない。", "天気": "形は合うが意味が合わない。天気として式典が行われるとは言えない。", "果物": "形は合うが意味が合わない。果物として式典が行われるとは言えない。"}, "sentence_index": 6, "correct_answer": "行事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "行事を食べるべきかどうか、保護者が議論している。", "explanation": "行事は催しなので、食べる対象にならない。"}, {"text": "行事が毎日の食事のように、歩いて家に帰ってきた。", "explanation": "行事は催しで、人のように歩くことはできない。"}, {"text": "行事をかばんに入れて、駅まで運んだ。", "explanation": "行事は催しなので、かばんに入れて運べる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52854, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎年、神社で行事が食べられる。", "corrected_sentence": "毎年、神社で行事が行われる。", "error_description": "行事は「行われる」ものであり、「食べられる」とは言えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52854, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国の行事を、式典が厳かに執り行われた。", "corrected_sentence": "国の行事として、式典が厳かに執り行われた。", "error_description": "「国の行事として」とするのが正しい。「を」では意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52855, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「眠りが」の「が」で、眠りを主語にして「午後の仕事を楽にしてくれる」と続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すため、「眠りを、午後の仕事を楽にしてくれる」では主語と述語が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "修飾の「の」だが、「眠りの、」の後に名詞がなく、文が途切れて成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「眠りへ、午後の仕事を楽にしてくれる」は主語を示せず不自然。"}], "correct_answer": "が", "explanations": {"が": "「眠りが」の「が」で、眠りを主語にして「午後の仕事を楽にしてくれる」と続く。", "を": "目的語を示すため、「眠りを、午後の仕事を楽にしてくれる」では主語と述語が成り立たない。", "の": "修飾の「の」だが、「眠りの、」の後に名詞がなく、文が途切れて成り立たない。", "へ": "方向を示すため、「眠りへ、午後の仕事を楽にしてくれる」は主語を示せず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52855, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「眠りにつく」の「に」で、眠りへ至る動作の到達点を示す。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すため、「眠りでついている」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「眠りへついている」は慣用的な表現として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「眠りからついている」は不自然。起点は「眠りから覚める」で使う。"}], "correct_answer": "に", "explanations": {"に": "「眠りにつく」の「に」で、眠りへ至る動作の到達点を示す。", "で": "場所や手段を示すため、「眠りでついている」は意味が通らない。", "へ": "方向を示すが、「眠りへついている」は慣用的な表現として成り立たない。", "から": "起点を示すため、「眠りからついている」は不自然。起点は「眠りから覚める」で使う。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52855, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ねむること。目をとじて、しばらく何もしないこと。", "primary_collocate": null, "pronunciation": "ねむり", "ipa": "nemɯɾi", "syllable_count": 3, "sentences": [{"text": "電車の中で短い眠りをとったら、少し元気になった。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で短[みじか]い眠[ねむ]りをとったら、少[すこ]し元気[げんき]になった。", "sentence_source": "generated"}, {"text": "昼食のあとの十分ほどの眠りが、午後の仕事を楽にしてくれる。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "昼食[ちゅうしょく]のあとの十分[じゅっぷん]ほどの眠[ねむ]りが、午後[ごご]の仕事[しごと]を楽[らく]にしてくれる。", "sentence_source": "generated"}, {"text": "彼は机にふせて、浅い眠りに入った。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "彼[かれ]は机[つくえ]にふせて、浅[あさ]い眠[ねむ]りに入[はい]った。", "sentence_source": "generated"}, {"text": "長旅の途中、バスの揺れに誘われて眠りについた。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "長旅[ながたび]の途中[とちゅう]、バスの揺[ゆ]れに誘[さそ]われて眠[ねむ]りについた。", "sentence_source": "generated"}, {"text": "試験の前の晩は、緊張して眠りにつけなかった。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]の晩[ばん]は、緊張[きんちょう]して眠[ねむ]りにつけなかった。", "sentence_source": "generated"}, {"text": "授業中の短い眠りを先生に見つかって、注意された。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "授業中[じゅぎょうちゅう]の短[みじか]い眠[ねむ]りを先生[せんせい]に見[み]つかって、注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "夜の眠りを少し長くしたら、朝がつらくなくなった。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "夜[よる]の眠[ねむ]りを少[すこ]し長[なが]くしたら、朝[あさ]がつらくなくなった。", "sentence_source": "generated"}, {"text": "日だまりで犬が気持ちよさそうな眠りについている。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "日[ひ]だまりで犬[いぬ]が気持[きも]ちよさそうな眠[ねむ]りについている。", "sentence_source": "generated"}, {"text": "夜中に電話が鳴って、せっかくの眠りが破られた。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "夜中[よなか]に電話[でんわ]が鳴[な]って、せっかくの眠[ねむ]りが破[やぶ]られた。", "sentence_source": "generated"}, {"text": "病院では、患者の眠りを守るために夜は照明を落とす。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "病院[びょういん]では、患者[かんじゃ]の眠[ねむ]りを守[まも]るために夜[よる]は照明[しょうめい]を落[お]とす。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眠り", "label": "基本形"}, {"form": "眠りに", "label": "に格"}], "register": "neutral", "sense_fingerprint": "目をとじて休むという行為としての眠ること（仮眠・居眠りなども含む）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: 日だまり (Zipf 1.86)']::text[], 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52855, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眠り", "is_correct": true, "explanation": "目を閉じて休む行為としての眠りで、「短い眠りをとった」と自然に続く。"}, {"text": "目覚め", "is_correct": false, "explanation": "目を覚ますこと。「短い目覚めをとった」は、眠る行為の文脈と合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝ているときの呼吸音。「短い寝息をとった」は意味が通らない。"}, {"text": "夢見", "is_correct": false, "explanation": "夢を見ること。「短い夢見をとった」は、休む行為として不自然。"}], "explanations": {"眠り": "目を閉じて休む行為としての眠りで、「短い眠りをとった」と自然に続く。", "目覚め": "目を覚ますこと。「短い目覚めをとった」は、眠る行為の文脈と合わない。", "寝息": "寝ているときの呼吸音。「短い寝息をとった」は意味が通らない。", "夢見": "夢を見ること。「短い夢見をとった」は、休む行為として不自然。"}, "sentence_index": 0, "correct_answer": "眠り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤ちゃんの眠りが、すやすやと小さく聞こえた。", "explanation": "〈寝息〉の意味。寝ている間の呼吸音は寝息と言い、眠りという状態は聞こえるものではない。"}, {"text": "洗濯のあと、眠りを庭に広げて干した。", "explanation": "〈布団〉の意味。干すのは布団などの寝具で、眠りという状態は干せない。"}, {"text": "寝つけない夜が続き、医者に眠りを処方された。", "explanation": "〈睡眠薬〉の意味。処方されるのは薬で、眠りという睡眠の状態は処方できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52855, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠り", "is_correct": true, "explanation": "睡眠の時間や状態を表し、「夜の眠りを少し長くしたら」と自然に続く。"}, {"text": "寝顔", "is_correct": false, "explanation": "寝ている人の顔のこと。「夜の寝顔を少し長くしたら」は意味が通らない。"}, {"text": "覚醒", "is_correct": false, "explanation": "目が覚めている状態。「夜の覚醒を少し長くしたら」は文脈と合わない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝ている間に話す言葉。「夜の寝言を少し長くしたら」は不自然。"}], "explanations": {"眠り": "睡眠の時間や状態を表し、「夜の眠りを少し長くしたら」と自然に続く。", "寝顔": "寝ている人の顔のこと。「夜の寝顔を少し長くしたら」は意味が通らない。", "覚醒": "目が覚めている状態。「夜の覚醒を少し長くしたら」は文脈と合わない。", "寝言": "寝ている間に話す言葉。「夜の寝言を少し長くしたら」は不自然。"}, "sentence_index": 6, "correct_answer": "眠り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業中、眠りを感じて目をこすった。", "explanation": "〈眠気〉の意味。感じるのは眠気で、眠りという行為そのものを感じるとは言わない。"}, {"text": "授業中、先生の話を聞きながら眠りをして叱られた。", "explanation": "〈居眠り〉の意味。「居眠りをする」とは言うが、「眠りをする」とは言わない。"}, {"text": "映画を見ながら、眠りを見た。", "explanation": "〈夢〉の意味。夢は見るものだが、眠りを見るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52855, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電車の中で短い眠りがとったら、すっきりした。", "corrected_sentence": "電車の中で短い眠りをとったら、すっきりした。", "error_description": "格助詞の「が」が誤り。「とる」の目的語は「を」で示すので、「眠りを」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52855, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜中に電話が鳴って、せっかくの眠りが突然破った。", "corrected_sentence": "夜中に電話が鳴って、せっかくの眠りが突然破られた。", "error_description": "「破る」の態が誤り。眠りが主語なので受身の「破られた」が必要で、「破った」は他動詞の能動形になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52856, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52856, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「眠りから覚めた」の起点を示す「から」で、眠りの後ろに直接つながる。"}, {"text": "に", "is_correct": false, "explanation": "「眠りに覚めた」は起点ではなく到達を示すことになり、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「眠りを覚めた」は他動詞の形を取るため、自動詞「覚める」と合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同を示すため、「眠りと覚めた」は意味が通らない。"}], "correct_answer": "から", "explanations": {"から": "「眠りから覚めた」の起点を示す「から」で、眠りの後ろに直接つながる。", "に": "「眠りに覚めた」は起点ではなく到達を示すことになり、不自然。", "を": "「眠りを覚めた」は他動詞の形を取るため、自動詞「覚める」と合わない。", "と": "共同を示すため、「眠りと覚めた」は意味が通らない。"}, "error_tags": {"に": "帰着", "を": "対象", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52856, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "睡眠状態にあること。意識がなく、体が休んでいる状態。", "primary_collocate": null, "pronunciation": "ねむり", "ipa": "nemɯɾi", "syllable_count": 3, "sentences": [{"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "眠り", "complexity_tier": "T5", "furigana": "革[かわ]の匂[にお]いが漂[ただよ]う暗闇[くらやみ]の奥底[おくそこ]で、長[なが]き眠[ねむ]りについていたそれを引[ひ]きずり出[だ]した瞬間[しゅんかん]、埃[ほこり]っぽい記憶[きおく]の粒子[りゅうし]が舞[ま]い上[あ]がる。", "sentence_source": "mined"}, {"text": "昨夜は深い眠りだったので、朝まで一度も目が覚めなかった。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "昨夜[さくや]は深[ふか]い眠[ねむ]りだったので、朝[あさ]まで一度[いちど]も目[め]が覚[さ]めなかった。", "sentence_source": "generated"}, {"text": "赤ちゃんは静かな眠りの中で、小さく笑った。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは静[しず]かな眠[ねむ]りの中[なか]で、小[ちい]さく笑[わら]った。", "sentence_source": "generated"}, {"text": "疲れていた父は、すぐに深い眠りに落ちた。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "疲[つか]れていた父[ちち]は、すぐに深[ふか]い眠[ねむ]りに落[お]ちた。", "sentence_source": "generated"}, {"text": "眠りが浅いと、朝になっても疲れが取れない。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "眠[ねむ]りが浅[あさ]いと、朝[あさ]になっても疲[つか]れが取[と]れない。", "sentence_source": "generated"}, {"text": "母は眠りを妨げないように、そっとドアを閉めた。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "母[はは]は眠[ねむ]りを妨[さまた]げないように、そっとドアを閉[し]めた。", "sentence_source": "generated"}, {"text": "冬の間、クマは長い眠りにつく。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]、クマは長[なが]い眠[ねむ]りにつく。", "sentence_source": "generated"}, {"text": "眠りから覚めた猫が、大きくあくびをした。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "眠[ねむ]りから覚[さ]めた猫[ねこ]が、大[おお]きくあくびをした。", "sentence_source": "generated"}, {"text": "部屋が暑すぎて、夜の眠りが何度も途切れた。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "部屋[へや]が暑[あつ]すぎて、夜[よる]の眠[ねむ]りが何度[なんど]も途切[とぎ]れた。", "sentence_source": "generated"}, {"text": "患者は薬のおかげで穏やかな眠りを取り戻した。", "target_word": "眠り", "complexity_tier": "T3", "furigana": "患者[かんじゃ]は薬[くすり]のおかげで穏[おだ]やかな眠[ねむ]りを取[と]り戻[もど]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眠り", "label": "基本形"}, {"form": "眠りに", "label": "に格"}], "register": "neutral", "sense_fingerprint": "意識がなく体が休んでいる睡眠の状態（深い・浅い・長いなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 奥底 (Zipf 3.21), 長き (Zipf 3.3), 引きずり出し (Zipf 2.55), 舞い上がる (Zipf 2.61)']::text[], 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52856, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眠り", "is_correct": true, "explanation": "睡眠状態を表し、「長き眠りについていた」と自然につながる。"}, {"text": "目覚め", "is_correct": false, "explanation": "眠りから覚めること。「長き目覚めについていた」は意味が通らない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝ているときの呼吸音で、「長き寝息についていた」と続けると不自然。"}, {"text": "夢見", "is_correct": false, "explanation": "夢を見ること。「長き夢見についていた」は睡眠状態の描写として不自然。"}], "explanations": {"眠り": "睡眠状態を表し、「長き眠りについていた」と自然につながる。", "目覚め": "眠りから覚めること。「長き目覚めについていた」は意味が通らない。", "寝息": "寝ているときの呼吸音で、「長き寝息についていた」と続けると不自然。", "夢見": "夢を見ること。「長き夢見についていた」は睡眠状態の描写として不自然。"}, "sentence_index": 0, "correct_answer": "眠り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨夜は楽しい眠りを見て、朝まで笑っていた。", "explanation": "〈夢〉の意味。楽しい場面は夢として見るもので、眠りという睡眠の状態そのものを見るとは言わない。"}, {"text": "不眠が続いたので、医者に眠りを処方してもらった。", "explanation": "〈睡眠薬〉の意味。薬は処方するもので、眠りという睡眠の状態は処方するものではない。"}, {"text": "作業のあと、眠りを外に干して乾かした。", "explanation": "〈布団〉の意味。干して乾かすのは布団などの寝具で、眠りという状態は干せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52856, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠り", "is_correct": true, "explanation": "睡眠状態を表し、「冬の間、クマは長い眠りにつく」と自然に続く。"}, {"text": "寝顔", "is_correct": false, "explanation": "寝ている人の顔のこと。「長い寝顔につく」は意味が通らない。"}, {"text": "覚醒", "is_correct": false, "explanation": "目が覚めている状態。「長い覚醒につく」は文脈に合わない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝ている間に話す言葉。「長い寝言につく」は成り立たない。"}], "explanations": {"眠り": "睡眠状態を表し、「冬の間、クマは長い眠りにつく」と自然に続く。", "寝顔": "寝ている人の顔のこと。「長い寝顔につく」は意味が通らない。", "覚醒": "目が覚めている状態。「長い覚醒につく」は文脈に合わない。", "寝言": "寝ている間に話す言葉。「長い寝言につく」は成り立たない。"}, "sentence_index": 6, "correct_answer": "眠り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議中、眠りを感じて何度もあくびが出た。", "explanation": "〈眠気〉の意味。感じるのは眠気で、眠りという睡眠の状態そのものは感じるものではない。"}, {"text": "赤ちゃんは小さな眠りの音を立てて、ぐっすり寝ている。", "explanation": "〈寝息〉の意味。寝ているときの呼吸音は寝息と言い、眠りとは言わない。"}, {"text": "毎日、眠り時間を八時間確保するようにしている。", "explanation": "〈睡眠時間〉の意味。時間の長さは睡眠時間と言い、眠り時間とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52856, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅の疲れで、すぐに深い眠りを落ちた。", "corrected_sentence": "旅の疲れで、すぐに深い眠りに落ちた。", "error_description": "格助詞の「を」が誤り。「落ちる」の到達点を示す「に」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52856, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の間、クマは長い眠りにつきた。", "corrected_sentence": "冬の間、クマは長い眠りについた。", "error_description": "「つく」の過去形の活用が誤り。正しくは「ついた」（カ行五段動詞「つく」の過去形）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52858, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「帰属を感じる」で感じる対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「帰属に強く感じている」は不自然で文にならない。"}, {"text": "で", "is_correct": false, "explanation": "「帰属で感じている」では対象を示せず意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「帰属へ強く感じている」は感じる対象を示せず、文として成立しない。"}], "correct_answer": "を", "explanations": {"を": "「帰属を感じる」で感じる対象を示す。", "に": "「帰属に強く感じている」は不自然で文にならない。", "で": "「帰属で感じている」では対象を示せず意味が通らない。", "へ": "「帰属へ強く感じている」は感じる対象を示せず、文として成立しない。"}, "error_tags": {"に": "wrong_case", "で": "wrong_case", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疎外", "is_correct": true, "explanation": "仲間に入れず外に置かれることで、帰属の反対にあたる。"}, {"text": "所属", "is_correct": false, "explanation": "帰属に近い類義語で、反対の意味ではない。"}, {"text": "参加", "is_correct": false, "explanation": "活動に加わることで、帰属の反対ではない。"}, {"text": "加入", "is_correct": false, "explanation": "集団に入ることで、帰属の反対ではない。"}], "correct_answer": "疎外", "explanations": {"疎外": "仲間に入れず外に置かれることで、帰属の反対にあたる。", "所属": "帰属に近い類義語で、反対の意味ではない。", "参加": "活動に加わることで、帰属の反対ではない。", "加入": "集団に入ることで、帰属の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52858, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「国家への帰属」で帰属先を名詞につなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「国家へを帰属」は助詞が重なって成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「国家へで帰属」は成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「国家へから帰属」は成立しない。"}], "correct_answer": "の", "explanations": {"の": "「国家への帰属」で帰属先を名詞につなぐ。", "を": "「国家へを帰属」は助詞が重なって成立しない。", "で": "「国家へで帰属」は成立しない。", "から": "「国家へから帰属」は成立しない。"}, "error_tags": {"を": "wrong_case", "で": "wrong_case", "から": "wrong_case"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "離脱", "is_correct": true, "explanation": "集団から離れることで、帰属の反対にあたる。"}, {"text": "所属", "is_correct": false, "explanation": "帰属に近い類義語で、反対の意味ではない。"}, {"text": "団結", "is_correct": false, "explanation": "集団がまとまることで、帰属の反対ではない。"}, {"text": "連帯", "is_correct": false, "explanation": "結びつきを表し、帰属の反対ではない。"}], "correct_answer": "離脱", "explanations": {"離脱": "集団から離れることで、帰属の反対にあたる。", "所属": "帰属に近い類義語で、反対の意味ではない。", "団結": "集団がまとまることで、帰属の反対ではない。", "連帯": "結びつきを表し、帰属の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52858, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある集団や組織の一員であること。また、その意識。", "primary_collocate": null, "pronunciation": "きぞく", "ipa": "kizokɯ", "syllable_count": 3, "sentences": [{"text": "この創造的プロセスこそが、行事の記憶を永続的なものへと変貌させ、参加者の帰属意識を強固なものへと昇華させるのである。", "target_word": "帰属", "complexity_tier": "T6", "furigana": "この創造的[そうぞうてき]プロセスこそが、行事[ぎょうじ]の記憶[きおく]を永続的[えいぞくてき]なものへと変貌[へんぼう]させ、参加者[さんかしゃ]の帰属[きぞく]意識[いしき]を強固[きょうこ]なものへと昇華[しょうか]させるのである。", "sentence_source": "mined"}, {"text": "彼は会社への帰属を強く感じている。", "target_word": "帰属", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]への帰属[きぞく]を強[つよ]く感[かん]じている。", "sentence_source": "generated"}, {"text": "この学校に帰属する生徒は三百人です。", "target_word": "帰属する", "complexity_tier": "T3", "furigana": "この学校[がっこう]に帰属[きぞく]する生徒[せいと]は三百人[さんびゃくにん]です。", "sentence_source": "generated"}, {"text": "帰属の感覚が弱いと、人は孤独になりやすい。", "target_word": "帰属", "complexity_tier": "T4", "furigana": "帰属[きぞく]の感覚[かんかく]が弱[よわ]いと、人[ひと]は孤独[こどく]になりやすい。", "sentence_source": "generated"}, {"text": "転職する人が増えて、会社への帰属は弱くなった。", "target_word": "帰属", "complexity_tier": "T3", "furigana": "転職[てんしょく]する人[ひと]が増[ふ]えて、会社[かいしゃ]への帰属[きぞく]は弱[よわ]くなった。", "sentence_source": "generated"}, {"text": "若者は集団への帰属を求めて、SNSに集まる。", "target_word": "帰属", "complexity_tier": "T3", "furigana": "若者[わかもの]は集団[しゅうだん]への帰属[きぞく]を求[もと]めて、SNSに集[あつ]まる。", "sentence_source": "generated"}, {"text": "彼女は地元のチームに帰属していることを誇りに思っている。", "target_word": "帰属して", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は地元[じもと]のチームに帰属[きぞく]していることを誇[ほこ]りに思[おも]っている。", "sentence_source": "generated"}, {"text": "国家への帰属が問われる時代になった。", "target_word": "帰属", "complexity_tier": "T4", "furigana": "国家[こっか]への帰属[きぞく]が問[と]われる時代[じだい]になった。", "sentence_source": "generated"}, {"text": "帰属が曖昧な人ほど、不安を感じやすい。", "target_word": "帰属", "complexity_tier": "T3", "furigana": "帰属[きぞく]が曖昧[あいまい]な人[ひと]ほど、不安[ふあん]を感[かん]じやすい。", "sentence_source": "generated"}, {"text": "地域への帰属は、祭りに参加することで深まっていく。", "target_word": "帰属", "complexity_tier": "T4", "furigana": "地域[ちいき]への帰属[きぞく]は、祭[まつ]りに参加[さんか]することで深[ふか]まっていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "帰属する", "label": "活用"}, {"form": "帰属した", "label": "活用"}, {"form": "帰属意識", "label": "派生"}, {"form": "帰属先", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 集団の一員であること、その意識", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0dbfc7-ded3-42fa-8956-25a04f821c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52858, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帰属", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "規則", "is_correct": false, "explanation": "きそくで、ぞ→その清濁だけが違う別の語。"}, {"text": "記録", "is_correct": false, "explanation": "きろくで、ぞ→ろの1拍だけが違う別の語。"}, {"text": "記憶", "is_correct": false, "explanation": "きおくで、ぞ→おの1拍だけが違う別の語。"}, {"text": "寄贈", "is_correct": false, "explanation": "きぞうで、く→うの1拍だけが違う別の語。"}], "explanations": {"帰属": "見出し語そのもの。", "規則": "きそくで、ぞ→その清濁だけが違う別の語。", "記録": "きろくで、ぞ→ろの1拍だけが違う別の語。", "記憶": "きおくで、ぞ→おの1拍だけが違う別の語。", "寄贈": "きぞうで、く→うの1拍だけが違う別の語。"}, "sentence_index": null, "correct_answer": "帰属"}, "level_3": {"options": [{"text": "帰属", "is_correct": true, "explanation": "「帰属意識」で集団の一員である意識を表し、文意に合う。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、気温意識では意味が合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、洗濯意識では意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、地図意識では意味が合わない。"}], "explanations": {"帰属": "「帰属意識」で集団の一員である意識を表し、文意に合う。", "気温": "形は合うが、気温意識では意味が合わない。", "洗濯": "形は合うが、洗濯意識では意味が合わない。", "地図": "形は合うが、地図意識では意味が合わない。"}, "sentence_index": 0, "correct_answer": "帰属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、帰属を食べてから出かける。", "explanation": "帰属は集団の一員であることで、食べ物ではないので「食べる」の目的語にならない。"}, {"text": "この荷物は明日、帰属で東京に届く。", "explanation": "帰属は配送手段ではなく、「〜で届く」の手段としては使えない。"}, {"text": "帰属が高い山の上に、新しい家が建った。", "explanation": "帰属は場所を表す語ではなく、「高い山の上」を修飾する名詞として誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52858, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帰属", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "士族", "is_correct": false, "explanation": "しぞくで、き→しの1拍だけが違う別の語。"}, {"text": "義賊", "is_correct": false, "explanation": "ぎぞくで、き→ぎの清濁だけが違う別の語。"}, {"text": "卑俗", "is_correct": false, "explanation": "ひぞくで、き→ひの1拍だけが違う別の語。"}, {"text": "築く", "is_correct": false, "explanation": "きずくで、ぞ→ずの1拍（母音）だけが違う別の語。"}], "explanations": {"帰属": "見出し語そのもの。", "士族": "しぞくで、き→しの1拍だけが違う別の語。", "義賊": "ぎぞくで、き→ぎの清濁だけが違う別の語。", "卑俗": "ひぞくで、き→ひの1拍だけが違う別の語。", "築く": "きずくで、ぞ→ずの1拍（母音）だけが違う別の語。"}, "sentence_index": null, "correct_answer": "帰属"}, "level_3": {"options": [{"text": "帰属して", "is_correct": true, "explanation": "チームの一員であることを表し、誇りに思う文意に合う。"}, {"text": "入院して", "is_correct": false, "explanation": "形は合うが、チームに入院するでは意味が合わない。"}, {"text": "入浴して", "is_correct": false, "explanation": "形は合うが、チームに入浴するでは意味が合わない。"}, {"text": "到着して", "is_correct": false, "explanation": "形は合うが、チームに到着していることを誇るでは意味が合わない。"}], "explanations": {"帰属して": "チームの一員であることを表し、誇りに思う文意に合う。", "入院して": "形は合うが、チームに入院するでは意味が合わない。", "入浴して": "形は合うが、チームに入浴するでは意味が合わない。", "到着して": "形は合うが、チームに到着していることを誇るでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "帰属して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この靴は帰属が軽くて、とても走りやすい。", "explanation": "帰属は靴の性質を表す語ではなく、軽さの対象として誤用している。"}, {"text": "帰属を洗ってから、ご飯を食べた。", "explanation": "帰属は形のある物ではなく、洗う対象にならない。"}, {"text": "昨日の帰属は晴れで、気温も高かった。", "explanation": "帰属は天気を表す語ではなく、「晴れ」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52858, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この学校を帰属する生徒は三百人です。", "corrected_sentence": "この学校に帰属する生徒は三百人です。", "error_description": "「帰属する」の帰属先は「を」ではなく「に」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52858, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域への帰属は、祭りに参加することで短くなっていく。", "corrected_sentence": "地域への帰属は、祭りに参加することで強くなっていく。", "error_description": "帰属の度合いは「短い」ではなく「強い」で表す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b317f-f6df-4deb-b9f1-82ce0a8360f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52859, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "もろい", "is_correct": true, "explanation": "壊れやすいさまで、強固の反対です。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫という意味で、強固に近い語です。"}, {"text": "固い", "is_correct": false, "explanation": "かたいという意味で、強固に近い語です。"}, {"text": "重い", "is_correct": false, "explanation": "重さの語で、強固の反対ではありません。"}], "correct_answer": "もろい", "explanations": {"もろい": "壊れやすいさまで、強固の反対です。", "頑丈": "丈夫という意味で、強固に近い語です。", "固い": "かたいという意味で、強固に近い語です。", "重い": "重さの語で、強固の反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52859, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軟弱", "is_correct": true, "explanation": "かたさがなく弱いさまで、強固の反対です。"}, {"text": "堅牢", "is_correct": false, "explanation": "作りが固いという意味で、強固に近い語です。"}, {"text": "重厚", "is_correct": false, "explanation": "どっしりした様子で、強固の反対ではありません。"}, {"text": "巨大", "is_correct": false, "explanation": "大きさの語で、強固の反対ではありません。"}], "correct_answer": "軟弱", "explanations": {"軟弱": "かたさがなく弱いさまで、強固の反対です。", "堅牢": "作りが固いという意味で、強固に近い語です。", "重厚": "どっしりした様子で、強固の反対ではありません。", "巨大": "大きさの語で、強固の反対ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52859, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "かたくて、こわれにくいこと。", "primary_collocate": null, "pronunciation": "きょうこ", "ipa": "kʲoːko", "syllable_count": 3, "sentences": [{"text": "強固な壁だ。", "target_word": "強固", "complexity_tier": "T1", "furigana": "強固[きょうこ]な壁[かべ]だ。", "sentence_source": "generated"}, {"text": "この扉は強固です。", "target_word": "強固", "complexity_tier": "T2", "furigana": "この扉[とびら]は強固[きょうこ]です。", "sentence_source": "generated"}, {"text": "強固な橋ができました。", "target_word": "強固", "complexity_tier": "T2", "furigana": "強固[きょうこ]な橋[はし]ができました。", "sentence_source": "generated"}, {"text": "強固な鎖で門を閉めている。", "target_word": "強固", "complexity_tier": "T3", "furigana": "強固[きょうこ]な鎖[くさり]で門[もん]を閉[し]めている。", "sentence_source": "generated"}, {"text": "壁を強固に作り直した。", "target_word": "強固", "complexity_tier": "T3", "furigana": "壁[かべ]を強固[きょうこ]に作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "地震が来ても、強固な建物なら倒れない。", "target_word": "強固", "complexity_tier": "T4", "furigana": "地震[じしん]が来[き]ても、強固[きょうこ]な建物[たてもの]なら倒[たお]れない。", "sentence_source": "generated"}, {"text": "金庫は強固で、簡単には開かない。", "target_word": "強固", "complexity_tier": "T3", "furigana": "金庫[きんこ]は強固[きょうこ]で、簡単[かんたん]には開[あ]かない。", "sentence_source": "generated"}, {"text": "強固な鉄の箱に宝物をしまっておいた。", "target_word": "強固", "complexity_tier": "T4", "furigana": "強固[きょうこ]な鉄[てつ]の箱[はこ]に宝物[たからもの]をしまっておいた。", "sentence_source": "generated"}, {"text": "城の石垣は非常に強固で、四百年たった今も崩れていない。", "target_word": "強固", "complexity_tier": "T5", "furigana": "城[しろ]の石垣[いしがき]は非常[ひじょう]に強固[きょうこ]で、四百年[よんひゃくねん]たった今[いま]も崩[くず]れていない。", "sentence_source": "generated"}, {"text": "強固な柵で畑を囲んだ。", "target_word": "強固", "complexity_tier": "T3", "furigana": "強固[きょうこ]な柵[さく]で畑[はたけ]を囲[かこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強固な", "label": "活用"}, {"form": "強固に", "label": "活用"}, {"form": "強固だ", "label": "活用"}, {"form": "強固で", "label": "活用"}], "register": "formal", "sense_fingerprint": "形状詞 | 物が硬くて壊れにくいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52859, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "強固", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "証拠", "is_correct": false, "explanation": "しょうこ。最初の「きょ」が「しょ」に変わる1モーラ違いです。"}, {"text": "強度", "is_correct": false, "explanation": "きょうど。最後の「こ」が「ど」に変わる1モーラ違いです。"}, {"text": "京都", "is_correct": false, "explanation": "きょうと。最後の「こ」が「と」に変わる1モーラ違いです。"}, {"text": "強化", "is_correct": false, "explanation": "きょうか。最後の「こ」が「か」に変わる1モーラ違いです。"}], "explanations": {"強固": "見出し語そのものです。", "証拠": "しょうこ。最初の「きょ」が「しょ」に変わる1モーラ違いです。", "強度": "きょうど。最後の「こ」が「ど」に変わる1モーラ違いです。", "京都": "きょうと。最後の「こ」が「と」に変わる1モーラ違いです。", "強化": "きょうか。最後の「こ」が「か」に変わる1モーラ違いです。"}, "sentence_index": null, "correct_answer": "強固"}, "level_3": {"options": [{"text": "強固", "is_correct": true, "explanation": "かたくて壊れにくい壁という意味に合います。"}, {"text": "愉快", "is_correct": false, "explanation": "形は合うが意味が合わない。壁の性質として愉快とは言いません。"}, {"text": "柔軟", "is_correct": false, "explanation": "形は合うが意味が合わない。壁の性質としては不自然です。"}, {"text": "退屈", "is_correct": false, "explanation": "形は合うが意味が合わない。壁の様子を表せません。"}], "explanations": {"強固": "かたくて壊れにくい壁という意味に合います。", "愉快": "形は合うが意味が合わない。壁の性質として愉快とは言いません。", "柔軟": "形は合うが意味が合わない。壁の性質としては不自然です。", "退屈": "形は合うが意味が合わない。壁の様子を表せません。"}, "sentence_index": 0, "correct_answer": "強固"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強固な水を飲んだ。", "explanation": "強固は物がかたく壊れにくいことで、液体の水には使えません。"}, {"text": "強固な風が吹いて、帽子が飛んだ。", "explanation": "強固は風の強さを表さず、強い風には「強い」を使います。"}, {"text": "このクッションは強固で、とてもやわらかい。", "explanation": "強固はかたいさまなので、やわらかいと矛盾します。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52859, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "強固", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "教祖", "is_correct": false, "explanation": "きょうそ。最後の「こ」が「そ」に変わる1モーラ違いです。"}, {"text": "教師", "is_correct": false, "explanation": "きょうし。最後の「こ」が「し」に変わる1モーラ違いです。"}, {"text": "協和", "is_correct": false, "explanation": "きょうわ。最後の「こ」が「わ」に変わる1モーラ違いです。"}, {"text": "教護", "is_correct": false, "explanation": "きょうご。清濁だけが違う1モーラ違いです。"}], "explanations": {"強固": "見出し語そのものです。", "教祖": "きょうそ。最後の「こ」が「そ」に変わる1モーラ違いです。", "教師": "きょうし。最後の「こ」が「し」に変わる1モーラ違いです。", "協和": "きょうわ。最後の「こ」が「わ」に変わる1モーラ違いです。", "教護": "きょうご。清濁だけが違う1モーラ違いです。"}, "sentence_index": null, "correct_answer": "強固"}, "level_3": {"options": [{"text": "強固", "is_correct": true, "explanation": "かたく簡単には開かない金庫という意味に合います。"}, {"text": "派手", "is_correct": false, "explanation": "形は合うが意味が合わない。開きにくい理由になりません。"}, {"text": "静か", "is_correct": false, "explanation": "形は合うが意味が合わない。開かない理由として不自然です。"}, {"text": "愉快", "is_correct": false, "explanation": "形は合うが意味が合わない。金庫の性質を表せません。"}], "explanations": {"強固": "かたく簡単には開かない金庫という意味に合います。", "派手": "形は合うが意味が合わない。開きにくい理由になりません。", "静か": "形は合うが意味が合わない。開かない理由として不自然です。", "愉快": "形は合うが意味が合わない。金庫の性質を表せません。"}, "sentence_index": 6, "correct_answer": "強固"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "強固な声で歌った。", "explanation": "強固は物のかたさを表す語で、声の様子には使えません。"}, {"text": "強固な味のカレーを食べた。", "explanation": "強固は味を表す語ではなく、意味が合いません。"}, {"text": "その氷は強固で、手で簡単に割れた。", "explanation": "強固は壊れにくいことなので、簡単に割れたと矛盾します。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = 