INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52859, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この橋は強固で、風が吹いただけで折れた。", "corrected_sentence": "この橋は強固で、風が吹いても折れなかった。", "error_description": "強固は壊れにくいことなのに、風だけで折れたとなっていて意味が矛盾している。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強固", "is_correct": true, "explanation": "「です」に直接つながる語幹の形です。"}, {"text": "強固な", "is_correct": false, "explanation": "連体形なので「です」に続けられません。"}, {"text": "強固に", "is_correct": false, "explanation": "連用形なので「です」に続けられません。"}, {"text": "強固だ", "is_correct": false, "explanation": "「強固だです」となり文として成り立ちません。"}], "correct_form": "強固", "base_form": "強固", "form_label": "語幹（です接続）", "sentence_index": 1, "explanations": {"強固": "「です」に直接つながる語幹の形です。", "強固な": "連体形なので「です」に続けられません。", "強固に": "連用形なので「です」に続けられません。", "強固だ": "「強固だです」となり文として成り立ちません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52859, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強固な鉄の箱を、素手で簡単につぶした。", "corrected_sentence": "強固な鉄の箱は、素手ではつぶせなかった。", "error_description": "強固な箱は壊れにくいのに、簡単につぶしたとなっていて意味が矛盾している。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強固", "is_correct": true, "explanation": "後ろの「な」につながる語幹です。"}, {"text": "強固に", "is_correct": false, "explanation": "「強固にな鉄の箱」となり成り立ちません。"}, {"text": "強固で", "is_correct": false, "explanation": "「強固でな鉄の箱」となり成り立ちません。"}, {"text": "強固だ", "is_correct": false, "explanation": "「強固だな鉄の箱」となり名詞を修飾できません。"}], "correct_form": "強固", "base_form": "強固", "form_label": "語幹（な接続）", "sentence_index": 7, "explanations": {"強固": "後ろの「な」につながる語幹です。", "強固に": "「強固にな鉄の箱」となり成り立ちません。", "強固で": "「強固でな鉄の箱」となり成り立ちません。", "強固だ": "「強固だな鉄の箱」となり名詞を修飾できません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
