INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52860, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不安定", "is_correct": true, "explanation": "絆が揺らぎやすいさまで、強固の反対です。"}, {"text": "堅牢", "is_correct": false, "explanation": "守りが固いという意味で、強固に近い語です。"}, {"text": "安定", "is_correct": false, "explanation": "落ち着いているという意味で、強固に近い語です。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深いという意味で、強固の反対ではありません。"}], "correct_answer": "不安定", "explanations": {"不安定": "絆が揺らぎやすいさまで、強固の反対です。", "堅牢": "守りが固いという意味で、強固に近い語です。", "安定": "落ち着いているという意味で、強固に近い語です。", "慎重": "注意深いという意味で、強固の反対ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52860, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の状態や体制がしっかりしていて、簡単には揺るがないさま。", "primary_collocate": null, "pronunciation": "きょうこ", "ipa": "kʲoːko", "syllable_count": 3, "sentences": [{"text": "この創造的プロセスこそが、行事の記憶を永続的なものへと変貌させ、参加者の帰属意識を強固なものへと昇華させるのである。", "target_word": "強固", "complexity_tier": "T6", "furigana": "この創造的[そうぞうてき]プロセスこそが、行事[ぎょうじ]の記憶[きおく]を永続的[えいぞくてき]なものへと変貌[へんぼう]させ、参加者[さんかしゃ]の帰属[きぞく]意識[いしき]を強固[きょうこ]なものへと昇華[しょうか]させるのである。", "sentence_source": "mined"}, {"text": "二国の関係は強固です。", "target_word": "強固", "complexity_tier": "T2", "furigana": "二国[にこく]の関係[かんけい]は強固[きょうこ]です。", "sentence_source": "generated"}, {"text": "彼らの絆は強固でした。", "target_word": "強固", "complexity_tier": "T2", "furigana": "彼[かれ]らの絆[きずな]は強固[きょうこ]でした。", "sentence_source": "generated"}, {"text": "強固な信頼関係を築いている。", "target_word": "強固", "complexity_tier": "T3", "furigana": "強固[きょうこ]な信頼[しんらい]関係[かんけい]を築[きず]いている。", "sentence_source": "generated"}, {"text": "体制を強固にします。", "target_word": "強固", "complexity_tier": "T2", "furigana": "体制[たいせい]を強固[きょうこ]にします。", "sentence_source": "generated"}, {"text": "基盤が強固であれば、危機にも耐えられる。", "target_word": "強固", "complexity_tier": "T4", "furigana": "基盤[きばん]が強固[きょうこ]であれば、危機[きき]にも耐[た]えられる。", "sentence_source": "generated"}, {"text": "強固な意志で最後までやり抜いた。", "target_word": "強固", "complexity_tier": "T3", "furigana": "強固[きょうこ]な意志[いし]で最後[さいご]までやり抜[ぬ]いた。", "sentence_source": "generated"}, {"text": "強固な体制を作るために、全員が協力した。", "target_word": "強固", "complexity_tier": "T4", "furigana": "強固[きょうこ]な体制[たいせい]を作[つく]るために、全員[ぜんいん]が協力[きょうりょく]した。", "sentence_source": "generated"}, {"text": "長い年月をかけて、両国の同盟はさらに強固になった。", "target_word": "強固", "complexity_tier": "T5", "furigana": "長[なが]い年月[ねんげつ]をかけて、両国[りょうこく]の同盟[どうめい]はさらに強固[きょうこ]になった。", "sentence_source": "generated"}, {"text": "絆は強固だ。", "target_word": "強固", "complexity_tier": "T1", "furigana": "絆[きずな]は強固[きょうこ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強固な", "label": "活用"}, {"form": "強固に", "label": "活用"}, {"form": "強固だ", "label": "活用"}, {"form": "強固で", "label": "活用"}], "register": "formal", "sense_fingerprint": "形状詞 | 体制や関係が揺るがず堅固なさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52860, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "強固", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "証拠", "is_correct": false, "explanation": "しょうこ。最初の「きょ」が「しょ」に変わる1モーラ違いです。"}, {"text": "強度", "is_correct": false, "explanation": "きょうど。最後の「こ」が「ど」に変わる1モーラ違いです。"}, {"text": "京都", "is_correct": false, "explanation": "きょうと。最後の「こ」が「と」に変わる1モーラ違いです。"}, {"text": "強化", "is_correct": false, "explanation": "きょうか。最後の「こ」が「か」に変わる1モーラ違いです。"}], "explanations": {"強固": "見出し語そのものです。", "証拠": "しょうこ。最初の「きょ」が「しょ」に変わる1モーラ違いです。", "強度": "きょうど。最後の「こ」が「ど」に変わる1モーラ違いです。", "京都": "きょうと。最後の「こ」が「と」に変わる1モーラ違いです。", "強化": "きょうか。最後の「こ」が「か」に変わる1モーラ違いです。"}, "sentence_index": null, "correct_answer": "強固"}, "level_3": {"options": [{"text": "強固", "is_correct": true, "explanation": "帰属意識がしっかり揺るがないものになるという意味に合います。"}, {"text": "粗末", "is_correct": false, "explanation": "形は合うが意味が合わない。意識を粗末なものへ昇華させるとは言えません。"}, {"text": "滑稽", "is_correct": false, "explanation": "形は合うが意味が合わない。帰属意識を滑稽なものへ昇華させる文脈ではありません。"}, {"text": "窮屈", "is_correct": false, "explanation": "形は合うが意味が合わない。昇華という肯定的な流れに合いません。"}], "explanations": {"強固": "帰属意識がしっかり揺るがないものになるという意味に合います。", "粗末": "形は合うが意味が合わない。意識を粗末なものへ昇華させるとは言えません。", "滑稽": "形は合うが意味が合わない。帰属意識を滑稽なものへ昇華させる文脈ではありません。", "窮屈": "形は合うが意味が合わない。昇華という肯定的な流れに合いません。"}, "sentence_index": 0, "correct_answer": "強固"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の関係が強固だったので、すぐに壊れてしまった。", "explanation": "強固は簡単には揺るがないさまなので、すぐ壊れたという結果と矛盾します。"}, {"text": "彼は強固な顔で朝ごはんを食べた。", "explanation": "強固は体制や関係などの状態に使い、顔つきの様子には使えません。"}, {"text": "強固な天気が続いて、洗濯物がよく乾く。", "explanation": "強固は天気の状態を表す語ではなく、意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52860, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "強固", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "教祖", "is_correct": false, "explanation": "きょうそ。最後の「こ」が「そ」に変わる1モーラ違いです。"}, {"text": "教師", "is_correct": false, "explanation": "きょうし。最後の「こ」が「し」に変わる1モーラ違いです。"}, {"text": "協和", "is_correct": false, "explanation": "きょうわ。最後の「こ」が「わ」に変わる1モーラ違いです。"}, {"text": "教護", "is_correct": false, "explanation": "きょうご。清濁だけが違う1モーラ違いです。"}], "explanations": {"強固": "見出し語そのものです。", "教祖": "きょうそ。最後の「こ」が「そ」に変わる1モーラ違いです。", "教師": "きょうし。最後の「こ」が「し」に変わる1モーラ違いです。", "協和": "きょうわ。最後の「こ」が「わ」に変わる1モーラ違いです。", "教護": "きょうご。清濁だけが違う1モーラ違いです。"}, "sentence_index": null, "correct_answer": "強固"}, "level_3": {"options": [{"text": "強固", "is_correct": true, "explanation": "揺るがない意志という意味に合います。"}, {"text": "透明", "is_correct": false, "explanation": "形は合うが意味が合わない。意志を透明とは言いません。"}, {"text": "贅沢", "is_correct": false, "explanation": "形は合うが意味が合わない。最後までやり抜く意志の説明になりません。"}, {"text": "派手", "is_correct": false, "explanation": "形は合うが意味が合わない。意志の強さを表せません。"}], "explanations": {"強固": "揺るがない意志という意味に合います。", "透明": "形は合うが意味が合わない。意志を透明とは言いません。", "贅沢": "形は合うが意味が合わない。最後までやり抜く意志の説明になりません。", "派手": "形は合うが意味が合わない。意志の強さを表せません。"}, "sentence_index": 6, "correct_answer": "強固"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この提案は強固で、誰にも理解できない。", "explanation": "強固は理解しにくさを表さず、提案の難解さには使えません。"}, {"text": "強固なスープを作った。", "explanation": "強固は味や料理の性質を表す語ではなく、意味が合いません。"}, {"text": "彼への信頼は強固だから、少しの噂ですぐ崩れる。", "explanation": "強固なら簡単に崩れないはずで、すぐ崩れるという内容と矛盾します。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52860, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二国の関係は強固で、すぐに崩れそうだ。", "corrected_sentence": "二国の関係は強固で、簡単には崩れない。", "error_description": "強固は揺るがないさまなのに、すぐに崩れそうだと続けていて意味が矛盾している。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強固", "is_correct": true, "explanation": "「です」に直接つながる語幹の形です。"}, {"text": "強固な", "is_correct": false, "explanation": "連体形なので「です」に続けられません。"}, {"text": "強固に", "is_correct": false, "explanation": "連用形なので「です」に続けられません。"}, {"text": "強固で", "is_correct": false, "explanation": "「強固でです」となり文として成り立ちません。"}], "correct_form": "強固", "base_form": "強固", "form_label": "語幹（です接続）", "sentence_index": 1, "explanations": {"強固": "「です」に直接つながる語幹の形です。", "強固な": "連体形なので「です」に続けられません。", "強固に": "連用形なので「です」に続けられません。", "強固で": "「強固でです」となり文として成り立ちません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52860, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同盟は強固で、ガラスのようにもろい。", "corrected_sentence": "同盟は強固で、岩のように動かない。", "error_description": "強固は揺るがないさまなのに、もろいと続けていて意味が矛盾している。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強固", "is_correct": true, "explanation": "後ろの「な」につながる語幹です。"}, {"text": "強固に", "is_correct": false, "explanation": "「強固にな体制」となり成り立ちません。"}, {"text": "強固で", "is_correct": false, "explanation": "「強固でな体制」となり成り立ちません。"}, {"text": "強固だ", "is_correct": false, "explanation": "「強固だな体制」となり名詞を修飾できません。"}], "correct_form": "強固", "base_form": "強固", "form_label": "語幹（な接続）", "sentence_index": 7, "explanations": {"強固": "後ろの「な」につながる語幹です。", "強固に": "「強固にな体制」となり成り立ちません。", "強固で": "「強固でな体制」となり成り立ちません。", "強固だ": "「強固だな体制」となり名詞を修飾できません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52861, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「出る」の主語を示す。「血が出て」で、血が出たという文になる。"}, {"text": "を", "is_correct": false, "explanation": "「出る」は自動詞なので目的語の「を」は取れない。「血を出て」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「血に出て」は場所や方向として成り立たず、動詞とも合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「血へ出て」は方向を表すが、血が移動する文脈として不自然。"}], "correct_answer": "が", "explanations": {"が": "「出る」の主語を示す。「血が出て」で、血が出たという文になる。", "を": "「出る」は自動詞なので目的語の「を」は取れない。「血を出て」は成り立たない。", "に": "「血に出て」は場所や方向として成り立たず、動詞とも合わない。", "へ": "「血へ出て」は方向を表すが、血が移動する文脈として不自然。"}, "error_tags": {"を": "目的語", "に": "場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52861, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52861, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生き物の体の中を流れている赤い液体です。", "primary_collocate": null, "pronunciation": "ち", "ipa": "t͡ɕi", "syllable_count": 1, "sentences": [{"text": "指を切ったら、赤い血が出てきた。", "target_word": "血", "complexity_tier": "T3", "furigana": "指[ゆび]を切[き]ったら、赤[あか]い血[ち]が出[で]てきた。", "sentence_source": "generated"}, {"text": "転んで、ひざから血が出て痛かった。", "target_word": "血", "complexity_tier": "T3", "furigana": "転[ころ]んで、ひざから血[ち]が出[で]て痛[いた]かった。", "sentence_source": "generated"}, {"text": "血は、体の中をぐるぐる流れている。", "target_word": "血", "complexity_tier": "T3", "furigana": "血[ち]は、体[からだ]の中[なか]をぐるぐる流[なが]れている。", "sentence_source": "generated"}, {"text": "シャツについた血は、冷たい水で洗うと落ちやすい。", "target_word": "血", "complexity_tier": "T3", "furigana": "シャツについた血[ち]は、冷[つめ]たい水[みず]で洗[あら]うと落[お]ちやすい。", "sentence_source": "generated"}, {"text": "虫に刺された腕をかいて、血が出てしまった。", "target_word": "血", "complexity_tier": "T3", "furigana": "虫[むし]に刺[さ]された腕[うで]をかいて、血[ち]が出[で]てしまった。", "sentence_source": "generated"}, {"text": "病院で、腕の血を少しとって調べてもらった。", "target_word": "血", "complexity_tier": "T3", "furigana": "病院[びょういん]で、腕[うで]の血[ち]を少[すこ]しとって調[しら]べてもらった。", "sentence_source": "generated"}, {"text": "指を強く締めると血が止まって、白くなる。", "target_word": "血", "complexity_tier": "T3", "furigana": "指[ゆび]を強[つよ]く締[し]めると血[ち]が止[と]まって、白[しろ]くなる。", "sentence_source": "generated"}, {"text": "犬がけがをして、足から血を流していた。", "target_word": "血", "complexity_tier": "T3", "furigana": "犬[いぬ]がけがをして、足[あし]から血[ち]を流[なが]していた。", "sentence_source": "generated"}, {"text": "子どもに、血はなぜ赤いのかと聞かれた。", "target_word": "血", "complexity_tier": "T3", "furigana": "子[こ]どもに、血[ち]はなぜ赤[あか]いのかと聞[き]かれた。", "sentence_source": "generated"}, {"text": "蚊は人の血を吸って、卵を産む準備をする。", "target_word": "血", "complexity_tier": "T3", "furigana": "蚊[か]は人[ひと]の血[ち]を吸[す]って、卵[たまご]を産[う]む準備[じゅんび]をする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "血", "label": "基本形"}, {"form": "血の", "label": "の格"}], "register": "neutral", "sense_fingerprint": "けがをすると出てくる、体の中を流れる赤い液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52861, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "血", "is_correct": true, "explanation": "ここは〈けがで出る赤い液体〉の意味。「赤い血が出てきた」として文に合う。"}, {"text": "歌", "is_correct": false, "explanation": "「赤い歌が出てきた」は成り立たない。出てくるものとして不自然。"}, {"text": "眠気", "is_correct": false, "explanation": "「赤い眠気が出てきた」は意味が通らない。色や出てくる液体として合わない。"}, {"text": "音", "is_correct": false, "explanation": "「赤い音が出てきた」は成り立たない。音には赤いという色の性質がない。"}], "explanations": {"血": "ここは〈けがで出る赤い液体〉の意味。「赤い血が出てきた」として文に合う。", "歌": "「赤い歌が出てきた」は成り立たない。出てくるものとして不自然。", "眠気": "「赤い眠気が出てきた」は意味が通らない。色や出てくる液体として合わない。", "音": "「赤い音が出てきた」は成り立たない。音には赤いという色の性質がない。"}, "sentence_index": 0, "correct_answer": "血"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木の幹を切ったら、白い血がにじみ出た。", "explanation": "ここは〈樹液〉（木の汁）の意味。木からにじみ出るのは樹液で、血ではないので合わない。"}, {"text": "寒い夜、ストーブに血を足して部屋を暖めた。", "explanation": "ここは〈燃料〉（灯油など）の意味。ストーブに足すのは燃料で、血ではないので合わない。"}, {"text": "ペンの血がシャツについて、落ちなくなった。", "explanation": "ここは〈インク〉の意味。ペンの中身は血ではないので、血は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52861, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血", "is_correct": true, "explanation": "ここは〈体内の液体〉の意味。「指を締めると血が止まる」という文の主語に合う。"}, {"text": "柱", "is_correct": false, "explanation": "「柱が止まって」は意味が通らない。止まる対象として成り立たない。"}, {"text": "鍵", "is_correct": false, "explanation": "「鍵が止まって」は不自然。指を締めた結果として何かが止まる文脈に合わない。"}, {"text": "机", "is_correct": false, "explanation": "「机が止まって」は成り立たない。締める動作の結果として止まるものではない。"}], "explanations": {"血": "ここは〈体内の液体〉の意味。「指を締めると血が止まる」という文の主語に合う。", "柱": "「柱が止まって」は意味が通らない。止まる対象として成り立たない。", "鍵": "「鍵が止まって」は不自然。指を締めた結果として何かが止まる文脈に合わない。", "机": "「机が止まって」は成り立たない。締める動作の結果として止まるものではない。"}, "sentence_index": 6, "correct_answer": "血"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蝶は花の血を吸って、栄養をとる。", "explanation": "ここは〈蜜〉の意味。蝶が吸うのは花の蜜で、花に血はないので血は合わない。"}, {"text": "鍋から血があふれて、コンロが汚れた。", "explanation": "ここは〈ソース〉の意味。鍋からあふれるのは料理の汁やソースで、血ではない。"}, {"text": "大雨のあと、道に血がたまった。", "explanation": "ここは〈雨水〉の意味。道にたまるのは雨水で、血ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52861, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "かみそりで頬を切ったら、血に少し出た。", "corrected_sentence": "かみそりで頬を切ったら、血が少し出た。", "error_description": "「出る」の主語は「が」で示す。「血に出た」は「に」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52861, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫が塀から落ちて、耳から血の流れた。", "corrected_sentence": "猫が塀から落ちて、耳から血が流れた。", "error_description": "「流れた」の主語は「が」で示す。「血の流れた」は「の」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52863, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「〜と形容する」で評価の言葉を導く「と」が入り、「宝の山と形容して」が自然に成り立つ。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、評価の言葉を導く位置には入らない。「宝の山から形容して」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「宝の山より形容して」は比べる文脈がなく合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐので、「宝の山の形容して」は動詞「形容して」とつながらない。"}], "correct_answer": "と", "explanations": {"と": "正解。「〜と形容する」で評価の言葉を導く「と」が入り、「宝の山と形容して」が自然に成り立つ。", "から": "「から」は起点を示すので、評価の言葉を導く位置には入らない。「宝の山から形容して」は成り立たない。", "より": "「より」は比較を示すので、「宝の山より形容して」は比べる文脈がなく合わない。", "の": "「の」は名詞どうしをつなぐので、「宝の山の形容して」は動詞「形容して」とつながらない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52863, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「〜と形容する」で評価の言葉を導く「と」が入り、「『青い鏡』と形容していた」が自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着や相手を示すので、評価の言葉を導く「と形容する」の位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「白い呼吸へ形容していた」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「山の朝を」にすでに目的語の「を」があり、「白い呼吸を形容していた」と重ねると文が壊れる。"}], "correct_answer": "と", "explanations": {"と": "正解。「〜と形容する」で評価の言葉を導く「と」が入り、「『青い鏡』と形容していた」が自然に成り立つ。", "に": "「に」は帰着や相手を示すので、評価の言葉を導く「と形容する」の位置には入らない。", "へ": "「へ」は方向を示すので、「白い呼吸へ形容していた」は成り立たない。", "を": "「山の朝を」にすでに目的語の「を」があり、「白い呼吸を形容していた」と重ねると文が壊れる。"}, "error_tags": {"に": "相手・帰着", "へ": "方向", "を": "目的語（重複）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52863, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを、その感じやようすをことばで言いあらわすこと。", "primary_collocate": null, "pronunciation": "けいよう", "ipa": "keːjoː", "syllable_count": 4, "sentences": [{"text": "この味は言葉で形容しにくいほど複雑だ。", "target_word": "形容", "complexity_tier": "T3", "furigana": "この味[あじ]は言葉[ことば]で形容[けいよう]しにくいほど複雑[ふくざつ]だ。", "sentence_source": "generated"}, {"text": "母は私の部屋を「宝の山」と形容して笑った。", "target_word": "形容", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の部屋[へや]を「宝[たから]の山[やま]」と形容[けいよう]して笑[わら]った。", "sentence_source": "generated"}, {"text": "新しい店の雰囲気は、「隠れ家」という言葉で形容されている。", "target_word": "形容", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の雰囲気[ふんいき]は、「隠[かく]れ家[が]」という言葉[ことば]で形容[けいよう]されている。", "sentence_source": "generated"}, {"text": "彼女の声の感じを形容するなら、「澄んだ鈴の音」がぴったりだ。", "target_word": "形容", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の声[こえ]の感[かん]じを形容[けいよう]するなら、「澄[す]んだ鈴[すず]の音[ね]」がぴったりだ。", "sentence_source": "generated"}, {"text": "見たままを形容する練習として、毎日一つの物の様子を文章にした。", "target_word": "形容", "complexity_tier": "T3", "furigana": "見[み]たままを形容[けいよう]する練習[れんしゅう]として、毎日[まいにち]一[ひと]つの物[もの]の様子[ようす]を文章[ぶんしょう]にした。", "sentence_source": "generated"}, {"text": "彼の演奏は「力強い」の一言では形容しきれない。", "target_word": "形容", "complexity_tier": "T3", "furigana": "彼[かれ]の演奏[えんそう]は「力強[ちからづよ]い」の一言[ひとこと]では形容[けいよう]しきれない。", "sentence_source": "generated"}, {"text": "国語の授業で、りんごの色や形を形容する言葉を探した。", "target_word": "形容", "complexity_tier": "T3", "furigana": "国語[こくご]の授業[じゅぎょう]で、りんごの色[いろ]や形[かたち]を形容[けいよう]する言葉[ことば]を探[さが]した。", "sentence_source": "generated"}, {"text": "旅行記の中で、筆者は山の朝を「白い呼吸」と形容していた。", "target_word": "形容", "complexity_tier": "T3", "furigana": "旅行記[りょこうき]の中[なか]で、筆者[ひっしゃ]は山[やま]の朝[あさ]を「白[しろ]い呼吸[こきゅう]」と形容[けいよう]していた。", "sentence_source": "generated"}, {"text": "彼の笑顔は「春のようだ」と形容されるが、私もそう思う。", "target_word": "形容", "complexity_tier": "T3", "furigana": "彼[かれ]の笑顔[えがお]は「春[はる]のようだ」と形容[けいよう]されるが、私[わたし]もそう思[おも]う。", "sentence_source": "generated"}, {"text": "形容がうまい人は、短い言葉で様子を相手に思い浮かばせる。", "target_word": "形容", "complexity_tier": "T3", "furigana": "形容[けいよう]がうまい人[ひと]は、短[みじか]い言葉[ことば]で様子[ようす]を相手[あいて]に思[おも]い浮[う]かばせる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形容する", "label": "辞書形"}, {"form": "形容した", "label": "過去形"}, {"form": "形容される", "label": "受身形"}, {"form": "形容しにくい", "label": "難易形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "ものの感じやようすを言葉で言い表す（形容する・形容しにくい）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52863, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形容", "is_correct": true, "explanation": "正解。味を言葉で言い表す意味で、「言葉で形容しにくい」が自然に成り立つ。"}, {"text": "採点", "is_correct": false, "explanation": "採点は点数をつける意味で、味を言葉で言い表す文脈には合わない。"}, {"text": "撮影", "is_correct": false, "explanation": "味は写真に撮るものではないので、「言葉で撮影しにくい」は成り立たない。"}, {"text": "測定", "is_correct": false, "explanation": "味は数値で測るものではないので、「言葉で測定しにくい」は文脈に合わない。"}], "explanations": {"形容": "正解。味を言葉で言い表す意味で、「言葉で形容しにくい」が自然に成り立つ。", "採点": "採点は点数をつける意味で、味を言葉で言い表す文脈には合わない。", "撮影": "味は写真に撮るものではないので、「言葉で撮影しにくい」は成り立たない。", "測定": "味は数値で測るものではないので、「言葉で測定しにくい」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "形容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は作文を赤ペンで形容した。", "explanation": "ここは〈採点〉の意味。赤ペンで点数や評価を付けるのが採点で、言葉で様子を言い表す形容とは違う。"}, {"text": "体温計で熱を形容した。", "explanation": "ここは〈測定〉の意味。体温計で数値を測るのが測定で、熱を言葉で言い表す形容は合わない。"}, {"text": "カメラで景色を形容した。", "explanation": "ここは〈撮影〉の意味。カメラで景色を写すのが撮影で、言葉で言い表す形容とは別の行為になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52863, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形容", "is_correct": true, "explanation": "正解。りんごの色や形を言葉で言い表す言葉という意味に合う。"}, {"text": "解体", "is_correct": false, "explanation": "解体はばらす意味で、りんごの色や形を言葉で表す文脈に合わない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼む意味で、色や形を言葉で表す文脈には合わない。"}, {"text": "輸送", "is_correct": false, "explanation": "輸送は荷物を運ぶ意味で、色や形を言葉で言い表す文脈には合わない。"}], "explanations": {"形容": "正解。りんごの色や形を言葉で言い表す言葉という意味に合う。", "解体": "解体はばらす意味で、りんごの色や形を言葉で表す文脈に合わない。", "注文": "注文は品物を頼む意味で、色や形を言葉で表す文脈には合わない。", "輸送": "輸送は荷物を運ぶ意味で、色や形を言葉で言い表す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "形容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は怒りを身振りで形容した。", "explanation": "ここは〈表現〉の意味。身振りで気持ちを示すのが表現で、言葉で様子を言い表す形容とは違う。"}, {"text": "校長は行事の日程を丁寧に形容した。", "explanation": "ここは〈説明〉の意味。日程を順序立てて伝えるのが説明で、性質や様子を言い表す形容は合わない。"}, {"text": "司書は本をジャンルごとに形容した。", "explanation": "ここは〈分類〉の意味。ジャンルごとに仕分けるのが分類で、本の様子を言葉で言い表す形容とは別の行為になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52863, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この香りを一言で形容なら、柑橘だ。", "corrected_sentence": "この香りを一言で形容するなら、柑橘だ。", "error_description": "「形容」に動詞の「する」が抜けている。「形容なら」は不完全で、正しくは「形容するなら」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52863, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は初めての海を『青い鏡』に形容していた。", "corrected_sentence": "彼は初めての海を『青い鏡』と形容していた。", "error_description": "「〜と形容する」と評価の言葉を「と」で示す。「に」は誤りで、正しくは「と」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52865, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「赤いブーツで」は身につけた物を示し、水たまりに入る様子に自然に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「赤いブーツへ水たまりに入る」は身につけた物を示せず合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「赤いブーツから水たまりに入る」は身につけた物の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「赤いブーツより水たまりに入る」は文脈と合わない。"}], "correct_answer": "で", "explanations": {"で": "正解。「赤いブーツで」は身につけた物を示し、水たまりに入る様子に自然に合う。", "へ": "「へ」は方向を示すので、「赤いブーツへ水たまりに入る」は身につけた物を示せず合わない。", "から": "「から」は起点を示すので、「赤いブーツから水たまりに入る」は身につけた物の意味にならない。", "より": "「より」は比較を示すので、「赤いブーツより水たまりに入る」は文脈と合わない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52865, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「ブーツを脱ぐ」の目的語を示す「を」が入り、自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「ブーツに脱ぎ散らかす」では脱ぐ対象を示せず、目的語の位置に「に」は入らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「ブーツより脱ぎ散らかして」は脱ぐ対象を示せず合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、「ブーツと脱ぎ散らかして」は脱ぐ対象を示す文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「ブーツを脱ぐ」の目的語を示す「を」が入り、自然に成り立つ。", "に": "「ブーツに脱ぎ散らかす」では脱ぐ対象を示せず、目的語の位置に「に」は入らない。", "より": "「より」は比較を示すので、「ブーツより脱ぎ散らかして」は脱ぐ対象を示せず合わない。", "と": "「と」は並列や引用を示すので、「ブーツと脱ぎ散らかして」は脱ぐ対象を示す文として成り立たない。"}, "error_tags": {"に": "相手・帰着", "より": "比較", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52865, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あしをまもるくつ。", "primary_collocate": null, "pronunciation": "ぶーつ", "ipa": "buːtsɯ", "syllable_count": 3, "sentences": [{"text": "工事現場では、安全のために頑丈なブーツを履く決まりだ。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "工事[こうじ]現場[げんば]では、安全[あんぜん]のために頑丈[がんじょう]なブーツを履[は]く決[き]まりだ。", "sentence_source": "generated"}, {"text": "雨の日、子どもは赤いブーツで水たまりに入って喜んだ。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]、子[こ]どもは赤[あか]いブーツで水[みず]たまりに入[はい]って喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "寒い地方では、毛皮つきのブーツが欠かせない。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "寒[さむ]い地方[ちほう]では、毛皮[けがわ]つきのブーツが欠[か]かせない。", "sentence_source": "generated"}, {"text": "釣りに行くので、水に強いゴム製のブーツを借りた。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "釣[つ]りに行[い]くので、水[みず]に強[つよ]いゴム製[せい]のブーツを借[か]りた。", "sentence_source": "generated"}, {"text": "兵士たちは泥だらけのブーツで行進を続けた。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは泥[どろ]だらけのブーツで行進[こうしん]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "登山用のブーツは、足首を守るために底が硬い。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "登山用[とざんよう]のブーツは、足首[あしくび]を守[まも]るために底[そこ]が硬[かた]い。", "sentence_source": "generated"}, {"text": "雪かきをする前に、ブーツの中に厚い靴下を入れた。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "雪[ゆき]かきをする前[まえ]に、ブーツの中[なか]に厚[あつ]い靴下[くつした]を入[い]れた。", "sentence_source": "generated"}, {"text": "弟は玄関にブーツを脱ぎ散らかして、母に叱られた。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "弟[おとうと]は玄関[げんかん]にブーツを脱[ぬ]ぎ散[ち]らかして、母[はは]に叱[しか]られた。", "sentence_source": "generated"}, {"text": "農作業では、長いブーツが足を泥から守ってくれる。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "農作業[のうさぎょう]では、長[なが]いブーツが足[あし]を泥[どろ]から守[まも]ってくれる。", "sentence_source": "generated"}, {"text": "ブーツの底がすり減ったので、修理に出した。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "ブーツの底[そこ]がすり減[へ]ったので、修理[しゅうり]に出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブーツ", "label": "基本形"}, {"form": "ブーツを履く", "label": "動詞との結合形"}], "register": "日常語（中立）", "sense_fingerprint": "足を守るための丈夫な靴（作業用・雨用・防寒用のブーツ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52865, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブーツ", "is_correct": true, "explanation": "正解。足をまもるために履く頑丈な靴として、「履く決まり」に合う。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋は「はめる」もので、「履く決まり」とは合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "帽子は頭にかぶるもので、「履く」とは組み合わない。"}, {"text": "ネクタイ", "is_correct": false, "explanation": "ネクタイは首に締めるもので、足を守る話の文脈に合わない。"}], "explanations": {"ブーツ": "正解。足をまもるために履く頑丈な靴として、「履く決まり」に合う。", "手袋": "手袋は「はめる」もので、「履く決まり」とは合わない。", "帽子": "帽子は頭にかぶるもので、「履く」とは組み合わない。", "ネクタイ": "ネクタイは首に締めるもので、足を守る話の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ブーツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会場の受付ブーツで名前を書いた。", "explanation": "ここは〈ブース（受付の仕切り場所）〉の意味。受付の場所をブーツとは言わず、靴の意味では合わない。"}, {"text": "このソフトはブーツに時間がかかるのが欠点だ。", "explanation": "ここは〈ブート（起動）〉の意味。ソフトの起動はブートで、足を守る靴のブーツは当てはまらない。"}, {"text": "試合中、観客からブーツが湧き上がった。", "explanation": "ここは〈ブーイング（非難の声）〉の意味。湧き上がるのは非難の声で、靴のブーツは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52865, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブーツ", "is_correct": true, "explanation": "正解。靴の中に靴下を入れる文脈に合う履物。"}, {"text": "マフラー", "is_correct": false, "explanation": "マフラーの中に厚い靴下を入れるのは、文脈として成り立たない。"}, {"text": "ベルト", "is_correct": false, "explanation": "ベルトの中に靴下を入れる話にはならず、足を守る靴の文脈に合わない。"}, {"text": "コート", "is_correct": false, "explanation": "コートの中に厚い靴下を入れる話にはならず、雪かきの準備の文脈に合わない。"}], "explanations": {"ブーツ": "正解。靴の中に靴下を入れる文脈に合う履物。", "マフラー": "マフラーの中に厚い靴下を入れるのは、文脈として成り立たない。", "ベルト": "ベルトの中に靴下を入れる話にはならず、足を守る靴の文脈に合わない。", "コート": "コートの中に厚い靴下を入れる話にはならず、雪かきの準備の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "ブーツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "後ろのブーツに買い物袋を入れた。", "explanation": "ここは〈トランク（車の荷室）〉の意味。車の荷室をブーツとは日本語で言わず、靴の意味とも合わない。"}, {"text": "自転車のブーツを強く握った。", "explanation": "ここは〈ブレーキ〉の意味。握るのはブレーキで、靴のブーツは握る物ではない。"}, {"text": "寒い朝は、ブーツをはめて指先を温めた。", "explanation": "ここは〈手袋〉の使い方。指先を覆うのは手袋で、ブーツは「はめる」ものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52865, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "農夫は長いブーツで履いて畑へ出た。", "corrected_sentence": "農夫は長いブーツを履いて畑へ出た。", "error_description": "「履く」の目的語は「を」で示す。「で」は手段を表すので誤り。正しくは「ブーツを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52865, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、ブーツを水が入らないように気をつける。", "corrected_sentence": "雨の日は、ブーツに水が入らないように気をつける。", "error_description": "「水が入る」の場所を示すには「に」が必要。「を」は誤りで、正しくは「ブーツに」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52866, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「ブーツを履く」の目的語を示す「を」が入り、自然に成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、「厚いブーツと履いて」は目的語を示せず成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「ブーツへ履いて」は履く対象にならず合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「ブーツより履いて」は履く対象を示せず合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「ブーツを履く」の目的語を示す「を」が入り、自然に成り立つ。", "と": "「と」は並列や引用を示すので、「厚いブーツと履いて」は目的語を示せず成り立たない。", "へ": "「へ」は方向を示すので、「ブーツへ履いて」は履く対象にならず合わない。", "より": "「より」は比較を示すので、「ブーツより履いて」は履く対象を示せず合わない。"}, "error_tags": {"と": "並列・引用", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52866, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「ブーツの手入れ」で所属や修飾を示す「の」が入り、自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「ブーツに手入れ」では名詞どうしを修飾する関係が成り立たず、不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「ブーツから手入れ」は名詞を修飾する関係を作れない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「ブーツで手入れ」は手入れの対象を表せず不自然になる。"}], "correct_answer": "の", "explanations": {"の": "正解。「ブーツの手入れ」で所属や修飾を示す「の」が入り、自然に成り立つ。", "に": "「ブーツに手入れ」では名詞どうしを修飾する関係が成り立たず、不自然になる。", "から": "「から」は起点を示すので、「ブーツから手入れ」は名詞を修飾する関係を作れない。", "で": "「で」は手段や場所を示すので、「ブーツで手入れ」は手入れの対象を表せず不自然になる。"}, "error_tags": {"に": "相手・帰着", "から": "起点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52866, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くるぶしより上の部分までをおおう、皮などでできたくつ。", "primary_collocate": null, "pronunciation": "ぶーつ", "ipa": "buːtsɯ", "syllable_count": 3, "sentences": [{"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。", "target_word": "ブーツ", "complexity_tier": "T4", "furigana": "深紅[しんく]とも、あるいは乾[かわ]いた血[ち]の色[いろ]とも形容[けいよう]すべきそのブーツは、もはや単[たん]なる履物[はきもの]という枠組[わくぐ]みを超[こ]え、私[わたし]の内面[ないめん]に潜[ひそ]む情動[じょうどう]を可視化[かしか]する媒体[ばいたい]となっているのだ。", "sentence_source": "generated"}, {"text": "雪の日は、底が厚いブーツを履いて出かけた。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、底[そこ]が厚[あつ]いブーツを履[は]いて出[で]かけた。", "sentence_source": "generated"}, {"text": "彼女は黒い革のブーツに、長いスカートを合わせた。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は黒[くろ]い革[かわ]のブーツに、長[なが]いスカートを合[あ]わせた。", "sentence_source": "generated"}, {"text": "玄関でブーツのひもをきつく結んで、山道へ向かった。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "玄関[げんかん]でブーツのひもをきつく結[むす]んで、山道[やまみち]へ向[む]かった。", "sentence_source": "generated"}, {"text": "新品のブーツは硬くて、最初は靴擦れができてしまった。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "新品[しんぴん]のブーツは硬[かた]くて、最初[さいしょ]は靴擦[くつず]れができてしまった。", "sentence_source": "generated"}, {"text": "雨でブーツの中まで濡れたので、帰ってすぐ乾かした。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "雨[あめ]でブーツの中[なか]まで濡[ぬ]れたので、帰[かえ]ってすぐ乾[かわ]かした。", "sentence_source": "generated"}, {"text": "冬のセールで、茶色のブーツを一足買った。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "冬[ふゆ]のセールで、茶色[ちゃいろ]のブーツを一足[いっそく]買[か]った。", "sentence_source": "generated"}, {"text": "ブーツの手入れをするために、クリームと布を用意した。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "ブーツの手入[ていれ]をするために、クリームと布[ぬの]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "乗馬の時は、足首までしっかり守るブーツが必要だ。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "乗馬[じょうば]の時[とき]は、足首[あしくび]までしっかり守[まも]るブーツが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "このブーツは丈が長いので、座るとひざの裏が少し痛い。", "target_word": "ブーツ", "complexity_tier": "T3", "furigana": "このブーツは丈[たけ]が長[なが]いので、座[すわ]るとひざの裏[うら]が少[すこ]し痛[いた]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブーツ", "label": "基本形"}, {"form": "ブーツを履く", "label": "動詞との結合形"}], "register": "日常語（中立）", "sense_fingerprint": "足首より上まで覆う革などの靴（履物のブーツ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 深紅 (Zipf 2.91), 形容 (Zipf 3.21), 履物 (Zipf 2.6), 潜む (Zipf 3.39), 情動 (Zipf 2.72)']::text[], 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52866, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブーツ", "is_correct": true, "explanation": "正解。くるぶしまでおおう履物として「単なる履物という枠組み」の文脈に合う。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋は手にはめるもので、「単なる履物という枠組みを超え」の文脈に合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "帽子は頭にかぶるもので、履物の枠組みを話題にする文に合わない。"}, {"text": "ベルト", "is_correct": false, "explanation": "ベルトは腰に締めるもので、履物という話の流れと合わない。"}], "explanations": {"ブーツ": "正解。くるぶしまでおおう履物として「単なる履物という枠組み」の文脈に合う。", "手袋": "手袋は手にはめるもので、「単なる履物という枠組みを超え」の文脈に合わない。", "帽子": "帽子は頭にかぶるもので、履物の枠組みを話題にする文に合わない。", "ベルト": "ベルトは腰に締めるもので、履物という話の流れと合わない。"}, "sentence_index": 0, "correct_answer": "ブーツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古いパソコンはブーツに時間がかかるので、朝は待たされる。", "explanation": "ここは〈ブート（起動）〉の意味。パソコンの起動はブートで、履物のブーツは当てはまらない。"}, {"text": "判定の直後、会場全体からブーツが起こった。", "explanation": "ここは〈ブーイング（非難の声）〉の意味。会場から起こるのはブーイングで、靴のブーツは当てはまらない。"}, {"text": "歯みがきのあと、ブーツで歯をみがいた。", "explanation": "ここは〈ブラシ〉の意味。歯をみがくのはブラシで、靴のブーツは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52866, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブーツ", "is_correct": true, "explanation": "正解。一足で数える履物で、冬の買い物の文に合う。"}, {"text": "ネクタイ", "is_correct": false, "explanation": "ネクタイは一本で数えるので、「一足」とは合わない。"}, {"text": "マフラー", "is_correct": false, "explanation": "マフラーは一本・一枚で数えるので、「一足」とは数え方が合わない。"}, {"text": "コート", "is_correct": false, "explanation": "コートは一着で数えるので、「一足」は使えない。"}], "explanations": {"ブーツ": "正解。一足で数える履物で、冬の買い物の文に合う。", "ネクタイ": "ネクタイは一本で数えるので、「一足」とは合わない。", "マフラー": "マフラーは一本・一枚で数えるので、「一足」とは数え方が合わない。", "コート": "コートは一着で数えるので、「一足」は使えない。"}, "sentence_index": 6, "correct_answer": "ブーツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "後ろのブーツに買い物袋を入れた。", "explanation": "ここは〈トランク（車の荷室）〉の意味。車の荷室をブーツとは日本語で言わず、履物の意味とも合わない。"}, {"text": "展示会のブーツで新製品を紹介した。", "explanation": "ここは〈ブース（展示の仕切り場所）〉の意味。展示の場所をブーツとは言わず、履物では合わない。"}, {"text": "自転車のブーツを強く握った。", "explanation": "ここは〈ブレーキ〉の意味。握るのはブレーキで、ブーツは握る物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52866, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店員は黒いブーツで一足取り出した。", "corrected_sentence": "店員は黒いブーツを一足取り出した。", "error_description": "「取り出す」の目的語を示す「を」が必要。「で」は手段を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52866, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い朝は、起きてすぐブーツをかぶって外へ出た。", "corrected_sentence": "寒い朝は、起きてすぐブーツを履いて外へ出た。", "error_description": "ブーツは足に「履く」ものなので、「かぶって」は誤り。正しくは「履いて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52867, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「選ぶ」の対象（選ぶもの）を示す「を」。「歩きやすい履き物を選ぶ」で文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「選ぶ」の対象にはならない。「歩きやすい履き物が選んでください」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「履き物と選ぶ」は対象を表せず、文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「選ぶ」の対象にはならない。「履き物へ選ぶ」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「選ぶ」の対象（選ぶもの）を示す「を」。「歩きやすい履き物を選ぶ」で文が成り立つ。", "が": "「が」は主語を示すので、「選ぶ」の対象にはならない。「歩きやすい履き物が選んでください」は成り立たない。", "と": "「と」は並列や相手を示すので、「履き物と選ぶ」は対象を表せず、文として不自然。", "へ": "「へ」は方向を示すので、「選ぶ」の対象にはならない。「履き物へ選ぶ」は不自然。"}, "error_tags": {"が": "主格", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52867, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「買ってもらう」の対象（物）を示す「を」。「新しい履き物を買ってもらった」で文が成り立つ。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、「買ってもらう」の対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞なので、動詞「買う」の対象は示せない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は「もらう」の相手（くれる人）を示すので、物には使えない。"}], "correct_answer": "を", "explanations": {"を": "「買ってもらう」の対象（物）を示す「を」。「新しい履き物を買ってもらった」で文が成り立つ。", "より": "「より」は比較の基準を示すので、「買ってもらう」の対象にはならない。", "の": "「の」は名詞をつなぐ助詞なので、動詞「買う」の対象は示せない。", "に": "「に」は「もらう」の相手（くれる人）を示すので、物には使えない。"}, "error_tags": {"より": "比較", "の": "連体修飾", "に": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52867, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あしに はく ものです。", "primary_collocate": null, "pronunciation": "はきもの", "ipa": "hakimono", "syllable_count": 4, "sentences": [{"text": "玄関で履き物をそろえてから、部屋に上がった。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "玄関[げんかん]で履[は]き物[もの]をそろえてから、部屋[へや]に上[あ]がった。", "sentence_source": "generated"}, {"text": "山に登るときは、歩きやすい履き物を選んでください。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]るときは、歩[ある]きやすい履[は]き物[もの]を選[えら]んでください。", "sentence_source": "generated"}, {"text": "この店には、子ども用の履き物がたくさん並んでいる。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "この店[みせ]には、子[こ]ども用[よう]の履[は]き物[もの]がたくさん並[なら]んでいる。", "sentence_source": "generated"}, {"text": "雨の日は、濡れてもいい履き物で出かけた。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、濡[ぬ]れてもいい履[は]き物[もの]で出[で]かけた。", "sentence_source": "generated"}, {"text": "旅館の入り口で、履き物を脱いでください。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "旅館[りょかん]の入[い]り口[ぐち]で、履[は]き物[もの]を脱[ぬ]いでください。", "sentence_source": "generated"}, {"text": "祖母は、夏になると軽い履き物を好んで履く。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、夏[なつ]になると軽[かる]い履[は]き物[もの]を好[この]んで履[は]く。", "sentence_source": "generated"}, {"text": "履き物が合わないと、長く歩いたときに足が痛くなる。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "履[は]き物[もの]が合[あ]わないと、長[なが]く歩[ある]いたときに足[あし]が痛[いた]くなる。", "sentence_source": "generated"}, {"text": "運動会の前に、新しい履き物を買ってもらった。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の前[まえ]に、新[あたら]しい履[は]き物[もの]を買[か]ってもらった。", "sentence_source": "generated"}, {"text": "公園で遊ぶときは、走りやすい履き物がいい。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "公園[こうえん]で遊[あそ]ぶときは、走[はし]りやすい履[は]き物[もの]がいい。", "sentence_source": "generated"}, {"text": "履き物の裏が減ったので、新しいものと取り替えた。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "履[は]き物[もの]の裏[うら]が減[へ]ったので、新[あたら]しいものと取[と]り替[か]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "履き物", "label": "基本形"}], "register": "標準", "sense_fingerprint": "足にはくもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52867, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "履き物", "is_correct": true, "explanation": "「玄関で〜をそろえる」は脱いだ靴やサンダルを並べる意味になり、足にはくものである履き物が入ると文が成り立つ。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機は玄関で並べて揃える物ではなく、足にはくものでもないので、空欄に入ると文が成り立たない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は玄関で並べて揃える物ではない。「玄関で冷蔵庫をそろえる」は意味をなさない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は据え付けられた家電で、玄関でそろえてから上がる対象ではないため、文脈に合わない。"}], "explanations": {"履き物": "「玄関で〜をそろえる」は脱いだ靴やサンダルを並べる意味になり、足にはくものである履き物が入ると文が成り立つ。", "掃除機": "掃除機は玄関で並べて揃える物ではなく、足にはくものでもないので、空欄に入ると文が成り立たない。", "冷蔵庫": "冷蔵庫は玄関で並べて揃える物ではない。「玄関で冷蔵庫をそろえる」は意味をなさない。", "洗濯機": "洗濯機は据え付けられた家電で、玄関でそろえてから上がる対象ではないため、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "履き物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急に気分が悪くなり、床にできた履き物を雑巾で拭いた。", "explanation": "ここは〈吐いたもの〉の意味（吐き物）。足にはく履き物は床にできるものとしては使わないので、この文は誤り。"}, {"text": "日差しが強いので、履き物をかぶって出かけた。", "explanation": "ここは〈帽子〉の意味。かぶるのは帽子で、足にはく履き物は頭にかぶれないので合わない。"}, {"text": "寒いので、履き物を手にはめて出かけた。", "explanation": "ここは〈手袋〉の意味。はめるのは手袋で、足にはく履き物は手にはめられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52867, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "履き物", "is_correct": true, "explanation": "足に合わないと足が痛くなるという文脈で、足にはくものの履き物が入ると文が成り立つ。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪は指に合うもので、合わないと足が痛くなる原因にはならないので文脈に合わない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡が合わないと目が疲れることはあるが、長く歩いて足が痛くなる文脈には合わない。"}, {"text": "腕時計", "is_correct": false, "explanation": "腕時計はサイズが合わないこともあるが、足が痛くなる原因にはならないので文脈に合わない。"}], "explanations": {"履き物": "足に合わないと足が痛くなるという文脈で、足にはくものの履き物が入ると文が成り立つ。", "指輪": "指輪は指に合うもので、合わないと足が痛くなる原因にはならないので文脈に合わない。", "眼鏡": "眼鏡が合わないと目が疲れることはあるが、長く歩いて足が痛くなる文脈には合わない。", "腕時計": "腕時計はサイズが合わないこともあるが、足が痛くなる原因にはならないので文脈に合わない。"}, "sentence_index": 6, "correct_answer": "履き物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は、履き物を差して出かけた。", "explanation": "ここは〈傘〉の意味。傘は差すものだが、足にはく履き物は差せないので合わない。"}, {"text": "目が悪いので、履き物をかけて本を読んだ。", "explanation": "ここは〈眼鏡〉の意味。眼鏡はかけるものだが、足にはく履き物は顔にかけられないので合わない。"}, {"text": "記念日に、彼は指に履き物をはめた。", "explanation": "ここは〈指輪〉の意味。指輪は指にはめるものだが、足にはく履き物は指にははめられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52867, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨で道がぬかるんでいたので、泥が付きにくい履き物に選んだ。", "corrected_sentence": "雨で道がぬかるんでいたので、泥が付きにくい履き物を選んだ。", "error_description": "「選ぶ」の対象は助詞「を」で示す。「履き物に選んだ」は「に」が誤り。正しくは「履き物を選んだ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52867, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い朝は、暖かい履き物を履くて出かけた。", "corrected_sentence": "寒い朝は、暖かい履き物を履いて出かけた。", "error_description": "「履く」の連用形（て形）は「履いて」。「履くて」は誤った活用なので、正しくは「履いて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52868, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「売る」の対象（売るもの）を示す「を」。「履き物を専門に売る店」で文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は「売る」の相手（客）や場所を示すもので、売る対象（物）は示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、「売る」の対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「履き物から専門に売る」は売る対象を表せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「売る」の対象（売るもの）を示す「を」。「履き物を専門に売る店」で文が成り立つ。", "に": "「に」は「売る」の相手（客）や場所を示すもので、売る対象（物）は示せないので合わない。", "より": "「より」は比較の基準を示すので、「売る」の対象にはならない。", "から": "「から」は起点を示すが、「履き物から専門に売る」は売る対象を表せず、文が成り立たない。"}, "error_tags": {"に": "相手・場所", "より": "比較", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52868, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52868, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "足に履くものの総称。靴やスリッパなど。", "primary_collocate": null, "pronunciation": "はきもの", "ipa": "hakimono", "syllable_count": 4, "sentences": [{"text": "靴やサンダルなど、足に履くものをまとめて履き物と呼ぶ。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "靴[くつ]やサンダルなど、足[あし]に履[は]くものをまとめて履[は]き物[もの]と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "駅の近くに、履き物を専門に売る店ができた。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに、履[は]き物[もの]を専門[せんもん]に売[う]る店[みせ]ができた。", "sentence_source": "generated"}, {"text": "和室に入る前に、スリッパなどの履き物は廊下で脱ぐ。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "和室[わしつ]に入[はい]る前[まえ]に、スリッパなどの履[は]き物[もの]は廊下[ろうか]で脱[ぬ]ぐ。", "sentence_source": "generated"}, {"text": "日本には、下駄や草履など昔から続く履き物がある。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "日本[にほん]には、下駄[げた]や草履[ぞうり]など昔[むかし]から続[つづ]く履[は]き物[もの]がある。", "sentence_source": "generated"}, {"text": "工事現場では、安全のために決められた履き物を必ず履く。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "工事現場[こうじげんば]では、安全[あんぜん]のために決[き]められた履[は]き物[もの]を必[かなら]ず履[は]く。", "sentence_source": "generated"}, {"text": "夏祭りでは、浴衣に合う履き物を選ぶのが楽しい。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "夏祭[なつまつ]りでは、浴衣[ゆかた]に合[あ]う履[は]き物[もの]を選[えら]ぶのが楽[たの]しい。", "sentence_source": "generated"}, {"text": "姉は、履き物の工場でデザインの仕事をしている。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "姉[あね]は、履[は]き物[もの]の工場[こうじょう]でデザインの仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "冬は雪が多いので、すべりにくい履き物が必要だ。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "冬[ふゆ]は雪[ゆき]が多[おお]いので、すべりにくい履[は]き物[もの]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "履き物の種類が多すぎて、どれを買うか迷ってしまった。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "履[は]き物[もの]の種類[しゅるい]が多[おお]すぎて、どれを買[か]うか迷[まよ]ってしまった。", "sentence_source": "generated"}, {"text": "病院では、静かに歩ける履き物を履くように言われた。", "target_word": "履き物", "complexity_tier": "T3", "furigana": "病院[びょういん]では、静[しず]かに歩[ある]ける履[は]き物[もの]を履[は]くように言[い]われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "履き物", "label": "基本形"}], "register": "標準", "sense_fingerprint": "靴やスリッパなど足に履くものの総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52868, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "履き物", "is_correct": true, "explanation": "靴やサンダルなどをまとめて指す語として、足にはくものの総称である履き物が入ると文が成り立つ。"}, {"text": "文房具", "is_correct": false, "explanation": "文房具は足にはくものの総称にはならない。「足に履くものを文房具と呼ぶ」は意味が成り立たない。"}, {"text": "食器", "is_correct": false, "explanation": "食器は足に履くものではないので、まとめて食器と呼ぶと文脈に合わない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は寝るときに使う物で、足にはくものを寝具と呼ぶことはないので合わない。"}], "explanations": {"履き物": "靴やサンダルなどをまとめて指す語として、足にはくものの総称である履き物が入ると文が成り立つ。", "文房具": "文房具は足にはくものの総称にはならない。「足に履くものを文房具と呼ぶ」は意味が成り立たない。", "食器": "食器は足に履くものではないので、まとめて食器と呼ぶと文脈に合わない。", "寝具": "寝具は寝るときに使う物で、足にはくものを寝具と呼ぶことはないので合わない。"}, "sentence_index": 0, "correct_answer": "履き物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吐き気が止まらず、床にできた履き物を拭いた。", "explanation": "ここは〈吐いたもの〉の意味（吐き物）。足にはく履き物は床にできるものとしては使わないので、この文は誤り。"}, {"text": "朝、履き物を手首にはめて家を出た。", "explanation": "ここは〈腕時計〉の意味。腕時計は手首にはめるものだが、足にはく履き物は手首にはめられないので合わない。"}, {"text": "庭で摘んだ花を、履き物に生けた。", "explanation": "ここは〈花瓶〉の意味。花を生けるのは花瓶で、履き物は花を入れる容器にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52868, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "履き物", "is_correct": true, "explanation": "履き物を作る工場は製品を作る場所として自然で、デザインの仕事をする場所と合う。"}, {"text": "公園", "is_correct": false, "explanation": "公園に工場はなく、「公園の工場でデザインの仕事をする」は成り立たない。"}, {"text": "病院", "is_correct": false, "explanation": "病院は工場ではないので、「病院の工場」は文脈に合わない。"}, {"text": "砂場", "is_correct": false, "explanation": "砂場は子どもが遊ぶ場所で、工場の前には来ないので合わない。"}], "explanations": {"履き物": "履き物を作る工場は製品を作る場所として自然で、デザインの仕事をする場所と合う。", "公園": "公園に工場はなく、「公園の工場でデザインの仕事をする」は成り立たない。", "病院": "病院は工場ではないので、「病院の工場」は文脈に合わない。", "砂場": "砂場は子どもが遊ぶ場所で、工場の前には来ないので合わない。"}, "sentence_index": 6, "correct_answer": "履き物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い夜は、履き物をかけて寝た。", "explanation": "ここは〈布団〉の意味。布団は体にかけて寝るものだが、足にはく履き物は体にかけて使えないので合わない。"}, {"text": "寒いので、履き物を首に巻いて出かけた。", "explanation": "ここは〈マフラー〉の意味。マフラーは首に巻くものだが、足にはく履き物は首に巻けないので合わない。"}, {"text": "古い本を、履き物に並べて整理した。", "explanation": "ここは〈本棚〉の意味。本を並べる家具であり、履き物は本を並べる棚にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52868, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日の泥汚れを落とすため、履き物を飲んだ。", "corrected_sentence": "雨の日の泥汚れを落とすため、履き物を洗った。", "error_description": "履き物に使う動詞は「洗う」など。「飲む」は飲み物に使う動詞で、履き物とは組み合わない。正しくは「洗った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52868, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "足元が冷えるので、厚手の履き物が買った。", "corrected_sentence": "足元が冷えるので、厚手の履き物を買った。", "error_description": "「買う」の対象は助詞「を」で示す。「が」は主語を示すので、「履き物が買った」は誤り。正しくは「履き物を買った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52869, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「駆られる」が取る「に」。激しい情動に駆られる、という形で自然につながる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だが、「情動が駆られて」では「駆られる」の対象が成り立たず、文が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「駆られる」と組まないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「駆られる」とは組まず、「情動へ駆られて」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「駆られる」が取る「に」。激しい情動に駆られる、という形で自然につながる。", "が": "主語の「が」だが、「情動が駆られて」では「駆られる」の対象が成り立たず、文が通らない。", "を": "目的語の「を」は「駆られる」と組まないので合わない。", "へ": "方向の「へ」は「駆られる」とは組まず、「情動へ駆られて」は不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52869, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「満ちる」が取る「に」。深い情動に満ちた音色、という形で自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「満ちる」は対象を「を」で取らないので「情動を満ちた」は非文。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手の「と」は、「情動と満ちた」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「満ちる」と合わず、「情動から満ちた」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「満ちる」が取る「に」。深い情動に満ちた音色、という形で自然につながる。", "を": "「満ちる」は対象を「を」で取らないので「情動を満ちた」は非文。", "と": "並列や相手の「と」は、「情動と満ちた」では文が成り立たない。", "から": "起点の「から」は「満ちる」と合わず、「情動から満ちた」は不自然。"}, "error_tags": {"を": "目的語", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52869, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心の中で感じる、強い気持ちのこと。", "primary_collocate": null, "pronunciation": "じょうどう", "ipa": "d͡ʑoːdoː", "syllable_count": 4, "sentences": [{"text": "彼は強い情動に突き動かされ、手紙を書き上げた。", "target_word": "情動", "complexity_tier": "T3", "furigana": "彼[かれ]は強[つよ]い情動[じょうどう]に突[つ]き動[うご]かされ、手紙[てがみ]を書[か]き上[あ]げた。", "sentence_source": "generated"}, {"text": "激しい情動に駆られて、思わず大声で叫んでしまった。", "target_word": "情動", "complexity_tier": "T3", "furigana": "激[はげ]しい情動[じょうどう]に駆[か]られて、思[おも]わず大声[おおごえ]で叫[さけ]んでしまった。", "sentence_source": "generated"}, {"text": "怒りの情動が収まるまで、私は黙って待った。", "target_word": "情動", "complexity_tier": "T3", "furigana": "怒[いか]りの情動[じょうどう]が収[おさ]まるまで、私[わたし]は黙[だま]って待[ま]った。", "sentence_source": "generated"}, {"text": "彼女は情動を表に出さず、静かに話を聞いていた。", "target_word": "情動", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は情動[じょうどう]を表[おもて]に出[だ]さず、静[しず]かに話[はなし]を聞[き]いていた。", "sentence_source": "generated"}, {"text": "試合に勝った瞬間、選手たちの情動が大きく高ぶった。", "target_word": "情動", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]った瞬間[しゅんかん]、選手[せんしゅ]たちの情動[じょうどう]が大[おお]きく高[たか]ぶった。", "sentence_source": "generated"}, {"text": "小説の主人公は、情動の波に飲み込まれていく。", "target_word": "情動", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の主人公[しゅじんこう]は、情動[じょうどう]の波[なみ]に飲[の]み込[こ]まれていく。", "sentence_source": "generated"}, {"text": "一時の情動で決めると、あとで後悔することが多い。", "target_word": "情動", "complexity_tier": "T3", "furigana": "一時[いちじ]の情動[じょうどう]で決[き]めると、あとで後悔[こうかい]することが多[おお]い。", "sentence_source": "generated"}, {"text": "深い情動に満ちた音色で、彼はピアノを弾いた。", "target_word": "情動", "complexity_tier": "T3", "furigana": "深[ふか]い情動[じょうどう]に満[み]ちた音色[ねいろ]で、彼[かれ]はピアノを弾[ひ]いた。", "sentence_source": "generated"}, {"text": "夜の海を見ていると、説明できない情動が湧いてくる。", "target_word": "情動", "complexity_tier": "T3", "furigana": "夜[よる]の海[うみ]を見[み]ていると、説明[せつめい]できない情動[じょうどう]が湧[わ]いてくる。", "sentence_source": "generated"}, {"text": "彼の演説は、聞く人の情動に直接訴えかけた。", "target_word": "情動", "complexity_tier": "T3", "furigana": "彼[かれ]の演説[えんぜつ]は、聞[き]く人[ひと]の情動[じょうどう]に直接[ちょくせつ]訴[うった]えかけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "情動", "label": "基本形"}, {"form": "情動的", "label": "形容動詞的派生形"}], "register": "書き言葉・硬い", "sense_fingerprint": "心の中に強く湧く気持ち（怒り・悲しみ・興奮など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52869, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情動", "is_correct": true, "explanation": "強い感情に突き動かされるという意味で、文脈に合う。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとの意味で、人を突き動かすという文脈に合わない。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序の意味で、強い気持ちに突き動かされるとは言えない。"}, {"text": "相場", "is_correct": false, "explanation": "市場価格の意味で、人を突き動かす力にはならない。"}], "explanations": {"情動": "強い感情に突き動かされるという意味で、文脈に合う。", "規則": "決まりごとの意味で、人を突き動かすという文脈に合わない。", "手順": "作業の順序の意味で、強い気持ちに突き動かされるとは言えない。", "相場": "市場価格の意味で、人を突き動かす力にはならない。"}, "sentence_index": 0, "correct_answer": "情動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は情動を傾けて、毎日研究に打ち込んでいる。", "explanation": "ここは〈情熱〉（物事に打ち込む熱い思い）の意味。情動は心に起こる感情の動きを指すので、打ち込む熱い思いには使わない。"}, {"text": "彼は情動が旺盛で、何にでも興味を持つ。", "explanation": "ここは〈好奇心〉の意味。情動は感情の動きで、知りたがる気持ちの旺盛さには使わない。"}, {"text": "夕暮れの情動が美しく、思わず足を止めた。", "explanation": "ここは〈情景〉（ある場面の様子）の意味。情動は心の感情の動きで、風景の様子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52869, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情動", "is_correct": true, "explanation": "一時の感情の高ぶりで決める、という意味で自然。"}, {"text": "文法", "is_correct": false, "explanation": "言葉の仕組みの意味で、一時の状態で決めるという文に合わない。"}, {"text": "語彙", "is_correct": false, "explanation": "言葉の集まりの意味で、決め方の根拠としては成り立たない。"}, {"text": "音階", "is_correct": false, "explanation": "音の高さの並びの意味で、決める根拠にはならない。"}], "explanations": {"情動": "一時の感情の高ぶりで決める、という意味で自然。", "文法": "言葉の仕組みの意味で、一時の状態で決めるという文に合わない。", "語彙": "言葉の集まりの意味で、決め方の根拠としては成り立たない。", "音階": "音の高さの並びの意味で、決める根拠にはならない。"}, "sentence_index": 6, "correct_answer": "情動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は情動を持って仕事に取り組んでいる。", "explanation": "ここは〈熱意〉（物事に進んで取り組む気持ち）の意味。情動は心に湧く感情の動きで、仕事への取り組み方には合わない。"}, {"text": "その件について、情動によると来月から料金が上がるそうだ。", "explanation": "ここは〈情報〉（知らせや資料）の意味。情動は心の感情の動きを指すので、料金の知らせの根拠にはならない。"}, {"text": "彼女は情動が鋭く、作品の細かな違いを見抜く。", "explanation": "ここは〈感性〉（物事の良さを感じ取る力）の意味。情動は感情の動きなので、鋭く見抜く感覚の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52869, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は強い情動に押し流して、判断を誤った。", "corrected_sentence": "彼は強い情動に押し流されて、判断を誤った。", "error_description": "誤りは「押し流して」。「押し流される」（受け身）の形が必要で、「情動に押し流して」では主語が欠けるので、正しくは「押し流されて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52869, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は一時の情動を任せて、大事な約束を破ってしまった。", "corrected_sentence": "彼は一時の情動に任せて、大事な約束を破ってしまった。", "error_description": "誤りは「情動を任せて」の「を」。「任せる」は「に」を取るので、正しくは「情動に任せて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52870, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「揺さぶる」の対象を示す「を」。揺さぶられるのが情動なので、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だが、「情動が強く揺さぶった」では「揺さぶる」の対象が欠け、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向の「に」だが、「揺さぶる」は対象を「を」で取るので「情動に」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手の「と」だが、「情動と揺さぶった」では目的語にならず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「揺さぶる」の対象を示す「を」。揺さぶられるのが情動なので、ここに入る。", "が": "主語の「が」だが、「情動が強く揺さぶった」では「揺さぶる」の対象が欠け、文が成り立たない。", "に": "相手や方向の「に」だが、「揺さぶる」は対象を「を」で取るので「情動に」は合わない。", "と": "並列や相手の「と」だが、「情動と揺さぶった」では目的語にならず文が成り立たない。"}, "error_tags": {"が": "主語", "に": "相手・方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52870, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「情動の変化」の「の」。情動と変化をつなぐ連体修飾で、ここに入る。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」だが、「情動へ変化を観察した」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、「情動から変化を観察した」では文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」は、「情動で変化を観察した」ではつながらない。"}], "correct_answer": "の", "explanations": {"の": "「情動の変化」の「の」。情動と変化をつなぐ連体修飾で、ここに入る。", "へ": "方向の「へ」だが、「情動へ変化を観察した」では意味が通らない。", "から": "起点の「から」は、「情動から変化を観察した」では文脈に合わない。", "で": "手段や場所の「で」は、「情動で変化を観察した」ではつながらない。"}, "error_tags": {"へ": "方向", "から": "起点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52870, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心にわき起こる、喜びや悲しみなどの感情の動き。", "primary_collocate": null, "pronunciation": "じょうどう", "ipa": "d͡ʑoːdoː", "syllable_count": 4, "sentences": [{"text": "鳥の声を聞くと、理由のわからない情動がわき起こった。", "target_word": "情動", "complexity_tier": "T3", "furigana": "鳥[とり]の声[こえ]を聞[き]くと、理由[りゆう]のわからない情動[じょうどう]がわき起[お]こった。", "sentence_source": "generated"}, {"text": "映画の最後の場面は、観客の情動を強く揺さぶった。", "target_word": "情動", "complexity_tier": "T3", "furigana": "映画[えいが]の最後[さいご]の場面[ばめん]は、観客[かんきゃく]の情動[じょうどう]を強[つよ]く揺[ゆ]さぶった。", "sentence_source": "generated"}, {"text": "音楽には、言葉より先に人の情動を呼び起こす力がある。", "target_word": "情動", "complexity_tier": "T3", "furigana": "音楽[おんがく]には、言葉[ことば]より先[さき]に人[ひと]の情動[じょうどう]を呼[よ]び起[お]こす力[ちから]がある。", "sentence_source": "generated"}, {"text": "子どもは情動をうまく抑えられず、すぐに泣き出してしまう。", "target_word": "情動", "complexity_tier": "T3", "furigana": "子[こ]どもは情動[じょうどう]をうまく抑[おさ]えられず、すぐに泣[な]き出[だ]してしまう。", "sentence_source": "generated"}, {"text": "心理学の授業で、情動と思考の関係について学んだ。", "target_word": "情動", "complexity_tier": "T3", "furigana": "心理学[しんりがく]の授業[じゅぎょう]で、情動[じょうどう]と思考[しこう]の関係[かんけい]について学[まな]んだ。", "sentence_source": "generated"}, {"text": "彼女の詩は、抑えきれない情動をそのまま言葉にしている。", "target_word": "情動", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の詩[し]は、抑[おさ]えきれない情動[じょうどう]をそのまま言葉[ことば]にしている。", "sentence_source": "generated"}, {"text": "突然の別れに、悲しみという情動が一気にあふれた。", "target_word": "情動", "complexity_tier": "T3", "furigana": "突然[とつぜん]の別[わか]れに、悲[かな]しみという情動[じょうどう]が一気[いっき]にあふれた。", "sentence_source": "generated"}, {"text": "医師は、患者の情動の変化を注意深く観察した。", "target_word": "情動", "complexity_tier": "T3", "furigana": "医師[いし]は、患者[かんじゃ]の情動[じょうどう]の変化[へんか]を注意深[ちゅういぶか]く観察[かんさつ]した。", "sentence_source": "generated"}, {"text": "絵を描くと、胸の中の情動が少し落ち着く気がする。", "target_word": "情動", "complexity_tier": "T3", "furigana": "絵[え]を描[えが]くと、胸[むね]の中[なか]の情動[じょうどう]が少[すこ]し落[お]ち着[つ]く気[き]がする。", "sentence_source": "generated"}, {"text": "情動が高ぶると、心拍数が上がることがある。", "target_word": "情動", "complexity_tier": "T3", "furigana": "情動[じょうどう]が高[たか]ぶると、心拍数[しんぱくすう]が上[あ]がることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "情動", "label": "基本形"}, {"form": "情動的", "label": "形容動詞的派生形"}], "register": "書き言葉・硬い（学術的）", "sense_fingerprint": "喜びや悲しみなど心に起こる感情の動き（心理学的な感情反応）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52870, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情動", "is_correct": true, "explanation": "心に湧く感情の動きを指し、わき起こるという文脈に合う。"}, {"text": "予算", "is_correct": false, "explanation": "お金の見積もりや配分の意味で、内面に潜むものを可視化する文脈に合わない。"}, {"text": "契約", "is_correct": false, "explanation": "取り決めの意味で、内面の感情を表すこの文には入らない。"}, {"text": "相場", "is_correct": false, "explanation": "市場価格の意味で、「内面に潜む」という表現と結びつかない。"}], "explanations": {"情動": "心に湧く感情の動きを指し、わき起こるという文脈に合う。", "予算": "お金の見積もりや配分の意味で、内面に潜むものを可視化する文脈に合わない。", "契約": "取り決めの意味で、内面の感情を表すこの文には入らない。", "相場": "市場価格の意味で、「内面に潜む」という表現と結びつかない。"}, "sentence_index": 0, "correct_answer": "情動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は情動が鋭く、味の違いをすぐに見分ける。", "explanation": "ここは〈感覚〉の意味。情動は心に湧く感情の動きを指し、味覚の鋭さには使わないので合わない。"}, {"text": "この町には情動が残っていて、古い街並みを歩くと心が和む。", "explanation": "ここは〈情緒〉（町などが醸し出す趣や雰囲気）の意味。情動は個人の内に湧く感情を指すので、町の雰囲気には合わない。"}, {"text": "その国の情動は不安定で、政府が対応に追われている。", "explanation": "ここは〈情勢〉（国や社会の動きや状況）の意味。情動は個人の感情の動きなので、国の状況には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52870, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情動", "is_correct": true, "explanation": "悲しみという感情の動きが一気にあふれる、という文脈に合う。"}, {"text": "方針", "is_correct": false, "explanation": "物事の進め方の意味で、感情があふれるという文に合わない。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序の意味で、あふれるものとしては成り立たない。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとの意味で、感情があふれるという表現に合わない。"}], "explanations": {"情動": "悲しみという感情の動きが一気にあふれる、という文脈に合う。", "方針": "物事の進め方の意味で、感情があふれるという文に合わない。", "手順": "作業の順序の意味で、あふれるものとしては成り立たない。", "規則": "決まりごとの意味で、感情があふれるという表現に合わない。"}, "sentence_index": 6, "correct_answer": "情動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その布は情動が柔らかく、手触りがとても心地よい。", "explanation": "ここは〈感触〉の意味。情動は心に湧く感情の動きで、布の手触りには使えない。"}, {"text": "被告人の情動が酌量され、刑が軽くなった。", "explanation": "ここは〈情状〉（刑を軽くする根拠になる事情）の意味。情動は個人の感情の動きを指すので、裁判での事情の酌量には使わない。"}, {"text": "統計の情動によると、来年は雨が多いという。", "explanation": "ここは〈情報〉（知らせやデータ）の意味。情動は心の感情の動きを指し、予報や統計の根拠には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52870, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の歌は、聞く人の情動に大きく揺り動かした。", "corrected_sentence": "彼の歌は、聞く人の情動を大きく揺り動かした。", "error_description": "誤りは「情動に」の「に」。「揺り動かす」は対象を「を」で取る他動詞なので、正しくは「情動を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52870, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は情動を抑えきれ、声を震わせた。", "corrected_sentence": "彼は情動を抑えきれず、声を震わせた。", "error_description": "誤りは「抑えきれ」。「抑えきれず」の「ず」が必要で、この形のままでは文が続かない。正しくは「抑えきれず」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52871, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "原因を示す「に」。熱気に、先生も笑顔になった、という形で自然につながる。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手の「と」は、「熱気と笑顔になった」では原因を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「熱気の、先生も」と文が続かず、原因を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「笑顔になる」は目的語の「を」を取らず、「熱気を笑顔になった」は非文。"}], "correct_answer": "に", "explanations": {"に": "原因を示す「に」。熱気に、先生も笑顔になった、という形で自然につながる。", "と": "並列や相手の「と」は、「熱気と笑顔になった」では原因を示せない。", "の": "連体の「の」では「熱気の、先生も」と文が続かず、原因を示せない。", "を": "「笑顔になる」は目的語の「を」を取らず、「熱気を笑顔になった」は非文。"}, "error_tags": {"と": "並列", "の": "連体", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52871, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「は」。「熱気は」が主題になり、最後まで続いたと述べる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、自動詞「続く」と組まないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「熱気へ最後まで続いた」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「熱気より最後まで続いた」と文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題の「は」。「熱気は」が主題になり、最後まで続いたと述べる。", "を": "目的語の「を」は、自動詞「続く」と組まないので合わない。", "へ": "方向の「へ」は「熱気へ最後まで続いた」では意味が通らない。", "より": "比較の「より」は「熱気より最後まで続いた」と文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52871, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とてもあつい気持ちや、元気な感じのことです。", "primary_collocate": null, "pronunciation": "ねっき", "ipa": "nekːi", "syllable_count": 3, "sentences": [{"text": "祭りの夜、町は人々の熱気で明るく感じられた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "祭[まつ]りの夜[よる]、町[まち]は人々[ひとびと]の熱気[ねっき]で明[あか]るく感[かん]じられた。", "sentence_source": "generated"}, {"text": "子どもたちの熱気に、先生もつい笑顔になった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "子[こ]どもたちの熱気[ねっき]に、先生[せんせい]もつい笑顔[えがお]になった。", "sentence_source": "generated"}, {"text": "初めての大会に向けて、部員たちの熱気が高まっている。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "初[はじ]めての大会[たいかい]に向[む]けて、部員[ぶいん]たちの熱気[ねっき]が高[たか]まっている。", "sentence_source": "generated"}, {"text": "商店街のセールは、お客さんの熱気ですごいにぎわいだった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "商店街[しょうてんがい]のセールは、お客[きゃく]さんの熱気[ねっき]ですごいにぎわいだった。", "sentence_source": "generated"}, {"text": "彼女の熱気ある話し方に、みんな引きこまれた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の熱気[ねっき]ある話[はな]し方[かた]に、みんな引[ひ]きこまれた。", "sentence_source": "generated"}, {"text": "発表会が終わるころには、会場全体が熱気に満ちていた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "発表会[はっぴょうかい]が終[お]わるころには、会場[かいじょう]全体[ぜんたい]が熱気[ねっき]に満[み]ちていた。", "sentence_source": "generated"}, {"text": "新入生歓迎会は、先輩たちの熱気であふれていた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "新入生[しんにゅうせい]歓迎会[かんげいかい]は、先輩[せんぱい]たちの熱気[ねっき]であふれていた。", "sentence_source": "generated"}, {"text": "決勝戦の日、応援席の熱気は最後まで続いた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "決勝戦[けっしょうせん]の日[ひ]、応援席[おうえんせき]の熱気[ねっき]は最後[さいご]まで続[つづ]いた。", "sentence_source": "generated"}, {"text": "夢を語る若者たちの熱気が、店の中に広がった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "夢[ゆめ]を語[かた]る若者[わかもの]たちの熱気[ねっき]が、店[みせ]の中[なか]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "練習試合なのに、選手たちの熱気は本物の試合のようだった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "練習[れんしゅう]試合[じあい]なのに、選手[せんしゅ]たちの熱気[ねっき]は本物[ほんもの]の試合[しあい]のようだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱気", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人々の元気であつい気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52871, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熱気", "is_correct": true, "explanation": "人々の元気で熱い気持ちが町を明るく感じさせる、という文脈に合う。"}, {"text": "契約", "is_correct": false, "explanation": "取り決めの意味で、町を明るく感じさせる理由にならない。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序の意味で、人々の気持ちを表す語としては合わない。"}, {"text": "音階", "is_correct": false, "explanation": "音の高さの並びの意味で、町を明るくする理由にはならない。"}], "explanations": {"熱気": "人々の元気で熱い気持ちが町を明るく感じさせる、という文脈に合う。", "契約": "取り決めの意味で、町を明るく感じさせる理由にならない。", "手順": "作業の順序の意味で、人々の気持ちを表す語としては合わない。", "音階": "音の高さの並びの意味で、町を明るくする理由にはならない。"}, "sentence_index": 0, "correct_answer": "熱気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は熱気の教師で、生徒の相談に毎日乗っている。", "explanation": "ここは〈熱血〉（情熱的で一生懸命なさま）の意味。熱気は場の活気を指すので、人の性格を表す語には合わない。"}, {"text": "雨の熱気が強くなってきたので、傘をさした。", "explanation": "ここは〈勢い〉（力強く進む様子）の意味。熱気は人の気持ちや場の活気を指すので、雨脚の強さには使わない。"}, {"text": "やけどで熱気を負い、病院に行った。", "explanation": "ここは〈熱傷〉（やけどによる傷）の意味。熱気は活気や気持ちを表すので、傷には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52871, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熱気", "is_correct": true, "explanation": "先輩たちの熱い気持ちで会場がいっぱいになる、という文脈に合う。"}, {"text": "予算", "is_correct": false, "explanation": "お金の枠の意味で、あふれているという文に合わない。"}, {"text": "文法", "is_correct": false, "explanation": "言葉の仕組みの意味で、人であふれる文脈に合わない。"}, {"text": "相場", "is_correct": false, "explanation": "市場価格の意味で、先輩たちであふれるという文に合わない。"}], "explanations": {"熱気": "先輩たちの熱い気持ちで会場がいっぱいになる、という文脈に合う。", "予算": "お金の枠の意味で、あふれているという文に合わない。", "文法": "言葉の仕組みの意味で、人であふれる文脈に合わない。", "相場": "市場価格の意味で、先輩たちであふれるという文に合わない。"}, "sentence_index": 6, "correct_answer": "熱気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "やかんに水を入れ、熱気を沸かした。", "explanation": "ここは〈熱湯〉（沸いたお湯）の意味。熱気は活気を指し、沸かす対象にはならない。"}, {"text": "熱気の森には珍しい植物がたくさん生えている。", "explanation": "ここは〈熱帯〉（一年中暑い地域）の意味。熱気は活気を指し、地域や気候を表す語の代わりにはならない。"}, {"text": "二人は熱気の末に結婚した。", "explanation": "ここは〈熱愛〉（強く愛すること）の意味。熱気は場の活気を指し、恋愛の深い愛情には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52871, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝練の体育館には、部員たちの熱気をみなぎっていた。", "corrected_sentence": "朝練の体育館には、部員たちの熱気がみなぎっていた。", "error_description": "誤りは「熱気を」。「みなぎる」は「が」で主語を取るので、正しくは「熱気が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52871, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "初めての大会を前に、選手たちの熱気が静かに高めていった。", "corrected_sentence": "初めての大会を前に、選手たちの熱気が静かに高まっていった。", "error_description": "誤りは「高めていった」。熱気が主語の自動詞「高まる」が必要なので、正しくは「高まっていった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52872, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「包まれる」が取る「に」。熱気に包まれる、という形で自然につながる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」だが、「熱気が包まれていた」では受け身の形が不自然で、文が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、受け身の「包まれる」とは組まないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「包まれる」とは組まず、「熱気へ包まれていた」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「包まれる」が取る「に」。熱気に包まれる、という形で自然につながる。", "が": "主語の「が」だが、「熱気が包まれていた」では受け身の形が不自然で、文が通らない。", "を": "目的語の「を」は、受け身の「包まれる」とは組まないので合わない。", "へ": "方向の「へ」は「包まれる」とは組まず、「熱気へ包まれていた」では意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52872, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「は」。「会場の熱気は」が主題になり、冷めなかったと続く。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「冷めなかった」と合わず、「熱気から冷めなかった」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は「冷めなかった」の主語にならず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は名詞に続くだけで、「熱気の冷めなかった」と述語が続かない。"}], "correct_answer": "は", "explanations": {"は": "主題の「は」。「会場の熱気は」が主題になり、冷めなかったと続く。", "から": "起点の「から」は「冷めなかった」と合わず、「熱気から冷めなかった」は不自然。", "と": "並列の「と」は「冷めなかった」の主語にならず、文が成り立たない。", "の": "連体の「の」は名詞に続くだけで、「熱気の冷めなかった」と述語が続かない。"}, "error_tags": {"から": "起点", "と": "並列", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52872, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や物事の中にある、あつくて強い気持ちやエネルギー。", "primary_collocate": null, "pronunciation": "ねっき", "ipa": "nekːi", "syllable_count": 3, "sentences": [{"text": "雨の中でも、観客の熱気は少しも衰えなかった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "雨[あめ]の中[なか]でも、観客[かんきゃく]の熱気[ねっき]は少[すこ]しも衰[おとろ]えなかった。", "sentence_source": "generated"}, {"text": "試合開始の前から、スタジアムは観客の熱気に包まれていた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "試合[しあい]開始[かいし]の前[まえ]から、スタジアムは観客[かんきゃく]の熱気[ねっき]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "新しい店の開店日、行列の熱気に店員も驚いた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の開店日[かいてんび]、行列[ぎょうれつ]の熱気[ねっき]に店員[てんいん]も驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "選挙の演説会場には、候補者を応援する人々の熱気があふれていた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "選挙[せんきょ]の演説[えんぜつ]会場[かいじょう]には、候補者[こうほしゃ]を応援[おうえん]する人々[ひとびと]の熱気[ねっき]があふれていた。", "sentence_source": "generated"}, {"text": "彼の話しぶりには、聞く人を動かすほどの熱気があった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]しぶりには、聞[き]く人[ひと]を動[うご]かすほどの熱気[ねっき]があった。", "sentence_source": "generated"}, {"text": "議論が進むにつれて、会議室の熱気は高まっていった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "議論[ぎろん]が進[すす]むにつれて、会議室[かいぎしつ]の熱気[ねっき]は高[たか]まっていった。", "sentence_source": "generated"}, {"text": "文化祭の準備が始まると、教室は生徒たちの熱気でいっぱいになった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "文化祭[ぶんかさい]の準備[じゅんび]が始[はじ]まると、教室[きょうしつ]は生徒[せいと]たちの熱気[ねっき]でいっぱいになった。", "sentence_source": "generated"}, {"text": "コンサートが終わっても、会場の熱気はなかなか冷めなかった。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "コンサートが終[お]わっても、会場[かいじょう]の熱気[ねっき]はなかなか冷[さ]めなかった。", "sentence_source": "generated"}, {"text": "若い研究者たちの熱気に押されて、先生も新しい計画に賛成した。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "若[わか]い研究者[けんきゅうしゃ]たちの熱気[ねっき]に押[お]されて、先生[せんせい]も新[あたら]しい計画[けいかく]に賛成[さんせい]した。", "sentence_source": "generated"}, {"text": "熱気のこもった応援のおかげで、チームは最後まで走りぬいた。", "target_word": "熱気", "complexity_tier": "T3", "furigana": "熱気[ねっき]のこもった応援[おうえん]のおかげで、チームは最後[さいご]まで走[はし]りぬいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱気", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人や場に満ちる強い気持ちや活気", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52872, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熱気", "is_correct": true, "explanation": "観客の熱い気持ちを指し、雨の中でも衰えない様子に合う。"}, {"text": "予算", "is_correct": false, "explanation": "お金の枠の意味で、抗って記憶する対象にはならない。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとの意味で、熱さに抗った記憶という文脈に合わない。"}, {"text": "文法", "is_correct": false, "explanation": "言葉の仕組みの意味で、記憶の対象として文に合わない。"}], "explanations": {"熱気": "観客の熱い気持ちを指し、雨の中でも衰えない様子に合う。", "予算": "お金の枠の意味で、抗って記憶する対象にはならない。", "規則": "決まりごとの意味で、熱さに抗った記憶という文脈に合わない。", "文法": "言葉の仕組みの意味で、記憶の対象として文に合わない。"}, "sentence_index": 0, "correct_answer": "熱気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この食品は熱気が高く、ダイエット中は控えたい。", "explanation": "ここは〈熱量〉（食べ物のエネルギーの量）の意味。熱気は人や場の活気や気持ちを指すので、食品の熱量には使わない。"}, {"text": "ラーメンを作るため、鍋に熱気を注いだ。", "explanation": "ここは〈熱湯〉（沸いたお湯）の意味。熱気は人や場の活気を指し、鍋に注ぐ液体には使わない。"}, {"text": "彼は試合で熱気を燃やし、最後まで戦い抜いた。", "explanation": "ここは〈闘志〉（戦おうとする強い気持ち）の意味。熱気は場の活気を指し、燃やして戦う気力とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52872, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熱気", "is_correct": true, "explanation": "生徒たちの熱い気持ちで教室が満ちる、という文脈に合う。"}, {"text": "契約", "is_correct": false, "explanation": "取り決めの意味で、教室がいっぱいになるという文に合わない。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序の意味で、いっぱいになるものとして成り立たない。"}, {"text": "相場", "is_correct": false, "explanation": "市場価格の意味で、教室を満たすものとしては不自然。"}], "explanations": {"熱気": "生徒たちの熱い気持ちで教室が満ちる、という文脈に合う。", "契約": "取り決めの意味で、教室がいっぱいになるという文に合わない。", "手順": "作業の順序の意味で、いっぱいになるものとして成り立たない。", "相場": "市場価格の意味で、教室を満たすものとしては不自然。"}, "sentence_index": 6, "correct_answer": "熱気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "やけどで熱気を負い、一週間仕事を休んだ。", "explanation": "ここは〈熱傷〉（やけどによる傷）の意味。熱気は活気や気持ちを表すので、傷には使わない。"}, {"text": "熱気の島には珍しい鳥が多く、研究者が毎年訪れる。", "explanation": "ここは〈熱帯〉（一年中暑い地域）の意味。熱気は活気の意味で、地域や気候を表す語の代わりにはならない。"}, {"text": "彼は熱気で、困っている友人を放っておけない。", "explanation": "ここは〈熱血〉（情熱的で一生懸命なさま）の意味。熱気は場の活気を指し、人の性格を表す語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52872, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "入学式の会場には、保護者たちの熱気を静かに満ちていた。", "corrected_sentence": "入学式の会場には、保護者たちの熱気が静かに満ちていた。", "error_description": "誤りは「熱気を」。「満ちる」は「が」で主語を示す自動詞なので、正しくは「熱気が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52872, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゴールの瞬間、会場の熱気が一気に高めた。", "corrected_sentence": "ゴールの瞬間、会場の熱気が一気に高まった。", "error_description": "誤りは「高めた」。熱気が主語の自動詞「高まる」が必要なので、正しくは「高まった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52873, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「大きな会社に抗って」の「に」。抗う相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「会社を抗う」は不自然。抗うの相手は「に」で示す。"}, {"text": "で", "is_correct": false, "explanation": "「会社で抗う」は場所や手段を示し、抵抗の相手にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「会社へ抗う」は方向を示し、抵抗の対象を表せない。"}], "correct_answer": "に", "explanations": {"に": "「大きな会社に抗って」の「に」。抗う相手を示す。", "を": "「会社を抗う」は不自然。抗うの相手は「に」で示す。", "で": "「会社で抗う」は場所や手段を示し、抵抗の相手にはならない。", "へ": "「会社へ抗う」は方向を示し、抵抗の対象を表せない。"}, "error_tags": {"を": "対象", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52873, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「敵の大軍に抗う」の「に」。抗う相手を示す。"}, {"text": "から", "is_correct": false, "explanation": "「敵の大軍から抗う」は起点を示し、抵抗の相手を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「大軍を抗う」は誤り。「抗う」の相手は「に」で示す。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、抵抗の相手を示せない。"}], "correct_answer": "に", "explanations": {"に": "「敵の大軍に抗う」の「に」。抗う相手を示す。", "から": "「敵の大軍から抗う」は起点を示し、抵抗の相手を示せない。", "を": "「大軍を抗う」は誤り。「抗う」の相手は「に」で示す。", "より": "「より」は比較を示し、抵抗の相手を示せない。"}, "error_tags": {"から": "起点", "を": "対象", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52873, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "反対したり、戦ったりすること。", "primary_collocate": null, "pronunciation": "あらがう", "ipa": "aɾaɡaɯ", "syllable_count": 4, "sentences": [{"text": "国民は不当な命令に抗うことを決めた。", "target_word": "抗う", "complexity_tier": "T3", "furigana": "国民[こくみん]は不当[ふとう]な命令[めいれい]に抗[あらが]うことを決[き]めた。", "sentence_source": "generated"}, {"text": "小さな村は大きな会社に抗って、土地を守った。", "target_word": "抗って", "complexity_tier": "T3", "furigana": "小[ちい]さな村[むら]は大[おお]きな会社[かいしゃ]に抗[あらが]って、土地[とち]を守[まも]った。", "sentence_source": "generated"}, {"text": "弱い立場の人も、理不尽な扱いには抗っていいはずだ。", "target_word": "抗って", "complexity_tier": "T3", "furigana": "弱[よわ]い立場[たちば]の人[ひと]も、理不尽[りふじん]な扱[あつか]いには抗[あらが]っていいはずだ。", "sentence_source": "generated"}, {"text": "彼は周囲の反対に抗い、自分の夢を追い続けた。", "target_word": "抗い", "complexity_tier": "T3", "furigana": "彼[かれ]は周囲[しゅうい]の反対[はんたい]に抗[あらが]い、自分[じぶん]の夢[ゆめ]を追[お]い続[つづ]けた。", "sentence_source": "generated"}, {"text": "市民が抗わなければ、法律は変わらなかっただろう。", "target_word": "抗わ", "complexity_tier": "T3", "furigana": "市民[しみん]が抗[あらが]わなければ、法律[ほうりつ]は変[か]わらなかっただろう。", "sentence_source": "generated"}, {"text": "寒さに抗うように、子どもたちは雪の中を走りまわった。", "target_word": "抗う", "complexity_tier": "T3", "furigana": "寒[さむ]さに抗[あらが]うように、子[こ]どもたちは雪[ゆき]の中[なか]を走[はし]りまわった。", "sentence_source": "generated"}, {"text": "彼は上司の意見に抗えず、計画を変更した。", "target_word": "抗えず", "complexity_tier": "T3", "furigana": "彼[かれ]は上司[じょうし]の意見[いけん]に抗[あらが]えず、計画[けいかく]を変更[へんこう]した。", "sentence_source": "generated"}, {"text": "敵の大軍に抗う力は、もう残っていなかった。", "target_word": "抗う", "complexity_tier": "T3", "furigana": "敵[てき]の大軍[たいぐん]に抗[あらが]う力[ちから]は、もう残[のこ]っていなかった。", "sentence_source": "generated"}, {"text": "社員たちは給料の引き下げに抗って、話し合いを求めた。", "target_word": "抗って", "complexity_tier": "T3", "furigana": "社員[しゃいん]たちは給料[きゅうりょう]の引[ひ]き下[さ]げに抗[あらが]って、話[はな]し合[あ]いを求[もと]めた。", "sentence_source": "generated"}, {"text": "漁師たちは港の再開発計画に抗うため、集会を開いた。", "target_word": "抗う", "complexity_tier": "T3", "furigana": "漁師[りょうし]たちは港[みなと]の再開発[さいかいはつ]計画[けいかく]に抗[あらが]うため、集会[しゅうかい]を開[ひら]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗う", "label": "辞書形"}, {"form": "抗い", "label": "連用形"}, {"form": "抗わ", "label": "未然形"}, {"form": "抗え", "label": "可能・仮定形"}, {"form": "抗った", "label": "夕形"}, {"form": "抗って", "label": "テ形"}], "register": "neutral", "sense_fingerprint": "相手に反対して立ち向かう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52873, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗う", "is_correct": true, "explanation": "辞書形で「抗うことを決めた」と名詞化の「こと」に続く。"}, {"text": "抗い", "is_correct": false, "explanation": "連用形は「こと」に直接続かず、「抗いことを」は成り立たない。"}, {"text": "抗って", "is_correct": false, "explanation": "テ形は「こと」に続けられず、「抗ってことを」は不成立。"}, {"text": "抗え", "is_correct": false, "explanation": "可能・仮定・命令の形で、「こと」の前には置けない。"}], "explanations": {"抗う": "辞書形で「抗うことを決めた」と名詞化の「こと」に続く。", "抗い": "連用形は「こと」に直接続かず、「抗いことを」は成り立たない。", "抗って": "テ形は「こと」に続けられず、「抗ってことを」は不成立。", "抗え": "可能・仮定・命令の形で、「こと」の前には置けない。"}, "sentence_index": 0, "correct_answer": "抗う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は英語の文章を辞書で調べ、一語ずつ抗った。", "explanation": "ここは〈読む〉の意味。抗うは反対・抵抗の動詞で、文章を読み進める場面には使わない。"}, {"text": "子どもは雨の日、窓の外を眺めて抗った。", "explanation": "ここは〈見る〉の意味。抗うは反対・抵抗の動詞で、外の景色を見る場面には使わない。"}, {"text": "彼女は散らかった書類を一枚ずつ抗ってまとめた。", "explanation": "ここは〈片付ける〉の意味。抗うは力に反対する動詞で、書類を整理する場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52873, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗えず", "is_correct": true, "explanation": "「上司の意見に抗えず」と否定の連用形で、抵抗できなかった意味に合う。"}, {"text": "抗わ", "is_correct": false, "explanation": "未然形だけでは文が続かず、「抗わ、計画を変更した」は成り立たない。"}, {"text": "抗う", "is_correct": false, "explanation": "辞書形で文を終えられず、「抗う、彼は」は文の構造が崩れる。"}, {"text": "抗える", "is_correct": false, "explanation": "肯定の可能形で「抵抗できた」の意味になり、計画を変えた文脈と合わない。"}], "explanations": {"抗えず": "「上司の意見に抗えず」と否定の連用形で、抵抗できなかった意味に合う。", "抗わ": "未然形だけでは文が続かず、「抗わ、計画を変更した」は成り立たない。", "抗う": "辞書形で文を終えられず、「抗う、彼は」は文の構造が崩れる。", "抗える": "肯定の可能形で「抵抗できた」の意味になり、計画を変えた文脈と合わない。"}, "sentence_index": 6, "correct_answer": "抗えず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は新しい仕事に抗い、すぐに自信をつけた。", "explanation": "ここは〈挑む〉の意味。抗うは反対して押し返す動詞で、新しい仕事に取り組む場面には使わない。"}, {"text": "社長は重大な役目に抗い、丁寧にお礼を述べた。", "explanation": "ここは〈感謝する〉の意味。抗うは反対・抵抗の動詞で、ありがたく受ける場面には使わない。"}, {"text": "市民は新しい駅の開業に抗い、大勢で祝った。", "explanation": "ここは〈歓迎する〉の意味。抗うは反対する動詞で、開業を喜ぶ場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52873, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市民は不当な決定を抗うため、署名を集めた。", "corrected_sentence": "市民は不当な決定に抗うため、署名を集めた。", "error_description": "助詞の誤り。「抗う」の相手は「に」で示す。「決定を抗う」は誤りで、「決定に抗う」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "抗って", "is_correct": true, "explanation": "テ形で「大きな会社に抗って、土地を守った」と動作の並列を表す。"}, {"text": "抗わ", "is_correct": false, "explanation": "未然形は中止の「、」に続けられず、「抗わ、土地を守った」は成り立たない。"}, {"text": "抗った", "is_correct": false, "explanation": "夕形は文を完結させるため、「抗った、土地を守った」の並列には使えない。"}, {"text": "抗え", "is_correct": false, "explanation": "可能・仮定・命令の形で、過去の行動の並列には合わない。"}], "correct_form": "抗って", "base_form": "抗う", "form_label": "テ形", "sentence_index": 1, "explanations": {"抗って": "テ形で「大きな会社に抗って、土地を守った」と動作の並列を表す。", "抗わ": "未然形は中止の「、」に続けられず、「抗わ、土地を守った」は成り立たない。", "抗った": "夕形は文を完結させるため、「抗った、土地を守った」の並列には使えない。", "抗え": "可能・仮定・命令の形で、過去の行動の並列には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52873, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人は時代の波に抗いて、ひとり店を続けた。", "corrected_sentence": "老人は時代の波に抗って、ひとり店を続けた。", "error_description": "テ形の誤り。「抗う」のテ形は「抗って」で、「抗いて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "抗う", "is_correct": true, "explanation": "辞書形で「敵の大軍に抗う力」と名詞「力」を修飾する。"}, {"text": "抗わ", "is_correct": false, "explanation": "未然形のため名詞を修飾できず、「抗わ力」は成り立たない。"}, {"text": "抗って", "is_correct": false, "explanation": "テ形は名詞を修飾できず、「抗って力」は不自然。"}, {"text": "抗えず", "is_correct": false, "explanation": "否定の連用形で「抗えず力」と名詞を修飾できず、文の構造が崩れる。"}], "correct_form": "抗う", "base_form": "抗う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"抗う": "辞書形で「敵の大軍に抗う力」と名詞「力」を修飾する。", "抗わ": "未然形のため名詞を修飾できず、「抗わ力」は成り立たない。", "抗って": "テ形は名詞を修飾できず、「抗って力」は不自然。", "抗えず": "否定の連用形で「抗えず力」と名詞を修飾できず、文の構造が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52874, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「病気に抗う」の「に」。「抗う」は相手を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「病気を抗う」は不自然。「抗う」は「を」ではなく「に」で相手を示す。"}, {"text": "が", "is_correct": false, "explanation": "「病気が抗う」では病気が主語になり、人が抵抗する意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "「病気で抗う」は手段や場所を示すが、抵抗の相手を示せない。"}], "correct_answer": "に", "explanations": {"に": "「病気に抗う」の「に」。「抗う」は相手を「に」で示す。", "を": "「病気を抗う」は不自然。「抗う」は「を」ではなく「に」で相手を示す。", "が": "「病気が抗う」では病気が主語になり、人が抵抗する意味にならない。", "で": "「病気で抗う」は手段や場所を示すが、抵抗の相手を示せない。"}, "error_tags": {"を": "対象", "が": "主語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52874, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「敵に抗った」の「に」。抗う相手を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「敵へ抗った」は向かう方向を示すため、抵抗の相手を示す「に」の代わりにはならない。"}, {"text": "から", "is_correct": false, "explanation": "「敵から抗った」は起点を示し、抵抗の対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「敵の抗った」は名詞修飾になり、文の動詞との関係が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「敵に抗った」の「に」。抗う相手を示す。", "へ": "「敵へ抗った」は向かう方向を示すため、抵抗の相手を示す「に」の代わりにはならない。", "から": "「敵から抗った」は起点を示し、抵抗の対象を示せない。", "の": "「敵の抗った」は名詞修飾になり、文の動詞との関係が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52874, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "抵抗する。反抗する。逆らう。", "primary_collocate": null, "pronunciation": "あらがう", "ipa": "aɾaɡaɯ", "syllable_count": 4, "sentences": [{"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "抗った", "complexity_tier": "T5", "furigana": "深紅[しんく]とも、あるいは乾[かわ]いた血[ち]の色[いろ]とも形容[けいよう]すべきそのブーツは、もはや単[たん]なる履物[はきもの]という枠組[わくぐ]みを超[こ]え、私[わたし]の内面[ないめん]に潜[ひそ]む情動[じょうどう]を可視化[かしか]する媒体[ばいたい]となっているのだ。\n\n指先[ゆびさき]でなぞる革[かわ]の質感[しつかん]は、過[す]ぎ去[さ]りし季節[きせつ]の冷[つめ]たさと、それに抗[あらが]った熱気[ねっき]を同時[どうじ]に記憶[きおく]している。", "sentence_source": "mined"}, {"text": "彼は病気に抗うために、毎日リハビリを続けた。", "target_word": "抗う", "complexity_tier": "T3", "furigana": "彼[かれ]は病気[びょうき]に抗[あらが]うために、毎日[まいにち]リハビリを続[つづ]けた。", "sentence_source": "generated"}, {"text": "住民たちは工場の建設計画に抗って、署名を集めた。", "target_word": "抗って", "complexity_tier": "T3", "furigana": "住民[じゅうみん]たちは工場[こうじょう]の建設[けんせつ]計画[けいかく]に抗[あらが]って、署名[しょめい]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "人は老いに抗えないが、健康でいる努力はできる。", "target_word": "抗えない", "complexity_tier": "T3", "furigana": "人[ひと]は老[お]いに抗[あらが]えないが、健康[けんこう]でいる努力[どりょく]はできる。", "sentence_source": "generated"}, {"text": "強い風に抗いながら、登山者は頂上を目指した。", "target_word": "抗い", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]に抗[あらが]いながら、登山者[とざんしゃ]は頂上[ちょうじょう]を目指[めざ]した。", "sentence_source": "generated"}, {"text": "彼女は時代の流れに抗って、自分の道を選んだ。", "target_word": "抗って", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は時代[じだい]の流[なが]れに抗[あらが]って、自分[じぶん]の道[みち]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "眠気に抗えず、彼は会議の途中で目を閉じてしまった。", "target_word": "抗えず", "complexity_tier": "T3", "furigana": "眠気[ねむけ]に抗[あらが]えず、彼[かれ]は会議[かいぎ]の途中[とちゅう]で目[め]を閉[と]じてしまった。", "sentence_source": "generated"}, {"text": "兵士たちは最後まで敵に抗ったが、ついに城は落ちた。", "target_word": "抗った", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは最後[さいご]まで敵[てき]に抗[あらが]ったが、ついに城[しろ]は落[お]ちた。", "sentence_source": "generated"}, {"text": "運命に抗う主人公の姿が、観客の心を打った。", "target_word": "抗う", "complexity_tier": "T3", "furigana": "運命[うんめい]に抗[あらが]う主人公[しゅじんこう]の姿[すがた]が、観客[かんきゃく]の心[こころ]を打[う]った。", "sentence_source": "generated"}, {"text": "誘惑に抗うのは、思ったよりむずかしい。", "target_word": "抗う", "complexity_tier": "T3", "furigana": "誘惑[ゆうわく]に抗[あらが]うのは、思[おも]ったよりむずかしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗う", "label": "辞書形"}, {"form": "抗い", "label": "連用形"}, {"form": "抗わ", "label": "未然形"}, {"form": "抗え", "label": "可能・仮定形"}, {"form": "抗った", "label": "夕形"}, {"form": "抗って", "label": "テ形"}], "register": "neutral", "sense_fingerprint": "力や流れに逆らって抵抗する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52874, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗った", "is_correct": true, "explanation": "「それに抗った熱気」と過去の出来事として熱気を修飾する。文脈の過去の時制にも合う。"}, {"text": "抗い", "is_correct": false, "explanation": "連用形のままでは名詞「熱気」を修飾できず、「それに抗い熱気を」は文が成り立たない。"}, {"text": "抗って", "is_correct": false, "explanation": "テ形は名詞を直接修飾できない。「抗って熱気」では文の構造が崩れる。"}, {"text": "抗え", "is_correct": false, "explanation": "可能・仮定・命令の形で、名詞修飾には使えない。「抗え熱気」は不自然。"}], "explanations": {"抗った": "「それに抗った熱気」と過去の出来事として熱気を修飾する。文脈の過去の時制にも合う。", "抗い": "連用形のままでは名詞「熱気」を修飾できず、「それに抗い熱気を」は文が成り立たない。", "抗って": "テ形は名詞を直接修飾できない。「抗って熱気」では文の構造が崩れる。", "抗え": "可能・仮定・命令の形で、名詞修飾には使えない。「抗え熱気」は不自然。"}, "sentence_index": 0, "correct_answer": "抗った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は届いた荷物を一つずつ抗い、棚に収めた。", "explanation": "ここは〈整理する〉の意味。抗うは力に反対する動詞で、荷物を棚に収める場面には使わない。"}, {"text": "彼は初めての海外旅行に抗い、大いに楽しんだ。", "explanation": "ここは〈挑む〉の意味。抗うは相手の力に反対する動詞で、新しいことに進んで取り組む場面には使わない。"}, {"text": "彼は母の手作りの料理に抗い、ゆっくり味わった。", "explanation": "ここは〈味わう〉の意味。抗うは力や圧力に反対する動詞で、料理を味わう場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52874, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗えず", "is_correct": true, "explanation": "「眠気に抗えず」と否定の連用形で、抵抗できなかったという意味に合う。"}, {"text": "抗わ", "is_correct": false, "explanation": "未然形だけでは文が完結せず、「眠気に抗わ、」は成り立たない。"}, {"text": "抗う", "is_correct": false, "explanation": "辞書形で文を終えられず、「眠気に抗う、彼は」は文の構造が崩れる。"}, {"text": "抗える", "is_correct": false, "explanation": "肯定の可能形なので「抵抗できた」の意味になり、眠ってしまった文脈に合わない。"}], "explanations": {"抗えず": "「眠気に抗えず」と否定の連用形で、抵抗できなかったという意味に合う。", "抗わ": "未然形だけでは文が完結せず、「眠気に抗わ、」は成り立たない。", "抗う": "辞書形で文を終えられず、「眠気に抗う、彼は」は文の構造が崩れる。", "抗える": "肯定の可能形なので「抵抗できた」の意味になり、眠ってしまった文脈に合わない。"}, "sentence_index": 6, "correct_answer": "抗えず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い会議のあと、彼は資料に抗い、夜遅くまで机に向かった。", "explanation": "ここは〈検討する〉の意味。抗うは力や圧力に反対する動詞で、資料を検討する場面には使わない。"}, {"text": "彼女はその曲の高音部に抗い、すっかり覚えた。", "explanation": "ここは〈練習する〉の意味。抗うは押し返す動詞で、難しい部分を練習する場面には使わない。"}, {"text": "駅前の古い看板に抗って、彼は丁寧に磨いた。", "explanation": "ここは〈掃除する〉の意味。抗うは押し返す動詞で、看板を手入れする場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52874, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い風を抗いながら、登山者は頂上を目指した。", "corrected_sentence": "寒い風に抗いながら、登山者は頂上を目指した。", "error_description": "助詞の誤り。「抗う」が取る相手は「に」で示す。「寒い風を抗う」は誤りで、正しくは「寒い風に抗う」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "抗う", "is_correct": true, "explanation": "辞書形。「病気に抗うために」と目的を示す文脈に合う。"}, {"text": "抗わず", "is_correct": false, "explanation": "未然形＋「ず」の否定形で、「抗わずために」と続けると意味が通らない。"}, {"text": "抗えず", "is_correct": false, "explanation": "否定の連用形で「ために」に続かず、「抗えずために」は成り立たない。"}, {"text": "抗え", "is_correct": false, "explanation": "可能・仮定・命令の形で、「ために」の前には置けない。"}], "correct_form": "抗う", "base_form": "抗う", "form_label": "辞書形", "sentence_index": 1, "explanations": {"抗う": "辞書形。「病気に抗うために」と目的を示す文脈に合う。", "抗わず": "未然形＋「ず」の否定形で、「抗わずために」と続けると意味が通らない。", "抗えず": "否定の連用形で「ために」に続かず、「抗えずために」は成り立たない。", "抗え": "可能・仮定・命令の形で、「ために」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52874, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その若い選手は、強豪チームの攻撃に抗いて、勝利を手にした。", "corrected_sentence": "その若い選手は、強豪チームの攻撃に抗って、勝利を手にした。", "error_description": "テ形の誤り。「抗う」のテ形は「抗って」で、「抗いて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "抗った", "is_correct": true, "explanation": "夕形。「敵に抗ったが、城は落ちた」と過去の出来事を表す文脈に合う。"}, {"text": "抗わ", "is_correct": false, "explanation": "未然形のみでは「抗わが」と続けられず、過去の文として成立しない。"}, {"text": "抗わず", "is_correct": false, "explanation": "否定の連用形「抗わず」は抵抗しなかったことを表し、「最後まで」と矛盾する。"}, {"text": "抗える", "is_correct": false, "explanation": "可能形で「抵抗できる」の意味になり、敵に抗ったという事実と合わない。"}], "correct_form": "抗った", "base_form": "抗う", "form_label": "夕形", "sentence_index": 7, "explanations": {"抗った": "夕形。「敵に抗ったが、城は落ちた」と過去の出来事を表す文脈に合う。", "抗わ": "未然形のみでは「抗わが」と続けられず、過去の文として成立しない。", "抗わず": "否定の連用形「抗わず」は抵抗しなかったことを表し、「最後まで」と矛盾する。", "抗える": "可能形で「抵抗できる」の意味になり、敵に抗ったという事実と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
