INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52875, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "指で線を書くように、ものをそっとさわること。", "primary_collocate": null, "pronunciation": "なぞる", "ipa": "nazoɾɯ", "syllable_count": 3, "sentences": [{"text": "赤ちゃんの頬を、指でそっとなぞった。", "target_word": "なぞった", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの頬[ほお]を、指[ゆび]でそっとなぞった。", "sentence_source": "generated"}, {"text": "彼は窓ガラスの水滴を指でなぞった。", "target_word": "なぞった", "complexity_tier": "T3", "furigana": "彼[かれ]は窓[まど]ガラスの水滴[すいてき]を指[ゆび]でなぞった。", "sentence_source": "generated"}, {"text": "少女は曇った鏡に指で星の形をなぞった。", "target_word": "なぞった", "complexity_tier": "T3", "furigana": "少女[しょうじょ]は曇[くも]った鏡[かがみ]に指[ゆび]で星[ほし]の形[かたち]をなぞった。", "sentence_source": "generated"}, {"text": "母は古い写真の顔を、指先でやさしくなぞった。", "target_word": "なぞった", "complexity_tier": "T3", "furigana": "母[はは]は古[ふる]い写真[しゃしん]の顔[かお]を、指先[ゆびさき]でやさしくなぞった。", "sentence_source": "generated"}, {"text": "雪の積もった車の上を、指でなぞって線を描いた。", "target_word": "なぞって", "complexity_tier": "T3", "furigana": "雪[ゆき]の積[つ]もった車[くるま]の上[うえ]を、指[ゆび]でなぞって線[せん]を描[えが]いた。", "sentence_source": "generated"}, {"text": "彼は本の表紙の文字を指でなぞり、ゆっくり開いた。", "target_word": "なぞり", "complexity_tier": "T3", "furigana": "彼[かれ]は本[ほん]の表紙[ひょうし]の文字[もじ]を指[ゆび]でなぞり、ゆっくり開[ひら]いた。", "sentence_source": "generated"}, {"text": "机のほこりを指でなぞると、白い線ができた。", "target_word": "なぞる", "complexity_tier": "T3", "furigana": "机[つくえ]のほこりを指[ゆび]でなぞると、白[しろ]い線[せん]ができた。", "sentence_source": "generated"}, {"text": "彼女は恋人の手の傷あとを、そっとなぞった。", "target_word": "なぞった", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は恋人[こいびと]の手[て]の傷[きず]あとを、そっとなぞった。", "sentence_source": "generated"}, {"text": "祖父は木彫りの模様を、指で一つずつなぞって確かめた。", "target_word": "なぞって", "complexity_tier": "T3", "furigana": "祖父[そふ]は木彫[きぼ]りの模様[もよう]を、指[ゆび]で一[ひと]つずつなぞって確[たし]かめた。", "sentence_source": "generated"}, {"text": "眠る娘の眉を、指先でそっとなぞった。", "target_word": "なぞった", "complexity_tier": "T3", "furigana": "眠[ねむ]る娘[むすめ]の眉[まゆ]を、指先[ゆびさき]でそっとなぞった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "なぞる", "label": "辞書形"}, {"form": "なぞり", "label": "連用形"}, {"form": "なぞら", "label": "未然形"}, {"form": "なぞれ", "label": "可能・仮定形"}, {"form": "なぞった", "label": "夕形"}, {"form": "なぞって", "label": "テ形"}], "register": "neutral", "sense_fingerprint": "指でそっと線を描くようにさわる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52875, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "なぞった", "is_correct": true, "explanation": "夕形で「指でそっとなぞった」と過去の動作を文末で表す。"}, {"text": "なぞり", "is_correct": false, "explanation": "連用形は文を終えられず、「指でそっとなぞり。」は不完全な文になる。"}, {"text": "なぞら", "is_correct": false, "explanation": "未然形は文を完結できず、文脈に合わない。"}, {"text": "なぞれ", "is_correct": false, "explanation": "可能・仮定・命令の形で、過去の動作を表せない。"}], "explanations": {"なぞった": "夕形で「指でそっとなぞった」と過去の動作を文末で表す。", "なぞり": "連用形は文を終えられず、「指でそっとなぞり。」は不完全な文になる。", "なぞら": "未然形は文を完結できず、文脈に合わない。", "なぞれ": "可能・仮定・命令の形で、過去の動作を表せない。"}, "sentence_index": 0, "correct_answer": "なぞった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はエレベーターのボタンを指でなぞった。", "explanation": "ここは〈押す〉の意味。なぞるは線を描くように軽くさわる動作で、ボタンを押す場面には使わない。"}, {"text": "彼女は子どもの小さな手を力いっぱいなぞった。", "explanation": "ここは〈握る〉の意味。なぞるは軽く表面をたどる動作で、力いっぱい握る場面には使わない。"}, {"text": "少年は机をこぶしでなぞって、怒りを示した。", "explanation": "ここは〈叩く〉の意味。なぞるは指で軽くたどる動作で、こぶしで強く叩く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52875, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "なぞる", "is_correct": true, "explanation": "辞書形で「指でなぞると、白い線ができた」と条件の「と」に続く。"}, {"text": "なぞって", "is_correct": false, "explanation": "テ形は「と」に続けられず、「なぞってと」は成り立たない。"}, {"text": "なぞれ", "is_correct": false, "explanation": "命令形は「と」に続けられず、「なぞれと」は成り立たない。"}, {"text": "なぞらない", "is_correct": false, "explanation": "否定形で「なぞらないと」は意味が逆になり、白い線ができた結果と合わない。"}], "explanations": {"なぞる": "辞書形で「指でなぞると、白い線ができた」と条件の「と」に続く。", "なぞって": "テ形は「と」に続けられず、「なぞってと」は成り立たない。", "なぞれ": "命令形は「と」に続けられず、「なぞれと」は成り立たない。", "なぞらない": "否定形で「なぞらないと」は意味が逆になり、白い線ができた結果と合わない。"}, "sentence_index": 6, "correct_answer": "なぞる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は食卓の油汚れを布巾でなぞった。", "explanation": "ここは〈拭く〉の意味。なぞるは線や表面を指でたどる動作で、汚れを布で拭き取る場面には使わない。"}, {"text": "子どもは摘んだ花びらを指でなぞって、ポケットに入れた。", "explanation": "ここは〈ちぎる〉の意味。なぞるは表面をたどる動作で、花びらを指先でちぎり取る場面には使わない。"}, {"text": "少年はノートの間違いを消しゴムでなぞった。", "explanation": "ここは〈取り除く〉の意味。なぞるは表面をたどる動作で、間違いを消して取り除く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52875, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人は古い手紙の文字に指でそっとなぞった。", "corrected_sentence": "老人は古い手紙の文字を指でそっとなぞった。", "error_description": "助詞の誤り。「なぞる」の対象は「を」で示す。「文字に」は誤りで、「文字を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "なぞった", "is_correct": true, "explanation": "夕形で、窓ガラスの水滴をなぞった過去の動作に合う。"}, {"text": "なぞら", "is_correct": false, "explanation": "未然形は文を終えられず、「窓ガラスの水滴を指でなぞら。」は成り立たない。"}, {"text": "なぞれ", "is_correct": false, "explanation": "可能・仮定・命令の形で、過去の動作を表せない。"}, {"text": "なぞって", "is_correct": false, "explanation": "テ形は文を過去として完結させず、後続の文へつなぐ形になる。"}], "correct_form": "なぞった", "base_form": "なぞる", "form_label": "夕形", "sentence_index": 1, "explanations": {"なぞった": "夕形で、窓ガラスの水滴をなぞった過去の動作に合う。", "なぞら": "未然形は文を終えられず、「窓ガラスの水滴を指でなぞら。」は成り立たない。", "なぞれ": "可能・仮定・命令の形で、過去の動作を表せない。", "なぞって": "テ形は文を過去として完結させず、後続の文へつなぐ形になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52875, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは窓の霜を指でなぞりて、花の形を描いた。", "corrected_sentence": "子どもは窓の霜を指でなぞって、花の形を描いた。", "error_description": "テ形の誤り。「なぞる」のテ形は「なぞって」で、「なぞりて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "なぞった", "is_correct": true, "explanation": "夕形で「そっとなぞった」と過去の動作を表す。"}, {"text": "なぞらった", "is_correct": false, "explanation": "未然形に「た」は続かず、「なぞらった」は成り立たない。"}, {"text": "なぞれた", "is_correct": false, "explanation": "可能・仮定形に「た」は続かず、「なぞれた」は文法的に成り立たない。"}, {"text": "なぞりた", "is_correct": false, "explanation": "「なぞりた」は誤った形で、夕形は「なぞった」になる。"}], "correct_form": "なぞった", "base_form": "なぞる", "form_label": "夕形", "sentence_index": 7, "explanations": {"なぞった": "夕形で「そっとなぞった」と過去の動作を表す。", "なぞらった": "未然形に「た」は続かず、「なぞらった」は成り立たない。", "なぞれた": "可能・仮定形に「た」は続かず、「なぞれた」は文法的に成り立たない。", "なぞりた": "「なぞりた」は誤った形で、夕形は「なぞった」になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52876, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52876, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「机の傷をなぞりながら」の「を」。なぞる対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「傷でなぞる」は手段を示し、なぞる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「傷へなぞる」は方向を示し、なぞる対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「傷となぞる」は相手や並列を示し、なぞる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「机の傷をなぞりながら」の「を」。なぞる対象を示す。", "で": "「傷でなぞる」は手段を示し、なぞる対象を示せない。", "へ": "「傷へなぞる」は方向を示し、なぞる対象を示せない。", "と": "「傷となぞる」は相手や並列を示し、なぞる対象を示せない。"}, "error_tags": {"で": "手段", "へ": "方向", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52876, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "指やペンなどで、物の表面をたどるようにして動かすこと。また、文字や絵を写し取るようにしてなぞること。", "primary_collocate": null, "pronunciation": "なぞる", "ipa": "nazoɾɯ", "syllable_count": 3, "sentences": [{"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "なぞる", "complexity_tier": "T5", "furigana": "深紅[しんく]とも、あるいは乾[かわ]いた血[ち]の色[いろ]とも形容[けいよう]すべきそのブーツは、もはや単[たん]なる履物[はきもの]という枠組[わくぐ]みを超[こ]え、私[わたし]の内面[ないめん]に潜[ひそ]む情動[じょうどう]を可視化[かしか]する媒体[ばいたい]となっているのだ。\n\n指先[ゆびさき]でなぞる革[かわ]の質感[しつかん]は、過[す]ぎ去[さ]りし季節[きせつ]の冷[つめ]たさと、それに抗[あらが]った熱気[ねっき]を同時[どうじ]に記憶[きおく]している。", "sentence_source": "mined"}, {"text": "子どもは先生が書いた文字を、鉛筆でていねいになぞった。", "target_word": "なぞった", "complexity_tier": "T3", "furigana": "子[こ]どもは先生[せんせい]が書[か]いた文字[もじ]を、鉛筆[えんぴつ]でていねいになぞった。", "sentence_source": "generated"}, {"text": "地図の道を指でなぞりながら、目的地を探した。", "target_word": "なぞり", "complexity_tier": "T3", "furigana": "地図[ちず]の道[みち]を指[ゆび]でなぞりながら、目的地[もくてきち]を探[さが]した。", "sentence_source": "generated"}, {"text": "手本の線をなぞる練習で、字がきれいになった。", "target_word": "なぞる", "complexity_tier": "T3", "furigana": "手本[てほん]の線[せん]をなぞる練習[れんしゅう]で、字[じ]がきれいになった。", "sentence_source": "generated"}, {"text": "彼は絵の輪郭をペンでなぞって、下書きを完成させた。", "target_word": "なぞって", "complexity_tier": "T3", "furigana": "彼[かれ]は絵[え]の輪郭[りんかく]をペンでなぞって、下書[したが]きを完成[かんせい]させた。", "sentence_source": "generated"}, {"text": "古い石碑の文字を、指先でそっとなぞってみた。", "target_word": "なぞって", "complexity_tier": "T3", "furigana": "古[ふる]い石碑[せきひ]の文字[もじ]を、指先[ゆびさき]でそっとなぞってみた。", "sentence_source": "generated"}, {"text": "習字の時間に、薄く印刷された字をなぞる。", "target_word": "なぞる", "complexity_tier": "T3", "furigana": "習字[しゅうじ]の時間[じかん]に、薄[うす]く印刷[いんさつ]された字[じ]をなぞる。", "sentence_source": "generated"}, {"text": "彼女は机の傷を指でなぞりながら、昔を思い出した。", "target_word": "なぞり", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は机[つくえ]の傷[きず]を指[ゆび]でなぞりながら、昔[むかし]を思[おも]い出[だ]した。", "sentence_source": "generated"}, {"text": "透明な紙を重ねて、写真の線をなぞった。", "target_word": "なぞった", "complexity_tier": "T3", "furigana": "透明[とうめい]な紙[かみ]を重[かさ]ねて、写真[しゃしん]の線[せん]をなぞった。", "sentence_source": "generated"}, {"text": "絵本の図形を鉛筆でなぞり、ノートに写し取った。", "target_word": "なぞり", "complexity_tier": "T3", "furigana": "絵本[えほん]の図形[ずけい]を鉛筆[えんぴつ]でなぞり、ノートに写[うつ]し取[と]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "なぞる", "label": "辞書形"}, {"form": "なぞり", "label": "連用形"}, {"form": "なぞら", "label": "未然形"}, {"form": "なぞれ", "label": "可能・仮定形"}, {"form": "なぞった", "label": "夕形"}, {"form": "なぞって", "label": "テ形"}], "register": "neutral", "sense_fingerprint": "線や文字の上を指やペンでたどる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e26ec329-2fd3-4b2d-a749-fb0d50ea0e8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52876, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "なぞる", "is_correct": true, "explanation": "辞書形で「指先でなぞる革の質感」と名詞「質感」を修飾する。"}, {"text": "なぞり", "is_correct": false, "explanation": "連用形のままでは名詞を修飾できず、「指先でなぞり革」は成り立たない。"}, {"text": "なぞら", "is_correct": false, "explanation": "未然形は文を続けられず、名詞修飾にも使えない。"}, {"text": "なぞれ", "is_correct": false, "explanation": "可能・仮定・命令の形で、名詞を修飾する文脈には合わない。"}], "explanations": {"なぞる": "辞書形で「指先でなぞる革の質感」と名詞「質感」を修飾する。", "なぞり": "連用形のままでは名詞を修飾できず、「指先でなぞり革」は成り立たない。", "なぞら": "未然形は文を続けられず、名詞修飾にも使えない。", "なぞれ": "可能・仮定・命令の形で、名詞を修飾する文脈には合わない。"}, "sentence_index": 0, "correct_answer": "なぞる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は床を雑巾でなぞって、きれいにした。", "explanation": "ここは〈拭く〉の意味。なぞるは指やペンで線や表面をたどる動作で、雑巾で汚れを拭く場面には使わない。"}, {"text": "部屋が暑かったので、彼は窓を大きくなぞった。", "explanation": "ここは〈開ける〉の意味。なぞるは軽く表面をたどる動作で、窓を大きく開ける場面には使わない。"}, {"text": "大工は板の長さを巻き尺でなぞって測った。", "explanation": "ここは〈計量する〉の意味。なぞるは表面をたどる動作で、長さを数値で量る場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52876, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "なぞる", "is_correct": true, "explanation": "辞書形で「字をなぞる。」と習慣的な動作を文末で表す。"}, {"text": "なぞって", "is_correct": false, "explanation": "テ形は文を終えられず、「字をなぞって。」は不完全な文になる。"}, {"text": "なぞれた", "is_correct": false, "explanation": "可能・仮定形に「た」は続かず、文末に置けない。"}, {"text": "なぞらった", "is_correct": false, "explanation": "未然形に「た」は続かず、「なぞらった」は成り立たない。"}], "explanations": {"なぞる": "辞書形で「字をなぞる。」と習慣的な動作を文末で表す。", "なぞって": "テ形は文を終えられず、「字をなぞって。」は不完全な文になる。", "なぞれた": "可能・仮定形に「た」は続かず、文末に置けない。", "なぞらった": "未然形に「た」は続かず、「なぞらった」は成り立たない。"}, "sentence_index": 6, "correct_answer": "なぞる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は本棚の板を金づちでなぞった。", "explanation": "ここは〈叩く〉の意味。なぞるは指やペンで表面をたどる動作で、金づちで打つ場面には使わない。"}, {"text": "彼は呼び鈴のボタンを強くなぞった。", "explanation": "ここは〈押す〉の意味。なぞるは軽く線を描くようにさわる動作で、強く押す場面には使わない。"}, {"text": "先生は詩の一行を声に出してなぞった。", "explanation": "ここは〈読む〉の意味。なぞるは指やペンで表面をたどる動作で、声に出して読む場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52876, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は画面の地図に指でなぞった。", "corrected_sentence": "彼は画面の地図を指でなぞった。", "error_description": "助詞の誤り。「なぞる」の対象は「を」で示す。「地図に」は誤りで、「地図を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "なぞった", "is_correct": true, "explanation": "夕形で、子どもが文字をなぞった過去の動作に合う。"}, {"text": "なぞら", "is_correct": false, "explanation": "未然形は文を終えられず、「鉛筆でていねいになぞら。」は成り立たない。"}, {"text": "なぞれ", "is_correct": false, "explanation": "可能・仮定・命令の形で、過去の動作を表せない。"}, {"text": "なぞって", "is_correct": false, "explanation": "テ形は後続の動作へつなぐ形で、文を過去として完結させない。"}], "correct_form": "なぞった", "base_form": "なぞる", "form_label": "夕形", "sentence_index": 1, "explanations": {"なぞった": "夕形で、子どもが文字をなぞった過去の動作に合う。", "なぞら": "未然形は文を終えられず、「鉛筆でていねいになぞら。」は成り立たない。", "なぞれ": "可能・仮定・命令の形で、過去の動作を表せない。", "なぞって": "テ形は後続の動作へつなぐ形で、文を過去として完結させない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52876, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は窓の曇りを指でなぞらて、名前を書いた。", "corrected_sentence": "彼女は窓の曇りを指でなぞって、名前を書いた。", "error_description": "テ形の誤り。「なぞる」のテ形は「なぞって」で、「なぞらて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "なぞり", "is_correct": true, "explanation": "連用形で「指でなぞりながら」と同時の動作を表す。"}, {"text": "なぞる", "is_correct": false, "explanation": "辞書形には「ながら」が続かず、「なぞるながら」は成り立たない。"}, {"text": "なぞった", "is_correct": false, "explanation": "夕形で、同時進行の「ながら」とは合わない。"}, {"text": "なぞら", "is_correct": false, "explanation": "未然形で「ながら」に続けられず、文が成り立たない。"}], "correct_form": "なぞり", "base_form": "なぞる", "form_label": "連用形", "sentence_index": 7, "explanations": {"なぞり": "連用形で「指でなぞりながら」と同時の動作を表す。", "なぞる": "辞書形には「ながら」が続かず、「なぞるながら」は成り立たない。", "なぞった": "夕形で、同時進行の「ながら」とは合わない。", "なぞら": "未然形で「ながら」に続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa3cae0f-df1a-4a79-93d1-07e6acb50db3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52877, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「凌ぎになった」の「に」。「なる」の結果を示す形を作る。"}, {"text": "を", "is_correct": false, "explanation": "「凌ぎをなった」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「凌ぎへなった」は不自然で合わない。"}, {"text": "で", "is_correct": false, "explanation": "「凌ぎでなった」は成り立たない。手段の「で」は「なる」とは続かない。"}], "correct_answer": "に", "explanations": {"に": "「凌ぎになった」の「に」。「なる」の結果を示す形を作る。", "を": "「凌ぎをなった」は文として成り立たない。", "へ": "「へ」は方向を示すが、「凌ぎへなった」は不自然で合わない。", "で": "「凌ぎでなった」は成り立たない。手段の「で」は「なる」とは続かない。"}, "error_tags": {"を": "対象", "へ": "方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52877, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「凌ぎに」の「に」。凌ぎが何のための手段かを示す。"}, {"text": "を", "is_correct": false, "explanation": "「凌ぎを」は目的語を示すが、ここでは手段を示す「に」が必要。"}, {"text": "と", "is_correct": false, "explanation": "「凌ぎと」は並列の意味になり、文の流れに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示すが、凌ぎは到達先ではないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「凌ぎに」の「に」。凌ぎが何のための手段かを示す。", "を": "「凌ぎを」は目的語を示すが、ここでは手段を示す「に」が必要。", "と": "「凌ぎと」は並列の意味になり、文の流れに合わない。", "へ": "「へ」は向かう先を示すが、凌ぎは到達先ではないので合わない。"}, "error_tags": {"を": "対象", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52877, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "寒いのをがまんするための、ちょっとした方法。", "primary_collocate": null, "pronunciation": "しのぎ", "ipa": "ɕinoɡi", "syllable_count": 3, "sentences": [{"text": "冬の朝、新聞紙を服の中に入れて、寒さの凌ぎにした。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]、新聞紙[しんぶんし]を服[ふく]の中[なか]に入[い]れて、寒[さむ]さの凌[しの]ぎにした。", "sentence_source": "generated"}, {"text": "古い毛布は、キャンプの夜の寒さの凌ぎになった。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "古[ふる]い毛布[もうふ]は、キャンプの夜[よる]の寒[さむ]さの凌[しの]ぎになった。", "sentence_source": "generated"}, {"text": "暖房が壊れたので、お湯を入れたペットボトルを抱えて寝て、それを寒さの凌ぎにした。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "暖房[だんぼう]が壊[こわ]れたので、お湯[ゆ]を入[い]れたペットボトルを抱[かか]えて寝[ね]て、それを寒[さむ]さの凌[しの]ぎにした。", "sentence_source": "generated"}, {"text": "祖母は寒さの凌ぎに、いつも厚い靴下を二枚重ねて履く。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "祖母[そぼ]は寒[さむ]さの凌[しの]ぎに、いつも厚[あつ]い靴下[くつした]を二枚[にまい]重[かさ]ねて履[は]く。", "sentence_source": "generated"}, {"text": "熱いお茶は、ほんの寒さの凌ぎのつもりだったが、体がよく温まった。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "熱[あつ]いお茶[ちゃ]は、ほんの寒[さむ]さの凌[しの]ぎのつもりだったが、体[からだ]がよく温[あたた]まった。", "sentence_source": "generated"}, {"text": "山小屋では、焚き火が何よりの寒さの凌ぎだった。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "山小屋[やまごや]では、焚[た]き火[び]が何[なに]よりの寒[さむ]さの凌[しの]ぎだった。", "sentence_source": "generated"}, {"text": "駅のホームで電車を待つあいだ、足踏みをして寒さの凌ぎにした。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "駅[えき]のホームで電車[でんしゃ]を待[ま]つあいだ、足踏[あしぶ]みをして寒[さむ]さの凌[しの]ぎにした。", "sentence_source": "generated"}, {"text": "彼は寒さの凌ぎにコートの襟を立てて歩いた。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "彼[かれ]は寒[さむ]さの凌[しの]ぎにコートの襟[えり]を立[た]てて歩[ある]いた。", "sentence_source": "generated"}, {"text": "窓にビニールを張るのは、昔から使われてきた寒さの凌ぎだ。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "窓[まど]にビニールを張[は]るのは、昔[むかし]から使[つか]われてきた寒[さむ]さの凌[しの]ぎだ。", "sentence_source": "generated"}, {"text": "犬小屋にわらを敷くのは、犬の寒さの凌ぎになるからだ。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "犬小屋[いぬごや]にわらを敷[し]くのは、犬[いぬ]の寒[さむ]さの凌[しの]ぎになるからだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凌ぎ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "寒さをがまんするための手軽な工夫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52877, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凌ぎ", "is_correct": true, "explanation": "「寒さの＿にした」に入り、寒さをがまんする工夫の意味になる。"}, {"text": "日焼け", "is_correct": false, "explanation": "日光で肌が焼けることで、寒さをしのぐ工夫の意味にはならない。"}, {"text": "大掃除", "is_correct": false, "explanation": "家を大きく掃除する行事で、寒さをしのぐ工夫の意味にはならない。"}, {"text": "地図", "is_correct": false, "explanation": "道を示す図で、「寒さの＿にした」という形には入らない。"}], "explanations": {"凌ぎ": "「寒さの＿にした」に入り、寒さをがまんする工夫の意味になる。", "日焼け": "日光で肌が焼けることで、寒さをしのぐ工夫の意味にはならない。", "大掃除": "家を大きく掃除する行事で、寒さをしのぐ工夫の意味にはならない。", "地図": "道を示す図で、「寒さの＿にした」という形には入らない。"}, "sentence_index": 0, "correct_answer": "凌ぎ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い日は、凌ぎを一年分まとめて買い込んだ。", "explanation": "ここは〈防寒グッズ〉の意味。〈凌ぎ〉は寒さをしのぐ工夫で、買える品物は指さないので合わない。"}, {"text": "その刀の凌ぎは、朝日を受けて鋭く光った。", "explanation": "ここは〈刀の稜線〉の意味。〈凌ぎ〉は寒さをしのぐ工夫で、刀の稜線は指さないので合わない。"}, {"text": "寒い日は、凌ぎをはめて指先を守った。", "explanation": "ここは〈手袋〉の意味。〈凌ぎ〉は身につける物ではなく工夫を指すので、「はめて」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52877, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凌ぎ", "is_correct": true, "explanation": "「寒さの＿にした」に入り、寒さをがまんする工夫の意味になる。"}, {"text": "目覚まし", "is_correct": false, "explanation": "朝に鳴らして起こす道具で、寒さをしのぐ工夫の意味にはならない。"}, {"text": "旅行", "is_correct": false, "explanation": "遠くへ出かけることで、寒さをしのぐ工夫の意味にはならない。"}, {"text": "郵便", "is_correct": false, "explanation": "物を届ける仕組みの語で、「寒さの＿にした」という形には入らない。"}], "explanations": {"凌ぎ": "「寒さの＿にした」に入り、寒さをがまんする工夫の意味になる。", "目覚まし": "朝に鳴らして起こす道具で、寒さをしのぐ工夫の意味にはならない。", "旅行": "遠くへ出かけることで、寒さをしのぐ工夫の意味にはならない。", "郵便": "物を届ける仕組みの語で、「寒さの＿にした」という形には入らない。"}, "sentence_index": 6, "correct_answer": "凌ぎ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い朝、凌ぎを一皿に盛って家族に出した。", "explanation": "ここは〈料理〉の意味。〈凌ぎ〉は寒さをしのぐ工夫で、料理として皿に盛る物ではない。"}, {"text": "職人の凌ぎのおかげで、暖炉は一日で完成した。", "explanation": "ここは〈技術〉の意味。〈凌ぎ〉は寒さを一時しのぐ工夫で、職人の腕前や技術は指さないので合わない。"}, {"text": "光熱費を節約するため、暖房の凌ぎを減らした。", "explanation": "ここは〈防寒具〉の意味。〈凌ぎ〉は寒さをしのぐ工夫で、身につける防寒具を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52877, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜、古い毛布で寒さの凌ぎを食べた。", "corrected_sentence": "寒い夜、古い毛布で寒さの凌ぎにした。", "error_description": "「凌ぎ」は食べ物ではないので「食べた」とは組み合わない。正しくは「凌ぎにした」（「を食べた」を「にした」に）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52877, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は寒い朝、寒さの凌ぎを手袋をはめて歩いた。", "corrected_sentence": "彼は寒い朝、寒さの凌ぎに手袋をはめて歩いた。", "error_description": "「凌ぎ」は「寒さの凌ぎに」の形で手段を表すため、続く助詞は「に」。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52878, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「凌ぎに」の「に」。凌ぎが何のための手段かを示す。"}, {"text": "を", "is_correct": false, "explanation": "「凌ぎを」は目的語を示すが、ここでは「なった」の前に目的を示す「に」が必要。"}, {"text": "と", "is_correct": false, "explanation": "「凌ぎと」は並列になり、なめた物が二つに分かれて文が不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示すが、凌ぎは到達先ではないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「凌ぎに」の「に」。凌ぎが何のための手段かを示す。", "を": "「凌ぎを」は目的語を示すが、ここでは「なった」の前に目的を示す「に」が必要。", "と": "「凌ぎと」は並列になり、なめた物が二つに分かれて文が不自然。", "へ": "「へ」は向かう先を示すが、凌ぎは到達先ではないので合わない。"}, "error_tags": {"を": "対象", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52878, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「凌ぎに」の「に」。凌ぎが何のための手段かを示す。"}, {"text": "が", "is_correct": false, "explanation": "「凌ぎが」は主語になり、食べたのは凌ぎではなく人なので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「凌ぎと」は並列になり、食べた物が二つに分かれて文が不自然。"}, {"text": "より", "is_correct": false, "explanation": "「凌ぎより」は比較の意味になり、「食べた」の理由が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「凌ぎに」の「に」。凌ぎが何のための手段かを示す。", "が": "「凌ぎが」は主語になり、食べたのは凌ぎではなく人なので合わない。", "と": "「凌ぎと」は並列になり、食べた物が二つに分かれて文が不自然。", "より": "「凌ぎより」は比較の意味になり、「食べた」の理由が成り立たない。"}, "error_tags": {"が": "主語", "より": "比較", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52878, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "困難や苦しみを一時的にしのぐこと。また、そのための手段。", "primary_collocate": null, "pronunciation": "しのぎ", "ipa": "ɕinoɡi", "syllable_count": 3, "sentences": [{"text": "私がこの赤い靴を履くという行為は、決して寒さ凌ぎの方便ではない。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "私[わたし]がこの赤[あか]い靴[くつ]を履[は]くという行為[こうい]は、決[けっ]して寒[さむ]さ凌[しの]ぎの方便[ほうべん]ではない。", "sentence_source": "mined"}, {"text": "朝ごはんを食べていなかったので、空腹の凌ぎにアメをなめた。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんを食[た]べていなかったので、空腹[くうふく]の凌[しの]ぎにアメをなめた。", "sentence_source": "generated"}, {"text": "この修理は急場の凌ぎにすぎないから、また雨が降ったら水が漏れるだろう。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "この修理[しゅうり]は急場[きゅうば]の凌[しの]ぎにすぎないから、また雨[あめ]が降[ふ]ったら水[みず]が漏[も]れるだろう。", "sentence_source": "generated"}, {"text": "ボーナスが出るまでは、短いアルバイトで当座の凌ぎにするつもりだ。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "ボーナスが出[で]るまでは、短[みじか]いアルバイトで当座[とうざ]の凌[しの]ぎにするつもりだ。", "sentence_source": "generated"}, {"text": "言い訳はその場の凌ぎにすぎないので、先生は納得しないだろう。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "言い訳[いいわけ]はその場[ば]の凌[しの]ぎにすぎないので、先生[せんせい]は納得[なっとく]しないだろう。", "sentence_source": "generated"}, {"text": "橋の下は、雨風の凌ぎにはなるが、長く住める場所ではない。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "橋[はし]の下[した]は、雨風[あめかぜ]の凌[しの]ぎにはなるが、長[なが]く住[す]める場所[ばしょ]ではない。", "sentence_source": "generated"}, {"text": "この薬は痛みを抑えるだけの凌ぎで、病気が治るわけではない。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "この薬[くすり]は痛[いた]みを抑[おさ]えるだけの凌[しの]ぎで、病気[びょうき]が治[なお]るわけではない。", "sentence_source": "generated"}, {"text": "夏の暑さの凌ぎに、公園の木陰でかき氷を食べた。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]さの凌[しの]ぎに、公園[こうえん]の木陰[こかげ]でかき氷[ごおり]を食[た]べた。", "sentence_source": "generated"}, {"text": "退屈の凌ぎに、マンガを読んで雨の午後を過ごした。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "退屈[たいくつ]の凌[しの]ぎに、マンガを読[よ]んで雨[あめ]の午後[ごご]を過[す]ごした。", "sentence_source": "generated"}, {"text": "この対策は一時の凌ぎにすぎず、根本的な解決が必要だ。", "target_word": "凌ぎ", "complexity_tier": "T3", "furigana": "この対策[たいさく]は一時[いっとき]の凌[しの]ぎにすぎず、根本的[こんぽんてき]な解決[かいけつ]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凌ぎ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "困難や苦しみを一時的にやり過ごすこと、またその手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52878, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凌ぎ", "is_correct": true, "explanation": "「寒さ＿の方便」に入り、寒さをしのぐ手段という意味になる。"}, {"text": "靴下", "is_correct": false, "explanation": "身につける物であり、寒さをしのぐ手段の意味にはならない。"}, {"text": "晴天", "is_correct": false, "explanation": "天気の状態を表す語で、手段の意味にはならない。"}, {"text": "地図", "is_correct": false, "explanation": "道を示す図の語で、「寒さ＿の方便」という形には入らない。"}], "explanations": {"凌ぎ": "「寒さ＿の方便」に入り、寒さをしのぐ手段という意味になる。", "靴下": "身につける物であり、寒さをしのぐ手段の意味にはならない。", "晴天": "天気の状態を表す語で、手段の意味にはならない。", "地図": "道を示す図の語で、「寒さ＿の方便」という形には入らない。"}, "sentence_index": 0, "correct_answer": "凌ぎ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は新しい凌ぎを開発して、大きな利益を上げた。", "explanation": "ここは〈製品〉の意味。〈凌ぎ〉は困難をしのぐ一時の手段で、開発して売る品物を指さないので合わない。"}, {"text": "その刀の凌ぎは、朝日を受けて鋭く光った。", "explanation": "ここは〈刀の稜線〉の意味。〈凌ぎ〉は困難をしのぐ一時の手段で、刀の稜線は指さないので合わない。"}, {"text": "その問題は、凌ぎによって完全に解決された。", "explanation": "ここは〈根治〉の意味。〈凌ぎ〉は一時のしのぎで、問題を根本から治すことはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52878, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凌ぎ", "is_correct": true, "explanation": "「抑えるだけの＿で」に入り、痛みをしのぐ一時的な手段の意味になる。"}, {"text": "気温", "is_correct": false, "explanation": "温度の状態を表す語で、手段の意味にはならない。"}, {"text": "手袋", "is_correct": false, "explanation": "身につける物で、痛みを抑える手段という意味にはならない。"}, {"text": "郵便", "is_correct": false, "explanation": "物を届ける仕組みの語で、ここに入ると文が成り立たない。"}], "explanations": {"凌ぎ": "「抑えるだけの＿で」に入り、痛みをしのぐ一時的な手段の意味になる。", "気温": "温度の状態を表す語で、手段の意味にはならない。", "手袋": "身につける物で、痛みを抑える手段という意味にはならない。", "郵便": "物を届ける仕組みの語で、ここに入ると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "凌ぎ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二社は新商品の開発で、凌ぎを削って競い合った。", "explanation": "ここは〈競争〉の意味（「凌ぎを削る」の慣用）。〈凌ぎ〉は苦しみをしのぐ手段で、競う意味はないので合わない。"}, {"text": "その凌ぎで、彼らは長年の夢を叶えた。", "explanation": "ここは〈目標〉の意味。〈凌ぎ〉は困難をしのぐための手段で、夢の達成という目標を表す語ではない。"}, {"text": "この凌ぎで、会議の議題はすべて片付いた。", "explanation": "ここは〈結論〉の意味。〈凌ぎ〉は一時の間に合わせで、議題を最終的に結論づける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52878, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この毛布は、寒さの凌ぐになった。", "corrected_sentence": "この毛布は、寒さの凌ぎになった。", "error_description": "「凌ぐ」は動詞なので、名詞の「凌ぎ」が入る場所に動詞の形が入っている。正しくは「寒さの凌ぎになった」（「ぐ」を「ぎ」に）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52878, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の暑さの凌ぎを、川辺で冷たいスイカを食べた。", "corrected_sentence": "夏の暑さの凌ぎに、川辺で冷たいスイカを食べた。", "error_description": "「凌ぎ」は「〜の凌ぎに」の形で手段を表すため、続く助詞は「に」。「を」は誤り（正しくは「凌ぎに」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52879, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「長靴を履いて」の「を」。履くの目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「長靴に履いて」は誤り。履くは靴を目的語に取るので「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「長靴が履いて」は主語として不自然で、文に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「長靴で履いて」は手段の意味にならず、文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「長靴を履いて」の「を」。履くの目的語を示す。", "に": "「長靴に履いて」は誤り。履くは靴を目的語に取るので「を」が正しい。", "が": "「長靴が履いて」は主語として不自然で、文に合わない。", "で": "「長靴で履いて」は手段の意味にならず、文に合わない。"}, "error_tags": {"に": "方向・対象", "が": "主語", "で": "手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱ぐ", "is_correct": true, "explanation": "「履く」の対義語。足に身につけた物を外す動作で、はくと対になる。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の動作で、履くの対義語ではない。"}, {"text": "結ぶ", "is_correct": false, "explanation": "ひもを締める動作で、履くの対義語ではない。"}, {"text": "磨く", "is_correct": false, "explanation": "表面をきれいにする動作で、履くの対義語ではない。"}], "correct_answer": "脱ぐ", "explanations": {"脱ぐ": "「履く」の対義語。足に身につけた物を外す動作で、はくと対になる。", "歩く": "移動の動作で、履くの対義語ではない。", "結ぶ": "ひもを締める動作で、履くの対義語ではない。", "磨く": "表面をきれいにする動作で、履くの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52879, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「サンダルを履いて」の「を」。履くの目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「サンダルへ履いて」は方向を示し、履く対象を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「サンダルと履いて」は並列の意味になり、履く対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「サンダルより履いて」は比較の意味になり、文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「サンダルを履いて」の「を」。履くの目的語を示す。", "へ": "「サンダルへ履いて」は方向を示し、履く対象を示せないので合わない。", "と": "「サンダルと履いて」は並列の意味になり、履く対象を示せない。", "より": "「サンダルより履いて」は比較の意味になり、文に合わない。"}, "error_tags": {"へ": "方向", "と": "並列", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱ぐ", "is_correct": true, "explanation": "「履く」の対義語。足に身につけた物を外す動作で、はくと対になる。"}, {"text": "走る", "is_correct": false, "explanation": "移動の動作で、履くの対義語ではない。"}, {"text": "乾かす", "is_correct": false, "explanation": "濡れた物を乾燥させる動作で、履くの対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "休息の状態を表す動詞で、履くの対義語ではない。"}], "correct_answer": "脱ぐ", "explanations": {"脱ぐ": "「履く」の対義語。足に身につけた物を外す動作で、はくと対になる。", "走る": "移動の動作で、履くの対義語ではない。", "乾かす": "濡れた物を乾燥させる動作で、履くの対義語ではない。", "眠る": "休息の状態を表す動詞で、履くの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52879, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "足に、くつやくつしたなどをはくこと。", "primary_collocate": null, "pronunciation": "はく", "ipa": "hakɯ", "syllable_count": 2, "sentences": [{"text": "運動会の朝、新しい白い靴を履いて学校へ行った。", "target_word": "履いて", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の朝[あさ]、新[あたら]しい白[しろ]い靴[くつ]を履[は]いて学校[がっこう]へ行[い]った。", "sentence_source": "generated"}, {"text": "妹は赤い長靴を履いて、水たまりで遊んでいる。", "target_word": "履いて", "complexity_tier": "T3", "furigana": "妹[いもうと]は赤[あか]い長靴[ながぐつ]を履[は]いて、水[みず]たまりで遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "雪の日は、すべらない靴を履くようにしている。", "target_word": "履く", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、すべらない靴[くつ]を履[は]くようにしている。", "sentence_source": "generated"}, {"text": "家に入るときは、靴を脱いでスリッパを履く。", "target_word": "履く", "complexity_tier": "T3", "furigana": "家[いえ]に入[はい]るときは、靴[くつ]を脱[ぬ]いでスリッパを履[は]く。", "sentence_source": "generated"}, {"text": "祖父は毎朝、靴下を履いてから散歩に出る。", "target_word": "履いて", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎朝[まいあさ]、靴下[くつした]を履[は]いてから散歩[さんぽ]に出[で]る。", "sentence_source": "generated"}, {"text": "靴のひもを結ばずに履くと、すぐに脱げてしまう。", "target_word": "履く", "complexity_tier": "T3", "furigana": "靴[くつ]のひもを結[むす]ばずに履[は]くと、すぐに脱[ぬ]げてしまう。", "sentence_source": "generated"}, {"text": "彼女はヒールの高い靴を履いて、駅まで急いだ。", "target_word": "履いて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はヒールの高[たか]い靴[くつ]を履[は]いて、駅[えき]まで急[いそ]いだ。", "sentence_source": "generated"}, {"text": "素足でサンダルを履いて、海辺を歩いた。", "target_word": "履いて", "complexity_tier": "T3", "furigana": "素足[すあし]でサンダルを履[は]いて、海辺[うみべ]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "小さくなった靴は、もう履けない。", "target_word": "履けない", "complexity_tier": "T3", "furigana": "小[ちい]さくなった靴[くつ]は、もう履[は]けない。", "sentence_source": "generated"}, {"text": "父は仕事用の黒い靴をていねいに磨いてから履く。", "target_word": "履く", "complexity_tier": "T3", "furigana": "父[ちち]は仕事用[しごとよう]の黒[くろ]い靴[くつ]をていねいに磨[みが]いてから履[は]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "履く", "label": "終止形"}, {"form": "履き", "label": "連用形"}, {"form": "履いて", "label": "て形"}, {"form": "履いた", "label": "過去形"}, {"form": "履かない", "label": "否定形"}, {"form": "履けば", "label": "仮定形"}, {"form": "履ける", "label": "可能形"}, {"form": "履こう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "足にくつやくつしたなどをはくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52879, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "履いて", "is_correct": true, "explanation": "て形で「新しい白い靴を＿学校へ行った」につながる。"}, {"text": "履いた", "is_correct": false, "explanation": "過去形は「靴を履いた学校へ行った」と名詞修飾になり、文意が通らない。"}, {"text": "履ける", "is_correct": false, "explanation": "可能形は「靴を履ける学校へ行った」と名詞修飾になり、意味が通らない。"}, {"text": "履こう", "is_correct": false, "explanation": "意志形は後ろに続かず、文が成り立たない。"}], "explanations": {"履いて": "て形で「新しい白い靴を＿学校へ行った」につながる。", "履いた": "過去形は「靴を履いた学校へ行った」と名詞修飾になり、文意が通らない。", "履ける": "可能形は「靴を履ける学校へ行った」と名詞修飾になり、意味が通らない。", "履こう": "意志形は後ろに続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "履いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い日は、マフラーを履いて出かける。", "explanation": "ここは〈巻く〉の意味。マフラーは首に巻く物で、履くは足にはく物に使う。"}, {"text": "寒い朝は、帽子を履いて出かける。", "explanation": "ここは〈被る〉の意味。帽子は頭に被る物で、履くは足にはく物に使う。"}, {"text": "寒い日は、手袋を履いて出かける。", "explanation": "ここは〈はめる〉の意味。手袋は手にはめる物で、足にはく物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52879, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "履いて", "is_correct": true, "explanation": "て形で「ヒールの高い靴を＿、駅まで急いだ」につながる。"}, {"text": "履く", "is_correct": false, "explanation": "終止形は後ろの「駅まで急いだ」と続かず、文が成り立たない。"}, {"text": "履け", "is_correct": false, "explanation": "命令形は文の流れに合わず、成り立たない。"}, {"text": "履けば", "is_correct": false, "explanation": "仮定形は「〜ば、駅まで急いだ」と条件になり、文意が通らない。"}], "explanations": {"履いて": "て形で「ヒールの高い靴を＿、駅まで急いだ」につながる。", "履く": "終止形は後ろの「駅まで急いだ」と続かず、文が成り立たない。", "履け": "命令形は文の流れに合わず、成り立たない。", "履けば": "仮定形は「〜ば、駅まで急いだ」と条件になり、文意が通らない。"}, "sentence_index": 6, "correct_answer": "履いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は毎朝、靴ひもを履いてから出かける。", "explanation": "ここは〈結ぶ〉の意味。靴ひもは足にはく物ではなく、履くは使えない。"}, {"text": "彼女は式のために、指輪を履いて出かけた。", "explanation": "ここは〈はめる〉の意味。指輪は指にはめる物で、足にはく物ではない。"}, {"text": "父は毎朝、腕時計を履いてから出勤する。", "explanation": "ここは〈つける〉の意味。腕時計は腕につける物で、足にはく物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52879, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、長靴を履くで出かけた。", "corrected_sentence": "雨の日は、長靴を履いて出かけた。", "error_description": "後ろの動詞につなぐには、て形の「履いて」にする必要がある。正しくは「履いて」（「くで」を「いて」に）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "履いて", "is_correct": true, "explanation": "て形で、後ろの「遊んでいる」につながる正しい形。"}, {"text": "履かない", "is_correct": false, "explanation": "否定形は「はかないで遊ぶ」の意味になり、文の内容に合わない。"}, {"text": "履ける", "is_correct": false, "explanation": "可能形で、「はける」の意味になり文の意味が変わる。"}, {"text": "履こう", "is_correct": false, "explanation": "意志形は「遊んでいる」の前に続かず、文に合わない。"}], "correct_form": "履いて", "base_form": "履く", "form_label": "て形", "sentence_index": 1, "explanations": {"履いて": "て形で、後ろの「遊んでいる」につながる正しい形。", "履かない": "否定形は「はかないで遊ぶ」の意味になり、文の内容に合わない。", "履ける": "可能形で、「はける」の意味になり文の意味が変わる。", "履こう": "意志形は「遊んでいる」の前に続かず、文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52879, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は毎朝、靴に履いてから出かける。", "corrected_sentence": "母は毎朝、靴を履いてから出かける。", "error_description": "「履く」の目的語は「靴を」の「を」。「靴に」は誤り（正しくは「靴を履いて」）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "履いて", "is_correct": true, "explanation": "て形で、後ろの「海辺を歩いた」につながる正しい形。"}, {"text": "履く", "is_correct": false, "explanation": "終止形は「歩いた」と続かず、文が成り立たない。"}, {"text": "履け", "is_correct": false, "explanation": "命令形は文の流れに合わず、成り立たない。"}, {"text": "履けば", "is_correct": false, "explanation": "仮定形は「海辺を歩いた」と条件でつながり、文意が通らない。"}], "correct_form": "履いて", "base_form": "履く", "form_label": "て形", "sentence_index": 7, "explanations": {"履いて": "て形で、後ろの「海辺を歩いた」につながる正しい形。", "履く": "終止形は「歩いた」と続かず、文が成り立たない。", "履け": "命令形は文の流れに合わず、成り立たない。", "履けば": "仮定形は「海辺を歩いた」と条件でつながり、文意が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52881, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「靴があります」の靴は存在の主語なので「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「あります」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、存在を表すこの文には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「靴から あります」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「靴があります」の靴は存在の主語なので「が」が入る。", "を": "「を」は目的語を示すが、「あります」は目的語を取らないので合わない。", "へ": "「へ」は方向を示すので、存在を表すこの文には合わない。", "から": "「から」は起点を示すので、「靴から あります」は成り立たない。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52881, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「靴が汚れた」の靴は主語なので「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「汚れる」は目的語を取らないので「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「靴に汚れた」は成り立たず、「に」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、汚れた状態の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「靴が汚れた」の靴は主語なので「が」が入る。", "を": "「汚れる」は目的語を取らないので「を」は合わない。", "に": "「靴に汚れた」は成り立たず、「に」は合わない。", "へ": "「へ」は方向を示すので、汚れた状態の主語にはならない。"}, "error_tags": {"を": "対象", "に": "場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52881, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あしに はく ものです。", "primary_collocate": null, "pronunciation": "くつ", "ipa": "kɯtsɯ", "syllable_count": 2, "sentences": [{"text": "公園へ行くので、新しい靴を履きます。", "target_word": "靴", "complexity_tier": "T3", "furigana": "公園[こうえん]へ行[い]くので、新[あたら]しい靴[くつ]を履[は]きます。", "sentence_source": "generated"}, {"text": "玄関に、父の大きな靴があります。", "target_word": "靴", "complexity_tier": "T3", "furigana": "玄関[げんかん]に、父[ちち]の大[おお]きな靴[くつ]があります。", "sentence_source": "generated"}, {"text": "雨の日は、靴がぬれてしまいます。", "target_word": "靴", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、靴[くつ]がぬれてしまいます。", "sentence_source": "generated"}, {"text": "この靴は小さくて、足が入りません。", "target_word": "靴", "complexity_tier": "T3", "furigana": "この靴[くつ]は小[ちい]さくて、足[あし]が入[はい]りません。", "sentence_source": "generated"}, {"text": "妹は、靴を左右反対に履いてしまいました。", "target_word": "靴", "complexity_tier": "T3", "furigana": "妹[いもうと]は、靴[くつ]を左右反対[さゆうはんたい]に履[は]いてしまいました。", "sentence_source": "generated"}, {"text": "店で、白い靴を買いました。", "target_word": "靴", "complexity_tier": "T3", "furigana": "店[みせ]で、白[しろ]い靴[くつ]を買[か]いました。", "sentence_source": "generated"}, {"text": "かばんの横に、靴が置いてあります。", "target_word": "靴", "complexity_tier": "T3", "furigana": "かばんの横[よこ]に、靴[くつ]が置[お]いてあります。", "sentence_source": "generated"}, {"text": "靴が汚れたので、水で洗いました。", "target_word": "靴", "complexity_tier": "T3", "furigana": "靴[くつ]が汚[よご]れたので、水[みず]で洗[あら]いました。", "sentence_source": "generated"}, {"text": "先生は、毎日同じ靴で学校に来ます。", "target_word": "靴", "complexity_tier": "T3", "furigana": "先生[せんせい]は、毎日[まいにち]同[おな]じ靴[くつ]で学校[がっこう]に来[き]ます。", "sentence_source": "generated"}, {"text": "兄の靴は、わたしの靴よりずっと大きいです。", "target_word": "靴", "complexity_tier": "T3", "furigana": "兄[あに]の靴[くつ]は、わたしの靴[くつ]よりずっと大[おお]きいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "靴", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "足に履くもの、履物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52881, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "靴", "is_correct": true, "explanation": "「新しい___を履きます」に入る。履くのは靴。"}, {"text": "帽子", "is_correct": false, "explanation": "帽子は頭にかぶるもので、「履きます」とは続かない。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋は手にはめるもので、「履きます」とは続かない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は差す・持つもので、「履きます」とは続かない。"}], "explanations": {"靴": "「新しい___を履きます」に入る。履くのは靴。", "帽子": "帽子は頭にかぶるもので、「履きます」とは続かない。", "手袋": "手袋は手にはめるもので、「履きます」とは続かない。", "傘": "傘は差す・持つもので、「履きます」とは続かない。"}, "sentence_index": 0, "correct_answer": "靴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時間を確かめるため、靴を腕に巻いた。", "explanation": "ここは〈腕時計〉の意味。靴は腕に巻く物ではないので合わない。"}, {"text": "強い日差しを避けるため、靴を頭にかぶった。", "explanation": "ここは〈帽子〉の意味。靴は頭にかぶるものではないので合わない。"}, {"text": "雨が降ってきたので、靴を広げて差した。", "explanation": "ここは〈傘〉の意味。靴は雨をよけるために差すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52881, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "靴", "is_correct": true, "explanation": "「かばんの横に、___が置いてあります」に入る。置いてあるのは靴。"}, {"text": "影", "is_correct": false, "explanation": "影は物として置くものではないので、「置いてあります」と合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いは置けるものではないので、この文には入らない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は置いてあるものではないので、この文には入らない。"}], "explanations": {"靴": "「かばんの横に、___が置いてあります」に入る。置いてあるのは靴。", "影": "影は物として置くものではないので、「置いてあります」と合わない。", "匂い": "匂いは置けるものではないので、この文には入らない。", "煙": "煙は置いてあるものではないので、この文には入らない。"}, "sentence_index": 6, "correct_answer": "靴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "けがの手当てに、靴を傷口に貼った。", "explanation": "ここは〈絆創膏〉の意味。靴は傷口に貼るものではないので合わない。"}, {"text": "ドアを開けようと、靴を鍵穴に差し込んだ。", "explanation": "ここは〈キー〉の意味。靴は錠を開ける道具ではないので合わない。"}, {"text": "続きを知りたくて、靴のページをめくった。", "explanation": "ここは〈本〉の意味。靴にはページがなく、めくる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52881, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "わたしは、古い靴に捨てた。", "corrected_sentence": "わたしは、古い靴を捨てた。", "error_description": "「捨てる」は目的語に「を」を取る。靴に付いた「に」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52881, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い朝は、靴に中に新聞紙を入れる。", "corrected_sentence": "寒い朝は、靴の中に新聞紙を入れる。", "error_description": "「靴の中」は「の」で続ける。「靴に中」の「に」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52883, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「方便として」の「と」は資格を示し、方便に付く。"}, {"text": "が", "is_correct": false, "explanation": "「方便が〜して」は主語と述語が合わず、この文には合わない。"}, {"text": "を", "is_correct": false, "explanation": "「方便をして」は不自然で、この文には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、資格を表すこの文には合わない。"}], "correct_answer": "と", "explanations": {"と": "「方便として」の「と」は資格を示し、方便に付く。", "が": "「方便が〜して」は主語と述語が合わず、この文には合わない。", "を": "「方便をして」は不自然で、この文には合わない。", "へ": "「へ」は方向を示すので、資格を表すこの文には合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52883, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜を方便にして」の「に」は、方便を手段として示す。"}, {"text": "が", "is_correct": false, "explanation": "「方便が、おばけの話をした」は主語として不自然で、この文には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、この文の手段の意味には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」で続けると「方便の、おばけの話」となり、文として続かない。"}], "correct_answer": "に", "explanations": {"に": "「〜を方便にして」の「に」は、方便を手段として示す。", "が": "「方便が、おばけの話をした」は主語として不自然で、この文には合わない。", "へ": "「へ」は方向を示すので、この文の手段の意味には合わない。", "の": "「の」で続けると「方便の、おばけの話」となり、文として続かない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52883, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることをするための、一時的な方法や手段のこと。", "primary_collocate": null, "pronunciation": "ほうべん", "ipa": "hoːbeɴ", "syllable_count": 4, "sentences": [{"text": "工事のあいだ、倉庫を教室にするのは一時的な方便だ。", "target_word": "方便", "complexity_tier": "T3", "furigana": "工事[こうじ]のあいだ、倉庫[そうこ]を教室[きょうしつ]にするのは一時的[いちじてき]な方便[ほうべん]だ。", "sentence_source": "generated"}, {"text": "資金が集まるまでの方便として、友人から車を借りた。", "target_word": "方便", "complexity_tier": "T3", "furigana": "資金[しきん]が集[あつ]まるまでの方便[ほうべん]として、友人[ゆうじん]から車[くるま]を借[か]りた。", "sentence_source": "generated"}, {"text": "嘘も方便だと言って、彼は私を幹事に誘った。", "target_word": "方便", "complexity_tier": "T3", "furigana": "嘘[うそ]も方便[ほうべん]だと言[い]って、彼[かれ]は私[わたし]を幹事[かんじ]に誘[さそ]った。", "sentence_source": "generated"}, {"text": "これはあくまで方便であり、正式な契約ではない。", "target_word": "方便", "complexity_tier": "T3", "furigana": "これはあくまで方便[ほうべん]であり、正式[せいしき]な契約[けいやく]ではない。", "sentence_source": "generated"}, {"text": "彼女は留学を方便にして、故郷を離れた。", "target_word": "方便", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は留学[りゅうがく]を方便[ほうべん]にして、故郷[こきょう]を離[はな]れた。", "sentence_source": "generated"}, {"text": "病気を方便に仕事を休むのはよくない。", "target_word": "方便", "complexity_tier": "T3", "furigana": "病気[びょうき]を方便[ほうべん]に仕事[しごと]を休[やす]むのはよくない。", "sentence_source": "generated"}, {"text": "試験に受かるための方便として、問題を暗記だけで覚えた。", "target_word": "方便", "complexity_tier": "T3", "furigana": "試験[しけん]に受[う]かるための方便[ほうべん]として、問題[もんだい]を暗記[あんき]だけで覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "父は子どもを早く寝かせる方便にして、おばけの話をした。", "target_word": "方便", "complexity_tier": "T3", "furigana": "父[ちち]は子[こ]どもを早[はや]く寝[ね]かせる方便[ほうべん]に、おばけの話[はなし]をした。", "sentence_source": "generated"}, {"text": "方便を使ってでも、この場を収めなければならない。", "target_word": "方便", "complexity_tier": "T3", "furigana": "方便[ほうべん]を使[つか]ってでも、この場[ば]を収[おさ]めなければならない。", "sentence_source": "generated"}, {"text": "急場をしのぐ方便としては、この方法で十分だ。", "target_word": "方便", "complexity_tier": "T3", "furigana": "急場[きゅうば]をしのぐ方便[ほうべん]としては、この方法[ほうほう]で十分[じゅうぶん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "方便", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある事をするための一時的な方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52883, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方便", "is_correct": true, "explanation": "「一時的な___だ」に入る。工事中だけ使う仮の方法の意味。"}, {"text": "祝日", "is_correct": false, "explanation": "祝日は休日のことで、「一時的な祝日」は文脈に合わない。"}, {"text": "財産", "is_correct": false, "explanation": "財産は一時的なものとして扱う語ではなく、この文には合わない。"}, {"text": "教訓", "is_correct": false, "explanation": "教訓は学んだ内容を指し、「一時的な教訓」は文脈に合わない。"}], "explanations": {"方便": "「一時的な___だ」に入る。工事中だけ使う仮の方法の意味。", "祝日": "祝日は休日のことで、「一時的な祝日」は文脈に合わない。", "財産": "財産は一時的なものとして扱う語ではなく、この文には合わない。", "教訓": "教訓は学んだ内容を指し、「一時的な教訓」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "方便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "役所の窓口で、方便を図ってもらい、手続きが早く済んだ。", "explanation": "方便は手段の意味で、〈便宜〉（べんぎ）とは別語。「便宜を図る」とは言えず合わない。"}, {"text": "部屋を明るくするため、方便を飾った。", "explanation": "ここは〈花〉の意味。方便は飾るものではないので合わない。"}, {"text": "家族のため、方便を建てた。", "explanation": "ここは〈住まい〉の意味。方便は建てる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52883, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方便", "is_correct": true, "explanation": "「受かるための___として」に入る。試験に受かるための一時的な手段の意味。"}, {"text": "雨具", "is_correct": false, "explanation": "雨具は雨の日に使う物で、「受かるための雨具」は文脈に合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は手段にならず、「受かるための眠気」は文脈に合わない。"}, {"text": "祝日", "is_correct": false, "explanation": "祝日は手段にならず、「受かるための祝日」は文脈に合わない。"}], "explanations": {"方便": "「受かるための___として」に入る。試験に受かるための一時的な手段の意味。", "雨具": "雨具は雨の日に使う物で、「受かるための雨具」は文脈に合わない。", "眠気": "眠気は手段にならず、「受かるための眠気」は文脈に合わない。", "祝日": "祝日は手段にならず、「受かるための祝日」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "方便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業のために、方便を読んだ。", "explanation": "ここは〈教科書〉の意味。方便は読む物ではないので合わない。"}, {"text": "寒いので、方便を着て出かけた。", "explanation": "ここは〈服〉の意味。方便は身につける物ではないので合わない。"}, {"text": "換気のため、方便を開けた。", "explanation": "ここは〈窓〉の意味。方便は開け閉めする物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52883, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この場を収めるため、彼は方便に使った。", "corrected_sentence": "この場を収めるため、彼は方便を使った。", "error_description": "「使う」は目的語に「を」を取る。「方便に」の「に」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52883, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもを寝かせるため、父は方便を食べた。", "corrected_sentence": "子どもを寝かせるため、父は方便を使った。", "error_description": "「方便」は「使う」と結びつく。「食べる」は誤った組み合わせ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52884, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「嘘も方便と言う」の「と」は引用を表し、方便に付く。"}, {"text": "が", "is_correct": false, "explanation": "「方便が言う」は主語と動詞が合わず成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「方便に言う」は相手を取る形になり、方便には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「方便の言う」は修飾が続かず、この文の形には合わない。"}], "correct_answer": "と", "explanations": {"と": "「嘘も方便と言う」の「と」は引用を表し、方便に付く。", "が": "「方便が言う」は主語と動詞が合わず成り立たない。", "に": "「方便に言う」は相手を取る形になり、方便には合わない。", "の": "「方便の言う」は修飾が続かず、この文の形には合わない。"}, "error_tags": {"が": "主語", "に": "相手", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52884, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52884, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目的を達成するために一時的に用いる手段や方法。また、その場しのぎのやり方。", "primary_collocate": null, "pronunciation": "ほうべん", "ipa": "hoːbeɴ", "syllable_count": 4, "sentences": [{"text": "私がこの赤い靴を履くという行為は、決して寒さ凌ぎの方便ではない。", "target_word": "方便", "complexity_tier": "T3", "furigana": "私[わたし]がこの赤[あか]い靴[くつ]を履[は]くという行為[こうい]は、決[けっ]して寒[さむ]さ凌[しの]ぎの方便[ほうべん]ではない。", "sentence_source": "mined"}, {"text": "嘘も方便と言うが、ずっと隠し通すのは良くない。", "target_word": "方便", "complexity_tier": "T3", "furigana": "嘘[うそ]も方便[ほうべん]と言[い]うが、ずっと隠[かく]し通[とお]すのは良[よ]くない。", "sentence_source": "generated"}, {"text": "彼にとって留学は、就職のための方便にすぎなかった。", "target_word": "方便", "complexity_tier": "T3", "furigana": "彼[かれ]にとって留学[りゅうがく]は、就職[しゅうしょく]のための方便[ほうべん]にすぎなかった。", "sentence_source": "generated"}, {"text": "会議を早く終わらせるため、課長は急用があるという方便を使った。", "target_word": "方便", "complexity_tier": "T3", "furigana": "会議[かいぎ]を早[はや]く終[お]わらせるため、課長[かちょう]は急用[きゅうよう]があるという方便[ほうべん]を使[つか]った。", "sentence_source": "generated"}, {"text": "その場の方便で問題を先送りしても、根本的な解決にはならない。", "target_word": "方便", "complexity_tier": "T3", "furigana": "その場(そのば)の方便(ほうべん)で問題(もんだい)を先送り(さきおくり)しても、根本的(こんぽんてき)な解決(かいけつ)にはならない。", "sentence_source": "generated"}, {"text": "母は子どもに薬を飲ませようと、「ジュースだよ」と方便を使った。", "target_word": "方便", "complexity_tier": "T3", "furigana": "母[はは]は子[こ]どもに薬[くすり]を飲[の]ませようと、「ジュースだよ」と方便[ほうべん]を使[つか]った。", "sentence_source": "generated"}, {"text": "結婚を生活のための方便だと考える人もいる。", "target_word": "方便", "complexity_tier": "T3", "furigana": "結婚[けっこん]を生活[せいかつ]のための方便[ほうべん]だと考[かんが]える人[ひと]もいる。", "sentence_source": "generated"}, {"text": "一時的な方便ではなく、根本的な解決策が必要だ。", "target_word": "方便", "complexity_tier": "T3", "furigana": "一時的[いちじてき]な方便[ほうべん]ではなく、根本的[こんぽんてき]な解決策[かいけつさく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼は方便で友人を安心させたが、後で本当のことを話した。", "target_word": "方便", "complexity_tier": "T3", "furigana": "彼[かれ]は方便[ほうべん]で友人[ゆうじん]を安心[あんしん]させたが、後[あと]で本当[ほんとう]のことを話[はな]した。", "sentence_source": "generated"}, {"text": "上司の機嫌をとるための方便だとわかっていても、褒められるとうれしい。", "target_word": "方便", "complexity_tier": "T3", "furigana": "上司[じょうし]の機嫌[きげん]をとるための方便[ほうべん]だとわかっていても、褒[ほ]められるとうれしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "方便", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "目的のための一時的な手段・その場しのぎ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52884, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方便", "is_correct": true, "explanation": "「寒さ凌ぎの___ではない」に入る。寒さをしのぐための一時的な手段の意味。"}, {"text": "挨拶", "is_correct": false, "explanation": "「寒さ凌ぎの挨拶」は意味が通らず、この文脈に合わない。"}, {"text": "化粧", "is_correct": false, "explanation": "「寒さ凌ぎの化粧」は意味が通らず、この文脈に合わない。"}, {"text": "冗談", "is_correct": false, "explanation": "「寒さ凌ぎの冗談」は意味が通らず、この文脈に合わない。"}], "explanations": {"方便": "「寒さ凌ぎの___ではない」に入る。寒さをしのぐための一時的な手段の意味。", "挨拶": "「寒さ凌ぎの挨拶」は意味が通らず、この文脈に合わない。", "化粧": "「寒さ凌ぎの化粧」は意味が通らず、この文脈に合わない。", "冗談": "「寒さ凌ぎの冗談」は意味が通らず、この文脈に合わない。"}, "sentence_index": 0, "correct_answer": "方便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪をひいたので、方便を飲んで寝た。", "explanation": "ここは〈薬〉の意味。方便は手段や方法を指し、飲めるものではないので合わない。"}, {"text": "犯人ではないと示すため、方便を見せた。", "explanation": "ここは〈証拠〉の意味。方便は人に見せる物ではないので合わない。"}, {"text": "取引先の担当者に方便を図ってもらった。", "explanation": "方便は〈便宜〉（べんぎ）とは別語で、「便宜を図る」とは言えず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52884, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方便", "is_correct": true, "explanation": "「生活のための___だと考える」に入る。生活を続けるための一時的な手段の意味。"}, {"text": "贅沢", "is_correct": false, "explanation": "「生活のための贅沢」は意味が逆になり、この文脈に合わない。"}, {"text": "趣味", "is_correct": false, "explanation": "「生活のための趣味」は文脈に合わず、手段の意味にならない。"}, {"text": "儀式", "is_correct": false, "explanation": "「生活のための儀式」は文脈に合わず、この文には入らない。"}], "explanations": {"方便": "「生活のための___だと考える」に入る。生活を続けるための一時的な手段の意味。", "贅沢": "「生活のための贅沢」は意味が逆になり、この文脈に合わない。", "趣味": "「生活のための趣味」は文脈に合わず、手段の意味にならない。", "儀式": "「生活のための儀式」は文脈に合わず、この文には入らない。"}, "sentence_index": 6, "correct_answer": "方便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パーティーで、方便を配った。", "explanation": "ここは〈菓子〉の意味。方便は配れるものではないので合わない。"}, {"text": "思い出に、方便を撮った。", "explanation": "ここは〈写真〉の意味。方便は撮影の対象になるものではないので合わない。"}, {"text": "感謝を伝えるため、方便を書いて送った。", "explanation": "ここは〈手紙〉の意味。方便は書いて送るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52884, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの人は、いつも方便を話をそらす。", "corrected_sentence": "あの人は、いつも方便で話をそらす。", "error_description": "「話をそらす」は手段を表す「で」が必要。「方便を」の「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52884, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はその場しのぎの方便を読んだ。", "corrected_sentence": "彼はその場しのぎの方便を使った。", "error_description": "「方便」は「使う」と結びつく。「読んだ」は方便と結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
