INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52885, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ねずみいろのこと。", "primary_collocate": null, "pronunciation": "はいいろ", "ipa": "haiiɾo", "syllable_count": 4, "sentences": [{"text": "灰色の猫が窓辺で眠っている。", "target_word": "灰色", "complexity_tier": "T2", "furigana": "灰色[はいいろ]の猫[ねこ]が窓辺[まどべ]で眠[ねむ]っている。", "sentence_source": "generated"}, {"text": "洗いすぎたせいで、白いシャツが灰色になった。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "洗[あら]いすぎたせいで、白[しろ]いシャツが灰色[はいいろ]になった。", "sentence_source": "generated"}, {"text": "灰色の石でできた橋を渡った。", "target_word": "灰色", "complexity_tier": "T2", "furigana": "灰色[はいいろ]の石[いし]でできた橋[はし]を渡[わた]った。", "sentence_source": "generated"}, {"text": "煙突から灰色の煙が出ている。", "target_word": "灰色", "complexity_tier": "T2", "furigana": "煙突[えんとつ]から灰色[はいいろ]の煙[けむり]が出[で]ている。", "sentence_source": "generated"}, {"text": "灰色のセーターを買ったが、少し地味だった。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "灰色[はいいろ]のセーターを買[か]ったが、少[すこ]し地味[じみ]だった。", "sentence_source": "generated"}, {"text": "曇りの日は、湖の水も灰色に見える。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "曇[くも]りの日[ひ]は、湖[みずうみ]の水[みず]も灰色[はいいろ]に見[み]える。", "sentence_source": "generated"}, {"text": "ゾウの皮膚は灰色で、しわが多い。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "ゾウの皮膚[ひふ]は灰色[はいいろ]で、しわが多[おお]い。", "sentence_source": "generated"}, {"text": "妹は灰色のランドセルを選んだ。", "target_word": "灰色", "complexity_tier": "T2", "furigana": "妹[いもうと]は灰色[はいいろ]のランドセルを選[えら]んだ。", "sentence_source": "generated"}, {"text": "絵の具の黒と白を混ぜると、灰色ができる。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]の黒[くろ]と白[しろ]を混[ま]ぜると、灰色[はいいろ]ができる。", "sentence_source": "generated"}, {"text": "灰色の鳩が広場に集まっていた。", "target_word": "灰色", "complexity_tier": "T2", "furigana": "灰色[はいいろ]の鳩[はと]が広場[ひろば]に集[あつ]まっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "灰色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ねずみ色(黒と白の中間の色)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52885, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灰色", "is_correct": true, "explanation": "「〜の猫」と毛色を表す色名が続く形。ねずみ色の灰色が入って文が成立する。"}, {"text": "鉛", "is_correct": false, "explanation": "「鉛の猫」は毛色を表さず、不自然。"}, {"text": "窓", "is_correct": false, "explanation": "「窓の猫」は場所を指すだけで、毛色は表さない。"}, {"text": "煙", "is_correct": false, "explanation": "「煙の猫」は意味が通らない。煙は毛色の名称ではない。"}], "explanations": {"灰色": "「〜の猫」と毛色を表す色名が続く形。ねずみ色の灰色が入って文が成立する。", "鉛": "「鉛の猫」は毛色を表さず、不自然。", "窓": "「窓の猫」は場所を指すだけで、毛色は表さない。", "煙": "「煙の猫」は意味が通らない。煙は毛色の名称ではない。"}, "sentence_index": 0, "correct_answer": "灰色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同じ作業の繰り返しで、灰色の時間が流れた。", "explanation": "ここは〈単調で味気ない〉の意味。色の名称ではなく、変化のない時間の様子を表す。"}, {"text": "暖炉の掃除をしたら、床に灰色が一面に散らばった。", "explanation": "ここは〈灰〉の意味。灰色は色の名称で、燃えかすそのものを指す語ではない。"}, {"text": "彼女は灰色の声で、軽やかに笑った。", "explanation": "ここは〈くすんで暗い〉の意味。軽やかな笑い声とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52885, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灰色", "is_correct": true, "explanation": "「ゾウの皮膚は〜で、しわが多い」の空所には、皮膚の色を表す灰色が入る。"}, {"text": "糸", "is_correct": false, "explanation": "「糸で、しわが多い」は皮膚の色を表さず、文として成立しない。"}, {"text": "霧", "is_correct": false, "explanation": "「霧で、しわが多い」は皮膚の描写として不自然。"}, {"text": "雨", "is_correct": false, "explanation": "「雨で、しわが多い」は皮膚の色を表さず、意味が通らない。"}], "explanations": {"灰色": "「ゾウの皮膚は〜で、しわが多い」の空所には、皮膚の色を表す灰色が入る。", "糸": "「糸で、しわが多い」は皮膚の色を表さず、文として成立しない。", "霧": "「霧で、しわが多い」は皮膚の描写として不自然。", "雨": "「雨で、しわが多い」は皮膚の色を表さず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "灰色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕暮れの海が灰色のように鮮やかに光った。", "explanation": "ここは〈鮮烈〉の意味。ここで光を強く印象づけるのは「鮮烈」で、灰色はくすんだ色で合わない。"}, {"text": "たき火が消えて、灰色だけが残った。", "explanation": "ここは〈灰〉の意味。灰色は色の名称で、燃えかすを指す語ではない。"}, {"text": "湖の水は灰色に澄み、底まで見えた。", "explanation": "ここは〈透明〉の意味。澄んだ水の透明さは「透明」が表し、灰色は色の名称で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52885, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗いすぎたシャツは灰色を変わった。", "corrected_sentence": "洗いすぎたシャツは灰色に変わった。", "error_description": "「変わる」は助詞「に」を取る。「灰色を」は誤りで、「灰色に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52885, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "灰色で猫が広場に集まっていた。", "corrected_sentence": "灰色の猫が広場に集まっていた。", "error_description": "名詞を修飾する形は「の」。「灰色で」は誤りで、「灰色の猫」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
