INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52886, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "色の名前。黒と白をまぜたような色。また、つまらなくて、かわりのないようす。", "primary_collocate": null, "pronunciation": "はいいろ", "ipa": "haiiɾo", "syllable_count": 4, "sentences": [{"text": "それは、灰色に均質化された日常の景観に対し、鮮烈な色彩の楔を打ち込む、個人的かつ審美的な反逆の儀式に他ならない。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "それは、灰色[はいいろ]に均質化[きんしつか]された日常[にちじょう]の景観[けいかん]に対[たい]し、鮮烈[せんれつ]な色彩[しきさい]の楔[くさび]を打[う]ち込[こ]む、個人的[こじんてき]かつ審美的[しんびてき]な反逆[はんぎゃく]の儀式[ぎしき]に他[ほか]ならない。", "sentence_source": "mined"}, {"text": "空は朝から厚い灰色の雲におおわれていた。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "空[そら]は朝[あさ]から厚[あつ]い灰色[はいいろ]の雲[くも]におおわれていた。", "sentence_source": "generated"}, {"text": "灰色のコートは、どんな服にも合わせやすい。", "target_word": "灰色", "complexity_tier": "T2", "furigana": "灰色[はいいろ]のコートは、どんな服[ふく]にも合[あ]わせやすい。", "sentence_source": "generated"}, {"text": "毎日同じことの繰り返しで、灰色の日々が続いている。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "毎日[まいにち]同[おな]じことの繰[く]り返[かえ]しで、灰色[はいいろ]の日々[ひび]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "雨が降る前の海は、重い灰色に見えた。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る前[まえ]の海[うみ]は、重[おも]い灰色[はいいろ]に見[み]えた。", "sentence_source": "generated"}, {"text": "彼は灰色のスーツを着て、面接に向かった。", "target_word": "灰色", "complexity_tier": "T2", "furigana": "彼[かれ]は灰色[はいいろ]のスーツを着[き]て、面接[めんせつ]に向[む]かった。", "sentence_source": "generated"}, {"text": "古い壁は汚れて、すっかり灰色になってしまった。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "古[ふる]い壁[かべ]は汚[よご]れて、すっかり灰色[はいいろ]になってしまった。", "sentence_source": "generated"}, {"text": "灰色の毎日を変えたくて、新しい趣味を始めた。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "灰色[はいいろ]の毎日[まいにち]を変[か]えたくて、新[あたら]しい趣味[しゅみ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "工場が並ぶ町は、どこも灰色で味気なかった。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "工場[こうじょう]が並[なら]ぶ町[まち]は、どこも灰色[はいいろ]で味気[あじけ]なかった。", "sentence_source": "generated"}, {"text": "猫は灰色の毛をしていて、暗い道ではほとんど見えなかった。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "猫[ねこ]は灰色[はいいろ]の毛[け]をしていて、暗[くら]い道[みち]ではほとんど見[み]えなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "灰色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "黒と白の混ざった色・単調で味気ないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 均質 (Zipf 2.7), 鮮烈 (Zipf 2.73), 楔 (Zipf 2.53), 打ち込む (Zipf 3.22), 審美 (Zipf 2.76)']::text[], '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52886, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灰色", "is_correct": true, "explanation": "「灰色に均質化された」の空所には、色の状態を表す語が入る。灰色は黒と白が混じった色で、この文を成立させる唯一の語。"}, {"text": "景観", "is_correct": false, "explanation": "「景観に均質化された」は意味をなさない。景観は均質化される対象の物であり、その状態を表す語ではない。"}, {"text": "儀式", "is_correct": false, "explanation": "「儀式に均質化された」は不自然。儀式は行為の名称で、色や様子を表さない。"}, {"text": "楔", "is_correct": false, "explanation": "「楔に均質化された」は文が成り立たない。楔は打ち込む道具で、均質化の結果としての状態を表さない。"}], "explanations": {"灰色": "「灰色に均質化された」の空所には、色の状態を表す語が入る。灰色は黒と白が混じった色で、この文を成立させる唯一の語。", "景観": "「景観に均質化された」は意味をなさない。景観は均質化される対象の物であり、その状態を表す語ではない。", "儀式": "「儀式に均質化された」は不自然。儀式は行為の名称で、色や様子を表さない。", "楔": "「楔に均質化された」は文が成り立たない。楔は打ち込む道具で、均質化の結果としての状態を表さない。"}, "sentence_index": 0, "correct_answer": "灰色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は灰色の声で、客に明るくあいさつした。", "explanation": "ここは〈明るく活気のある〉の意味。灰色は色や単調な様子に使い、声の調子には使わない。"}, {"text": "ストーブの掃除で、灰色の山が床にできた。", "explanation": "ここは〈灰〉の意味。灰色は色の名称で、燃えかすそのものを指す語ではない。"}, {"text": "祭りの夜、灰色の歓声が広場を包んだ。", "explanation": "ここは〈華やかで活気のある〉の意味。灰色は色や単調さを表す語で、歓声の描写には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52886, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灰色", "is_correct": true, "explanation": "「すっかり〜になってしまった」は、汚れて変わった色を表す語が入る。灰色が正しい。"}, {"text": "雨", "is_correct": false, "explanation": "「雨になってしまった」は意味が通らない。壁の色の変化を表さない。"}, {"text": "霧", "is_correct": false, "explanation": "「霧になってしまった」は壁の状態として不自然で、色の変化を表さない。"}, {"text": "糸", "is_correct": false, "explanation": "「糸になってしまった」は壁の色の変化として成り立たない。"}], "explanations": {"灰色": "「すっかり〜になってしまった」は、汚れて変わった色を表す語が入る。灰色が正しい。", "雨": "「雨になってしまった」は意味が通らない。壁の色の変化を表さない。", "霧": "「霧になってしまった」は壁の状態として不自然で、色の変化を表さない。", "糸": "「糸になってしまった」は壁の色の変化として成り立たない。"}, "sentence_index": 6, "correct_answer": "灰色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の動きは灰色で、ボールにすぐ飛びついた。", "explanation": "ここは〈機敏〉の意味。すばやい動きは「機敏」が表し、灰色は色の名称で、動作には使わない。"}, {"text": "彼女は灰色の足で、誰よりも速く走った。", "explanation": "ここは〈俊足〉の意味。足の速さは「俊足」などが表し、灰色は色の名称で合わない。"}, {"text": "夏の海は灰色の明るさで、子どもたちを喜ばせた。", "explanation": "ここは〈晴れやか〉の意味。夏の海の晴れやかな印象は「晴れやか」が表し、灰色はくすんだ色で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52886, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工事のあと、壁は灰色を汚れてしまった。", "corrected_sentence": "工事のあと、壁は灰色に汚れてしまった。", "error_description": "「汚れる」は助詞「に」を取る。「灰色を」は誤りで、「灰色に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52886, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "灰色で海が朝の光に照らされていた。", "corrected_sentence": "灰色の海が朝の光に照らされていた。", "error_description": "名詞を修飾する形は「の」。「灰色で」は誤りで、「灰色の海」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
