INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52887, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "色や感じがとても強くて、目立つことです。", "primary_collocate": null, "pronunciation": "せんれつ", "ipa": "seɴɾetsɯ", "syllable_count": 4, "sentences": [{"text": "鮮烈な赤いドレスが、パーティーで一番目立っていた。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "鮮烈[せんれつ]な赤[あか]いドレスが、パーティーで一番[いちばん]目立[めだ]っていた。", "sentence_source": "generated"}, {"text": "旅先で見た星空は、鮮烈な記憶として残っている。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "旅先[たびさき]で見[み]た星空[ほしぞら]は、鮮烈[せんれつ]な記憶[きおく]として残[のこ]っている。", "sentence_source": "generated"}, {"text": "その映画の最後の場面は鮮烈だった。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "その映画[えいが]の最後[さいご]の場面[ばめん]は鮮烈[せんれつ]だった。", "sentence_source": "generated"}, {"text": "彼は鮮烈な色の傘をさして歩いていた。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "彼[かれ]は鮮烈[せんれつ]な色[いろ]の傘[かさ]をさして歩[ある]いていた。", "sentence_source": "generated"}, {"text": "初恋の鮮烈な思い出は、大人になっても消えない。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "初恋[はつこい]の鮮烈[せんれつ]な思[おも]い出[で]は、大人[おとな]になっても消[き]えない。", "sentence_source": "generated"}, {"text": "鮮烈な緑の葉が、雨にぬれて光っていた。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "鮮烈[せんれつ]な緑[みどり]の葉[は]が、雨[あめ]にぬれて光[ひか]っていた。", "sentence_source": "generated"}, {"text": "若い歌手の鮮烈な歌声に、観客は息をのんだ。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "若[わか]い歌手[かしゅ]の鮮烈[せんれつ]な歌声[うたごえ]に、観客[かんきゃく]は息[いき]をのんだ。", "sentence_source": "generated"}, {"text": "彼女は会った人に鮮烈な印象を与える人だ。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は会[あ]った人[ひと]に鮮烈[せんれつ]な印象[いんしょう]を与[あた]える人[ひと]だ。", "sentence_source": "generated"}, {"text": "鮮烈な黄色の花畑が、丘いっぱいに広がっている。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "鮮烈[せんれつ]な黄色[きいろ]の花畑[はなばたけ]が、丘[おか]いっぱいに広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "兄の決勝ゴールは鮮烈だった。", "target_word": "鮮烈", "complexity_tier": "T3", "furigana": "兄[あに]の決勝[けっしょう]ゴールは鮮烈[せんれつ]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鮮烈だ", "label": "終止形"}, {"form": "鮮烈な", "label": "連体形"}, {"form": "鮮烈に", "label": "連用形"}, {"form": "鮮烈で", "label": "連用形(で)"}], "register": "literary", "sense_fingerprint": "色や感じがとても強く目立つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3afdc553-98d6-45c4-bb15-73a4894d55c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52887, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鮮烈", "is_correct": true, "explanation": "「鮮烈な赤いドレス」の形で、目立つほど強く鮮やかなさまを表す語が入る。"}, {"text": "寡黙", "is_correct": false, "explanation": "「寡黙な赤いドレス」は人の性質を表す語で、服の形容には使えない。"}, {"text": "内気", "is_correct": false, "explanation": "「内気な赤いドレス」は人の性格を表す語で、服には合わない。"}, {"text": "厳格", "is_correct": false, "explanation": "「厳格な赤いドレス」は人の態度を表す語で、服の形容には合わない。"}], "explanations": {"鮮烈": "「鮮烈な赤いドレス」の形で、目立つほど強く鮮やかなさまを表す語が入る。", "寡黙": "「寡黙な赤いドレス」は人の性質を表す語で、服の形容には使えない。", "内気": "「内気な赤いドレス」は人の性格を表す語で、服には合わない。", "厳格": "「厳格な赤いドレス」は人の態度を表す語で、服の形容には合わない。"}, "sentence_index": 0, "correct_answer": "鮮烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この果物は鮮烈で、甘みが強い。", "explanation": "ここは〈新鮮〉の意味。鮮烈は強く印象的なさまを表し、果物の鮮度は表さない。"}, {"text": "この湖は鮮烈で、底が見えないほど深い。", "explanation": "ここは〈深い〉の意味。鮮烈は色や感じの強さを表し、湖の深さには使わない。"}, {"text": "彼女の鮮烈な計算は、いつも正確だ。", "explanation": "ここは〈堅実〉の意味。計算の確かさは「堅実」が表し、鮮烈は目立つ色や感じに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52887, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鮮烈", "is_correct": true, "explanation": "「若い歌手の鮮烈な歌声」の形で、強く印象的な歌声を表す語が入る。"}, {"text": "無口", "is_correct": false, "explanation": "「無口な歌声」は人の性質を表す語で、声の形容としては合わない。"}, {"text": "薄情", "is_correct": false, "explanation": "「薄情な歌声」は人の情の薄さを表す語で、歌声の形容には合わない。"}, {"text": "陰険", "is_correct": false, "explanation": "「陰険な歌声」は人の性格を表す語で、歌声の形容には使えない。"}], "explanations": {"鮮烈": "「若い歌手の鮮烈な歌声」の形で、強く印象的な歌声を表す語が入る。", "無口": "「無口な歌声」は人の性質を表す語で、声の形容としては合わない。", "薄情": "「薄情な歌声」は人の情の薄さを表す語で、歌声の形容には合わない。", "陰険": "「陰険な歌声」は人の性格を表す語で、歌声の形容には使えない。"}, "sentence_index": 6, "correct_answer": "鮮烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この家の壁は鮮烈で、雨にも強い。", "explanation": "ここは〈丈夫〉の意味ではない。鮮烈は色や印象の強さを表す語で、物の強度は表さない。"}, {"text": "鮮烈な湿気が部屋にこもり、息苦しかった。", "explanation": "ここは〈じっとりと蒸す〉の意味。鮮烈は強く印象的なさまを表し、蒸し暑さは表さない。"}, {"text": "彼の声は鮮烈に小さく、ほとんど聞こえなかった。", "explanation": "ここは〈かすかな〉の意味。鮮烈は強く目立つさまで、かすかな声は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52887, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の鮮烈が赤いドレスは目を引いた。", "corrected_sentence": "彼女の鮮烈な赤いドレスは目を引いた。", "error_description": "「鮮烈」が名詞を修飾するときは連体形「な」。「が」は誤りで、「な」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "鮮烈だ", "is_correct": false, "explanation": "終止形。名詞を修飾する位置では連体形が必要で、「鮮烈な記憶」の形ではない。"}, {"text": "鮮烈な", "is_correct": true, "explanation": "連体形。「鮮烈な記憶」のように名詞を修飾する形。"}, {"text": "鮮烈に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞の前には使わない。"}, {"text": "鮮烈で", "is_correct": false, "explanation": "連用形（で）。名詞を直接修飾しない。"}], "correct_form": "鮮烈な", "base_form": "鮮烈だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"鮮烈だ": "終止形。名詞を修飾する位置では連体形が必要で、「鮮烈な記憶」の形ではない。", "鮮烈な": "連体形。「鮮烈な記憶」のように名詞を修飾する形。", "鮮烈に": "連用形。動詞や形容詞を修飾する形で、名詞の前には使わない。", "鮮烈で": "連用形（で）。名詞を直接修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52887, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その歌手の鮮烈で歌声は観客を驚かせた。", "corrected_sentence": "その歌手の鮮烈な歌声は観客を驚かせた。", "error_description": "名詞「歌声」を修飾するときは連体形「な」。「で」は誤りで、「な」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "鮮烈だろう", "is_correct": false, "explanation": "推量の形。名詞「印象」を修飾する形ではない。"}, {"text": "鮮烈な", "is_correct": true, "explanation": "連体形。「鮮烈な印象」のように名詞「印象」を修飾する形。"}, {"text": "鮮烈ならば", "is_correct": false, "explanation": "仮定の形。名詞を直接修飾しないので「印象」の前には入らない。"}, {"text": "鮮烈であれ", "is_correct": false, "explanation": "命令・願望の形で、名詞「印象」を修飾する形にはならない。"}], "correct_form": "鮮烈な", "base_form": "鮮烈だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"鮮烈だろう": "推量の形。名詞「印象」を修飾する形ではない。", "鮮烈な": "連体形。「鮮烈な印象」のように名詞「印象」を修飾する形。", "鮮烈ならば": "仮定の形。名詞を直接修飾しないので「印象」の前には入らない。", "鮮烈であれ": "命令・願望の形で、名詞「印象」を修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590628d3-6279-4cd8-8886-42f4af419d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52889, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「楔を入れて」の「を」は、入れる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「楔が入れて」では楔が動作主になり、入れる対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「楔と入れて」では並列になり、入れる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「楔へ入れて」は移動先を示し、入れる対象の「を」には合わない。"}], "correct_answer": "を", "explanations": {"を": "「楔を入れて」の「を」は、入れる対象を示す。", "が": "「楔が入れて」では楔が動作主になり、入れる対象として不自然。", "と": "「楔と入れて」では並列になり、入れる対象を示せない。", "へ": "「楔へ入れて」は移動先を示し、入れる対象の「を」には合わない。"}, "error_tags": {"が": "主格の誤り", "と": "並列の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52889, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「楔を順番に打って」の「を」は、打つ対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「楔へ順番に打って」は移動先を示し、打つ対象にならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「楔より順番に打って」は比較になり、打つ対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「楔と順番に打って」は並列になり、打つ対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「楔を順番に打って」の「を」は、打つ対象を示す。", "へ": "「楔へ順番に打って」は移動先を示し、打つ対象にならず不自然。", "より": "「楔より順番に打って」は比較になり、打つ対象を示せない。", "と": "「楔と順番に打って」は並列になり、打つ対象を示せない。"}, "error_tags": {"へ": "方向の誤り", "より": "比較の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52889, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くさびは、木や石を割るときに使う、先がとがった道具です。", "primary_collocate": null, "pronunciation": "くさび", "ipa": "kɯsabi", "syllable_count": 3, "sentences": [{"text": "木を割るために、木の幹に楔を打ち込んだ。", "target_word": "楔", "complexity_tier": "T3", "furigana": "木[き]を割[わ]るために、木[き]の幹[みき]に楔[くさび]を打[う]ち込[こ]んだ。", "sentence_source": "generated"}, {"text": "石屋さんは石の小さな穴に楔を入れて、大きな石を割った。", "target_word": "楔", "complexity_tier": "T3", "furigana": "石屋[いしや]さんは石[いし]の小[ちい]さな穴[あな]に楔[くさび]を入[い]れて、大[おお]きな石[いし]を割[わ]った。", "sentence_source": "generated"}, {"text": "祖父は薪を割るとき、鉄の楔と大きな槌を使っていた。", "target_word": "楔", "complexity_tier": "T3", "furigana": "祖父[そふ]は薪[まき]を割[わ]るとき、鉄[てつ]の楔[くさび]と大[おお]きな槌[つち]を使[つか]っていた。", "sentence_source": "generated"}, {"text": "道具箱から楔を出して、倒れた木を割る準備をした。", "target_word": "楔", "complexity_tier": "T3", "furigana": "道具箱[どうぐばこ]から楔[くさび]を出[だ]して、倒[たお]れた木[き]を割[わ]る準備[じゅんび]をした。", "sentence_source": "generated"}, {"text": "この楔は先がとがっているので、固い木にも入りやすい。", "target_word": "楔", "complexity_tier": "T3", "furigana": "この楔[くさび]は先[さき]がとがっているので、固[かた]い木[き]にも入[はい]りやすい。", "sentence_source": "generated"}, {"text": "楔を二、三本使えば、太い丸太も割れる。", "target_word": "楔", "complexity_tier": "T3", "furigana": "楔[くさび]を二[に]、三本[さんぼん]使[つか]えば、太[ふと]い丸太[まるた]も割[わ]れる。", "sentence_source": "generated"}, {"text": "ハンマーで楔を叩くと、岩に細いひびが入った。", "target_word": "楔", "complexity_tier": "T3", "furigana": "ハンマーで楔[くさび]を叩[たた]くと、岩[いわ]に細[ほそ]いひびが入[はい]った。", "sentence_source": "generated"}, {"text": "昔の石切り場では、岩に並べた楔を順番に打って石を切り出した。", "target_word": "楔", "complexity_tier": "T3", "furigana": "昔[むかし]の石切[いしき]り場[ば]では、岩[いわ]に並[なら]べた楔[くさび]を順番[じゅんばん]に打[う]って石[いし]を切[き]り出[だ]した。", "sentence_source": "generated"}, {"text": "楔が深く入るほど、木の割れ目は大きく広がっていく。", "target_word": "楔", "complexity_tier": "T3", "furigana": "楔[くさび]が深[ふか]く入[はい]るほど、木[き]の割[わ]れ目[め]は大[おお]きく広[ひろ]がっていく。", "sentence_source": "generated"}, {"text": "大きな丸太は、楔を打ち込んでから斧で割ると楽になる。", "target_word": "楔", "complexity_tier": "T3", "furigana": "大[おお]きな丸太[まるた]は、楔[くさび]を打[う]ち込[こ]んでから斧[おの]で割[わ]ると楽[らく]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "楔", "label": "基本形"}, {"form": "くさび", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "木や石を割るために打ち込む、先のとがった道具。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52889, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楔", "is_correct": true, "explanation": "「木の幹に楔を打ち込んだ」は、割るための道具として自然。"}, {"text": "鋸", "is_correct": false, "explanation": "鋸は引いて切る道具で、幹に打ち込むものではない。"}, {"text": "鉋", "is_correct": false, "explanation": "鉋は面を削る道具で、幹に打ち込むことはできない。"}, {"text": "金槌", "is_correct": false, "explanation": "金槌は打つ道具で、打ち込まれる対象としては意味が通らない。"}], "explanations": {"楔": "「木の幹に楔を打ち込んだ」は、割るための道具として自然。", "鋸": "鋸は引いて切る道具で、幹に打ち込むものではない。", "鉋": "鉋は面を削る道具で、幹に打ち込むことはできない。", "金槌": "金槌は打つ道具で、打ち込まれる対象としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "楔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "倒れた木を、楔を振り下ろして一撃で割った。", "explanation": "ここは〈斧〉の意味。楔は打ち込んで少しずつ割り広げる道具で、振り下ろして一撃で割る用途には使わない。"}, {"text": "倒れた木を、楔でひき切った。", "explanation": "ここは〈鋸〉の意味。楔は隙間に打ち込む道具で、ひいて切る用途では使わない。"}, {"text": "ほつれた布を、楔で縫い直した。", "explanation": "ここは〈針〉の意味。楔は隙間に打ち込む道具で、布を縫う用途では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52889, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楔", "is_correct": true, "explanation": "「ハンマーで楔を叩く」は、道具として自然な動作。"}, {"text": "紐", "is_correct": false, "explanation": "紐は叩いて岩にひびを入れる道具ではなく、ここでは意味が通らない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は叩けないので、岩にひびを入れる文脈には合わない。"}, {"text": "湯気", "is_correct": false, "explanation": "湯気は叩けないので、ここでは成り立たない。"}], "explanations": {"楔": "「ハンマーで楔を叩く」は、道具として自然な動作。", "紐": "紐は叩いて岩にひびを入れる道具ではなく、ここでは意味が通らない。", "霧": "霧は叩けないので、岩にひびを入れる文脈には合わない。", "湯気": "湯気は叩けないので、ここでは成り立たない。"}, "sentence_index": 6, "correct_answer": "楔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "邪魔な枝を、楔で払い落とした。", "explanation": "ここは〈鉈〉の意味。楔は打ち込んで割り広げる道具で、枝を払い切る用途には使わない。"}, {"text": "重い丸太を、楔で縛って運んだ。", "explanation": "ここは〈ロープ〉の意味。楔は隙間に打ち込む道具で、物を縛る用途では使わない。"}, {"text": "ノートの端に、楔で線を引いた。", "explanation": "ここは〈鉛筆〉の意味。楔は隙間に打ち込む道具で、線を引く用途では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52889, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薪を割るため、鉄の楔が丸太の割れ目に打ち込んだ。", "corrected_sentence": "薪を割るため、鉄の楔を丸太の割れ目に打ち込んだ。", "error_description": "正しくは「楔を打ち込んだ」。打ち込む対象は「を」で示すので、「楔が」は主語になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52889, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い石の隙間に楔を入って、少しずつ割った。", "corrected_sentence": "古い石の隙間に楔を入れて、少しずつ割った。", "error_description": "正しくは「楔を入れて」。「入れる」は他動詞で「楔を」と対応する。「入って」は自動詞で目的語を取れず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52890, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「楔を打ち込み」の「を」は、打ち込む対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「楔が打ち込み」では楔自身が動作主になり、打ち込む対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「楔と打ち込み」では並列になり、打ち込む対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「楔へ打ち込み」は移動先を示し、打ち込む対象を示す「を」の代わりにはならない。"}], "correct_answer": "を", "explanations": {"を": "「楔を打ち込み」の「を」は、打ち込む対象を示す。", "が": "「楔が打ち込み」では楔自身が動作主になり、打ち込む対象として不自然。", "と": "「楔と打ち込み」では並列になり、打ち込む対象を示せない。", "へ": "「楔へ打ち込み」は移動先を示し、打ち込む対象を示す「を」の代わりにはならない。"}, "error_tags": {"が": "主格の誤り", "と": "並列の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52890, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「楔となった」の「と」は、結果としてその役割を果たしたことを示す。"}, {"text": "を", "is_correct": false, "explanation": "「楔をなった」では成り立たず、なる相手を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「楔でなった」は手段を示す「で」で、なるという結果には使えない。"}, {"text": "の", "is_correct": false, "explanation": "「楔のなった」は所属を示す「の」で、結果を表す言い方にならない。"}], "correct_answer": "と", "explanations": {"と": "「楔となった」の「と」は、結果としてその役割を果たしたことを示す。", "を": "「楔をなった」では成り立たず、なる相手を示せない。", "で": "「楔でなった」は手段を示す「で」で、なるという結果には使えない。", "の": "「楔のなった」は所属を示す「の」で、結果を表す言い方にならない。"}, "error_tags": {"を": "対象の誤り", "で": "手段の誤り", "の": "所属の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52890, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物と物の間に打ち込んで、隙間を広げたり、固定したりするための、先端が薄く尖った道具。また、比喩的に、ある状態を変えるきっかけとなるもの。", "primary_collocate": null, "pronunciation": "くさび", "ipa": "kɯsabi", "syllable_count": 3, "sentences": [{"text": "それは、灰色に均質化された日常の景観に対し、鮮烈な色彩の楔を打ち込む、個人的かつ審美的な反逆の儀式に他ならない。", "target_word": "楔", "complexity_tier": "T4", "furigana": "それは、灰色[はいいろ]に均質化[きんしつか]された日常[にちじょう]の景観[けいかん]に対[たい]し、鮮烈[せんれつ]な色彩[しきさい]の楔[くさび]を打[う]ち込[こ]む、個人的[こじんてき]かつ審美的[しんびてき]な反逆[はんぎゃく]の儀式[ぎしき]に他[ほか]ならない。", "sentence_source": "mined"}, {"text": "大工さんは丸太の割れ目に楔を打ち込み、少しずつ幅を広げた。", "target_word": "楔", "complexity_tier": "T3", "furigana": "大工[だいく]さんは丸太[まるた]の割[わ]れ目[め]に楔[くさび]を打[う]ち込[こ]み、少[すこ]しずつ幅[はば]を広[ひろ]げた。", "sentence_source": "generated"}, {"text": "ドアが閉まらないよう、隙間に楔を挟んでおいた。", "target_word": "楔", "complexity_tier": "T3", "furigana": "ドアが閉[し]まらないよう、隙間[すきま]に楔[くさび]を挟[はさ]んでおいた。", "sentence_source": "generated"}, {"text": "その発表は、長年変わらなかった業界の慣習に楔を打ち込んだ。", "target_word": "楔", "complexity_tier": "T3", "furigana": "その発表[はっぴょう]は、長年[ながねん]変[か]わらなかった業界[ぎょうかい]の慣習[かんしゅう]に楔[くさび]を打[う]ち込[こ]んだ。", "sentence_source": "generated"}, {"text": "机の脚がぐらつくので、薄い楔を差し込んで高さを合わせた。", "target_word": "楔", "complexity_tier": "T3", "furigana": "机[つくえ]の脚[あし]がぐらつくので、薄[うす]い楔[くさび]を差[さ]し込[こ]んで高[たか]さを合[あ]わせた。", "sentence_source": "generated"}, {"text": "柄に楔を打って、ハンマーの頭をしっかり固定した。", "target_word": "楔", "complexity_tier": "T3", "furigana": "柄[え]に楔[くさび]を打[う]って、ハンマーの頭[あたま]をしっかり固定[こてい]した。", "sentence_source": "generated"}, {"text": "新しい店の成功は、大企業が独占する市場に楔を打ち込む第一歩だった。", "target_word": "楔", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の成功[せいこう]は、大企業[だいきぎょう]が独占[どくせん]する市場[しじょう]に楔[くさび]を打[う]ち込[こ]む第一歩[だいいっぽ]だった。", "sentence_source": "generated"}, {"text": "小さな反対運動が、計画を変える楔となった。", "target_word": "楔", "complexity_tier": "T3", "furigana": "小[ちい]さな反対運動[はんたいうんどう]が、計画[けいかく]を変[か]える楔[くさび]となった。", "sentence_source": "generated"}, {"text": "柱と梁の接合部には、木の楔が使われている。", "target_word": "楔", "complexity_tier": "T3", "furigana": "柱[はしら]と梁[はり]の接合部[せつごうぶ]には、木[き]の楔[くさび]が使[つか]われている。", "sentence_source": "generated"}, {"text": "彼女の一言は、停滞していた会議に楔を打ち込み、議論を動かした。", "target_word": "楔", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の一言[ひとこと]は、停滞[ていたい]していた会議[かいぎ]に楔[くさび]を打[う]ち込[こ]み、議論[ぎろん]を動[うご]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "楔", "label": "基本形"}, {"form": "くさび", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "打ち込んで割る・固定する道具。比喩では状況を変えるきっかけ。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52890, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楔", "is_correct": true, "explanation": "「色彩の楔を打ち込む」は、景観を崩す比喩として自然に収まる。"}, {"text": "鋸", "is_correct": false, "explanation": "鋸は引いて切る道具で、打ち込むものではないため、ここでは意味が通らない。"}, {"text": "鉋", "is_correct": false, "explanation": "鉋は面を削る道具で、打ち込む対象にはならない。"}, {"text": "金槌", "is_correct": false, "explanation": "金槌は打つ道具で、打ち込まれる対象としては意味が通らない。"}], "explanations": {"楔": "「色彩の楔を打ち込む」は、景観を崩す比喩として自然に収まる。", "鋸": "鋸は引いて切る道具で、打ち込むものではないため、ここでは意味が通らない。", "鉋": "鉋は面を削る道具で、打ち込む対象にはならない。", "金槌": "金槌は打つ道具で、打ち込まれる対象としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "楔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁に楔を打ち込んで、額縁を掛けた。", "explanation": "ここは〈釘〉の意味。楔は隙間に差し込んで広げたり固定したりする道具で、額を掛けるのには使わない。"}, {"text": "ゴルフで楔を振って、ボールを遠くへ飛ばした。", "explanation": "ここは〈ウェッジ〉（ゴルフクラブ）の意味。楔は隙間に打ち込む道具で、ゴルフクラブの名前ではない。"}, {"text": "嵐の前に、船を楔で港に留めた。", "explanation": "ここは〈錨〉の意味。楔は隙間に打ち込む道具で、船を港に留める用途では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52890, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楔", "is_correct": true, "explanation": "「市場に楔を打ち込む」は、独占を崩す比喩として自然。"}, {"text": "梃子", "is_correct": false, "explanation": "梃子は支点で力を加える道具で、市場に打ち込むものではない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は錠に差すもので、市場に打ち込むものとしては意味が通らない。"}, {"text": "滑車", "is_correct": false, "explanation": "滑車は回して力を伝える道具で、打ち込むことはできない。"}], "explanations": {"楔": "「市場に楔を打ち込む」は、独占を崩す比喩として自然。", "梃子": "梃子は支点で力を加える道具で、市場に打ち込むものではない。", "鍵": "鍵は錠に差すもので、市場に打ち込むものとしては意味が通らない。", "滑車": "滑車は回して力を伝える道具で、打ち込むことはできない。"}, "sentence_index": 6, "correct_answer": "楔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "散歩の前に、犬を楔でつないでおいた。", "explanation": "ここは〈鎖〉の意味。楔は隙間に打ち込む道具で、動物をつなぐ用途では使わない。"}, {"text": "封筒のふたを、楔で貼りつけた。", "explanation": "ここは〈糊〉の意味。楔は隙間に打ち込んで固定する道具で、紙を貼る用途では使わない。"}, {"text": "書類の束を、楔で留めた。", "explanation": "ここは〈ホチキス〉の意味。楔は隙間に打ち込む道具で、紙を綴じる用途では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52890, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "柱の根元に楔に打ち込んで、ぐらつきを止めた。", "corrected_sentence": "柱の根元に楔を打ち込んで、ぐらつきを止めた。", "error_description": "正しくは「楔を打ち込んで」。打ち込む対象は「を」で示すので、「楔に」は格助詞の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52890, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い床板の隙間に楔を打ち込むで、きしみを止めた。", "corrected_sentence": "古い床板の隙間に楔を打ち込んで、きしみを止めた。", "error_description": "正しくは「打ち込んで」。動詞「打ち込む」の接続形は「打ち込んで」で、「打ち込むで」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
