INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52891, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "美しいものや芸術を味わうことに関する、という意味。", "primary_collocate": null, "pronunciation": "しんび", "ipa": "ɕimbi", "syllable_count": 3, "sentences": [{"text": "美術館で絵を見るのは、私にとって審美的な楽しみだ。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で絵[え]を見[み]るのは、私[わたし]にとって審美的[しんびてき]な楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "祖母は審美的な趣味が高く、毎朝庭の花を眺めている。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "祖母[そぼ]は審美的[しんびてき]な趣味[しゅみ]が高[たか]く、毎朝[まいあさ]庭[にわ]の花[はな]を眺[なが]めている。", "sentence_source": "generated"}, {"text": "音楽や絵画を味わうことは、審美的な経験と呼ばれる。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "音楽[おんがく]や絵画[かいが]を味[あじ]わうことは、審美的[しんびてき]な経験[けいけん]と呼[よ]ばれる。", "sentence_source": "generated"}, {"text": "審美的な喜びを求めて、週末に陶器の展覧会へ行った。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "審美的[しんびてき]な喜[よろこ]びを求[もと]めて、週末[しゅうまつ]に陶器[とうき]の展覧会[てんらんかい]へ行[い]った。", "sentence_source": "generated"}, {"text": "その詩人は、自然の中に審美的な満足を見いだした。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "その詩人[しじん]は、自然[しぜん]の中[なか]に審美的[しんびてき]な満足[まんぞく]を見[み]いだした。", "sentence_source": "generated"}, {"text": "子どもに審美的な感覚を育てるために、本物の芸術を見せたい。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "子[こ]どもに審美[しんび]的[てき]な感覚[かんかく]を育[そだ]てるために、本物[ほんもの]の芸術[げいじゅつ]を見[み]せたい。", "sentence_source": "generated"}, {"text": "この授業では、芸術を審美的に味わう方法を学ぶ。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "この授業[じゅぎょう]では、芸術[げいじゅつ]を審美的[しんびてき]に味[あじ]わう方法[ほうほう]を学[まな]ぶ。", "sentence_source": "generated"}, {"text": "彼の文章は内容より審美的な魅力で読者を引きつける。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "彼[かれ]の文章[ぶんしょう]は内容[ないよう]より審美的[しんびてき]な魅力[みりょく]で読者[どくしゃ]を引[ひ]きつける。", "sentence_source": "generated"}, {"text": "能の舞台は、見る人に審美的な感動を与える。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "能[のう]の舞台[ぶたい]は、見[み]る人[ひと]に審美的[しんびてき]な感動[かんどう]を与[あた]える。", "sentence_source": "generated"}, {"text": "審美的な体験は、忙しい毎日の心を落ち着かせてくれる。", "target_word": "審美的", "complexity_tier": "T3", "furigana": "審美的[しんびてき]な体験[たいけん]は、忙[いそが]しい毎日[まいにち]の心[こころ]を落[お]ち着[つ]かせてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "審美", "label": "基本形"}, {"form": "審美的", "label": "形状詞化(的)"}, {"form": "審美的な", "label": "連体形"}, {"form": "審美的に", "label": "連用形"}], "register": "formal", "sense_fingerprint": "美しいものや芸術を味わうことに関する。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52891, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "審美的", "is_correct": true, "explanation": "「私にとって審美的な楽しみ」は、美しさを味わう楽しみを表し、ここに入る。"}, {"text": "機械的", "is_correct": false, "explanation": "機械的は融通がきかない様子を表し、美術館で絵を見る楽しみには合わない。"}, {"text": "幾何学的", "is_correct": false, "explanation": "幾何学的は図形や数量の理論に関する語で、楽しみの性質を表すのには合わない。"}, {"text": "化学的", "is_correct": false, "explanation": "化学的は化学の理論や物質に関する語で、ここでは意味が通らない。"}], "explanations": {"審美的": "「私にとって審美的な楽しみ」は、美しさを味わう楽しみを表し、ここに入る。", "機械的": "機械的は融通がきかない様子を表し、美術館で絵を見る楽しみには合わない。", "幾何学的": "幾何学的は図形や数量の理論に関する語で、楽しみの性質を表すのには合わない。", "化学的": "化学的は化学の理論や物質に関する語で、ここでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "審美的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この株は審美的に割安で、今が買い時だ。", "explanation": "ここは〈経済的〉の意味。審美的は美しさや芸術的価値に関する語で、株価の割安さには使わない。"}, {"text": "この店は審美的に清潔で、客が安心できる。", "explanation": "ここは〈衛生的〉の意味。審美的は美しさの感じ取りに関する語で、清潔さや安全性を言うのには使わない。"}, {"text": "この問題は審美的に解けば答えが出る。", "explanation": "ここは〈数学的〉の意味。審美的は美しさや芸術に関する語で、問題を解く方法には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52891, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "審美的", "is_correct": true, "explanation": "「芸術を審美的に味わう」は、美しさを感じ取る仕方を表し、ここに入る。"}, {"text": "地質学的", "is_correct": false, "explanation": "地質学的は大地の成り立ちに関する語で、芸術を味わう方法には結びつかない。"}, {"text": "植物学的", "is_correct": false, "explanation": "植物学的は植物に関する語で、芸術の味わい方には合わない。"}, {"text": "考古学的", "is_correct": false, "explanation": "考古学的は遺跡や古代の研究に関する語で、芸術の味わい方には合わない。"}], "explanations": {"審美的": "「芸術を審美的に味わう」は、美しさを感じ取る仕方を表し、ここに入る。", "地質学的": "地質学的は大地の成り立ちに関する語で、芸術を味わう方法には結びつかない。", "植物学的": "植物学的は植物に関する語で、芸術の味わい方には合わない。", "考古学的": "考古学的は遺跡や古代の研究に関する語で、芸術の味わい方には合わない。"}, "sentence_index": 6, "correct_answer": "審美的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の議事録を、審美的な方法で整理した。", "explanation": "ここは〈事務的〉の意味。審美的は美しさの感じ取りに関する語で、書類の整理の仕方には合わない。"}, {"text": "彼は審美的になって、会議で大声を出した。", "explanation": "ここは〈感情的〉の意味。審美的は美しさの感じ取りに関する語で、怒りや興奮の状態は表さない。"}, {"text": "この部品は審美的に大量生産されている。", "explanation": "ここは〈工業的〉の意味。審美的は美しさや芸術に関する語で、機械による大量生産には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52891, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は美術館をめぐり、審美的の喜びを味わう。", "corrected_sentence": "週末は美術館をめぐり、審美的な喜びを味わう。", "error_description": "正しくは「審美的な喜び」。形状詞は後ろの名詞に「な」を付けて修飾し、「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52891, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この展示は作品を審美的を並べている。", "corrected_sentence": "この展示は作品を審美的に並べている。", "error_description": "正しくは「審美的に並べている」。「並べる」を修飾する連用形は「に」で、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52893, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「結ぶ」の対象を示す「を」で、「靴紐を結ぶ」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、結ぶ動作の対象にはならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ連体修飾で、動詞「結ぶ」の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示し、結ぶ動作の対象としては不自然。"}], "correct_answer": "を", "explanations": {"を": "「結ぶ」の対象を示す「を」で、「靴紐を結ぶ」が正しい。", "が": "「が」は主語を示すため、結ぶ動作の対象にはならず不自然。", "の": "「の」は名詞をつなぐ連体修飾で、動詞「結ぶ」の目的語にはならない。", "と": "「と」は相手や並列を示し、結ぶ動作の対象としては不自然。"}, "error_tags": {"が": "主格（対象に不適）", "の": "連体修飾（目的語に不適）", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
