INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52893, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くつのひもです。", "primary_collocate": null, "pronunciation": "くつひも", "ipa": "kɯtsɯçimo", "syllable_count": 4, "sentences": [{"text": "靴紐がほどけたよ、と友だちが教えてくれた。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "靴紐[くつひも]がほどけたよ、と友[とも]だちが教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "娘は毎朝、自分で靴紐を結ぶ練習をしている。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "娘[むすめ]は毎朝[まいあさ]、自分[じぶん]で靴紐[くつひも]を結[むす]ぶ練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "運動会の日、靴紐が切れて困った。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の日[ひ]、靴紐[くつひも]が切[き]れて困[こま]った。", "sentence_source": "generated"}, {"text": "スニーカーの靴紐をピンク色のものに替えた。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "スニーカーの靴紐[くつひも]をピンク色[いろ]のものに替[か]えた。", "sentence_source": "generated"}, {"text": "靴紐を結ぶと、足がしっかり固定されて走りやすい。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "靴紐[くつひも]を結[むす]ぶと、足[あし]がしっかり固定[こてい]されて走[はし]りやすい。", "sentence_source": "generated"}, {"text": "店で新しい靴紐を二本買った。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "店[みせ]で新[あたら]しい靴紐[くつひも]を二本[にほん]買[か]った。", "sentence_source": "generated"}, {"text": "靴紐が長すぎるので、少し短く切った。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "靴紐[くつひも]が長[なが]すぎるので、少[すこ]し短[みじか]く切[き]った。", "sentence_source": "generated"}, {"text": "靴を脱ぐときは、先に靴紐をゆるめると楽だ。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "靴[くつ]を脱[ぬ]ぐときは、先[さき]に靴紐[くつひも]をゆるめると楽[らく]だ。", "sentence_source": "generated"}, {"text": "祖父は靴紐を二重に結んで、散歩に出かけた。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "祖父[そふ]は靴紐[くつひも]を二重[にじゅう]に結[むす]んで、散歩[さんぽ]に出[で]かけた。", "sentence_source": "generated"}, {"text": "靴紐が濡れて重くなったので、乾かしておいた。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "靴紐[くつひも]が濡[ぬ]れて重[おも]くなったので、乾[かわ]かしておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "靴紐", "label": "基本形"}, {"form": "靴ひも", "label": "混ぜ書き表記"}, {"form": "くつひも", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "靴につけて結ぶ紐。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52893, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "靴紐", "is_correct": true, "explanation": "ほどける対象として文脈に合い、友だちが知らせた内容とつながる。"}, {"text": "靴べら", "is_correct": false, "explanation": "靴べらはほどけるものではないので、文脈に合わない。"}, {"text": "靴底", "is_correct": false, "explanation": "靴底がほどけるとは言わないので、この文脈では不自然。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪はほどけるものではないので、ほどけたよという文脈に合わない。"}], "explanations": {"靴紐": "ほどける対象として文脈に合い、友だちが知らせた内容とつながる。", "靴べら": "靴べらはほどけるものではないので、文脈に合わない。", "靴底": "靴底がほどけるとは言わないので、この文脈では不自然。", "指輪": "指輪はほどけるものではないので、ほどけたよという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "靴紐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、靴紐を二重にはめて出かけた。", "explanation": "ここは〈手袋〉の意味。靴紐は手にはめる物ではないので合わない。"}, {"text": "腕時計の靴紐を新しいものに替えた。", "explanation": "ここは〈ベルト〉の意味。靴紐は腕時計には付かないので合わない。"}, {"text": "朝ごはんに、靴紐を味噌汁の具として入れた。", "explanation": "ここは〈具材〉の意味。靴紐は食べられないので、料理の具材としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52893, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "靴紐", "is_correct": true, "explanation": "長すぎるので短く切るという文脈に合う、切る対象の紐。"}, {"text": "窓", "is_correct": false, "explanation": "窓が長すぎるので短く切るという文脈は不自然で、合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "屋根が長すぎて短く切るという文脈は成立しないので合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は長さを切って調整する物ではないので、文脈に合わない。"}], "explanations": {"靴紐": "長すぎるので短く切るという文脈に合う、切る対象の紐。", "窓": "窓が長すぎるので短く切るという文脈は不自然で、合わない。", "屋根": "屋根が長すぎて短く切るという文脈は成立しないので合わない。", "花瓶": "花瓶は長さを切って調整する物ではないので、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "靴紐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い朝は、靴紐を首に巻いて出かけた。", "explanation": "ここは〈マフラー〉の意味。靴紐は首に巻く物ではないので合わない。"}, {"text": "床が汚れたので、靴紐をよく絞って拭いた。", "explanation": "ここは〈雑巾〉の意味。靴紐は拭く道具ではないので合わない。"}, {"text": "古い家の屋根を、靴紐で葺き直した。", "explanation": "ここは〈瓦〉の意味。靴紐は屋根を葺く材料ではないので、この文脈では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52893, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は毎朝、靴紐に自分で結ぶ練習をしている。", "corrected_sentence": "妹は毎朝、靴紐を自分で結ぶ練習をしている。", "error_description": "「結ぶ」の目的語には「を」を使う。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52893, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は靴紐を結ぶで、近所の店へ出かけた。", "corrected_sentence": "祖父は靴紐を結んで、近所の店へ出かけた。", "error_description": "「結ぶ」の連用形からつなぐ「て」の形は「結んで」が正しい。「結ぶで」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52894, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「結び直す」の対象を示す「を」で、「靴紐を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、結び直す動作の対象にはならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾で、動詞「結び直す」の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、結び直す対象にはならないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「結び直す」の対象を示す「を」で、「靴紐を」が正しい。", "が": "「が」は主語を示すため、結び直す動作の対象にはならず不自然。", "の": "「の」は連体修飾で、動詞「結び直す」の目的語にはならない。", "へ": "「へ」は方向を示し、結び直す対象にはならないので合わない。"}, "error_tags": {"が": "主格（対象に不適）", "の": "連体修飾（目的語に不適）", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52894, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「通す」の対象を示す「を」で、「靴紐を通す」が正しい。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、通す動作の対象を示せないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ連体修飾で、通す動作の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示し、通す動作の対象にはならないので不自然。"}], "correct_answer": "を", "explanations": {"を": "「通す」の対象を示す「を」で、「靴紐を通す」が正しい。", "より": "「より」は比較を表し、通す動作の対象を示せないので合わない。", "の": "「の」は名詞をつなぐ連体修飾で、通す動作の目的語にはならない。", "と": "「と」は相手や並列を示し、通す動作の対象にはならないので不自然。"}, "error_tags": {"より": "比較", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52894, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "靴を足に固定するための紐。通例、左右一対の靴の甲の部分に通して結ぶ。", "primary_collocate": null, "pronunciation": "くつひも", "ipa": "kɯtsɯçimo", "syllable_count": 4, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "靴紐", "complexity_tier": "T4", "furigana": "靴紐[くつひも]を固[かた]く結[むす]び、踵[かかと]で床[ゆか]を鳴[な]らせば、鈍[にぶ]い音[おと]が魂[たましい]の鼓動[こどう]と共鳴[きょうめい]する。", "sentence_source": "mined"}, {"text": "走る前に、靴紐をもう一度きつく結び直した。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "走[はし]る前[まえ]に、靴紐[くつひも]をもう一度[いちど]きつく結[むす]び直[なお]した。", "sentence_source": "generated"}, {"text": "靴紐がほどけていたので、道の端でしゃがんで結んだ。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "靴紐[くつひも]がほどけていたので、道[みち]の端[はし]でしゃがんで結[むす]んだ。", "sentence_source": "generated"}, {"text": "古くなった靴紐が切れて、新しいものに替えた。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "古[ふる]くなった靴紐[くつひも]が切[き]れて、新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "弟はまだ靴紐を上手に結べないので、母が手伝っている。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "弟[おとうと]はまだ靴紐[くつひも]を上手[じょうず]に結[むす]べないので、母[はは]が手伝[てつだ]っている。", "sentence_source": "generated"}, {"text": "長い靴紐を使うと、蝶結びが大きくなって目立つ。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "長[なが]い靴紐[くつひも]を使[つか]うと、蝶結[ちょうむす]びが大[おお]きくなって目立[めだ]つ。", "sentence_source": "generated"}, {"text": "靴紐を踏んで転ばないように、余った部分は中に入れた。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "靴紐[くつひも]を踏[ふ]んで転[ころ]ばないように、余[あま]った部分[ぶぶん]は中[なか]に入[い]れた。", "sentence_source": "generated"}, {"text": "白い靴に赤い靴紐を通すと、足元が明るい印象になる。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "白[しろ]い靴[くつ]に赤[あか]い靴紐[くつひも]を通[とお]すと、足元[あしもと]が明[あか]るい印象[いんしょう]になる。", "sentence_source": "generated"}, {"text": "登山の前に、靴紐が緩んでいないか確認する。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "登山[とざん]の前[まえ]に、靴紐[くつひも]が緩[ゆる]んでいないか確認[かくにん]する。", "sentence_source": "generated"}, {"text": "靴紐の先が取れてしまって、穴に通しにくい。", "target_word": "靴紐", "complexity_tier": "T3", "furigana": "靴紐[くつひも]の先[さき]が取[と]れてしまって、穴[あな]に通[とお]しにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "靴紐", "label": "基本形"}, {"form": "靴ひも", "label": "混ぜ書き表記"}, {"form": "くつひも", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "靴を足に固定するため、甲の部分に通して結ぶ紐。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 踵 (Zipf 3.15), 鳴らせ (Zipf 3.25), 鈍い (Zipf 3.23), 共鳴 (Zipf 3.38)','sentence 5 above tier T3: contains vocabulary far above tier T3: 蝶結び (Zipf 1.78)']::text[], '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52894, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "靴紐", "is_correct": true, "explanation": "固く結ぶ対象であり、踵で床を鳴らす動きと結びつく道具として文脈に合う。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下を固く結んで音を出すという文脈は不自然で、合わない。"}, {"text": "靴底", "is_correct": false, "explanation": "靴底は結ぶものではないので、固く結ぶ文脈に合わない。"}, {"text": "靴べら", "is_correct": false, "explanation": "靴べらは靴を履くための補助具で、結んで固定する物ではないため合わない。"}], "explanations": {"靴紐": "固く結ぶ対象であり、踵で床を鳴らす動きと結びつく道具として文脈に合う。", "靴下": "靴下を固く結んで音を出すという文脈は不自然で、合わない。", "靴底": "靴底は結ぶものではないので、固く結ぶ文脈に合わない。", "靴べら": "靴べらは靴を履くための補助具で、結んで固定する物ではないため合わない。"}, "sentence_index": 0, "correct_answer": "靴紐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "靴紐を耳たぶに通して、ピアスにした。", "explanation": "ここは〈ピアス〉の意味。靴紐は耳に付ける装飾品ではないので、この使い方は合わない。"}, {"text": "眠る前に、靴紐を枕の代わりに頭の下へ敷いた。", "explanation": "ここは〈枕〉の意味。靴紐は頭を載せる物ではないので、この使い方は合わない。"}, {"text": "昼ごはんのスープを、靴紐でかき混ぜた。", "explanation": "ここは〈おたま〉の意味。靴紐は料理をかき混ぜる道具ではないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52894, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "靴紐", "is_correct": true, "explanation": "踏んで転ばないように余った部分を中に入れる、という文脈の対象として合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓を踏んで転ばないように、余った部分を中に入れるという文脈は成立しない。"}, {"text": "屋根", "is_correct": false, "explanation": "屋根を踏むことと余った部分を中に入れることは結びつかず、合わない。"}, {"text": "壁", "is_correct": false, "explanation": "壁は踏んで転ぶ対象ではなく、余った部分を中に入れる文脈に合わない。"}], "explanations": {"靴紐": "踏んで転ばないように余った部分を中に入れる、という文脈の対象として合う。", "窓": "窓を踏んで転ばないように、余った部分を中に入れるという文脈は成立しない。", "屋根": "屋根を踏むことと余った部分を中に入れることは結びつかず、合わない。", "壁": "壁は踏んで転ぶ対象ではなく、余った部分を中に入れる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "靴紐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "縫い物で、靴紐に糸を通すのがうまくできない。", "explanation": "ここは〈針〉の場面。靴紐は糸を通す道具ではないので、この使い方は合わない。"}, {"text": "靴紐の底がすり減ってしまったので、新しく買い替えた。", "explanation": "ここは〈靴底〉の意味。靴紐には底がないので合わない。"}, {"text": "バッグの靴紐が切れてしまって、穴に通しにくい。", "explanation": "ここは〈ストラップ〉の意味。靴紐はバッグには付かないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52894, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試合の前に、靴紐が丁寧に結んだ。", "corrected_sentence": "試合の前に、靴紐を丁寧に結んだ。", "error_description": "「結ぶ」の目的語には「を」を使う。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52894, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ほどけた靴紐に踏まないように、余った部分は中に入れた。", "corrected_sentence": "ほどけた靴紐を踏まないように、余った部分は中に入れた。", "error_description": "「踏む」の目的語には「を」を使う。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52895, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服従", "is_correct": true, "explanation": "反逆の対義語で、ルールや上の人に従うことを表すため、この意味と対になる。"}, {"text": "挑戦", "is_correct": false, "explanation": "新しいことに向かう行為であり、反逆の対義語ではない。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠る行為で、反逆と対になる関係ではない。"}, {"text": "反省", "is_correct": false, "explanation": "自分を振り返る行為で、反逆の対義語にはならない。"}], "correct_answer": "服従", "explanations": {"服従": "反逆の対義語で、ルールや上の人に従うことを表すため、この意味と対になる。", "挑戦": "新しいことに向かう行為であり、反逆の対義語ではない。", "睡眠": "眠る行為で、反逆と対になる関係ではない。", "反省": "自分を振り返る行為で、反逆の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52895, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服従", "is_correct": true, "explanation": "反逆の対義語で、上の人やルールに従うことを表すため、この意味と対になる。"}, {"text": "散歩", "is_correct": false, "explanation": "外を歩く行為で、反逆と対になる関係ではない。"}, {"text": "解散", "is_correct": false, "explanation": "組織を終わらせることを表し、反逆の対義語にはならない。"}, {"text": "監視", "is_correct": false, "explanation": "見張る行為で、反逆と対になる関係ではない。"}], "correct_answer": "服従", "explanations": {"服従": "反逆の対義語で、上の人やルールに従うことを表すため、この意味と対になる。", "散歩": "外を歩く行為で、反逆と対になる関係ではない。", "解散": "組織を終わらせることを表し、反逆の対義語にはならない。", "監視": "見張る行為で、反逆と対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52895, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の上の人やルールに逆らうこと。", "primary_collocate": null, "pronunciation": "はんぎゃく", "ipa": "haŋɡʲaku", "syllable_count": 4, "sentences": [{"text": "部下が上司に反逆するなど、この会社では考えられない。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "部下[ぶか]が上司[じょうし]に反逆[はんぎゃく]するなど、この会社[かいしゃ]では考[かんが]えられない。", "sentence_source": "generated"}, {"text": "兵士たちは隊長に反逆し、命令を拒んだ。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは隊長[たいちょう]に反逆[はんぎゃく]し、命令[めいれい]を拒[こば]んだ。", "sentence_source": "generated"}, {"text": "彼は親に反逆して、家を飛び出した。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "彼[かれ]は親[おや]に反逆[はんぎゃく]して、家[いえ]を飛[と]び出[だ]した。", "sentence_source": "generated"}, {"text": "ルールに反逆する選手は、チームから外された。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "ルールに反逆[はんぎゃく]する選手[せんしゅ]は、チームから外[はず]された。", "sentence_source": "generated"}, {"text": "家臣の反逆に気づいた殿様は、城門を固めさせた。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "家臣[かしん]の反逆[はんぎゃく]に気[き]づいた殿様[とのさま]は、城門[じょうもん]を固[かた]めさせた。", "sentence_source": "generated"}, {"text": "先生に反逆したくなる年ごろだ。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "先生[せんせい]に反逆[はんぎゃく]したくなる年[とし]ごろだ。", "sentence_source": "generated"}, {"text": "王に反逆した貴族は、領地を取り上げられた。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "王[おう]に反逆[はんぎゃく]した貴族[きぞく]は、領地[りょうち]を取[と]り上[あ]げられた。", "sentence_source": "generated"}, {"text": "組織に反逆すれば、ただでは済まない。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "組織[そしき]に反逆[はんぎゃく]すれば、ただでは済[す]まない。", "sentence_source": "generated"}, {"text": "彼女は決まりごとに反逆するような子ではなかった。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は決[き]まりごとに反逆[はんぎゃく]するような子[こ]ではなかった。", "sentence_source": "generated"}, {"text": "部下の反逆を恐れて、社長は人事を急に変えた。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "部下[ぶか]の反逆[はんぎゃく]を恐[おそ]れて、社長[しゃちょう]は人事[じんじ]を急[きゅう]に変[か]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "反逆", "label": "名詞"}, {"form": "反逆する", "label": "辞書形"}, {"form": "反逆した", "label": "過去形"}, {"form": "反逆して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "上の人やルールに逆らう行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52895, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反逆", "is_correct": true, "explanation": "部下が上司に行う逆らう行為として、この会社では考えられないという文脈に合う。"}, {"text": "納品", "is_correct": false, "explanation": "部下が上司に納品するという言い方は不自然で、文脈に合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "解雇は上司が部下に行うもので、部下が上司に行うことにはならないので合わない。"}, {"text": "冷却", "is_correct": false, "explanation": "冷却は物の温度を下げることで、上司への行為として文脈に合わない。"}], "explanations": {"反逆": "部下が上司に行う逆らう行為として、この会社では考えられないという文脈に合う。", "納品": "部下が上司に納品するという言い方は不自然で、文脈に合わない。", "解雇": "解雇は上司が部下に行うもので、部下が上司に行うことにはならないので合わない。", "冷却": "冷却は物の温度を下げることで、上司への行為として文脈に合わない。"}, "sentence_index": 0, "correct_answer": "反逆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空が練習に反逆して、試合は延期になった。", "explanation": "ここは〈天候〉の場面。空は逆らう相手ではないので、反逆は使わない。"}, {"text": "練習の成果が試合に反逆した。", "explanation": "ここは〈反映〉の意味。成果は逆らう主体ではないので、反逆は使わない。"}, {"text": "天気予報に反逆して、雨の中を走った。", "explanation": "ここは〈無視〉の場面。天気予報は逆らう上の人やルールではないので、反逆は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52895, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反逆", "is_correct": true, "explanation": "王に逆らって領地を取り上げられた貴族の行為として、文脈に合う。"}, {"text": "朗読", "is_correct": false, "explanation": "王に朗読したという言い方は不自然で、この文脈には合わない。"}, {"text": "完成", "is_correct": false, "explanation": "王に完成したという言い方は意味が通らず、文脈に合わない。"}, {"text": "検診", "is_correct": false, "explanation": "王に検診するという行為は不自然で、領地を取り上げられる文脈に合わない。"}], "explanations": {"反逆": "王に逆らって領地を取り上げられた貴族の行為として、文脈に合う。", "朗読": "王に朗読したという言い方は不自然で、この文脈には合わない。", "完成": "王に完成したという言い方は意味が通らず、文脈に合わない。", "検診": "王に検診するという行為は不自然で、領地を取り上げられる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "反逆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部下の反逆が、社長の机の書類を吹き飛ばした。", "explanation": "ここは〈風〉の場面。反逆は人の行為で、物を吹き飛ばすものではないので合わない。"}, {"text": "部下の反逆が遅れて届いたので、社長は人事を急に変えた。", "explanation": "ここは〈報告書〉の場面。反逆は届くものではないので、この使い方は合わない。"}, {"text": "部下の反逆を書き写して、社長は人事を急に変えた。", "explanation": "ここは〈書類〉の場面。反逆は書き写すものではないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
