INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52895, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家臣は王に反逆しで、捕らえられた。", "corrected_sentence": "家臣は王に反逆して、捕らえられた。", "error_description": "「する」のて形は「して」。「しで」は活用の誤りで、正しくは「して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52896, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服従", "is_correct": true, "explanation": "反逆の対義語で、支配や権力に従うことを表すため、この意味と対になる。"}, {"text": "挑戦", "is_correct": false, "explanation": "新しいことに向かう行為であり、反逆の対義語ではない。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠る行為で、反逆と対になる関係ではない。"}, {"text": "反省", "is_correct": false, "explanation": "自分を振り返る行為で、反逆の対義語にはならない。"}], "correct_answer": "服従", "explanations": {"服従": "反逆の対義語で、支配や権力に従うことを表すため、この意味と対になる。", "挑戦": "新しいことに向かう行為であり、反逆の対義語ではない。", "睡眠": "眠る行為で、反逆と対になる関係ではない。", "反省": "自分を振り返る行為で、反逆の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52896, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「反逆の精神」の連体修飾にあたり、名詞をつなぐ「の」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、反逆と精神をつなぐ役割にはならないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「反逆へ精神」では成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、反逆と精神をつなぐ形としては不自然。"}], "correct_answer": "の", "explanations": {"の": "「反逆の精神」の連体修飾にあたり、名詞をつなぐ「の」が正しい。", "が": "「が」は主語を示し、反逆と精神をつなぐ役割にはならないので不自然。", "へ": "「へ」は方向を示し、「反逆へ精神」では成り立たない。", "から": "「から」は起点を示し、反逆と精神をつなぐ形としては不自然。"}, "error_tags": {"が": "主格（名詞句に不適）", "へ": "方向（名詞句に不適）", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服従", "is_correct": true, "explanation": "反逆の対義語で、支配や権力に従うことを表すため、この意味と対になる。"}, {"text": "散歩", "is_correct": false, "explanation": "外を歩く行為で、反逆と対になる関係ではない。"}, {"text": "解散", "is_correct": false, "explanation": "組織を終わらせることを表し、反逆の対義語にはならない。"}, {"text": "監視", "is_correct": false, "explanation": "見張る行為で、反逆と対になる関係ではない。"}], "correct_answer": "服従", "explanations": {"服従": "反逆の対義語で、支配や権力に従うことを表すため、この意味と対になる。", "散歩": "外を歩く行為で、反逆と対になる関係ではない。", "解散": "組織を終わらせることを表し、反逆の対義語にはならない。", "監視": "見張る行為で、反逆と対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52896, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "支配や権力に従わず、反対する行為や態度。", "primary_collocate": null, "pronunciation": "はんぎゃく", "ipa": "haŋɡʲaku", "syllable_count": 4, "sentences": [{"text": "それは、灰色に均質化された日常の景観に対し、鮮烈な色彩の楔を打ち込む、個人的かつ審美的な反逆の儀式に他ならない。", "target_word": "反逆", "complexity_tier": "T4", "furigana": "それは、灰色[はいいろ]に均質化[きんしつか]された日常[にちじょう]の景観[けいかん]に対[たい]し、鮮烈[せんれつ]な色彩[しきさい]の楔[くさび]を打[う]ち込[こ]む、個人的[こじんてき]かつ審美的[しんびてき]な反逆[はんぎゃく]の儀式[ぎしき]に他[ほか]ならない。", "sentence_source": "mined"}, {"text": "彼の反逆は、古い体制への静かな抗議から始まった。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "彼[かれ]の反逆[はんぎゃく]は、古[ふる]い体制[たいせい]への静[しず]かな抗議[こうぎ]から始[はじ]まった。", "sentence_source": "generated"}, {"text": "王に対する反逆の罪で、将軍は捕らえられた。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "王[おう]に対[たい]する反逆[はんぎゃく]の罪[つみ]で、将軍[しょうぐん]は捕[と]らえられた。", "sentence_source": "generated"}, {"text": "少年の目には、大人への反逆の気持ちが宿っていた。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "少年[しょうねん]の目[め]には、大人[おとな]への反逆[はんぎゃく]の気持[きも]ちが宿[やど]っていた。", "sentence_source": "generated"}, {"text": "髪を赤く染めたのは、学校の規則に対する小さな反逆だった。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "髪[かみ]を赤[あか]く染[そ]めたのは、学校[がっこう]の規則[きそく]に対[たい]する小[ちい]さな反逆[はんぎゃく]だった。", "sentence_source": "generated"}, {"text": "この小説は、権力への反逆を描いた作品として知られている。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、権力[けんりょく]への反逆[はんぎゃく]を描[えが]いた作品[さくひん]として知[し]られている。", "sentence_source": "generated"}, {"text": "反逆の歌は、抑圧された若者たちの心をとらえた。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "反逆[はんぎゃく]の歌[うた]は、抑圧[よくあつ]された若者[わかもの]たちの心[こころ]をとらえた。", "sentence_source": "generated"}, {"text": "彼は反逆の精神を失わず、最後まで不正と闘った。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "彼[かれ]は反逆[はんぎゃく]の精神[せいしん]を失[うしな]わず、最後[さいご]まで不正[ふせい]と闘[たたか]った。", "sentence_source": "generated"}, {"text": "反逆が失敗に終わり、首謀者たちは国外へ逃れた。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "反逆[はんぎゃく]が失敗[しっぱい]に終[お]わり、首謀者[しゅぼうしゃ]たちは国外[こくがい]へ逃[のが]れた。", "sentence_source": "generated"}, {"text": "親への反逆は、自立への第一歩でもある。", "target_word": "反逆", "complexity_tier": "T3", "furigana": "親[おや]への反逆[はんぎゃく]は、自立[じりつ]への第一歩[だいいっぽ]でもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "反逆", "label": "名詞"}, {"form": "反逆する", "label": "辞書形"}, {"form": "反逆した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "支配や権力に逆らい反対する行為・態度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 均質 (Zipf 2.7), 鮮烈 (Zipf 2.73), 楔 (Zipf 2.53), 打ち込む (Zipf 3.22), 審美 (Zipf 2.76)']::text[], '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52896, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反逆", "is_correct": true, "explanation": "権力に従わない反対の行為として、審美的な儀式を説明する文脈に合う。"}, {"text": "計算", "is_correct": false, "explanation": "「計算の儀式」という言い方は不自然で、この文脈には合わない。"}, {"text": "献辞", "is_correct": false, "explanation": "献辞の儀式という組み合わせは不自然で、この文脈には合わない。"}, {"text": "欠如", "is_correct": false, "explanation": "欠如は不足を表し、鮮烈な色彩を打ち込む儀式の説明には合わない。"}], "explanations": {"反逆": "権力に従わない反対の行為として、審美的な儀式を説明する文脈に合う。", "計算": "「計算の儀式」という言い方は不自然で、この文脈には合わない。", "献辞": "献辞の儀式という組み合わせは不自然で、この文脈には合わない。", "欠如": "欠如は不足を表し、鮮烈な色彩を打ち込む儀式の説明には合わない。"}, "sentence_index": 0, "correct_answer": "反逆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁に当たった音が反逆して、大きく響いた。", "explanation": "ここは〈反響〉の意味。音の跳ね返りには反逆を使わないので合わない。"}, {"text": "光が鏡に反逆して、まぶしかった。", "explanation": "ここは〈反射〉の意味。光の跳ね返りには反逆を使わないので合わない。"}, {"text": "会議で相手の意見に反逆した。", "explanation": "ここは〈反論〉の意味。議論での言い返しには反逆を使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52896, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反逆", "is_correct": true, "explanation": "抑圧された若者の心をとらえた、反抗的な歌を表す文脈に合う。"}, {"text": "誤差", "is_correct": false, "explanation": "誤差の歌という言い方は不自然で、文脈に合わない。"}, {"text": "欠陥", "is_correct": false, "explanation": "欠陥の歌という組み合わせは意味が通らず、この文脈には合わない。"}, {"text": "停滞", "is_correct": false, "explanation": "停滞は動かないことを表し、若者の心をとらえる反抗的な歌には合わない。"}], "explanations": {"反逆": "抑圧された若者の心をとらえた、反抗的な歌を表す文脈に合う。", "誤差": "誤差の歌という言い方は不自然で、文脈に合わない。", "欠陥": "欠陥の歌という組み合わせは意味が通らず、この文脈には合わない。", "停滞": "停滞は動かないことを表し、若者の心をとらえる反抗的な歌には合わない。"}, "sentence_index": 6, "correct_answer": "反逆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の花が反逆して、一晩で枯れてしまった。", "explanation": "ここは〈枯れる〉の意味。花は逆らう主体ではないので、反逆は使わない。"}, {"text": "二人は笑顔で握手して、反逆の仕事を終えた。", "explanation": "ここは〈協力〉の意味。反逆は逆らうことで、仲よく仕事を終えた場面には合わない。"}, {"text": "強い風に反逆して、一歩ずつ進んだ。", "explanation": "ここは〈抵抗〉の意味。自然現象には反逆を使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52896, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王への反逆に企てた家臣は、城から追放された。", "corrected_sentence": "王への反逆を企てた家臣は、城から追放された。", "error_description": "「企てる」の目的語には「を」を使う。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52896, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家臣たちは王に反逆を企てで、捕らえられた。", "corrected_sentence": "家臣たちは王に反逆を企てて、捕らえられた。", "error_description": "「企てて」のて形が正しい。「企てで」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52897, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「銃弾を」の「を」で、打ち込む対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では、銃弾を打つ対象を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、銃弾が打ち込まれる対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の「より」では、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「銃弾を」の「を」で、打ち込む対象を示す。", "へ": "方向の「へ」では、銃弾を打つ対象を表せない。", "から": "起点の「から」では、銃弾が打ち込まれる対象にならない。", "より": "比較・起点の「より」では、対象を示せない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較・起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52897, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「幹に」の「に」で、弾が刺さった場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「木の幹が」と主語にすると、弾が刺さった場所を示せない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示す「と」では、場所を表せない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では、打ち込まれる場所を示す働きにならない。"}], "correct_answer": "に", "explanations": {"に": "「幹に」の「に」で、弾が刺さった場所を示す。", "が": "「木の幹が」と主語にすると、弾が刺さった場所を示せない。", "と": "相手や引用を示す「と」では、場所を表せない。", "の": "連体修飾の「の」では、打ち込まれる場所を示す働きにならない。"}, "error_tags": {"が": "主語", "と": "相手・引用", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52897, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを強く押して中に入れること。", "primary_collocate": null, "pronunciation": "うちこむ", "ipa": "ɯtɕikomɯ", "syllable_count": 4, "sentences": [{"text": "弓兵が放った矢は、盾の中央に深く打ち込まれた。", "target_word": "打ち込まれた", "complexity_tier": "T3", "furigana": "弓兵[きゅうへい]が放[はな]った矢[や]は、盾[たて]の中央[ちゅうおう]に深[ふか]く打[う]ち込[こ]まれた。", "sentence_source": "generated"}, {"text": "彼は的の中心に銃弾を打ち込んだ。", "target_word": "打ち込んだ", "complexity_tier": "T3", "furigana": "彼[かれ]は的[まと]の中心[ちゅうしん]に銃弾[じゅうだん]を打[う]ち込[こ]んだ。", "sentence_source": "generated"}, {"text": "地面に鉄の棒を打ち込んで、土の深さを調べた。", "target_word": "打ち込んで", "complexity_tier": "T3", "furigana": "地面[じめん]に鉄[てつ]の棒[ぼう]を打[う]ち込[こ]んで、土[つち]の深[ふか]さを調[しら]べた。", "sentence_source": "generated"}, {"text": "工事の人が機械で鉄の杭を地中に打ち込んでいる。", "target_word": "打ち込んで", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が機械[きかい]で鉄[てつ]の杭[くい]を地中[ちちゅう]に打[う]ち込[こ]んでいる。", "sentence_source": "generated"}, {"text": "彼女は壁に大きな釘を強く打ち込んだ。", "target_word": "打ち込んだ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は壁[かべ]に大[おお]きな釘[くぎ]を強[つよ]く打[う]ち込[こ]んだ。", "sentence_source": "generated"}, {"text": "コンクリートにボルトを打ち込む前に、穴を開けておく。", "target_word": "打ち込む", "complexity_tier": "T3", "furigana": "コンクリートにボルトを打[う]ち込[こ]む前[まえ]に、穴[あな]を開[あ]けておく。", "sentence_source": "generated"}, {"text": "雪山で、登山家は氷の壁にピッケルを打ち込んだ。", "target_word": "打ち込んだ", "complexity_tier": "T3", "furigana": "雪山[ゆきやま]で、登山家[とざんか]は氷[こおり]の壁[かべ]にピッケルを打[う]ち込[こ]んだ。", "sentence_source": "generated"}, {"text": "犯人が撃った弾は、木の幹に打ち込まれていた。", "target_word": "打ち込まれて", "complexity_tier": "T3", "furigana": "犯人[はんにん]が撃[う]った弾[たま]は、木[き]の幹[みき]に打[う]ち込[こ]まれていた。", "sentence_source": "generated"}, {"text": "職人は丸太に鉄の輪を打ち込んで、割れを防いだ。", "target_word": "打ち込んで", "complexity_tier": "T3", "furigana": "職人[しょくにん]は丸太[まるた]に鉄[てつ]の輪[わ]を打[う]ち込[こ]んで、割[わ]れを防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "地盤が固くて、機械でも杭がなかなか打ち込めない。", "target_word": "打ち込め", "complexity_tier": "T3", "furigana": "地盤[じばん]が固[かた]くて、機械[きかい]でも杭[くい]がなかなか打[う]ち込[こ]めない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "打ち込む", "label": "辞書形"}, {"form": "打ち込んだ", "label": "過去形"}, {"form": "打ち込んで", "label": "て形"}, {"form": "打ち込まれた", "label": "受身過去形"}, {"form": "打ち込めない", "label": "可能否定形"}], "register": "neutral", "sense_fingerprint": "物を強い力で押し入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52897, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打ち込まれた", "is_correct": true, "explanation": "受身の過去形。矢が盾に刺さる出来事と合い、主語の「矢は」に対応する。"}, {"text": "打ち消された", "is_correct": false, "explanation": "否定・取り消しの受身。矢が打ち消されるという文にはならない。"}, {"text": "打ち明けられた", "is_correct": false, "explanation": "打ち明けるの受身。矢は秘密を話せないので合わない。"}, {"text": "打ち切られた", "is_correct": false, "explanation": "途中で終わらされる受身。矢が盾に対して打ち切られる文にはならない。"}], "explanations": {"打ち込まれた": "受身の過去形。矢が盾に刺さる出来事と合い、主語の「矢は」に対応する。", "打ち消された": "否定・取り消しの受身。矢が打ち消されるという文にはならない。", "打ち明けられた": "打ち明けるの受身。矢は秘密を話せないので合わない。", "打ち切られた": "途中で終わらされる受身。矢が盾に対して打ち切られる文にはならない。"}, "sentence_index": 0, "correct_answer": "打ち込まれた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍵穴に鍵を打ち込んだ。", "explanation": "ここは〈差し込む〉の場面。鍵は勢いよく打つ物ではなく、そっと差す物なので〈打ち込む〉とは言わない。"}, {"text": "庭に球根を打ち込んだ。", "explanation": "ここは〈埋める〉の場面。球根は打ち込む物ではなく埋める物なので、〈打ち込む〉とは言わない。"}, {"text": "ホワイトボードに地図を打ち込んだ。", "explanation": "ここは〈貼る〉の場面。紙の地図は打ち込む物ではないので、〈打ち込む〉の使い方ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52897, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打ち込んだ", "is_correct": true, "explanation": "正解。「ピッケルを」と対象があり、氷の壁に突き刺す意味に合う。"}, {"text": "打ち上げた", "is_correct": false, "explanation": "空へ打ち出す意味。氷の壁にピッケルを打ち上げる文にはならない。"}, {"text": "打ち鳴らした", "is_correct": false, "explanation": "音を鳴らす意味。ピッケルを鳴らすという文にはならない。"}, {"text": "打ち返した", "is_correct": false, "explanation": "打たれたものを打ち返す意味。氷の壁に対して使える動作ではない。"}], "explanations": {"打ち込んだ": "正解。「ピッケルを」と対象があり、氷の壁に突き刺す意味に合う。", "打ち上げた": "空へ打ち出す意味。氷の壁にピッケルを打ち上げる文にはならない。", "打ち鳴らした": "音を鳴らす意味。ピッケルを鳴らすという文にはならない。", "打ち返した": "打たれたものを打ち返す意味。氷の壁に対して使える動作ではない。"}, "sentence_index": 6, "correct_answer": "打ち込んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "布にボタンを打ち込んだ。", "explanation": "ここは〈縫い付ける〉の場面。ボタンは打ち込む物ではなく縫い付ける物なので、〈打ち込む〉は使わない。"}, {"text": "パンにバターを打ち込んだ。", "explanation": "ここは〈塗る〉の場面。バターは打ち込む物ではなく塗る物なので、〈打ち込む〉とは言わない。"}, {"text": "袋に服を打ち込んだ。", "explanation": "ここは〈押し込む〉の場面。衣服は打って入れる物ではないので、〈打ち込む〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52897, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大工が太い柱に鉄の輪が打ち込んだ。", "corrected_sentence": "大工が太い柱に鉄の輪を打ち込んだ。", "error_description": "目的語を示す「を」が正しいのに「が」を使っている。鉄の輪は打ち込まれる対象なので「を」が必要で、「が」だと鉄の輪が主語になり文が合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "打ち込んだ", "is_correct": true, "explanation": "過去形。的に銃弾を撃ち込んだという完了の事実を表す。"}, {"text": "打ち込もう", "is_correct": false, "explanation": "意志形。完了した動作の報告として合わない。"}, {"text": "打ち込めば", "is_correct": false, "explanation": "仮定形。条件節で終わるため、過去の報告文として成り立たない。"}, {"text": "打ち込まれる", "is_correct": false, "explanation": "受身の非過去形。銃弾が撃たれる側になり、主語「彼は」の動作と合わない。"}], "correct_form": "打ち込んだ", "base_form": "打ち込む", "form_label": "過去形", "sentence_index": 1, "explanations": {"打ち込んだ": "過去形。的に銃弾を撃ち込んだという完了の事実を表す。", "打ち込もう": "意志形。完了した動作の報告として合わない。", "打ち込めば": "仮定形。条件節で終わるため、過去の報告文として成り立たない。", "打ち込まれる": "受身の非過去形。銃弾が撃たれる側になり、主語「彼は」の動作と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52897, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "職人は作業場の床に鉄の釘を打ち込むた。", "corrected_sentence": "職人は作業場の床に鉄の釘を打ち込んだ。", "error_description": "活用の誤り。「た」は「打ち込んだ」の形で続くので、「打ち込むた」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "打ち込まれて", "is_correct": true, "explanation": "受身のて形。弾が木の幹に打ち込まれた状態を表し、主語の「弾は」と合う。"}, {"text": "打ち込んで", "is_correct": false, "explanation": "能動のて形。弾が打つ側になり、受身の状態を表さない。"}, {"text": "打ち込まない", "is_correct": false, "explanation": "否定形。打ち込まれた事実を否定することになり、文の意味と合わない。"}, {"text": "打ち込めた", "is_correct": false, "explanation": "可能過去形。できたという意味になり、弾が刺さった状態と合わない。"}], "correct_form": "打ち込まれて", "base_form": "打ち込む", "form_label": "受身て形", "sentence_index": 7, "explanations": {"打ち込まれて": "受身のて形。弾が木の幹に打ち込まれた状態を表し、主語の「弾は」と合う。", "打ち込んで": "能動のて形。弾が打つ側になり、受身の状態を表さない。", "打ち込まない": "否定形。打ち込まれた事実を否定することになり、文の意味と合わない。", "打ち込めた": "可能過去形。できたという意味になり、弾が刺さった状態と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52898, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「釘を」の「を」で、打ち込む対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「釘が」と主語にすると、釘が自分で打ち込んだことになり文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「柱に」とすでに場所があり、「釘に」では「に」が重なって対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すので、「釘と打ち込んだ」では動作の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「釘を」の「を」で、打ち込む対象を示す。", "が": "「釘が」と主語にすると、釘が自分で打ち込んだことになり文として不自然。", "に": "「柱に」とすでに場所があり、「釘に」では「に」が重なって対象を表せない。", "と": "「と」は並列や相手を表すので、「釘と打ち込んだ」では動作の対象にならない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52898, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「釘を」の「を」で、打ち込む対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、釘を打ち込む対象を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「釘から打ち込み」の対象関係にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の「より」では、釘を打ち込む対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「釘を」の「を」で、打ち込む対象を示す。", "へ": "方向を示す「へ」では、釘を打ち込む対象を表せない。", "から": "起点の「から」では「釘から打ち込み」の対象関係にならない。", "より": "比較・起点の「より」では、釘を打ち込む対象を示せない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52898, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を勢いよく打って中に差し込むこと。特に、釘や楔などを打ち込む。", "primary_collocate": null, "pronunciation": "うちこむ", "ipa": "ɯtɕikomɯ", "syllable_count": 4, "sentences": [{"text": "それは、灰色に均質化された日常の景観に対し、鮮烈な色彩の楔を打ち込む、個人的かつ審美的な反逆の儀式に他ならない。", "target_word": "打ち込む", "complexity_tier": "T4", "furigana": "それは、灰色[はいいろ]に均質化[きんしつか]された日常[にちじょう]の景観[けいかん]に対[たい]し、鮮烈[せんれつ]な色彩[しきさい]の楔[くさび]を打[う]ち込[こ]む、個人的[こじんてき]かつ審美的[しんびてき]な反逆[はんぎゃく]の儀式[ぎしき]に他[ほか]ならない。", "sentence_source": "mined"}, {"text": "大工は柱に釘を打ち込んだ。", "target_word": "打ち込んだ", "complexity_tier": "T3", "furigana": "大工[だいく]は柱[はしら]に釘[くぎ]を打[う]ち込[こ]んだ。", "sentence_source": "generated"}, {"text": "岩の割れ目に楔を打ち込んで、石を二つに割った。", "target_word": "打ち込んで", "complexity_tier": "T3", "furigana": "岩[いわ]の割[わ]れ目[め]に楔[くさび]を打[う]ち込[こ]んで、石[いし]を二[ふた]つに割[わ]った。", "sentence_source": "generated"}, {"text": "金づちで板に釘を打ち込む音が、朝から響いている。", "target_word": "打ち込む", "complexity_tier": "T3", "furigana": "金[かな]づちで板[いた]に釘[くぎ]を打[う]ち込[こ]む音[おと]が、朝[あさ]から響[ひび]いている。", "sentence_source": "generated"}, {"text": "父は庭の地面に杭を打ち込み、ロープを張った。", "target_word": "打ち込み", "complexity_tier": "T3", "furigana": "父[ちち]は庭[にわ]の地面[じめん]に杭[くい]を打[う]ち込[こ]み、ロープを張[は]った。", "sentence_source": "generated"}, {"text": "壁にフックを付けるため、ハンマーで釘を打ち込みます。", "target_word": "打ち込みます", "complexity_tier": "T3", "furigana": "壁[かべ]にフックを付[つ]けるため、ハンマーで釘[くぎ]を打[う]ち込[こ]みます。", "sentence_source": "generated"}, {"text": "木の幹に釘を打ち込んではいけません。", "target_word": "打ち込んで", "complexity_tier": "T3", "furigana": "木[き]の幹[みき]に釘[くぎ]を打[う]ち込[こ]んではいけません。", "sentence_source": "generated"}, {"text": "まず印の位置に釘を打ち込み、それから棚を取り付ける。", "target_word": "打ち込み", "complexity_tier": "T3", "furigana": "まず印[しるし]の位置[いち]に釘[くぎ]を打[う]ち込[こ]み、それから棚[たな]を取[と]り付[つ]ける。", "sentence_source": "generated"}, {"text": "彼は石の壁に鋲を打ち込んで、足場を作った。", "target_word": "打ち込んで", "complexity_tier": "T3", "furigana": "彼[かれ]は石[いし]の壁[かべ]に鋲[びょう]を打[う]ち込[こ]んで、足場[あしば]を作[つく]った。", "sentence_source": "generated"}, {"text": "風が強いので、テントの杭を深く打ち込んだ。", "target_word": "打ち込んだ", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]いので、テントの杭[くい]を深[ふか]く打[う]ち込[こ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "打ち込む", "label": "辞書形"}, {"form": "打ち込んだ", "label": "過去形"}, {"form": "打ち込んで", "label": "て形"}, {"form": "打ち込まない", "label": "否定形"}, {"form": "打ち込まれた", "label": "受身過去形"}], "register": "neutral", "sense_fingerprint": "釘や楔を勢いよく打って差し込む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '300e3b4e-e311-4e4c-b11e-25fa525496e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52898, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打ち込む", "is_correct": true, "explanation": "正解。楔を勢いよく差し込むという意味で、文の「楔を」と合う。"}, {"text": "打ち消す", "is_correct": false, "explanation": "否定する・取り消すという意味。楔を取り消すという文にはならない。"}, {"text": "打ち明ける", "is_correct": false, "explanation": "秘密や考えを話すという意味。物である楔には使えない。"}, {"text": "打ち切る", "is_correct": false, "explanation": "途中で終わりにするという意味。「楔を打ち切る」では文として成り立たない。"}], "explanations": {"打ち込む": "正解。楔を勢いよく差し込むという意味で、文の「楔を」と合う。", "打ち消す": "否定する・取り消すという意味。楔を取り消すという文にはならない。", "打ち明ける": "秘密や考えを話すという意味。物である楔には使えない。", "打ち切る": "途中で終わりにするという意味。「楔を打ち切る」では文として成り立たない。"}, "sentence_index": 0, "correct_answer": "打ち込む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "封筒に切手を打ち込んだ。", "explanation": "ここは〈貼る〉の場面。切手は打ち込む物ではなく貼る物なので、〈打ち込む〉とは言わない。"}, {"text": "プラグをコンセントに打ち込んだ。", "explanation": "ここは〈差し込む〉の場面。プラグは打って入れる物ではなく、そっと差す物なので〈打ち込む〉とは言わない。"}, {"text": "脱いだ服をかばんに打ち込んだ。", "explanation": "ここは〈押し込む〉の場面。衣服は打って入れる物ではないので、〈打ち込む〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52898, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打ち込んで", "is_correct": true, "explanation": "正解。「釘を打ち込んではいけません」の形で、打つ動作を禁止している。"}, {"text": "打ち破って", "is_correct": false, "explanation": "突き破るという意味。釘を打って木の幹を突き破る文としては合わない。"}, {"text": "打ち上げて", "is_correct": false, "explanation": "空へ打ち出すという意味。木の幹に釘を打ち上げる動作にはならない。"}, {"text": "打ち鳴らして", "is_correct": false, "explanation": "音を鳴らすという意味。釘は音を鳴らすために打つ物ではないので合わない。"}], "explanations": {"打ち込んで": "正解。「釘を打ち込んではいけません」の形で、打つ動作を禁止している。", "打ち破って": "突き破るという意味。釘を打って木の幹を突き破る文としては合わない。", "打ち上げて": "空へ打ち出すという意味。木の幹に釘を打ち上げる動作にはならない。", "打ち鳴らして": "音を鳴らすという意味。釘は音を鳴らすために打つ物ではないので合わない。"}, "sentence_index": 6, "correct_answer": "打ち込んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭に花の苗を打ち込んだ。", "explanation": "ここは〈植える〉の場面。苗は打ち込むのではなく植える物なので、〈打ち込む〉は使わない。"}, {"text": "壁に白いペンキを打ち込んだ。", "explanation": "ここは〈塗る〉の場面。液体は打ち込むものではないので、〈打ち込む〉とは言わない。"}, {"text": "ホワイトボードに地図を打ち込んだ。", "explanation": "ここは〈貼る〉の場面。紙の地図は打ち込む物ではなく、貼る物なので〈打ち込む〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52898, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "職人は屋根の板に釘へ打ち込んだ。", "corrected_sentence": "職人は屋根の板に釘を打ち込んだ。", "error_description": "目的語を示す「を」が正しいのに、方向の「へ」を使っている。「釘を打ち込む」が正しい形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "打ち込んだ", "is_correct": true, "explanation": "過去形。動作が済んだことを表し、文末の「打ち込んだ」と一致する。"}, {"text": "打ち込まない", "is_correct": false, "explanation": "否定形。釘を打ったという過去の出来事を否定することになり、文の意味と合わない。"}, {"text": "打ち込める", "is_correct": false, "explanation": "可能形。できるという意味になり、実際に打った出来事とは合わない。"}, {"text": "打ち込んで", "is_correct": false, "explanation": "て形。文を終える形ではなく、過去の文末にはならない。"}], "correct_form": "打ち込んだ", "base_form": "打ち込む", "form_label": "過去形", "sentence_index": 1, "explanations": {"打ち込んだ": "過去形。動作が済んだことを表し、文末の「打ち込んだ」と一致する。", "打ち込まない": "否定形。釘を打ったという過去の出来事を否定することになり、文の意味と合わない。", "打ち込める": "可能形。できるという意味になり、実際に打った出来事とは合わない。", "打ち込んで": "て形。文を終える形ではなく、過去の文末にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52898, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "キャンプ場で、テントの杭を深く打ち込てから、ロープを張った。", "corrected_sentence": "キャンプ場で、テントの杭を深く打ち込んでから、ロープを張った。", "error_description": "て形の誤り。「打ち込む」のて形は「打ち込んで」で、「打ち込て」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "打ち込み", "is_correct": true, "explanation": "連用形。「打ち込み、それから棚を」と中止して続く形。"}, {"text": "打ち込もう", "is_correct": false, "explanation": "意志を表す形。釘を打つ事実を述べる文にはならない。"}, {"text": "打ち込まれた", "is_correct": false, "explanation": "受身の過去形。釘が打たれる側になり、釘を打つ動作の文と合わない。"}, {"text": "打ち込めば", "is_correct": false, "explanation": "仮定形。条件の文になり、「それから棚を取り付ける」と続く流れに合わない。"}], "correct_form": "打ち込み", "base_form": "打ち込む", "form_label": "連用形", "sentence_index": 7, "explanations": {"打ち込み": "連用形。「打ち込み、それから棚を」と中止して続く形。", "打ち込もう": "意志を表す形。釘を打つ事実を述べる文にはならない。", "打ち込まれた": "受身の過去形。釘が打たれる側になり、釘を打つ動作の文と合わない。", "打ち込めば": "仮定形。条件の文になり、「それから棚を取り付ける」と続く流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52899, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52899, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「踵を」の「を」で、軸として使う対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置の「に」では、踵を軸にする関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、軸を示せない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列の「と」では、軸として使う対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「踵を」の「を」で、軸として使う対象を示す。", "に": "位置の「に」では、踵を軸にする関係が成り立たない。", "から": "起点の「から」では、軸を示せない。", "と": "相手や並列の「と」では、軸として使う対象を示せない。"}, "error_tags": {"に": "位置", "から": "起点", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d867132-af8e-429d-91ef-3f2aab2ccfbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
